window.__LIBQ=window.__LIBQ||{};window.__LIBQ["pham-nhan-tu-tien"]=window.__LIBQ["pham-nhan-tu-tien"]||{};window.__LIBQ["pham-nhan-tu-tien"]["q11"]=window.__LIBQ["pham-nhan-tu-tien"]["q11"]||{};window.__LIBQ["pham-nhan-tu-tien"]["q11"]["cotTruyen"]=[{"chuong":2171,"tieuDe":"Bế Quan","tomTat":"Trên đường rút lui, Hàn Lập và đội ngũ cảm nhận Đại Trận Mộc Giới bị kích nổ, chôn vùi lực lượng tinh nhuệ Ma tộc nhưng cũng khiến Mộc tộc mất thánh địa và khả năng tồn tại độc lập. Hai tháng sau, Hàn Lập gặp Mạc Giản Ly cùng Ngao Khiếu lão tổ gần thành Mộc Miên và biết Mộc tộc đã phân tán thành nhiều nhóm để phụ thuộc các tộc khác hoặc tiến vào vùng hoang dã. Ba người thống nhất cần cầm cự Ma tộc cho tới khi hai giới diện tách rời, đồng thời xác minh ba thủy tổ Ma tộc có thật sự tiến vào Linh giới hay không. Hàn Lập quyết định không trở lại Thiên Uyên thành mà tìm nơi kín đáo bế quan, dự định dùng lượng lớn Dị Ma Kim để tiến tới Hợp Thể Hậu Kỳ đỉnh phong. Ngao Khiếu giao Ngân Nguyệt cho Hàn Lập chăm nom và yêu cầu nàng tuyệt đối tuân theo sự sắp xếp của hắn. Sau năm tháng di chuyển, Hàn Lập đưa Ngân Nguyệt, Giải Đạo Nhân và Chu Quả Nhi tới một dãy núi vắng người giữa lãnh thổ Nhân tộc và Yêu tộc, dùng khôi lỗi đào động phủ rồi bố trí cấm chế che giấu. Hắn bế quan một năm rưỡi và luyện thành bí thuật thần niệm do Ngao Khiếu truyền, qua đó tăng thần niệm và thu được hiệu quả dưỡng tâm dưỡng khí. Sau khi quan sát Ngân Nguyệt đang tu luyện ở phòng bên cạnh, Hàn Lập lấy ra một khối khoáng thạch nửa trắng nửa đen để chuẩn bị cho bước tiếp theo."},{"chuong":2172,"tieuDe":"Bảo Quyết Đại Thành","tomTat":"Hàn Lập cắt Dị Ma Kim để lấy viên ngọc ẩn bên trong, phong kín gian phòng rồi hấp thu năng lượng và luyện hóa Địa Âm Sát Khí đi kèm. Sau hai năm, hắn tiêu hao khoảng chín phần số Dị Ma Kim mang về từ Ma giới, khiến pháp lực tăng ba phần và tu vi đạt Hợp Thể hậu kỳ đỉnh phong. Hắn chưa lập tức xung kích Đại Thừa kỳ mà dành thêm một năm củng cố pháp lực. Tiếp đó, Hàn Lập dùng Huyết Nha Mễ thượng hạng làm vật phụ trợ và bắt đầu tu luyện Bách Mạch Luyện Bảo Quyết. Hơn bốn mươi năm sau, động tĩnh dữ dội từ phòng bế quan khiến Ngân Nguyệt kinh sợ, nhưng nàng quyết định không tới quấy rầy. Hàn Lập thử một phần uy lực của bảo quyết, khiến linh văn bạc trên cánh tay kết thành pháp trận và hóa ra giao long xanh công kích cửa đá. Cuối cùng, hắn hoàn toàn luyện thành Bách Mạch Luyện Bảo Quyết, biến toàn thân thành bảo vật cực mạnh và có khả năng giết đối thủ ngang cấp mà không cần dùng pháp bảo."},{"chuong":2173,"tieuDe":"Tòa Cực Sơn Thứ Ba","tomTat":"Hàn Lập kiểm tra thân thể sau khi tu luyện, dùng quyền kình cách không phá nát cửa đá rồi dành ba ngày để hoàn toàn nắm giữ Bách Mạch Luyện Bảo Quyết. Nhờ thân thể và thần niệm đều đạt yêu cầu, hắn thuận lợi luyện thành tầng hai Luyện Thần Thuật, khiến thần niệm có thể bao phủ bán kính bảy tám vạn dặm. Hắn tiếp tục luyện hóa sạch Thanh Loan Chân Huyết, giúp Kinh Trập Quyết có thêm biến thân Thanh Loan. Sau hơn nửa tháng luyện bảo bằng hai khối vật liệu chứa Âm Dương Đại Ngũ Hành Chân Quang và nhiều tài liệu quý, hắn hoàn thành Âm Dương Đại Ngũ Hành Cực Sơn, dù lô đỉnh màu bạc bị phá hủy. Hàn Lập sau đó dành hơn năm năm nghiên cứu Thanh Nguyên Kiếm Quyết và mười một năm tìm hiểu Phạm Thánh Chân Ma công, nhờ kinh nghiệm của Ngao Khiếu cùng Mạc Giản Ly mà giải đáp nhiều điểm khó và sáng tạo thêm nhiều thần thông. Khi đã có ba tòa cực sơn, dược lực Tịnh Linh Liên cùng những điều kiện cần thiết khác, hắn tự đánh giá có sáu đến bảy phần thành công và rời gian phòng để chuẩn bị trùng kích Đại Thừa."},{"chuong":2174,"tieuDe":"Chuẩn Bị","tomTat":"Hàn Lập xuất quan khi pháp lực, thân thể và tinh thần đều đạt trạng thái tốt nhất, quyết định lập tức đánh sâu vào chướng ngại Đại Thừa. Giải Đạo Nhân đánh giá hắn có khoảng năm phần cơ hội thành công và nhận lời hộ pháp, còn Ngân Nguyệt sau một lần khuyên can cũng quyết định cùng tham gia bảo vệ. Qua Ngân Nguyệt, Hàn Lập biết Chu Quả Nhi đã chuyển tới một ngọn núi gần đó để mượn ánh mặt trời vượt chướng ngại của Tố Nữ Luân Hồi Công nên không đến quấy nhiễu. Ba người rời động phủ, tới vùng đất bằng phẳng cách đó khoảng vạn dặm, nơi Hàn Lập dùng khôi lỗi, trận kỳ, trận bàn, linh thạch và nhiều bảo vật chiến lợi phẩm để dựng đại trận che giấu dao động cùng thiên tượng. Hắn tiếp tục nâng đất thành đài, dùng linh hỏa màu bạc tôi luyện vật liệu, điều khiển bảy mươi hai thanh kiếm khắc linh văn và đặt bốn lá cờ quái thú tại bốn góc. Phiên Thiên Thai theo phương pháp của Mạc tiên bối được hoàn thành, sau đó bảy mươi hai thanh kiếm phân hóa thành hơn ngàn kiếm ảnh ẩn vào không gian xung quanh. Khu vực trong bán kính trăm trượng quanh pháp đài vì thế được bao phủ bởi kiếm khí dày đặc, hoàn tất lớp phòng vệ cuối cùng trước lúc Hàn Lập đột phá."},{"chuong":2175,"tieuDe":"Linh Triểu","tomTat":"Hàn Lập gọi ra ba ngọn núi đặt quanh bệ đài trong suốt, sau đó điều dưỡng từ giữa trưa đến rạng sáng hôm sau dưới sự quan sát của Ngân Nguyệt và Giải Đạo Nhân. Hắn giải phóng khí tức, hiện Phạm Thánh pháp tướng ba đầu sáu tay và kích hoạt khoảng một trăm pháp trận bằng văn tự, khiến thiên địa nguyên khí gần đó chấn động dữ dội. Sau nửa tháng tích lũy, khí tức của Hàn Lập đạt mức khiến tu sĩ Hợp Thể Kỳ kinh hãi, còn pháp tướng tăng tới ba trăm trượng và gần như ngưng thành thân thể thật. Nguyên anh màu vàng của hắn xuất khiếu, nuốt thiên lôi rồi tạo ra các khối lôi văn để dẫn nguyên khí năm màu thành dòng sông linh khí đổ vào nguyên anh cùng thân thể. Phạm Thánh pháp tướng tiếp tục tạo cơn lốc vàng, kéo thiên địa linh khí trong phạm vi mấy vạn dặm hội tụ thành linh triều tràn về vùng đất trũng. Khi nguyên anh và thân thể đạt giới hạn bão hòa, Hàn Lập dừng hấp thu để tránh nguy cơ nổ tung, còn pháp tướng há ba miệng tiếp quản và nuốt trọn dòng linh khí."},{"chuong":2176,"tieuDe":"Thiên Kiếp Ngũ Hành","tomTat":"Pháp tướng Phạm Thánh ba đầu sáu tay tiếp tục hấp thu dòng linh khí, giúp Hàn Lập luyện hóa lượng nguyên khí khổng lồ và tăng mạnh pháp lực. Hắn toàn lực vận chuyển Phạm Thánh Chân Ma Công suốt một tháng, cuối cùng khiến khí tức đạt tới cấp Đại Thừa, dù việc đột phá chỉ được xác lập sau khi vượt qua thiên kiếp. Bên ngoài thung lũng, Ngân Nguyệt, Chu Quả Nhi và Giải Đạo Nhân đều chăm chú theo dõi, trong đó Giải Đạo Nhân nhận định thử thách quyết định vẫn còn ở phía trước. Hàn Lập hiện thân trong trạng thái ma hóa với thân thể đầy thương tích nhưng đang nhanh chóng hồi phục. Mây đen sau đó tụ lại thành dị tượng năm màu, khiến Ngân Nguyệt nhận ra Thiên Kiếp Ngũ Hành. Đợt kim hành hóa thành vô số Kim Cương Khí, liên tiếp phá năm tầng trận pháp bảo hộ trước khi bị quyền ảnh từ pháp tướng sáu tay đánh tan. Kiếp lực còn lại nhanh chóng chuyển thành một luồng sáng xanh lớn, báo hiệu đợt công kích ngũ hành kế tiếp."},{"chuong":2177,"tieuDe":"Uy Phong Của Thiên Kiếp","tomTat":"Hàn Lập điều khiển bảy mươi hai Thanh Trúc Phong Vân Kiếm kết thành võng kiếm, cắt nát những cây khổng lồ rồi đánh tan vầng sáng xanh của mộc kiếp. Khi thủy kiếp giáng xuống, Phạm Thánh Pháp Tướng dùng ngân diễm hóa hơi dòng nước, nhưng những quả cầu Thiên hà trọng thủy vẫn xuyên qua linh diễm và phá hủy quá nửa sáu cánh tay của pháp tướng. Hàn Lập vận pháp tái tạo sáu tay, sau đó đảo ngược thuộc tính ngân diễm thành Cực hàn chi diễm để giằng co với biển quạ lửa trắng. Hắn tiếp tục hợp nhất kiếm quang thành cự nhận, giao cho pháp tướng bổ đôi quang đoàn đỏ sẫm và phá tan hỏa kiếp. Ngay sau đó, bụi vàng mang theo chiến khí hóa thành vô số binh sĩ đất sét cùng chim thú. Cự nhận có thể chém nát đội quân này, nhưng biển bụi lập tức tái ngưng tụ chúng, khiến Hàn Lập phải đối diện một tầng thiên kiếp chưa tìm được cách hóa giải."},{"chuong":2178,"tieuDe":"Chân Lôi Kiếp","tomTat":"Hàn Lập vận dụng pháp tướng Phạm Thánh tạo sóng âm rồi dựng lốc xoáy, hút sạch biển bụi cùng đội quân khổng lồ do nó biến ảo. Hắn ép toàn bộ biển bụi thành một khối đất vàng nặng hàng triệu cân và thu giữ vì nhận thấy vật này có tiềm năng luyện bảo. Sau khi thiên kiếp Ngũ Hành kết thúc, Chân Lôi Kiếp xuất hiện trong một lỗ hổng lôi điện giữa mây đen, đẩy Hàn Lập tới cửa ải sinh tử trước Tâm Kiếp. Hàn Lập kích hoạt các pháp trận còn lại, nâng ba tòa cực sơn thành thế tam giác và cho bảy mươi hai phi kiếm hóa sen xanh để bảo vệ bản thân. Trong khi đó, Ngân Nguyệt phát hiện người lạ đang tiến đến nên rời núi ngăn cản, còn Chu Quả Nhi ở lại và Giải Đạo Nhân chỉ âm thầm quan sát. Cách vùng đất trũng khoảng vạn dặm, nhóm tu sĩ Nhân tộc do thiếu nữ áo lam dẫn đầu đang bị một đội ngũ Ma tộc tinh nhuệ truy sát. Thiếu nữ dùng đỉnh nhỏ trong suốt giết hai Ma tộc Nguyên Anh nhưng đòn đánh bị Ma tộc đầu rắn mình người hóa giải. Hai Ma tộc Hóa Thần hậu kỳ chặn đường tháo chạy, buộc nhóm Nhân tộc phải phòng thủ trước cuộc tấn công đồng loạt của quân Ma tộc."},{"chuong":2179,"tieuDe":"Gặp Người Quen Cũ","tomTat":"Khi Hứa Thiên Vũ chuẩn bị dùng cấm thuật để đồng quy vu tận với toán Ma tộc truy sát, Ngân Nguyệt phá không xuất hiện và dùng vô số sợi tơ trong suốt tiêu diệt toàn bộ đối phương. Biết những người được cứu là hậu duệ Hứa gia, nàng nhận ra Hứa Thiên Vũ chính là người từng được Hàn Lập nhắc tới và cho biết một người bạn của mình có quan hệ sâu xa với Băng Phách tiên tử. Ngân Nguyệt giao phù báo tin cho Hứa Thiên Vũ, yêu cầu nhóm Hứa gia chia đội tuần tra ngoại vi rồi quay về nơi phát sinh lôi kiếp. Hứa Thiên Vũ bác bỏ sự nghi ngại của người anh họ, khẳng định gia tộc vừa mang ơn cứu mạng vừa không đủ sức trái lệnh vị tiền bối áo bạc. Tại khu đất trũng, Hàn Lập dùng ba tòa cực sơn, pháp tướng Phạm Thánh và hoa sen kiếm chống biển lôi điện, nhờ đó chưa bị thương nhưng đã tiêu hao bảy tám phần pháp lực. Khi hang động trên trời thu nhỏ và ép biển sấm chớp hội tụ, một lôi cầu hai màu đen trắng mang khí tức hủy diệt bắt đầu thành hình, báo hiệu đòn cuối của Thực Lôi Kiếp."},{"chuong":2180,"tieuDe":"Hắc Bạch Lôi Cầu","tomTat":"Lôi cầu hai màu đen trắng cuối cùng của Chân Lôi Kiếp mang theo thiên địa pháp tắc, khóa chặt bản thể Nguyên Anh khiến Hàn Lập không thể né tránh. Hắn dùng ba đoàn tinh huyết thi triển Tam Sơn Hợp Thể, đồng thời lần lượt điều động Phạm Thánh Kim Thân và kiếm liên màu xanh ngăn cản lôi cầu, nhưng cả hai thủ đoạn đều không thể hóa giải nó. Kiếm liên bị đánh nổ khiến bảy mươi hai khẩu phi kiếm tổn thương và Hàn Lập chịu phản phệ thổ huyết. Hợp Thể Cực Sơn sau đó có thể dùng hào quang nhiều màu từ từ mài nhỏ lôi cầu, song tốc độ tiêu hao pháp lực khiến Hàn Lập nhận ra mình sẽ kiệt sức trước. Hắn chủ động rút pháp lực, biến thành Kim Mao Cự Viên rồi dung hợp Kim Thân cùng các Chân Linh hư ảnh để thi triển Niết Bàn Thánh Thể đã tiến gần giai đoạn thứ ba. Khi Hợp Thể Cực Sơn tan rã, lôi cầu đánh vỡ quả cầu màu đen và giải phóng hơn mười đàn Phệ Kim Trùng cùng các Hậu Tuyển Trùng Vương. Toàn bộ trùng quần chỉ ngây dại vỗ cánh giữa không trung, trong khi kết quả của Chân Lôi Kiếp vẫn chưa được xác định."},{"chuong":2181,"tieuDe":"Trùng Biến","tomTat":"Hàng vạn Phệ Kim Trùng cắn nuốt lôi điện để cầm chân lôi cầu cuối cùng, giúp Hàn Lập hoàn tất biến thân dù phần lớn đàn trùng bị đánh hôn mê. Hàn Lập lần đầu đồng thời vận dụng Niết Bàn Thánh Thể, Kinh Trập Quyết và Bách Mạch Luyện Bảo Quyết, tạo giáp tay pháp trận rồi dùng bốn ảo ảnh cánh tay bạc bóp vỡ lôi cầu. Những khối điện còn lại đánh tan bốn cánh tay mới mọc và khiến hắn trọng thương, nhưng Chân Lôi Kiếp cuối cùng vẫn tiêu tán mà không lấy được tính mạng hắn. Sau khi giải trừ biến thân, ngoại thương của Hàn Lập nhanh chóng phục hồi, còn nội thương vẫn rất nặng. Đàn Phệ Kim Trùng tỉnh lại nhưng không tuân lệnh triệu hồi, chia thành nhiều đàn hỗn chiến để các dự bị trùng vương cắn nuốt đồng loại. Giữa lúc Hàn Lập do dự có nên cưỡng ép đàn trùng, vô số ma ảnh xuất hiện trong mây đen và phát ra âm thanh làm thần thức hoảng hốt. Một khuôn mặt xám trắng khổng lồ khiến tâm thần hắn mơ màng, đưa nhận thức của hắn vào một không gian hoàn toàn xa lạ."},{"chuong":2182,"tieuDe":"Thần Lôi Dọa Lui Ma","tomTat":"Hàn Lập nhận ra nguyên thần mình đã xuất khiếu và chính thức tiến vào Tâm Ma Kiếp dưới hình dáng thiếu niên. Thiên Ngoại Ma Quân nhân cơ hội này cách không đưa bản thể tới quấy nhiễu, nhưng Hàn Lập kích nổ bảy khối Kim Cương Diệt Ma Thần Lôi hoàn chỉnh, thiêu hủy phần lớn khí đen và khiến đối phương trọng thương. Khi Ma Quân dồn sức phản công, hắn đưa ra thêm bảy khối thần lôi chưa hoàn chỉnh làm nghi binh, khiến kẻ địch tưởng thật và vội bỏ chạy sau khi đe dọa sẽ chặn đường phi thăng của hắn. Kế hoạch này đã được Hàn Lập chuẩn bị từ khi đạt Hợp Thể Hậu Kỳ Đại Thành, bao gồm việc luyện hóa thần lôi cùng nguyên thần để có thể sử dụng trong kiếp cảnh. Sau khi đối thủ rút lui, vô số con mắt xám phát ánh sáng năm màu làm thần thức hắn mê man và kéo hắn vào ảo cảnh quê nhà thuở nhỏ. Hàn Lập quên mất tình cảnh độ kiếp, trở thành một đứa trẻ chơi cùng Cẩu Oa, Hắc Đản và Thiết Tru rồi vui mừng nhận ra Tiểu muội đang chạy tới. Bên ngoài, thân thể cùng Nguyên Anh của hắn vẫn ngồi giữa dải đất trũng và tự phát kim sắc lôi điện đánh tan các ma vật đến gần, trong khi Ngân Nguyệt, Chu Quả Nhi và Giải Đạo Nhân ở các đỉnh núi xa theo dõi tình hình."},{"chuong":2183,"tieuDe":"Tâm Ma Kiếp","tomTat":"Bên dưới tấm gương xám phát hào quang năm màu, các Phệ Kim Trùng bình thường bị nhóm cá thể tím sắp thành trùng vương cắn nuốt sạch, rồi những kẻ sống sót tiếp tục quyết đấu mà chưa thể sớm phân thắng bại. Trong Tâm Ma Kiếp, Hàn Lập bị cuốn vào cuộc đời của một người dân quê vừa cưới vợ và suýt chấp nhận viễn cảnh sinh con, sống cùng gia đình rồi già đi. Luồng khí lạnh từ đan điền giúp hắn khôi phục ký ức, nhìn thấu tân nương giả và chém tan huyễn cảnh trước khi dùng điện vàng đánh vào khí đen do tâm ma ẩn náu. Tâm ma tuyên bố nó hiểu rõ ký ức cùng tình cảm của Hàn Lập và sẽ khiến hắn trải qua vô số lần luân hồi phàm tục để tìm sơ hở, còn Hàn Lập lấy thành tựu Luyện Thần Thuật và thần niệm mạnh mẽ làm chỗ dựa chống lại. Tâm ma sau đó chuyển cảnh sang Mặc phủ, tái hiện lần gặp Mặc Thải Hoàn và dùng lực lượng thần bí khiến Hàn Lập quên thực tại, vô thức diễn lại ký ức năm xưa. Ở không gian bên ngoài, thân thể cùng Nguyên Anh của Hàn Lập vẫn bất động giữa ma khí, trong khi số lượng, sức mạnh và tần suất công kích của ma vật đều không ngừng gia tăng."},{"chuong":2184,"tieuDe":"Hai Yêu Vương Đến","tomTat":"Hàn Lập vẫn ngồi bất động tại vùng đất trũng trong lúc đối phó Tâm Ma Kiếp và số lượng lớn Thiên Ngoại Ma Đầu. Ngân Nguyệt trấn an Chu Quả Nhi, giao nàng ở lại giám sát nơi độ kiếp rồi lên đường sau khi nhận cảnh báo từ nhóm Hứa Thiên Vũ. Ở một dải núi khác, Giải Đạo Nhân dùng khí tức Đại Thừa áp chế Hắc Phượng Vương và Động Thiên Thử Vương, buộc hai người không được rời khỏi chỗ. Hai Đại Yêu Vương bí mật bàn về lai lịch của Giải Đạo Nhân và một vật có thể mang lại cơ hội tiến vào Đại Thừa Kỳ. Trong khi đó, Ngân Nguyệt triệu xuất pháp tướng sói bạc tấn công đám Ma tộc nhưng bị một Cổ Ma hai đầu bốn tay phá tan pháp tướng, khiến nàng thổ huyết và rơi vào hiểm cảnh. Ngay trước khi bốn ma khí đánh trúng nàng, một lưỡi dao màu xám bất ngờ xuất hiện sau lưng Cổ Ma và chém rơi một đầu của hắn, nhưng người ra tay vẫn chưa lộ diện."},{"chuong":2185,"tieuDe":"Chém Tâm Ma","tomTat":"Sau khi Cổ Ma bị chém mất đầu, Lão Ảnh hiện thân và xác nhận mình là Ảnh vệ có nhiệm vụ bảo vệ Ngân Nguyệt. Hai người nhanh chóng giết sạch tàn quân Ma tộc, khiến Hứa Thiên Vũ cùng các đệ tử Hứa gia kinh hãi trước thực lực của cao thủ Hợp Thể kỳ. Trong Tâm Ma Kiếp, Hàn Lập bị đưa vào cảnh Thất Huyền môn và gặp một ảo ảnh Lệ Phi Vũ dùng rượu độc cùng chuyện tranh quyền để thử hắn. Hàn Lập nhận ra đối phương là giả, dùng kiếm xanh chém điểm then chốt khiến cảnh cung điện sụp đổ. Hắn tiếp tục trải qua hơn trăm vòng luân hồi, nhiều lần tự phá phong ấn trí nhớ và chém các hóa thân thân hữu, hồng nhan, sư phụ cùng kẻ thù do tâm ma dựng nên. Những lần thử thách liên tiếp tôi luyện tâm thần Hàn Lập thêm một bậc và khiến tâm ma không còn tìm được nhược điểm để lay động hắn. Khi tâm ma hiện thành mặt quỷ khí đen và đe dọa biến thành Chân Tiên, Hàn Lập triệu Huyền Thiên Kiếm rồi chém xuống trong sự kinh hãi của đối phương."},{"chuong":2186,"tieuDe":"Tiến Cấp Đại Thừa","tomTat":"Sau hàng trăm lần luân hồi làm tâm ma suy yếu, Hàn Lập vận dụng một phần uy lực của Huyền Thiên Kiếm, dùng sức mạnh pháp tắc trói buộc rồi chém tan mặt quỷ hoàn toàn. Không gian Tâm Ma sụp đổ, nguyên thần của hắn thoát khỏi gương xám, trở về nguyên anh và nhập lại thân thể. Thiên địa nguyên khí sau đó tụ thành biển sáng năm màu, còn ba vòng mặt trời truyền Thái Dương Chân Tinh xuống, tạo nên dị tượng Tam Dương Quán Thể. Hàn Lập được đúc lại thân thể, pháp lực tăng nhiều lần, thể chất mạnh hơn trước quá nửa và nguyên anh chính thức trưởng thành, đánh dấu việc hắn tiến cấp Đại Thừa thành công. Dị tượng này khiến Ngân Nguyệt, Lão Ảnh, Hứa Thiên Vũ và những người quan sát từ xa đều chấn động. Giải Đạo Nhân chúc mừng Hàn Lập và xác nhận hắn đã đạt hai điều kiện cần thiết để tạm đủ tư cách làm chủ nhân của mình. Do địa điểm hiện tại không thích hợp, Hàn Lập quyết định để sau mới hỏi kỹ về những yêu cầu còn lại."},{"chuong":2187,"tieuDe":"Người Quen Cũ Thần Bí","tomTat":"Ngân Nguyệt chúc mừng Hàn Lập trở thành vị Đại Thừa thứ ba của Nhân tộc và Yêu tộc, còn hắn khẳng định quan hệ giữa hai người vẫn không thay đổi. Hứa Thiên Vũ báo rằng Huyết Linh đã rời Hứa gia rồi mất tích, khiến hy vọng đón chân thân Băng Phách trở về trở nên mong manh. Khi gặp Động Thiên Thử Vương, Hàn Lập nhận ra khí tức của đối phương giống một người quen cũ, nhưng không tin lời giải thích về hóa thân từng xuất hiện tại Vạn Bảo Đại Hội. Để giữ kín tin mình tiến giai, hắn yêu cầu hai vị Yêu Vương cùng đoàn tu sĩ Hứa gia tạm lưu lại động phủ. Hứa Thiên Vũ sau đó thuật lại tình hình tàn quân Ma tộc và tin tức về thệ ước bí mật giữa các Đại Thừa đại diện chư tộc với Tam đại Thủy tổ. Cuối cùng, Hàn Lập âm thầm tới mật thất gặp Động Thiên Thử Vương, còn đối phương đã chờ sẵn và thừa nhận lời che giấu trước đó không thể đánh lừa hắn."},{"chuong":2188,"tieuDe":"Tin Tức Của Sương Công","tomTat":"Hàn Lập nhận ra Động Thiên Thử Vương chính là bản thể của Thiên Lan Thánh Thú từng giáng phân thân xuống Nhân giới. Để hóa giải ân oán cũ, Thử Vương phải thừa nhận từng gặp Lục Dực Sương Công và tiết lộ rằng linh trùng đã đổi lấy một phần Nghịch Linh Chân Âm Đại Pháp từ Kim Khuyết Ngọc Thư. Công pháp này giúp Sương Công tiến vào Hợp Thể kỳ và còn mở ra khả năng tiến lên Đại Thừa, trong khi mối liên hệ yếu ớt còn sót lại từ Huyết Chú chủ tớ đã giúp Hàn Lập lần ra đầu mối. Sau khi nhận tinh bài màu lam nhạt, Hàn Lập xóa bỏ hiềm khích với Thử Vương nhưng buộc hắn dùng Tâm Ma thề giữ kín chuyện này. Hàn Lập tiếp tục gặp Hắc Phượng Vương và biết Đại Nhi đã được đưa vào cấm địa Hắc Phượng tộc bế quan từ đầu ma kiếp, hiện vẫn an toàn. Trở về mật thất, hắn chuẩn bị củng cố cảnh giới Đại Thừa để phát huy trọn vẹn thân thể và pháp lực đã biến đổi. Trước khi bế quan, hắn thả ba đoàn Kim Hoa, khiến chúng hóa thành ba quái vật cao vài trượng."},{"chuong":2189,"tieuDe":"Thần Du Vạn Dặm","tomTat":"Sau khi hấp thu chân lôi thiên kiếp và cắn nuốt lẫn nhau, đàn Phệ Kim Trùng của Hàn Lập chỉ còn ba hậu tuyển trùng vương có khí tức tương đương tu sĩ Hợp Thể hậu kỳ, nhưng cả ba vẫn hoàn toàn chịu thần niệm khống chế. Giải Đạo Nhân xác nhận Hàn Lập đã đủ tư cách cơ bản để trở thành chủ nhân chính thức, đồng thời trao một ngọc giản ghi danh sách vật liệu bắt buộc phải thu thập đủ trước khi tiết lộ những điều kiện tiếp theo. Hàn Lập chấp nhận thử sức, cất ngọc giản rồi nhập định suốt một tháng để củng cố cảnh giới Đại Thừa. Sau đó, hắn để thân thể cùng linh khu do Khúc Nhi điều khiển ở lại mật thất, còn Nguyên Anh mang theo tiểu kiếm và ba bán trùng vương thi triển Thần Du Vạn Dặm. Nguyên Anh tiến lên ngoại thiên, chịu đựng gió lốc và phong nhận dữ dội, thậm chí thoát khỏi một khe nứt không gian mà không bị tổn thương. Khi không gian xung quanh bắt đầu chấn động và vỡ vụn, một vật khổng lồ chưa rõ lai lịch từ nơi cao trên hư không thò ra, dùng đôi mắt lớn như lầu các nhìn chằm chằm vào Nguyên Anh Hàn Lập."},{"chuong":2190,"tieuDe":"Phàn Bào Tử Và Đạo Quả Đại Hội","tomTat":"Trong lần đầu để nguyên anh thoát xác thần du sau khi tiến giai Đại Thừa, Hàn Lập bị một tồn tại đáng sợ nhìn chằm chằm và phải thi triển pháp quyết làm chậm thời gian, không gian để thoát khỏi vùng uy hiếp. Sinh vật ấy là một Tử Tình Chân Long bị thương, sau đó hóa thành thiếu niên áo bạc và tự xưng Phàn Bào Tử. Hắn kể mình vừa lưỡng bại câu thương với Thất Thủ Kiêu vì tranh đoạt bảo vật, đồng thời đề nghị Hàn Lập hợp sức săn hung cầm với phần thưởng là nội đan quý hiếm. Hàn Lập kiên quyết từ chối vì vừa tiến giai và không muốn trêu chọc hung vật có thể gây họa diệt tộc. Phàn Bào Tử quyết định dưỡng thương rồi rời cảnh nội Nhân tộc, tránh để Thất Thủ Kiêu tìm đến trút giận lên cả tộc. Trước lúc chia tay, hắn trao cho Hàn Lập một lân phiến bạc làm thiếp mời tới Quảng Linh quả đại hội tại Chân Long đảo sau vài trăm năm. Phàn Bào Tử còn cảnh báo rằng nhiều Chân Linh thích săn ăn nguyên anh của tu sĩ Đại Thừa, rồi hóa lại thành ngân long và phá không rời đi."},{"chuong":2191,"tieuDe":"Trở Về","tomTat":"Sau khi cự long màu bạc rời vùng phụ cận hư không, Nguyên Anh của Hàn Lập trở về thân thể và hắn thu hồi Linh khu. Trải nghiệm Cương Phong tẩy lễ giúp hắn nhận ra Thần du Vạn dặm còn có thể củng cố Nguyên Anh và hỗ trợ tu luyện. Hàn Lập xem lại lân phiến màu bạc của Phàn Bào Tử, tìm hiểu Chân Long đảo và quyết định sẽ hỏi thêm Mạc Giản Ly trước khi cân nhắc tham dự Quảng linh đạo quả đại hội. Sau hai tháng tiếp tục bế quan, hắn dẫn Giải Đạo Nhân, Ngân Nguyệt và Chu Quả Nhi lên thuyền ngọc trở về Thiên Uyên thành. Tại Thiên Uyên thành, trưởng lão hội nghe báo cáo về việc khôi phục cấm chế, khôi lỗi và các công trình phòng thủ sau Ma kiếp, đồng thời lo ngại chiến tranh có thể bùng phát quanh lãnh địa cũ của Mộc tộc. Cốc trưởng lão sau đó thông báo sứ giả Thánh Đảo đã tới để đòi một đệ tử của Hàn Lập. Đại hán mặt vàng muốn giao người, còn nữ tử tóc tím và Ngân Quang tiên tử phản đối vì công lao, thực lực và khả năng Hàn Lập tiến giai Đại Thừa. Kim Việt thiền sư khép lại chương bằng việc nhắc tới tin đồn Hàn Lập được Ngao Khiếu và Mạc Giản Ly đặc biệt coi trọng."},{"chuong":2192,"tieuDe":"Sứ Giả Của Thánh Đảo","tomTat":"Trưởng lão hội Thiên Uyên thành tranh luận gay gắt về mệnh lệnh giao một đệ tử có ẩn lôi linh căn của Hàn Lập cho Thánh Đảo. Người này được dự định dùng để giúp Đỗ Vũ vượt Đại Thừa lôi kiếp, nhưng Ngân Quang tiên tử cảnh báo rằng việc cưỡng ép tăng tu vi có thể khiến hắn tiêu hao thọ nguyên và trở thành phế nhân. Phe ủng hộ coi đây là cái giá đáng chấp nhận để Nhân Yêu hai tộc có thêm một tu sĩ Đại Thừa, trong khi phe phản đối nhắc tới lời Hàn Lập phó thác bảo vệ môn nhân cùng cái chết của Thanh Long thượng nhân. Cốc trưởng lão quyết định trì hoãn, giữ đệ tử Hàn Lập trong thành, tìm cách liên hệ Ngao Khiếu và Mạc Giản Ly, đồng thời dò xét thái độ của Thánh Đảo. Ba tháng sau, nhiều trưởng lão và hơn trăm giáp sĩ tập trung ngoài cổng thành để chờ ba sứ giả chưa rõ thân phận. Một chiếc ngọc thuyền bất ngờ bay tới, nhưng người đứng ở mũi thuyền lại là Hàn Lập vừa trở về, khiến toàn bộ trưởng lão kinh hãi."},{"chuong":2193,"tieuDe":"Đỗ Vũ","tomTat":"Sau gần nửa năm liên tục đi đường, Hàn Lập cùng Ngân Nguyệt và Giải Đạo Nhân trở lại Thiên Uyên thành, khiến các trưởng lão Hợp Thể đang chờ ngoài cổng kinh ngạc vì không thể nhìn thấu cảnh giới của hắn. Đúng lúc Cốc trưởng lão còn do dự chưa nói rõ nguyên nhân tập trung, một thuyền ngọc trắng mang dấu hiệu Thánh đảo xuất hiện, chở Đỗ Vũ cùng hai tu sĩ Hợp Thể trung kỳ tới nơi. Đỗ Vũ xác nhận mình vừa xuất quan, đang chuẩn bị trùng kích Đại Thừa và cần Thiên Uyên thành trợ giúp. Hắn kiêng kị Hàn Lập vì những chiến tích được lưu truyền và vì không thể dò ra tu vi thật của đối phương. Mục đích chuyến đi của đoàn Thánh đảo liên quan đến một đệ tử của Hàn Lập có khả năng hỗ trợ chống lại một phần Chân lôi kiếp, nên việc Hàn Lập bất ngờ trở về khiến kế hoạch của họ có nguy cơ gặp trở ngại. Cốc trưởng lão mời hai bên vào đại sảnh một tòa tháp đá, nơi Hàn Lập trực tiếp hỏi liệu sự việc có quan hệ với mình hay không."},{"chuong":2194,"tieuDe":"Trở Mặt","tomTat":"Cốc trưởng lão cho Hàn Lập biết Thánh đảo muốn đưa Hải Nguyệt Thiên, người sở hữu Ẩn Lôi linh căn, tới hỗ trợ kế hoạch bồi dưỡng một Đại Thừa mới. Đỗ Vũ giải thích rằng Mạc Giản Ly và Ngao Khiếu đều sắp cạn thọ nguyên, khiến Nhân Yêu nhị tộc cần gấp người kế tục, còn năng lực của Hải Nguyệt Thiên có thể giúp ứng viên ngăn Chân lôi Đại Thừa chi kiếp. Hàn Lập vạch rõ muốn đạt hiệu quả ấy phải cưỡng ép đệ tử tăng một đại cảnh giới, đổi lại bằng tiềm lực và thọ nguyên, nên lời hứa giữ mạng không đủ bảo đảm tương lai cho Hải Nguyệt Thiên. Trước sức ép lấy đại cục hai tộc làm lý do, hắn yêu cầu phái đoàn phát tâm ma huyết thệ rằng sự hy sinh chắc chắn tạo ra Đại Thừa mới. Biết Đỗ Vũ cũng là ứng viên đột phá, Hàn Lập yêu cầu đối phương giao toàn bộ bảo vật và đan dược hỗ trợ cho mình để thử lập trường hy sinh vì đại cục, nhưng Đỗ Vũ từ chối. Hàn Lập lập tức chấm dứt thương lượng và đuổi ba sứ giả về Thánh đảo. Đỗ Vũ sau đó kéo Cốc trưởng lão và Kim Việt thiền sư vào cuộc, ám chỉ Thiên Uyên thành có thể bị liên lụy, khiến Cốc trưởng lão phải miễn cưỡng đề nghị đôi bên cùng nhượng bộ."},{"chuong":2195,"tieuDe":"Lấy Lớn Hiếp Nhỏ","tomTat":"Cốc trưởng lão đề nghị để Hàn Lập cùng Chu Quả Nhi tới Thánh Đảo nhằm dung hòa tranh chấp, nhưng Hàn Lập bác bỏ và đặt cược rằng chỉ cần một trong ba sứ giả bình yên đỡ được một chiêu của hắn thì hắn sẽ để học trò đi theo họ. Đỗ Vũ đại diện nhận lời vì tin vào Nho gia Thánh công cùng các bảo vật của mình, trong khi những trưởng lão Thiên Uyên Thành giữ thái độ trung lập. Mọi người di chuyển tới điện thi đấu, còn Giải Đạo Nhân dùng hào quang bạc và lôi điện đưa Ngân Nguyệt cùng Chu Quả Nhi đi theo. Tại quảng trường trong cung điện, Hàn Lập triệu pháp tướng ba đầu sáu tay màu vàng cao tới bảy tám mươi trượng và quạt một bàn tay khổng lồ xuống, khiến không gian phía trước nát vụn. Đỗ Vũ lấy ra một quyển sách ngọc cùng một nghiên mực trắng, trong đó một món là bảo vật cấp Thông Thiên Linh Bảo phi phàm và món kia là mảnh vỡ Huyền Thiên Chi Bảo. Khi linh văn bạc tạo thành hơn mười pháp trận trên bàn tay pháp tướng, linh áp tăng mạnh khiến Đỗ Vũ chưa kịp điều khiển bảo vật đã bị ép lùi. Hắn kinh hãi nhận ra Hàn Lập đã có thần thông cấp Đại Thừa, nhưng chương kết thúc trước khi bàn tay pháp tướng thực sự đánh trúng."},{"chuong":2196,"tieuDe":"Bại Trong Một Chiêu","tomTat":"Đỗ Vũ liều hao tổn tinh huyết và xuất Nguyên Anh để triệu hồi Hạo Nhiên Thánh Tượng chống lại Bàn tay Tử Kim của Hàn Lập. Thánh tượng phối hợp ngũ sắc tuyệt bút, nghiên mực và ngọc sách ngưng tụ chữ Nho màu bạc, hấp thu Thiên Địa nguyên khí để cản đòn. Hàn Lập tăng uy lực thần thông bằng vòng xoáy vàng trong lòng bàn tay, phá tan chữ Nho cùng Thánh tượng, khiến Nguyên Anh Đỗ Vũ bị thương và thân thể bị giam cầm. Sau khi phân định thắng bại, hắn tịch thu ngọc sách và nghiên mực, tuyên bố Đỗ Vũ chỉ có thể đến đòi lại khi tiến vào Đại Thừa kỳ. Trở ra ngoài màn sáng, Hàn Lập công khai xác nhận đã đột phá Đại Thừa từ vài tháng trước và phóng thích linh áp khiến các tu sĩ Hợp Thể phải lùi lại. Các trưởng lão Thiên Uyên thành lập tức đổi cách xưng hô và vui mừng hành lễ, còn đại hán tóc vàng cùng phụ nhân xấu xí cũng sợ hãi từ bỏ thái độ kiêu căng."},{"chuong":2197,"tieuDe":"Đoàn Tụ","tomTat":"Hàn Lập tha cho các trưởng lão và buộc nhóm sứ giả Thánh Đảo đưa Đỗ Vũ rời đi, đồng thời tuyên bố Hải Đại Thiếu không thể bị đem làm vật hi sinh. Sau khi rời khu điện thi đấu cùng Ngân Nguyệt, hắn giải thích rằng Đỗ Vũ dù có cơ hội tiến cấp Đại Thừa cũng chưa đủ sức uy hiếp mình, nhưng nếu thật sự trở thành mầm họa thì hắn sẽ ra tay trừ bỏ. Trở về căn lầu, Hàn Lập đoàn tụ với Hải Đại Thiếu, Khí Linh Tử và hơn mười môn đồ, đồng thời nhận thấy hai đệ tử đã đạt Hóa Thần và Hóa Thần hậu kỳ. Hắn giao họ thông báo cho các gia tộc lớn về đại lễ Đại Thừa dự kiến tổ chức sau một năm tại thành Thiên Uyên. Khí Linh Tử báo Bạch Quả Nhi vẫn đang du lịch bên ngoài, còn Băng Phượng đã vào khu vực hoang dã hơn mười năm nhưng Nguyên Mệnh Đăng vẫn bình an. Lo thân thể Băng Tủy khiến Bạch Quả Nhi bị tu sĩ âm hàn nhòm ngó, Hàn Lập lập tức gọi nàng trở về. Cuối cùng, hắn trách Hải Đại Thiếu làm lộ linh căn Ẩn Lôi khi say rượu, từ chối giao đệ tử ra ngoài và quyết định cho người này tạm lánh mặt sau đại lễ."},{"chuong":2198,"tieuDe":"Xao Hai Tộc","tomTat":"Hàn Lập trấn an Hải Nguyệt Thiên, giới thiệu Ngân Nguyệt và Giải Đạo Nhân với môn hạ, đồng thời cho phép Chu Quả Nhi tạm thời được coi như sư muội. Khí Linh Tử báo cáo rằng quân Ma tộc đã rút về Ma giới, giúp hai tộc Nhân–Yêu thu hồi lãnh thổ, nhưng Ngao Khiếu và Mạc Giản Ly lại đồng loạt mất tích sau ma kiếp. Hàn Lập cùng Ngân Nguyệt phân tích các khả năng mà không tìm được kết luận, vì vậy hắn quyết định tới Thánh Đảo điều tra và giao môn hạ tìm kiếm một danh sách vật phẩm quý hiếm. Giải Đạo Nhân cam kết tiếp tục đồng hành cho tới khi Hàn Lập vượt qua khảo nghiệm. Sáng hôm sau, Cốc trưởng lão dẫn toàn bộ trưởng lão Hợp Thể thành Thiên Uyên tới hội kiến bí mật với Hàn Lập. Tin Hàn Lập tiến cấp Đại Thừa nhanh chóng lan khắp hai tộc, khiến dân chúng, các thế lực, tán tu và sứ giả ngoại tộc chuẩn bị cho đại lễ sau một năm. Giữa phản ứng sôi nổi ấy, Thánh Đảo vẫn im lặng một cách khác thường."},{"chuong":2199,"tieuDe":"Đại Lễ Bắt Đầu","tomTat":"Tin Hàn Lập tổ chức đại lễ mừng tiến vào Đại Thừa kỳ khiến tu sĩ Nhân tộc và cường giả Yêu tộc từ nhiều nơi đổ về thành Thiên Uyên, có ngày lên tới khoảng mười vạn người. Các hoạt động kết giao, trao đổi tài nguyên và đấu giá diễn ra sôi nổi, trong khi phía thành phải mở thêm tháp đá, công trình dưới lòng đất và điện nghỉ chân để ứng phó tình trạng quá tải. Đến bình minh, Cốc trưởng lão ra lệnh đánh Chấn Thiên Chung đủ tám mươi mốt lượt, chính thức báo hiệu đại lễ bắt đầu. Giáp sĩ lập tức xuất hiện từ những quang trận quanh quảng trường, phong tỏa khu vực trung tâm và để lộ hơn mười truyền tống trận tạm thời đã được chuẩn bị theo kế hoạch của Hàn Lập. Những người chủ trì xác nhận thành Thiên Uyên đã lấy gần một phần ba kho tích trữ, chủ yếu là tài liệu luyện khí thông thường, để phục vụ kế hoạch này. Cùng lúc đó, Hàn Lập hoàn tất bước tế luyện tạm thời Đại Thừa Tiên Thai trong một tòa tháp đá rồi mang bảo vật tới phía trên quảng trường. Ngọn núi ba màu nhanh chóng phóng lớn, tỏa khí tức khủng bố và cuốn thiên địa nguyên khí đang hóa thành những đám mây năm màu hội tụ tới."},{"chuong":2200,"tieuDe":"Vạn Người Bái Lạy","tomTat":"Một ngọn núi ba màu cao tới vạn trượng đột ngột xuất hiện giữa Thành Thiên Uyên, trở thành Đại Thừa Tiên Thai dùng để tổ chức lễ mừng Hàn Lập tiến giai Đại Thừa. Hàn Lập kích hoạt cấm chế quanh cự sơn, hất những người tự ý tiếp cận ra ngoài rồi truyền âm hướng dẫn khách đủ tư cách sử dụng truyền tống trận để lên núi. Các đoàn khách được người hầu áo trắng dẫn theo sơn đạo, trong khi một nhóm rời đường bị cấm chế ảo thuật khống chế và phải nhờ lệnh bài màu bạc giải cứu. Trên quảng trường bạch ngọc ở đỉnh núi, Hàn Lập ngự trên thanh liên cùng Báo Lân thú, tiếp nhận hàng vạn tu sĩ Nhân tộc, Yêu tộc và sứ giả Dị tộc tới hành lễ. Đúng giữa trưa, Khí Linh Tử tuyên bố khai lễ, chuông nhạc cùng dị tượng xuất hiện và Thảo Mộc Chi Tinh lan hương khắp quảng trường. Vạn tu sau đó đồng loạt bái chúc Hàn Lập, còn tiếng chúc mừng được cấm chế khuếch đại và truyền vang khắp Thành Thiên Uyên."},{"chuong":2201,"tieuDe":"Sứ Giả Và Lễ Vật","tomTat":"Sau khi nhận chín lượt chúc mừng, Hàn Lập cho Khí Linh Tử điều động hàng trăm khôi lỗi thiếu nữ áo trắng dâng cực phẩm linh trà tới quan khách. Sứ giả Hoa Thiên Tông mở đầu việc trình lễ bằng đôi xác trùng vạn năm, nguyên liệu chính của An Thần Linh Dịch mà Hàn Lập đang cần sau khi tiến giai Đại Thừa. Các tông môn, thành trì và gia tộc Nhân–Yêu tiếp tục tranh nhau dâng lễ vật quý, trong đó Hàn Lập đặc biệt chú ý tới Hư Thiên Bảo Đỉnh của Hứa gia và công khai mời Hứa Thiên Vũ ở lại thăm núi. Hắn cũng thân thiện trò chuyện với Hiểu Phong tiên tử và Diệp Dĩnh, qua đó gián tiếp tạo sức răn đe bảo hộ Cốc gia và Diệp gia. Tân Đại trưởng lão Lũng gia đích thân cảm tạ Hàn Lập vì đã truyền tin lão tổ vẫn lạc, còn Hắc Phượng tộc cử một trưởng lão Hợp Thể tới thay Đại Nhi đang bế quan. Cuối cùng, Bôn Nguyệt thay mặt Thánh vương Linh tộc dâng hậu lễ và được phép hỏi đúng hai vấn đề. Hàn Lập xác nhận Thiên Thu Thánh nữ đã chết và người khiến nàng vẫn lạc là Thủy tổ Ma tộc."},{"chuong":2202,"tieuDe":"Hắc Kiêu Vương","tomTat":"Hàn Lập xác nhận vấn đề do sứ giả Linh tộc đưa ra có liên quan đến Thủy Tổ Ma tộc, khiến tu sĩ Nhân–Yêu vừa trải qua Ma Kiếp đều kinh sợ. Sau khi sứ giả các tộc lần lượt dâng lễ, Lý Dung bất ngờ tái xuất với tư cách đại diện Thánh Đảo, tặng trọng lễ và mời Hàn Lập tới thương nghị một chuyện quan trọng. Hắc Kiêu Vương của Dạ Xoa tộc đột nhiên xâm nhập qua nhiều tầng cấm chế, công khai đòi đệ tử có linh căn Ẩn Lôi của Hàn Lập để chống thiên kiếp và muốn bắt Lý Dung làm thị thiếp. Hắn còn tuyên bố Mặc Giản Ly và Ngao Khiếu đã không còn tọa trấn trong hai tộc, hiện chưa rõ sinh tử, khiến toàn quảng trường chấn động. Hàn Lập không chấp nhận uy hiếp, xác định đối phương là khách tới quấy rối và mở cấm chế ngọn núi ba màu tấn công. Hắc Kiêu Vương cho rằng việc Hàn Lập ra tay trước giúp hắn không vi phạm lời thề với một người bí ẩn, rồi tung hai quyền phát ra những vòng sóng âm màu đen để phản kích."},{"chuong":2203,"tieuDe":"Dao Mổ Trâu Giết Gà","tomTat":"Hắc Kiêu Vương hóa sóng âm màu đen thành hư ảnh kỳ lân mang theo gió lạnh, nhưng Hàn Lập dùng chim lửa màu bạc phóng cột sáng đỏ xuyên thủng thế công. Hắc Kiêu Vương tiếp đó biến thành cự nhân và thúc giục phiến ngọc xanh tạo quang hà bảy màu, hóa giải pháp bảo của các tu sĩ trên quảng trường và khiến nhiều người chịu phản phệ. Hàn Lập gọi ra Phạm Thánh Kim Thân ba đầu sáu tay để chặn quang hà, rồi biến đài sen xanh thành bảy mươi hai đạo kiếm quang hợp thành cự kiếm. Khi cự kiếm bị bóp vỡ, chùm tơ sáng giấu bên trong bất ngờ cắt lìa bàn tay Hắc Kiêu Vương; Hàn Lập còn dùng sức mạnh thân thể đánh gãy năm móng bạc và phá nát hơn nửa cánh tay đối thủ. Hắc Kiêu Vương vận dụng Bất Diệt Thân Thể để tái tạo toàn bộ chi thể bị hủy, xóa bỏ thương thế vừa chịu. Cuối chương, hắn thi triển Hóa Thiên Vi Địa bằng một sợi tơ đen mang dao động pháp tắc, khiến bầu trời tối như mực còn mặt đất chuyển thành sáng rõ."},{"chuong":2204,"tieuDe":"Trảm Đại Thừa","tomTat":"Cự hán Dạ Xoa vận dụng pháp tắc tạo thành thiên địa hắc bạch, áp chế mấy vạn tu luyện giả trên quảng trường và dùng cự hoàn trói buộc Hàn Lập. Hàn Lập dung hợp Phạm Thánh kim thân, hóa thành tử kim cự viên ba đầu sáu tay cao tám ngàn trượng rồi phá nát cự hoàn cùng toàn bộ không gian hắc bạch. Hắn tiếp tục dùng cự thủ bạc đánh tan ngọc phiến thất sắc và khối gạch đen, sau đó đoán trước vị trí dịch chuyển để phá hủy chiến giáp của đối phương. Cự hán nhận ra không thể chống đỡ nên bỏ chạy, nhưng bị Niệm Kiếm quyết chém ngang hông và phải để nguyên thần cuốn hai đoạn tàn thi đào tẩu. Hàn Lập phái ba ngụy Phệ Kim trùng vương có thực lực Hợp Thể hậu kỳ tiếp tục truy sát đối thủ. Chiến thắng áp đảo khiến tu sĩ Nhân Yêu hai tộc đồng loạt hoan hô, kỳ vọng Hàn Lập có thể dẫn dắt hai tộc đi đến cường thịnh. Các sứ giả dị tộc còn lại sinh lòng kiêng kị và quyết định nhanh chóng báo cáo sự trỗi dậy của Hàn Lập cho cao tầng bản tộc."},{"chuong":2205,"tieuDe":"Tin Tức Của Huyết Hồn","tomTat":"Sau lễ mừng Đại Thừa, Hàn Lập giải trừ hạn chế trên ngọn núi ba màu và công khai giảng giải kinh nghiệm tu luyện suốt bảy ngày đêm cho đông đảo tu sĩ thành Thiên Uyên. Khi buổi giảng kết thúc, Lý Dung cho biết Ngao Khiếu, Mạc Giản Ly cùng nhiều Đại Thừa Linh giới đã tiến vào Ma giới xử lý đại kiếp Minh Trùng Chi Mẫu, đổi lại Ma tộc rút khỏi những lãnh địa đã chiếm. Hàn Lập nhận ra Dạ Xoa tộc từng bí mật giữ Hắc Kiêu Vương ở lại để uy hiếp hai tộc Nhân–Yêu trong lúc lực lượng Đại Thừa vắng mặt. Hắn đồng ý cùng Lý Dung tới Thánh Đảo để thương nghị tranh chấp giữa các tộc, dò tin hai vị Đại Thừa và xem xét kho bí tịch cùng bản thân bảo vật Thánh Đảo. Trước khi đi, hắn giao những môn hạ ở lại cho Cốc trưởng lão cùng các trưởng lão thành Thiên Uyên bảo hộ, đồng thời lệnh Khí Linh Tử và Chu Quả Nhi chuẩn bị lên đường. Hứa Thiên Vũ sau đó báo rằng Huyết Hồn đã trọng thương trở về Hứa gia rồi hôn mê, dù gia tộc dùng hết phương pháp vẫn không thể chữa trị. Theo lời dặn của Huyết Hồn, Hứa Thiên Vũ chuyển Hư Thiên Đỉnh cho Hàn Lập và mời hắn tới Hứa gia, khiến Hàn Lập quyết định sẽ cùng người này lên đường sau vài ngày."},{"chuong":2206,"tieuDe":"Huyết Cổ Trùng","tomTat":"Ba ngày sau khi rời thành Thiên Uyên, Hàn Lập dẫn Ngân Nguyệt, Giải Đạo Nhân, Bạch Quả Nhi và Lý Dung tới nơi cư trú đã được khôi phục của Hứa gia. Gia chủ Hứa Giao thuật lại việc Huyết Hồn trở về trong trạng thái hôn mê, bị khí đen bao phủ và từng dặn phải mang Hư Thiên Đỉnh tới tìm Hàn Lập. Tại cấm địa Hứa gia, Hàn Lập kiểm tra Huyết Hồn đang nằm trong quan tài Huyền Băng vạn năm rồi phát hiện một Huyết Cổ Trùng hòa tan vô hình vô sắc trong máu nàng. Hắn dùng Thần niệm hóa ti kéo cổ trùng khỏi cơ thể, sau đó cắt nó thành vô số mảnh và tiêu diệt hoàn toàn. Hàn Lập tiếp tục truyền linh lực đả thông kinh mạch, cho Huyết Hồn dùng Bổ Nguyên Đan và giao Hứa gia hỗ trợ nàng hấp thu dược lực. Sau một khắc, Huyết Hồn tỉnh lại, tới gặp Hàn Lập và cho biết tình trạng trước mắt đã tạm thời ổn định."},{"chuong":2207,"tieuDe":"Bí Mật Của Linh Đỉnh","tomTat":"Huyết Hồn cho biết Bổ Nguyên Đan chỉ bù được một phần tinh khí và kể lại việc mình bị ám toán bằng Huyết Cổ Trùng tại Huyết Thiên Đại Lục. Ký ức vừa phục hồi giúp nàng xác nhận Băng Phách mất tích tại đó, đồng thời tìm được một số manh mối dù đã kết nhiều đại địch. Sau khi cho người ngoài lui khỏi đại điện, Huyết Hồn tiết lộ Hư Thiên Đỉnh là bảo vật phỏng chế được luyện theo thông tin trên Kim Khuyết Ngọc Thư và công dụng thật của nó là làm chìa khóa. Bí mật tiếp theo khiến Hàn Lập kinh sợ và dẫn tới một giao dịch chưa được công bố giữa hai người. Hàn Lập sau đó rời Hứa gia, chọn Thánh Đảo làm đích đến và để Lý Dung dẫn đường. Hai tháng sau, đoàn tới hòn đảo được bảo vệ nghiêm mật giữa vùng giáp ranh hai tộc Nhân Yêu. Trong lúc các trưởng lão Thánh Đảo bàn về chiến lực Hàn Lập và việc cứu Mặc Giản Ly cùng Ngao Khiếu khỏi Ma giới, Lý Dung báo rằng hắn đã lên đảo nhưng đang cùng Giải Đạo Nhân tới một nơi khác trước."},{"chuong":2208,"tieuDe":"Thiên Thư Các","tomTat":"Hàn Lập cùng Giải Đạo Nhân quan sát Hỗn Độn Vạn Linh Bảng dưới vách vực, nơi hắn nhận thấy hoa văn liên quan đến Huyền Thiên Trảm Linh Kiếm nóng rực và đau âm ỉ. Giải Đạo Nhân phát hiện trên vách tường tinh thể có một tia tiên linh khí rất tinh khiết, khiến Hàn Lập suy đoán Linh giới và Tiên giới vẫn còn liên hệ. Hai người sau đó dùng truyền tống trận tới Thiên Thư Các, nhưng Hàn Lập một mình vào trong để giao dịch. Hắn đưa ra gần một trăm ngọc giản bí thuật dị tộc, trong đó có sáu mươi mốt loại mà Thiên Thư Các chưa từng sưu tầm, rồi đổi lấy số bí thuật tương ứng. Bà lão canh giữ mở cấm chế cầu thang cho hắn lên lựa chọn, đồng thời cảnh báo những nội dung nhận được không được truyền cho người khác. Sau thời gian một bữa cơm, Hàn Lập rời tòa nhà trong khi bà lão bắt đầu nghi ngờ thân phận và cảnh giới thật của hắn. Ngay lúc ấy, ba khối ánh sáng vàng kim bất ngờ bay tới trên đỉnh đầu Hàn Lập."},{"chuong":2209,"tieuDe":"Trở Lại Ma Giới","tomTat":"Hàn Lập thu hồi ba Ngụy Phệ Kim Trùng Vương và biết Hắc Kiêu Vương đã trốn thoát, nhưng gần nửa thân thể bị đàn trùng nuốt mất. Tại Thiên Thư Các, hắn kiểm tra nửa khẩu quyết mới sao chép, ghép nó với phần từng lấy được ở Địa Uyên và hoàn chỉnh Tế Lôi Thuật. Sau khi hội hợp với Giải Đạo Nhân và Ngân Nguyệt, Hàn Lập rời Thánh Đảo, đồng thời yêu cầu nơi này giữ kín việc hắn rời Linh giới trong ít nhất một trăm năm. Vì tu vi Chu Quả Nhi còn thấp, hắn giao nàng cho trưởng lão họ Lạc chăm sóc và dặn nàng nâng cao tu vi để chuẩn bị cho hành trình tìm Tiểu Linh Thiên về sau. Sau hơn nửa tháng, đoàn người tới cứ điểm Ma quân hoang phế trên lãnh địa Yêu tộc, nơi còn sót lại một không gian tiết điểm thông sang Ma giới. Hàn Lập dùng nhãn thuật dò tìm dao động, bố trí pháp trận phá giới và kích hoạt Nghịch Tinh Bàn để mở một đường hầm tối xuyên qua vách ngăn hai giới. Cuối cùng, hắn đưa Giải Đạo Nhân và Ngân Nguyệt tiến vào Ma giới để tìm Mặc Giản Ly cùng Ngao Khiếu, còn Lý Dung, Chu Quả Nhi và trưởng lão họ Lạc ở lại Linh giới."},{"chuong":2210,"tieuDe":"Minh Trùng","tomTat":"Hàn Lập, Giải Đạo Nhân và Ngân Nguyệt xuất hiện phía trên một đầm lầy đen trong Ma giới, sau đó phát hiện khu nhà đá ven đầm đã bị phá cấm chế và hoàn toàn bỏ trống. Trên đường tìm đến tòa thành gần nhất để xác định vị trí, họ gặp hàng trăm Ma tộc và ma thú đang chạy trốn một biển quái trùng hung dữ. Giải Đạo Nhân nhận ra ma khí của đàn trùng không tinh thuần, còn Hàn Lập phán đoán chúng có quan hệ với Minh Trùng Mẫu nhưng chưa kết luận trùng chúa đã thoát phong ấn. Khi đoàn chạy nạn đến gần, một thiếu nữ Ma tộc cảnh báo ba người mau chạy, song Hàn Lập lập tức triển khai ba ngọn núi mang những uy năng khác nhau. Ánh sáng xám, kiếm khí vô hình và hào quang năm màu nhanh chóng tiêu diệt phần lớn biển trùng, đồng thời ngọn núi đen xóa sổ con quái trùng hai đầu đang chỉ huy rút lui. Hàn Lập không truy sát số quái trùng đã phân tán mà thu hồi pháp bảo, sau đó gọi những Ma tộc sống sót đến gần để hỏi chuyện."},{"chuong":2211,"tieuDe":"Thành Hắc Hồ","tomTat":"Sau khi được cứu, một thiếu nữ thuộc nhóm Thải Tinh Khách giao cho Hàn Lập bản đồ khu vực và chỉ đường tới thành Hắc Hồ. Nàng cho biết Minh Trùng đã đồng loạt dị biến trong gần trăm năm, tàn sát nhiều nơi tại Ma giới, trong khi phần lớn Thủy Tổ và Thánh Tổ cũng mất tin tức vào khoảng thời gian ấy. Hàn Lập cùng Ngân Nguyệt quyết định tới thành Hắc Hồ để tìm Tôn giả Ma tộc và điều tra tung tích các cường giả. Trước khi lên đường, Hàn Lập sưu hồn một con Minh Trùng hai đầu nhưng không thu được ký ức vì nó chỉ có ý thức bản năng, sau đó thiêu xác thành tro. Sau một ngày tiến về phía bắc, ba người nhìn thấy thành Hắc Hồ rộng lớn đang bị biển Minh Trùng bao vây. Quân thủ thành dùng cấm chế, ma khí, ma công, mưa tên và hàng trăm tháp phóng điện để chống trả, nhưng quầng sáng phòng hộ đã nhanh chóng suy yếu. Cuối chương, toàn bộ tháp đen đồng loạt ngừng phóng điện, đẩy thành Hắc Hồ tới sát nguy cơ thất thủ."},{"chuong":2212,"tieuDe":"Uy Chấn Hắc Hồ","tomTat":"Cấm chế thành Hắc Hồ nhanh chóng suy yếu sau khi hơn trăm tháp điện quang mất tác dụng, khiến Hàn Lập quyết định ra tay cứu thành. Hắn triệu ba ngọn núi, vận dụng Phạm Thánh Pháp Tướng cùng lửa bạc tàn sát biển minh trùng, trong khi Giải Đạo Nhân hóa thành sét bạc tiêu diệt các cá thể lớn và hàng nghìn quái trùng. Sau khoảng thời gian một bữa cơm, phần lớn đàn trùng bị quét sạch, chỉ còn một số cá thể mạnh chạy thoát. Hàn Lập, Giải Đạo Nhân và Ngân Nguyệt được cư dân thành Hắc Hồ long trọng nghênh đón, nhưng Hàn Lập từ chối tiết lộ danh tính và yêu cầu gặp riêng thành chủ. Hồ Nham cho biết minh trùng đã xuất hiện quanh vùng từ vài năm trước, nhiều lần bị tiêu diệt nhưng vẫn tái xuất, rồi bất ngờ hợp thành biển trùng vây thành từ hai ngày trước. Nhận thấy Hồ Nham do dự khi được hỏi về các Thủy tổ và Thánh tổ mất tích, Hàn Lập trực tiếp nêu khả năng Nguyên Yểm, Lục Cực cùng những cường giả khác đang bí mật đối phó Minh Trùng Mẫu."},{"chuong":2213,"tieuDe":"Thánh Tổ Tà Liên","tomTat":"Hàn Lập hỏi thành chủ Hắc Hồ về kiếp nạn Minh Trùng và được biết ma trùng bình thường đã biến dị vì khí tức thoát ra từ phong ấn Minh Trùng Mẫu. Khu vực thủy ấn, nơi ba vị Thủy Tổ cùng nhiều cường giả từng tập trung củng cố phong ấn, đã mất liên lạc suốt hai mươi năm và hiện bị biển Minh Trùng phong tỏa. Nhận định các Thánh Tổ còn ở bên ngoài có thể nắm giữ tin tức bí mật, Hàn Lập quyết định cùng Ngân Nguyệt và Giải Đạo Nhân tới dãy núi Vạn Hoa tìm Tà Liên. Sau một tháng di chuyển bằng phi xa, ba người đến Triêu Thiên Phong, nơi Hàn Lập dùng thần mục phá Chướng Nhãn Pháp và làm lộ cảnh quan thật cùng cung điện trên đỉnh núi. Tà Liên xuất hiện với dung mạo rất giống Bảo Hoa, nhưng Hàn Lập nhanh chóng nhận ra hai người không phải một. Nàng xác nhận Bảo Hoa là tỷ ruột, suy ra nhóm Hàn Lập đến từ giới khác và chủ động hỏi họ có phải tới vì sự việc của thủy ấn hay không."},{"chuong":2214,"tieuDe":"Bạch Quang Giới","tomTat":"Tà Liên nhận ra nhóm Hàn Lập đến từ Linh giới, đồng thời xác nhận Hàn Lập chính là người từng bị Nguyên Yểm và Lục Cực truy nã nhưng nay đã tiến cấp Đại Thừa. Nàng cũng nhận ra Giải Đạo Nhân ở Ma Nguyên Hải rồi mời cả nhóm vào động phủ tại Vạn Hoa Sơn để bàn kín về Thủy Ấn. Tại đây, Hàn Lập gặp Kim Soa và Thạch Định, hai cường giả Đại Thừa được Bạch Quang giới cử tới Ma giới. Kim Soa tỏ thái độ khinh thường và lộ sát ý với Hàn Lập, nhưng Tà Liên kịp thời ngăn cuộc đối đầu. Trong đại sảnh, Tà Liên hỏi các cường giả ngoại giới muốn hợp lực trấn áp Minh Trùng Mẫu hay chỉ cứu đồng bạn, đồng thời cảnh báo rằng thời gian đã quá cấp bách và mọi lực lượng phải tập trung mới có cơ hội thành công. Nàng còn tiết lộ sau một tháng, các Thánh tổ Ma giới cùng cường giả từ nhiều giới sẽ họp bàn phương án hóa giải đại kiếp. Hàn Lập chưa đưa ra lựa chọn mà yêu cầu Tà Liên công bố rõ tình hình Thủy Ấn trước."},{"chuong":2215,"tieuDe":"Chân Tướng","tomTat":"Hàn Lập nhận ra lời giải thích của phía Thánh Giới còn thiếu điểm mấu chốt nên tiếp tục truy vấn Tà Liên về tình trạng thủy ấn. Tà Liên cho biết Minh Trùng Mẫu đã thoát khỏi một nửa cấm chế, vây ngược lực lượng trấn áp rồi ngủ say vì tiêu hao quá nhiều năng lượng, trong khi Nguyên Yểm chỉ kịp truyền ra một tin tức mơ hồ trước khi mất liên lạc. Sau khi nhận tin, Bảo Hoa tự mình vượt biển côn trùng để điều tra và xác định hơn mười năm sau sẽ xuất hiện thời cơ thích hợp để vừa cứu người vừa tăng hiệu quả trấn áp Minh Trùng Mẫu. Tuy nhiên, biển trùng quanh thủy ấn đã trở nên dày đặc hơn và xuất hiện gần một ngàn Minh Trùng đỏ có khí tức chỉ khoảng Luyện Hư nhưng đủ làm Thánh Tổ bị thương nặng. Loài trùng này có thể thuấn di áp sát, tự bạo xuyên qua các biện pháp phòng ngự và làm ô uế linh hồn, khiến cả phân thân ở xa cũng chịu thương tổn. Vì vậy, phe cứu viện quyết định chờ thêm các cường giả Đại Thừa từ những giới diện khác, đồng thời đợi Bảo Hoa luyện xong hai bảo vật chuyên khắc chế Minh Trùng tự bạo rồi mới tiến vào thủy ấn."},{"chuong":2216,"tieuDe":"Tụ Hội","tomTat":"Tại Triêu Thiên Phong, Tà Liên tiết lộ rằng các giới tiếp giáp Thánh giới, ngoại trừ Hắc Viêm giới, đã phái hơn bốn mươi viện quân lần hai; riêng Thiên Nha giới cử chín Đại Thừa, bao gồm Đồng Nha Lão Nhân. Hàn Lập xác nhận sẽ cùng Giải Đạo Nhân tham gia tụ hội nhưng từ chối ở lại, đưa Ngân Nguyệt và Giải Đạo Nhân tới dãy núi Vạn Hoa lập động phủ tạm. Sau một tháng chờ đợi, hắn nhận được ngọc truyền tin của Tà Liên và dẫn hai người trở lại Triêu Thiên Phong. Các thành viên lần lượt bước vào pháp trận truyền tống trong mật điện, với Kim Soa cùng người đồng hành đi trước và Tà Liên cùng hai nữ đệ tử đi sau cùng. Nửa tháng sau, một tòa thành cổ màu vàng đất trồi lên giữa sa mạc, được hơn một vạn giáp sĩ rối bảo vệ và có cung điện vàng kim ở trung tâm. Nhiều đoàn cường giả dị giới lần lượt tới thành, trong đó có đôi nam nữ đi thú xa do bạch giao kéo và một ông lão đội vương miện được hơn nghìn giáp sĩ, tiên nữ hộ tống. Tất cả đều lặng lẽ tiến vào cung điện vàng kim để chuẩn bị cho cuộc tụ hội."},{"chuong":2217,"tieuDe":"Đồng Nha Lão Nhân","tomTat":"Hàn Lập cùng Tà Liên, Kim Soa và những người đồng hành tới thành đất của Hoàng Sa lão quái, nơi được hơn vạn Thổ Kiền thần vệ bảo vệ. Sau khi nhận ra cung điện vàng có thể ngăn thần niệm, Hàn Lập dẫn Giải Đạo Nhân và Ngân Nguyệt đi qua cấm chế truyền tống để vào phòng khách rộng lớn. Tại đây, hắn dùng một tiếng hừ lạnh chấn nhiếp những tu sĩ Đại Thừa tùy tiện dò xét mình, khiến các cường giả hiện diện phải thay đổi cách nhìn. Hoàng Sa lão quái lộ diện giữa cuộc tụ họp, trong khi các nhóm Đại Thừa từ nhiều giới diện tiếp tục được truyền tống tới. Đồng Nha Lão Nhân dẫn tám Đại Thừa Thiên Nha giới xuất hiện, chỉ bằng ánh mắt đã khiến nhiều người sợ hãi và chủ động tránh chỗ. Bảo Hoa cuối cùng tới cùng Hắc Ngạc trong trạng thái đã khôi phục toàn bộ nguyên khí, đồng thời kinh ngạc khi thấy Hàn Lập đã tiến vào Đại Thừa. Nàng tiếp nhận quyền chủ trì từ Hoàng Sa lão quái và chuẩn bị công bố hành động lớn mà các cường giả đã được triệu tập để tham gia."},{"chuong":2218,"tieuDe":"Lạc Tinh Phiên Và Tiểu Huyễn Thiên Kính","tomTat":"Bảo Hoa công bố đã luyện thành Lạc Tinh Phiên và Tiểu Huyễn Thiên Kính từ những tài liệu quý do các cường giả đóng góp, đồng thời xác nhận chúng là bản mô phỏng của Tinh Nguyệt Kỳ và Huyễn Thiên Kính. Dù chỉ kỳ vọng đạt một phần nhỏ uy lực nguyên bản, nàng cho rằng hai bảo vật đã đủ sức ứng phó minh trùng tự bạo. Theo yêu cầu của Lý Miểu, Bảo Hoa dùng quả cầu thủy tinh đen công khai đoạn tin tức không trọn vẹn do Nguyên Yểm truyền khỏi thủy ấn, qua đó xác nhận đoàn tu sĩ bên trong đang bị vây và cần cứu viện. Cuộc họp sau đó chuyển sang bàn kế hoạch trấn áp Minh Trùng Mẫu, nhưng tu sĩ Thiên Nha giới phản đối việc mặc nhiên xem Bảo Hoa là cường giả đứng đầu và đưa Đồng Nha Lão Nhân ra làm đối trọng. Đồng Nha tuyên bố chỉ quan tâm đến việc cứu người cháu thuộc chi chính, đồng thời dùng thần niệm áp chế Lục Thạch khi bị phản bác. Hàn Lập âm thầm đánh giá thần niệm của Đồng Nha vượt xa Đại Thừa thông thường nhưng vẫn kém mình. Cuối cùng, Bảo Hoa truyền âm một nội dung bí mật khiến Đồng Nha đổi sắc rồi giao cho lão một vật chứng để kiểm tra, mở ra khả năng dung hòa mục tiêu cứu người với kế hoạch chung."},{"chuong":2219,"tieuDe":"Phong Ấn Thượng Cổ","tomTat":"Bảo Hoa đưa ra một chiếc lông chim đỏ thẫm làm tín vật, khiến Đồng Nha Lão Nhân nể mặt vị đại nhân có liên quan và chấp nhận nghe kế hoạch của nàng. Nàng tiết lộ mình từng bí mật thâm nhập vùng biên Thủy Ấn, tại đó phát hiện phần phong ấn thượng cổ chưa bị Minh Trùng Mẫu kiểm soát đang tự khôi phục và có linh tính. Thay vì trực tiếp giao chiến với hung trùng, Bảo Hoa đề nghị kết nối với phong ấn, giúp nó đoạt lại sức mạnh để giải cứu nhóm Nguyên Yểm trước rồi tái áp chế Minh Trùng Mẫu. Sau khi chất vấn khả năng phối hợp với phong ấn và nguy cơ cả đoàn bị giam, các Đại Thừa tiếp tục thương nghị suốt một ngày một đêm rồi thống nhất xuất phát sau hơn mười ngày. Hàn Lập rời thành đất cùng Ngân Nguyệt và Giải Đạo Nhân nhưng nhanh chóng phát hiện Bảo Hoa cùng Hắc Ngạc đang ẩn nấp chặn đường. Bảo Hoa tỏ ra coi trọng thần thông của Hàn Lập sau khi hắn tiến cấp Đại Thừa và nói sự tham gia của hắn làm nàng thêm tin tưởng, còn Hàn Lập cảnh giác truy hỏi mục đích thật sự của nàng."},{"chuong":2220,"tieuDe":"Xuất Phát","tomTat":"Bảo Hoa chặn Hàn Lập tại một cồn cát và dựng cấm chế để bí mật đề nghị hắn cầm chân một đối thủ trong lúc nàng thực hiện kế hoạch riêng. Hàn Lập ban đầu từ chối vì đối phương quá mạnh, nhưng thay đổi quyết định khi Bảo Hoa đưa viên Thần Giao Đan cuối cùng cùng một lời hứa làm thù lao. Hắn nhận lời giữ chân người đó trong một ngày một đêm, đồng thời yêu cầu Bảo Hoa bảo đảm Ma tộc không xâm phạm địa bàn Nhân tộc và Yêu tộc tại Linh giới nếu nàng trở lại lãnh đạo Ma giới. Sau khi hai bên thống nhất điều kiện, Hàn Lập hội lại với Ngân Nguyệt và Giải Đạo Nhân. Mười ngày sau, mấy vạn Ma tộc tinh nhuệ cùng hàng trăm thuyền lớn rời Thổ Thành, còn ba tháng sau lực lượng tập kết đã lên đến mấy trăm vạn người. Bảo Hoa quyết định dùng các nhóm vệ sĩ thu hút biển Minh Trùng, trong khi đội ngũ Đại Thừa được quân tinh nhuệ hộ tống đột nhập thủy ấn từ hướng khác rồi chia nhau hoàn thành nhiệm vụ."},{"chuong":2221,"tieuDe":"Kịch Chiến Trong Biển Trùng (Thượng)","tomTat":"Đại quân Ma tộc chia thành nhiều cánh rời hoang cốc để thu hút phần lớn Minh Trùng quanh Thủy ấn, tạo đường cho lực lượng tinh nhuệ và các lão tổ Đại Thừa tiến vào. Sau bảy ngày, một cánh quân hơn mười vạn người bị biển trùng chặn đứng, khiến ba Ma tôn chỉ huy bất đồng về việc dùng lực lượng dự phòng và bí thuật kích thích tiềm lực để phá vây. Trong khi đó, đội chủ lực của Hàn Lập và Bảo Hoa tiêu diệt hơn mười đàn Minh Trùng cản đường rồi tiến thêm trăm vạn dặm. Một đàn côn trùng xanh biếc bất ngờ phóng cột sáng xuyên thủng phòng ngự, làm hàng nghìn Ma tộc Luyện Hư bốc hơi. Thánh tổ mặc giáp đen cùng các lão tổ Đại Thừa lập tức liên thủ, dùng lưới tơ, cuồng phong, lôi điện, hỏa cầu và kiếm quang quét sạch đàn trùng rồi tiếp tục hành quân. Quan sát trận chiến bằng thần niệm, Hàn Lập nhận ra đám côn trùng này chỉ mạnh về công kích nhưng phòng ngự quá yếu, chưa phải Minh Trùng cao cấp chân chính. Ngân Nguyệt được hắn để lại tại động phủ tạm thời trong sa mạc vì hành trình nguy hiểm, song việc xa cách khiến nàng bắt đầu phải đối mặt với ảnh hưởng của Vong Tình Quyết."},{"chuong":2222,"tieuDe":"Kịch Chiến Trong Biển Trùng (Hạ)","tomTat":"Một đàn Minh Trùng đỏ thẫm mang linh văn vàng dùng khả năng di chuyển tức thời để né công kích, áp sát các tu sĩ Đại Thừa và chuẩn bị tự bạo, nhưng Bảo Hoa kịp đánh văng chúng khỏi mục tiêu. Khi những đợt trùng lớn hơn tiếp tục vây công, nàng dùng Lạc Tinh Phiên tạo biển sao và dải ngân hà để giam giữ chúng, đồng thời điều khiển một chiếc kính hóa thành vầng trăng phóng tia sáng tiêu diệt hơn nửa đàn trùng. Bảo Hoa sau đó đảo ngược dải ngân hà, làm các vì sao phát nổ và tạo lốc xoáy chứa nhiều vết rách không gian, hút sạch số Minh Trùng còn lại nhưng khiến linh tính của Lạc Tinh Phiên tổn hao nghiêm trọng. Đoàn người vượt khỏi biển Minh Trùng sau gần nửa ngày, song đội ngũ tinh nhuệ Ma tộc đã mất hơn nửa quân số và chỉ còn hơn vạn người. Khi đến vùng đồi hoang vắng gần thủy ấn, họ nhận ra đàn trùng truy đuổi không dám tiến vào vì năng lượng phong ấn thượng cổ có thể khắc chế chúng. Đồng Nha Lão Nhân đề nghị để lực lượng khác canh giữ bên ngoài và cho các tu sĩ Đại Thừa tiến sâu vào thủy ấn. Bảo Hoa đồng ý, đồng thời giao Tước đạo hữu và Phong huynh dẫn thuộc hạ ở lại tu bổ những phần cấm chế ven ngoài bị hư hao."},{"chuong":2223,"tieuDe":"Cung Điện Ngầm","tomTat":"Bảo Hoa dẫn đoàn tu sĩ Đại Thừa tiến sâu vào thủy ấn và tìm thấy khe nứt liên tục phun tà khí màu tím của Minh Trùng Mẫu. Nàng giải thích rằng phong ấn thượng cổ cùng quần thể cung điện bên dưới đã bị trùng chúa chiếm một phần quyền điều khiển, khiến đoàn người chỉ có thể xâm nhập khi nguyên khí của phong ấn bùng phát và trở nên bất ổn. Sau cuộc tranh luận với Cổ Đạo Nhân, Bảo Hoa dùng trận bàn xác định đúng thời cơ rồi đưa mọi người xuyên qua khe sâu xuống quảng trường ngọc trắng. Tại đây, nàng chia lực lượng thành các nhóm phụ trách liên hệ linh trí phong ấn, tìm người bị giam, giám sát Minh Trùng Mẫu và tu bổ các mắt trận. Hàn Lập cùng Giải Đạo Nhân, Tà Liên và Lục Thạch nhận nhiệm vụ tu bổ một mắt trận nằm bên kia rừng mộ thượng cổ. Khi đang di chuyển, Hàn Lập phát hiện một dấu hiệu bí ẩn mà Tà Liên và Lục Thạch đều không thể dò thấy, khiến cả nhóm tạm đổi hướng để tới kiểm tra."},{"chuong":2224,"tieuDe":"Trùng Mặt Người","tomTat":"Nhóm Hàn Lập rời con đường lát gạch, vượt qua khu thạch tháp đổ nát rồi phát hiện hơn nửa thi thể cháy đen của một Minh Trùng mang khuôn mặt đàn ông xấu xí. Tà Liên xác định đây là con cháu trực hệ do Minh Trùng Mẫu sinh ra, còn phép thử bằng hỏa diễm của Lục Thạch gần như không thể phá hủy phần xác còn lại. Hàn Lập lần lượt dùng ba đạo kiếm quang kiểm tra, đến đạo cuối dung nhập Thanh Trúc Phong Vân Kiếm mới chém đôi được thi thể. Sau khi đánh giá nguy cơ từ loại Minh Trùng này, cả nhóm cho rằng số lượng của chúng khó có thể quá lớn và quyết định tiếp tục tới mắt trận để không làm chậm việc của Bảo Hoa. Trên đường xuyên qua vườn hoa bạc, Hàn Lập cảm thấy một tồn tại vô hình đang nhìn chằm chằm nhưng thần thức của hắn không thể tìm ra đối phương. Khi nhóm tới gần cung điện xám trắng đặt mắt trận, một bóng người trong hang động sâu bên dưới nhận ra Hàn Lập đã tu luyện Luyện Thần Thuật tới tầng thứ hai. Kẻ bí ẩn lập tức coi sự xuất hiện của hắn là cơ hội chấm dứt nhiều năm đau khổ chống đỡ và bật cười điên cuồng."},{"chuong":2225,"tieuDe":"Tế Lôi Thuật Tái Xuất","tomTat":"Hàn Lập, Giải Đạo Nhân, Tà Liên và Lục Thạch rời khu vườn, đi tới một quảng trường nhỏ đối diện cung điện được xây bằng Minh Hà Sa nên có thể ngăn cách thần niệm. Lục Thạch vận dụng Bách Sinh Vô Vọng Đại Pháp, phát hiện khí tức Minh Trùng ẩn bên trong, còn Hàn Lập dùng Ích Tà Thần Lôi oanh kích để buộc chúng xuất hiện. Năm Nhân Diện Trùng cỡ lớn lao ra, nói tiếng người và tỏ ý muốn ăn máu thịt của nhóm, khiến bốn người lập tức phân chia đối thủ. Tà Liên và Lục Thạch lần lượt dùng vòng tay bạc, biển đao xanh, đao khí hóa giao long và ấn vàng hóa núi để giao chiến với hai con trùng. Giải Đạo Nhân truy theo con đầu đàn màu lam vào không gian, phóng lớn thân hình và dùng cặp đao bạc đánh ngang ngửa với nó. Hàn Lập né đòn của hai con còn lại rồi thi triển Tế Lôi Thuật mới hoàn thiện, tạo cột sét vàng như thác nước và hóa một con thành tro bụi. Con trùng sống sót vừa sợ vừa giận, lập tức phát ra sóng âm tấn công Hàn Lập khi trận chiến vẫn chưa kết thúc."},{"chuong":2226,"tieuDe":"Đánh Chết Hung Trùng","tomTat":"Hàn Lập hóa giải sóng âm và những mũi nhọn màu đen của sâu mặt người, sau đó dùng tơ xanh ngưng tụ thành phi kiếm để chém nát cả thân thể lẫn nguyên thần của nó. Tà Liên dùng ba vòng bạc khóa cứng đối thủ rồi chém nó làm đôi, trong khi Giải Đạo Nhân hợp hai đao thành thương và phóng lôi điện tiêu diệt sâu mặt người màu xanh lam. Lục Thạch lão tổ từ chối trợ giúp, hợp chín ấn ngọc xanh với chiếc ấn vàng thành Kình Thiên Thanh Ấn, dẫn động sức mạnh pháp tắc nghiền nát hung trùng cuối cùng. Đòn đánh khiến khí tức của Lục Thạch suy yếu và làm hắn nhận ra mình là người yếu nhất trong nhóm. Sau khi năm hung trùng bị tiêu diệt, bốn người tiến vào đại cung và phát hiện nhiều đống xương trắng cùng chiến giáp, binh khí hư hỏng. Tà Liên nhận định những vệ sĩ canh giữ nơi đây đã bị Minh Trùng Mẫu ăn thịt sau khi nó phá phong ấn, rồi thiêu toàn bộ hài cốt thành tro."},{"chuong":2227,"tieuDe":"Rừng Đá Trong Lòng Đất","tomTat":"Hàn Lập kiểm tra những mảnh binh khí trong cung điện ngầm và phát hiện dấu bàn tay hằn trên một mảnh kiếm bằng Thái Ất Bạch Kim, từ đó nhận ra kẻ phá hủy nó có sức mạnh thân thể vượt xa đám trùng mặt người. Sau khi loại trừ khả năng Minh Trùng Mẫu đích thân ra tay, nhóm ba người suy đoán nơi đây còn tồn tại một loại hung trùng cực mạnh nhưng số lượng ít. Tại gian phòng trung tâm, Hàn Lập nghiên cứu bản thiết kế gốc rồi cùng Tà Liên tu bổ phần uy lực có thể kích phát ngay của cấm chế, còn Giải Đạo Nhân và Lục Thạch phụ trách canh gác. Khi cả nhóm đang chờ tín hiệu của Bảo Hoa, pháp trận bất ngờ tự vận hành trước thời điểm dự kiến. Biến động làm lộ một khu rừng đá có bố cục trận pháp, tám cột đồng đỏ máu và tế đàn thờ chiếc bát phủ khí đen đang phát ra tiếng cười âm u. Nhận định kế hoạch của Bảo Hoa đã gặp biến cố, Hàn Lập lập tức từ bỏ chờ đợi và dẫn Giải Đạo Nhân đi hội họp với các nhóm khác."},{"chuong":2228,"tieuDe":"Phượng Linh Bảo Bàn","tomTat":"Tà Liên nhận thấy tình hình đã lệch khỏi kế hoạch nên cùng Lục Thạch lão tổ rời chỗ cũ để điều tra nguồn biến cố. Hàn Lập và Giải Đạo Nhân men theo đường hầm đang nứt vỡ, trên đường gặp hai trùng mặt người mai phục và Hàn Lập dùng Huyền Thiên Trảm Linh Kiếm chém chết chúng. Hai người sau đó hội hợp với Bảo Hoa cùng các tu sĩ Đại Thừa tại một động phủ dưới lòng đất, nơi linh hồn phong ấn thượng cổ đang hiện thân trong biển sương mù. Bảo Hoa cho biết lực lượng trấn áp Minh Trùng Mẫu và giam giữ đám người Nguyên Yểm đều đã mất hơn một nửa, khiến Minh Trùng Mẫu sắp thức tỉnh và cung điện ngầm có nguy cơ sụp đổ. Nàng đề xuất để linh hồn phong ấn đưa nhóm mình thẳng tới nơi Minh Trùng Mẫu ngủ say, đánh trọng thương nó trước khi tỉnh hẳn và kéo dài thời gian cho nhóm Đồng Nha cứu người. Bảo Hoa còn tiết lộ đã mượn một Huyền Thiên bảo vật khắc chế Trùng tộc, rồi phân phát Phượng Linh Bảo Bàn có khả năng truyền tống hơn trăm vạn dặm để bảo đảm đường lui. Nhờ bảo vật bảo mệnh này, đại hán mặt đỏ cùng những người còn lại chấp nhận tham gia chuyến tập kích."},{"chuong":2229,"tieuDe":"Thổ Hoàng Đinh","tomTat":"Sau khi nhận vật bảo hộ từ Bảo Hoa, ba tu sĩ Đại Thừa đồng ý cùng nàng đối phó Minh Trùng Mẫu; Hàn Lập cũng tham chiến vì tin vào tu vi hiện tại và Huyền Thiên Trảm Linh Kiếm. Bảo Hoa mở đường xuyên qua sương xám, dẫn cả nhóm vào một truyền tống trận rồi tới vùng biển xanh vô tận nằm trong khe hở không gian do Minh Trùng Mẫu mở ra. Cùng lúc đó, giọng đàn ông trong chiếc bát đen tại đài tế tuy cho rằng nhóm Bảo Hoa đang tự tìm đường chết nhưng vẫn quyết định cứu một đứa nhỏ chưa rõ danh tính, đồng thời kích hoạt dị biến qua xích bạc và đèn cổ. Hàn Lập dùng kiếm quang làm lộ pháp trận đen trên trời cùng Minh Trùng Mẫu trắng như ngọc, lớn như núi và đang ngủ tại trung tâm. Bảo Hoa từ chối mở lối đón hai viện thủ Hắc Dạ giới vì lo việc ra vào sẽ đánh thức trùng chúa, còn Hàn Lập cảnh báo mọi người không được xem nhẹ kẻ từng khiến hai Chân Tiên chỉ có thể phong ấn. Sau khi dàn xếp tranh luận, Bảo Hoa yêu cầu cả nhóm dồn thủ đoạn mạnh nhất vào đòn đánh đầu tiên. Nàng lấy Thổ Hoàng Đinh ra, cho biết bảo vật chứa pháp tắc của cả một giới và có thể phong bế thần thông thuộc tính thổ, qua đó dự tính phế bỏ tám chín phần uy lực của Minh Trùng Mẫu nếu đánh trúng."},{"chuong":2230,"tieuDe":"Một Đòn Phối Hợp","tomTat":"Bảo Hoa hoàn thiện kế hoạch tập kích Minh Trùng Mẫu, dự định dùng Thổ Hoàng Đinh giam hãm mục tiêu để các cường giả đồng loạt tung sát chiêu. Nàng liên hệ linh hồn của tòa phong ấn, tập trung lực áp chế vào con trùng và dùng những ký hiệu màu xám che giấu khí tức của cả nhóm. Các Đại Thừa lần lượt chuẩn bị Vạn Thú Bài, thương ngắn đen, đao xương thú và lôi cầu, trong khi Hàn Lập hợp nhất với pháp tướng ba đầu sáu tay rồi gọi ra Huyền Thiên Trảm Linh Kiếm. Sau khi Thổ Hoàng Đinh xuyên qua cấm chế và ghim trúng Minh Trùng Mẫu, hoa ảnh, đàn thú, thương đen, đao ảnh, lưới sét và tơ kiếm xanh lục đồng loạt đánh xuống. Minh Trùng Mẫu không hề phản ứng trước đợt oanh kích, khiến mọi người nhanh chóng nhận ra tình hình khác thường. Khi hào quang tan hết, thân thể khổng lồ của nó đã biến mất, chỉ còn một viên tinh thạch đen bị Thổ Hoàng Đinh cắm sâu. Bảo Hoa lập tức ra lệnh rút lui, nhưng trận bàn nàng vừa lấy ra đã nổ tung."},{"chuong":2231,"tieuDe":"Bé Gái","tomTat":"Khi Bảo Hoa kích hoạt Phượng Linh Bàn để truyền tống, một bé gái da đen bất ngờ xuất hiện từ dưới mặt nước, phá vỡ vòng sáng năm màu và đánh nàng trọng thương. Những người có mặt nhận ra bé gái chính là Minh Trùng Mẫu, còn con sâu keo vừa bị tiêu diệt chỉ là lớp xác nó đã lột bỏ từ hơn mười vạn năm trước. Minh Trùng Mẫu nhận ra Giải Đạo Nhân là con rối chân tiên và tuyên bố lực không gian của Phượng Linh Bàn không đủ giúp họ trốn thoát. Gã to con mặt đỏ không tin lời cảnh cáo nên kích hoạt bảo bàn, nhưng bị đối phương xuyên thủng thân thể, lấy nguyên anh và dùng pháp tắc thời gian khiến xác thịt lão hóa thành tro trước khi nuốt sạch nguyên anh. Hàn Lập nhận thấy sức mạnh của đối phương có điểm bất hợp lý so với tình trạng vừa tỉnh lại và vẫn chịu phong ấn. Bảo Hoa cho biết bé gái chỉ là hóa thân do nguyên thần Minh Trùng Mẫu xuất khiếu, chỉ Huyền Thiên Chi Bảo mới có thể làm nó bị thương và mỗi lần sử dụng pháp tắc thời gian đều khiến nó suy yếu. Nàng đề nghị cùng Hàn Lập kiềm chế hóa thân để Dư đạo hữu xuống dưới tiêu diệt bản thể."},{"chuong":2232,"tieuDe":"Cuộc Chiến Với Minh Trùng Mẫu Thượng","tomTat":"Hàn Lập lo hai đồng minh sẽ bỏ trốn giữa trận, nhưng Bảo Hoa tiết lộ nàng có thể tạm thời vô hiệu hóa Phượng Linh Bàn, buộc họ phải tiếp tục hợp tác. Hóa thân bé gái của Minh Trùng Mẫu chọn Hàn Lập làm con mồi vì thần niệm của hắn rất mạnh, song chỉ đánh trúng một ảo ảnh và bị Huyền Thiên Trảm Linh Kiếm chém đôi. Dù tiếp tục bị tơ kiếm đánh tan thành khí đen và bụi nhỏ, hóa thân này vẫn liên tục tái sinh nguyên vẹn. Theo sự phân công của Bảo Hoa, lão già và bà lão áo đen xuống nước tấn công thân thể gốc, còn nàng cùng Hàn Lập giữ chân hóa thân nguyên thần. Bảo Hoa triển khai Huyền Thiên Linh Vực thành biển hoa rộng mấy ngàn trượng, dùng các cành hoa hóa thành ký hiệu năm màu xóa bỏ tay đối phương, nhưng Minh Trùng Mẫu vẫn nhanh chóng phục hồi bằng khí đen. Trước sức chống cự ngày càng dữ dội, Hàn Lập thi triển Niết Bàn Thánh Thể đến cực hạn, hiện hình ba đầu sáu tay và cầm Huyền Thiên Trảm Linh Kiếm chém xuống, nhưng kết quả đòn đánh vẫn chưa được xác định."},{"chuong":2233,"tieuDe":"Cuộc Chiến Với Minh Trùng Mẫu Trung","tomTat":"Hàn Lập lần đầu phát huy toàn bộ uy lực của Huyền Thiên Trảm Linh Kiếm kể từ khi tiến cấp Đại Thừa, ngoài dự liệu ngưng tụ Sợi Tơ Pháp Tắc và dùng nó phá tan phòng ngự, chém nát hóa thân bé gái của Minh Trùng Mẫu. Bảo Hoa tiếp tục điều khiển cây hoa trong Huyền Thiên Linh Vực, triệu ra vô số hoa đỏ thiêu sạch mọi phần thân thể còn lại của đối phương, nhưng cây hoa cũng cạn uy lực và khiến linh vực tan biến. Qua lời Bảo Hoa, Hàn Lập biết mình vừa chạm tới năng lực pháp tắc mà nhiều người tế luyện Huyền Thiên Chi Bảo hàng vạn năm vẫn chưa đạt được; đổi lại, nàng đồng ý trao đổi một phần phương pháp thi triển linh vực lấy từ sách cổ không trọn vẹn. Hai người nhanh chóng nhận ra áp lực từ thân thể thật của Minh Trùng Mẫu vẫn không suy giảm, cho thấy đối phương chưa chết và hóa thân vừa bị diệt chỉ là Minh Nhất. Minh Nhị lập tức xuất hiện, tạo bàn tay khổng lồ với năm móng hóa thành đao xanh chụp xuống, còn lão tam dùng tiếng cười quỷ dị gây mê loạn rồi dẫn Sát Lôi màu xám trắng tập kích Hàn Lập. Bảo Hoa hóa lớn Thổ Hoàng Đinh để cầm cự với Minh Nhị, trong khi Hàn Lập nhờ Luyện Thần Thuật tỉnh táo, phân hóa hơn mười ảo ảnh né tránh và dùng điện vàng chống lại các tia Sát Lôi. Cuối cùng hắn dùng một quyền phủ hào quang tím vàng đánh tan một tia sét, nhưng phải hao tổn đáng kể chân nguyên khi cuộc chiến vẫn chưa ngã ngũ."},{"chuong":2234,"tieuDe":"Cuộc Chiến Với Minh Trùng Mẫu Hạ","tomTat":"Hàn Lập nhận ra con sâu trong suốt nhiều mắt là kẻ từng dùng Sát Lôi khiến mình suýt mất mạng, nên giao nó cho Giải Đạo Nhân cầm chân rồi chuyển sang trợ giúp Bảo Hoa. Giải Đạo Nhân biến thành cua vàng khổng lồ, dùng điện cầu mang ký hiệu bạc đối đầu những mũi tên sét xám trắng và nhờ thân thể khôi lỗi mà không bị thần niệm của con sâu ảnh hưởng. Hàn Lập triệu hồi pháp tướng ba đầu sáu tay, phối hợp kiếm quang công kích bàn tay khổng lồ, tạo cơ hội để Bảo Hoa cho nguyên anh xuất khiếu đánh vào kẻ đang ẩn trong đám bụi. Ở vực thẳm dưới đáy biển, lão già áo đen và bà lão áo đen phát hiện một thi thể sâu trắng như ngọc dài tới vạn trượng, nghi là thân thể thật của Minh Trùng Mẫu. Thương ngắn màu đen của bà lão không thể để lại vết xước, còn Vạn Thú Bài và Hoàng Tuyền Uế Diễm cũng bị lực lượng vô hình ngăn cản. Cuối cùng, xác sâu phát ra tiếng cười lạnh rồi chống hai chân trước và từ từ đứng dậy."},{"chuong":2235,"tieuDe":"Hài Cốt Quỷ Ảnh","tomTat":"Dưới vực sâu đáy biển, lão già áo đen điều khiển những viên ngọc màu lam còn bà lão áo đen hóa thành rắn chín đầu, phối hợp công kích và ăn mòn bộ hài cốt khổng lồ. Nguyên thần Minh Trùng Mẫu trong hình dạng bé gái bất ngờ xuất hiện, dùng pháp tắc thời gian uy hiếp khiến bộ hài cốt tỏ vẻ khuất phục và phun ra một viên tinh thạch đen. Khi bé gái đến gần, bộ hài cốt phá tan các đòn công kích, dùng cái miệng ẩn dưới tinh thạch nuốt nó vào cơ thể rồi ngưng tụ lửa đen trong hai hốc mắt. Hai lão giả nhận ra tình thế nguy hiểm và tháo chạy, nhưng pháp tắc thời gian khiến họ tưởng đang bay lên trong khi thực tế lại quay xuống bên cạnh bộ hài cốt. Cả hai chưa kịp phản ứng đã bị cái miệng xương khổng lồ ngoạm xuống. Trên mặt biển, Hàn Lập giật đầu một con côn trùng khổng lồ rồi phát hiện hai chân trước của nó co lại và vết đứt không hề chảy máu, khiến hắn nảy sinh nghi ngờ."},{"chuong":2236,"tieuDe":"Mối Nghi Ngờ","tomTat":"Hàn Lập kiểm tra thi thể quái trùng và nhận thấy nó tan thành ánh sáng một cách bất thường, trong khi Bảo Hoa cùng Giải Đạo Nhân dùng Huyền Thiên Linh Vực áp chế con còn lại để hắn tung kiếm quang kết liễu. Từ việc hai đối thủ có thần thông cực đoan nhưng ít thủ đoạn và thân thể giống như được lực lượng mô phỏng, Hàn Lập cùng Bảo Hoa nghi ngờ có tồn tại từ giới diện khác can thiệp vào chuyện Minh Trùng Mẫu. Phong Ấn Chi Linh đã suy yếu nghiêm trọng nên không thể tiếp tục hỗ trợ, khiến Hàn Lập, Bảo Hoa và Giải Đạo Nhân quyết định tự tiến xuống vực sâu điều tra. Sau khi họ rời đi, trên bầu trời xuất hiện các vòng sáng ngũ sắc ngưng tụ thành hình giống một cặp mắt khổng lồ. Gần hài cốt sâu lớn, ngọc bài vỡ và đoản thương đen nứt nẻ cho thấy hai cường giả Đại Thừa có thể đã gặp nạn. Hai quái trùng vừa bị tiêu diệt tái ngưng tụ thành những hư ảnh suy yếu rồi quỳ lạy một nữ tử áo bạc bước ra từ ma diễm. Nữ tử này tuyên bố đã cắn nuốt nguyên thần Minh Trùng Mẫu, khôi phục gần một nửa nguyên thần của mình và chuẩn bị thu hồi lực lượng từ hai quái trùng."},{"chuong":2237,"tieuDe":"Tranh Đấu Về Linh Vực","tomTat":"Minh Trùng Mẫu thu hồi hai ảo ảnh sâu, luyện hóa rồi nuốt chúng trước khi nhập vào xác sâu giữa biển lửa để tái tạo chân thân ba đầu. Hàn Lập, Bảo Hoa và Giải Đạo Nhân đến vực sâu, nhận ra thân thể thật của đối phương và biết hai đồng bạn Đại Thừa đã bị giết, biến thành một phần thân thể nó. Khi Minh Trùng Mẫu phóng lưới tơ xám, Giải Đạo Nhân hóa thành cua vàng dùng lưới điện ngăn cản, Bảo Hoa tạo cánh hoa bao vây, còn Hàn Lập vận dụng Phạm Thánh Pháp Tướng và Huyền Thiên Trảm Linh Kiếm công kích. Minh Trùng Mẫu dùng pháp tắc thời gian phản nghịch đánh ngược mười hai tia kiếm quang, buộc Hàn Lập phải chém thêm một lượt để triệt tiêu và chịu hao tổn pháp lực lớn. Bảo Hoa nhận ra bản chất của lực phản nghịch nhưng ngụy Linh Vực của nàng bị quầng sáng trắng xám quanh Minh Trùng Mẫu bài xích. Minh Trùng Mẫu cuối cùng bắt đầu triển khai Huyền Thiên Linh Vực chân chính, khiến toàn bộ ánh sáng trong vực sâu trở nên âm u."},{"chuong":2238,"tieuDe":"Ác Chiến","tomTat":"Minh Trùng Mẫu triển khai Huyền Thiên Chi Vực, biến chiến trường thành không gian tối tăm đầy đầu lâu có ma hỏa và áp chế Huyền Thiên Hoa Vực của Bảo Hoa. Bảo Hoa thu nhỏ Hoa Vực để bảo vệ cả nhóm, trong khi Giải Đạo Nhân dùng lôi cầu ngăn mạng lưới khổng lồ tiếp tục hạ xuống. Hàn Lập hóa thành Cự Viên ba đầu sáu tay, tạo các vòng xoáy vàng để hút và nghiền biển đầu lâu, nhưng Minh Trùng Mẫu dùng Thời Gian Pháp Tắc khiến chúng lần lượt tiêu biến. Hàn Lập tiếp tục tạo thêm vòng xoáy nhằm ép đối phương tiêu hao, khiến Minh Trùng Mẫu đổi sang hợp biển đầu lâu thành giáp sĩ xương có khí tức cấp Đại Thừa. Giáp sĩ dùng cốt mâu phá các vòng xoáy rồi chuyển sang tấn công Bảo Hoa, buộc Hàn Lập dùng Huyền Thiên Trảm Linh Kiếm triệt tiêu đòn đánh và chịu hao tổn pháp lực lớn. Khi cốt mâu được tái tạo với khí tức mạnh hơn và mang lực lượng pháp tắc, Bảo Hoa cắm Thổ Hoàng đinh vào cây hoa duy trì Linh Vực, giúp nó phục hồi sinh cơ và lớn thêm để chuẩn bị đón đòn kế tiếp."},{"chuong":2239,"tieuDe":"Thực Lực Của Chi Khu","tomTat":"Dị biến của cây hoa làm Huyền Thiên Hoa Vực tăng mạnh số cánh hoa, trong khi Hàn Lập dùng Huyền Thiên Trảm Linh Kiếm chống lại đòn hợp kích hiến tế của hàng trăm giáp sĩ xương. Kiếm khí xanh triệt tiêu quá nửa số cốt mâu, nhưng phần còn lại vẫn xuyên vào và phá hủy Hoa Vực; Linh Vực của Minh Trùng Mẫu cũng suy kiệt rồi tan biến. Bảo Hoa kích hoạt chiếc Thổ Hoàng Đinh đã bí mật ghim vào chân Minh Trùng Mẫu, khiến thân thể đối phương thu nhỏ và quá nửa pháp lực bị khóa. Tuy nhiên, Minh Trùng Mẫu vẫn đánh bay rồi bắt lấy chiếc đinh thứ hai, làm kế hoạch phát huy trọn vẹn uy năng của cặp song đinh thất bại. Ả tiết lộ mình đã có thể phá phong ấn từ hơn mười vạn năm trước nhưng cố ý ở lại để mượn lực lượng Thượng Cổ Phong Ấn luyện Ngọc Cốt Chân Khu rồi Chân Cực Chi Khu. Sau khi tuyên bố thân thể hiện tại không thể bị ba đối thủ làm tổn thương, ả hút sạch phù văn cùng lực lượng pháp tắc đang chế ngự mình và tự nhổ chiếc Thổ Hoàng Đinh khỏi chân. Thực lực thân thể của Minh Trùng Mẫu khiến Bảo Hoa gần như mất hết lòng tin chiến thắng."},{"chuong":2240,"tieuDe":"Huyền Tiên","tomTat":"Giải Đạo Nhân nhận ra Chân Cực Chi Khu của Minh Trùng Mẫu và giải thích rằng đây gần như là dấu hiệu của Huyền Tiên, một con đường chuyên rèn luyện nhục thân nhưng rất khó tiến lên cảnh giới cao. Khi biết đáy vực đã bị phong tỏa, Phượng Linh Bàn mất tác dụng và bí thuật xé rách hư không cũng không thể mở đường thoát, Hàn Lập quyết định phối hợp với Bảo Hoa đánh cược sinh tử. Theo bố trí của hắn, Giải Đạo Nhân truyền gần như toàn bộ năng lượng cho Bảo Hoa để nàng thi triển pháp thuật hoa thụ dù có nguy cơ tụt xuống dưới Đại Thừa. Bảo Hoa thúc giục lực bổn nguyên của cặp Thổ Hoàng Đinh, khiến chúng hóa thành rắn bảy màu xuyên vào Minh Trùng Mẫu và khóa tinh hạch đen trong cơ thể ả. Pháp lực của Minh Trùng Mẫu bị phong tỏa hoàn toàn, nhưng lực bổn nguyên của cặp bảo vật cũng hao tổn đến mức cần ít nhất mười mấy vạn năm mới có thể khôi phục. Trong cơn thịnh nộ, Minh Trùng Mẫu đe dọa luyện hóa nguyên thần của mọi người thành khôi lỗi rồi phóng một đạo sương mù cực nhanh về phía Giải Đạo Nhân đang suy kiệt."},{"chuong":2241,"tieuDe":"Kiên Cường Chiến Đấu","tomTat":"Hàn Lập hóa thành vượn khổng lồ, chắn trước Giải Đạo Nhân và dùng nắm đấm vàng đánh tan những lưỡi đao khí của Minh Trùng Mẫu. Để quyết chiến bằng thân thể, hắn vận dụng hình thái ba đầu sáu tay, nhiều lớp vảy và linh văn, đồng thời liều lĩnh đốt Chân nguyên hỏa nhằm cưỡng ép tăng mạnh pháp lực cùng sức lực. Minh Trùng Mẫu nhận ra Niết Bàn Thánh Thể và Bách Mạch Luyện Bảo Quyết, từ đó suy đoán truyền thừa của Hàn Lập có liên quan đến Bách Tạo Sơn và Bách Tạo Tông tại Tiên giới. Hàn Lập hợp ba ngọn núi nhỏ thành cây côn đen khổng lồ rồi cận chiến ngang sức với đối phương, khiến vùng biển sâu rung chuyển và hư không liên tục nứt vỡ. Minh Trùng Mẫu sau đó áp sát, đánh lõm chiến giáp, phá lớp núi phòng thủ và dùng hai ngón tay công kích mắt Hàn Lập. Đòn đánh ấy lại đưa nó vào đúng vị trí Hàn Lập dự liệu, khiến linh văn vàng bạc bám sang thân thể và làm nó trở nên nặng trĩu. Chương kết thúc khi vô số sợi xích lớn hiện ra, trói chặt Minh Trùng Mẫu đến mức không thể nhúc nhích."},{"chuong":2242,"tieuDe":"Thần Niệm Liên Và Hình Phạt Chi Lôi","tomTat":"Hàn Lập dùng Luyện Thần Thuật biến hóa Thần Niệm Chi Liên, giữ Minh Trùng Mẫu tại chỗ trong lúc đối phương khôi phục pháp lực và định vận dụng Chân Cực Chi Khu phá vây. Một lôi trụ năm màu bất ngờ giáng xuống; Minh Trùng Mẫu chưa kịp tự bạo tinh hạch đã bị đánh tan thân thể thành tro bụi. Trong thạch lâm Địa Cung, nam tử điều khiển thiên lôi xác nhận mình đã tiêu hao chín phần lực Hồn Niệm để giết kẻ từng ám toán mình, khiến cổ đăng bên cạnh suy yếu gần tắt. Hàn Lập cũng kiệt quệ vì hao tổn chân nguyên và thần thức, còn Giải Đạo Nhân phải hóa thành cua vàng nhỏ rồi vào Linh Thú Hoàn dưỡng thương. Sau khi gọi Bảo Hoa đang ẩn nấp ra, Hàn Lập cùng nàng suy đoán người vừa ra tay có thể là một trong hai Chân Tiên từng phong ấn Trùng Mẫu, trong khi nguyên thần của Trùng Mẫu cũng có thể mang lai lịch Chân Tiên. Nam tử bí ẩn mời hai người tới gặp và báo rằng hư không do Minh Trùng Mẫu tạo ra sắp sụp đổ; ngay sau đó, đáy vực rung chuyển và nước biển bốn phía chấn động dữ dội."},{"chuong":2243,"tieuDe":"Cấm Thuật Của Tiên Giới","tomTat":"Khi vực sâu phong ấn bắt đầu sụp đổ, Hàn Lập thu lấy một hạt châu đen còn Bảo Hoa phát hiện trận bàn của mình đã bị vô hiệu hóa. Một pháp trận ánh sáng xám kịp thời truyền tống hai người đến tế đàn đặt Bát Nguyên Tỏa Hồn Đại Trận, ngay trước khi vực sâu bị phá hủy hoàn toàn. Người đàn ông giao tiếp qua bát đen xác nhận mình là một trong hai Chân Tiên từng xuống hạ giới phong ấn Minh Trùng Mẫu, đồng thời ghi nhận công lao của bộ tộc Bảo Hoa trong việc duy trì phong ấn. Ông ban Kim Dương Mộc cho Bảo Hoa để chữa thương tổn tiềm tàng rồi truyền tống nàng rời đi, giữ Hàn Lập ở lại gặp riêng. Vị Chân Tiên tiết lộ mình từng là sứ giả tuần tra và giám sát tại Tiên giới, nhờ đó phát hiện Hàn Lập đã luyện Luyện Thần Thuật đến tầng thứ hai. Ông giải thích rằng bí thuật tăng cường thần niệm này bị nghiêm cấm vì từng khiến nhiều người mất kiểm soát tâm ma, phát cuồng khát máu và gây ra tai họa suýt hủy diệt gần nửa Tiên giới. Biết mình có thể bị các thế lực cầm quyền truy sát và còn phải đối mặt với nguy cơ nhập ma, Hàn Lập bắt đầu cân nhắc giữa việc ẩn trốn để tiếp tục tu luyện hoặc tự phế bỏ môn thần thông."},{"chuong":2244,"tieuDe":"Chuyện Của Tiên","tomTat":"Chân Tiên bị phong ấn cảnh báo Hàn Lập rằng Luyện Thần Thuật không thể tự phế hoặc ngừng tu, đồng thời tiết lộ công pháp thực có bảy tầng. Nếu Hàn Lập không luyện thành tầng ba trong vòng một vạn năm, thần niệm không ngừng tăng trưởng sẽ làm thức hải nổ tung, ngay cả đoạt xá cũng không thể tránh chết. Chân Tiên kể lại việc mình cùng một nữ đồng hành được Tiên giới phái xuống tiêu diệt Minh Trùng Mẫu, nhưng biến động trời đất khiến họ bị áp lực giới diện áp chế và phải tự bạo thân thể để đánh sâu chúa trọng thương. Vì không thể phá hủy thân thể gần như bất tử của nó, họ nhờ hai tu sĩ cao cấp Ma tộc huy động lực lượng dựng đại phong ấn. Sau khi mất liên hệ với Tiên giới và mắc kẹt quá lâu, nữ Chân Tiên trở mặt, phong ấn nguyên thần đồng bạn vào Hắc Đàn Bát rồi mang dầu Ngọc Thanh Đăng đi tìm Minh Trùng Mẫu, có thể nhằm luyện Chân Cực Khu để cưỡng ép trở về. Chân Tiên hiện đã tự phá được một nửa phong ấn và đề nghị giúp Hàn Lập luyện tầng ba cùng truyền phương pháp chống thiên kiếp phi thăng. Đổi lại, Hàn Lập phải dùng thần niệm sau khi tăng cường để kích hoạt một lá bùa cực hiếm, gửi tin cho bạn cũ của Chân Tiên tại Tiên giới."},{"chuong":2245,"tieuDe":"Trợ Giúp","tomTat":"Người đàn ông trong chiếc bát đề nghị hướng dẫn Hàn Lập tu luyện tầng thứ ba của Luyện Thần Thuật, nhưng Hàn Lập chưa chấp nhận vì lo hậu họa sau khi phi thăng. Đối phương cảnh báo thức hải của hắn sẽ phát sinh bất ổn trong khoảng trăm đến ngàn năm, đồng thời hé lộ Tiên giới vô cùng rộng lớn và các sứ giả tuần tra chủ yếu hoạt động tại những nơi trọng điểm. Để trả công Hàn Lập góp sức giết Minh Trùng Mẫu, người này trao cho hắn một lá bùa chứa Tử Vân Tinh có thể bù đắp tổn thương chân nguyên, sau đó truyền tống hắn rời đài tế và tiếp tục ngủ chờ ngày tái ngộ. Một năm sau tại Ma giới, Hàn Lập thay Bảo Hoa gặp Nguyên Yểm nhằm giữ chân vị thủy tổ này, trong khi Bảo Hoa đến cốc Phỉ Vân đối phó Lục Cực. Nguyên Yểm thừa nhận Hàn Lập đã đủ sức đứng ngang hàng với các thủy tổ và vì mang ơn Bảo Hoa cứu khỏi phong ấn nên quyết định không can thiệp vào kế hoạch phục vị của nàng. Hai người tránh được giao chiến rồi ngồi lại trao đổi tâm đắc tu luyện. Cùng lúc, lão già Đồng Nha đối đầu một thanh niên mặc chiến giáp vàng bạc trên hòn đảo giữa hồ, còn một thung lũng trúc phủ sương trắng phát sinh tiếng nổ và ảo ảnh cánh hoa, báo hiệu các mũi hành động khác đang diễn ra."},{"chuong":2246,"tieuDe":"Quay Lại Quảng Nguyên Trai","tomTat":"Bảo Hoa vạch trần toàn bộ đường lui của Lục Cực: sáu hóa thân đã bị diệt, bản thể bị vây trong Huyền Thiên Linh Vực, viện binh bị cầm chân và hóa thân thứ bảy cũng đang bị Hắc Ngạc truy bắt. Nàng phát động đòn công kích cuối cùng, giết Lục Cực và hoàn thành cuộc báo thù. Trong lúc ấy, Hàn Lập luận đạo với Nguyên Yểm để giữ vị thủy tổ Ma giới này không thể tới cứu viện, rồi rời đi sau khi cảm ứng được kết quả trận chiến. Hắn trở về hội ngộ Ngân Nguyệt, Mạc Giản Ly và Ngao Khiếu trong niềm vui của cả nhóm. Ba tháng sau, Hàn Lập tới hồ Lam Bộc để thực hiện lời hứa giải thoát Tử Linh khỏi ràng buộc với Lục Cực, đưa nàng về Linh giới và tìm cách khôi phục thân thể Nhân tộc. Hắn dùng thần niệm phá thủng nhiều tầng cấm chế, điều khiển thuyền ngọc trắng tiến vào Quảng Nguyên Trai. Dì Chu hoảng hốt báo động, nhưng thiếu nữ áo gai sau khi suy tính đã nhận ra người tới là khách quý."},{"chuong":2247,"tieuDe":"Tâm Tư Của Tử Linh","tomTat":"Hàn Lập đến đại sảnh tầng ba của Quảng Nguyên Trai gặp Lam Dĩnh, nhờ nàng liên hệ Tử Linh và dùng mạng lưới của tổ chức để xác định vị trí bí tàng Khấp Linh từ bốn phần bản đồ. Năm ngày sau, Tử Linh tới gặp riêng Hàn Lập và biết rằng Lục Cực cùng toàn bộ đại hóa thân đã bị tiêu diệt, nhờ đó nàng không còn nguy cơ bị luyện hóa thành hóa thân. Hàn Lập đề nghị dùng những bí thuật đã tìm được để loại bỏ Chân Ma khí, khôi phục thể chất Nhân tộc cho nàng rồi cùng trở về Linh Giới. Khi bàn về phi thăng, hắn tiết lộ cơ duyên đạt được sau chuyến đi Thủy ấn đã nâng mức nắm chắc của mình lên khoảng bốn thành. Tử Linh nhận thấy thể chất hiện tại phù hợp với công pháp Ma giới hơn và quyết định ở lại để không từ bỏ dù chỉ một phần nhỏ cơ hội phi thăng. Dù được cảnh báo rằng tiến vào Đại Thừa sẽ khiến thân thể không thể nghịch chuyển, nàng vẫn giữ nguyên lựa chọn. Hàn Lập tôn trọng quyết định ấy và trao cho nàng những bí thuật tu luyện ma công cùng đan dược mình thu được tại Ma giới."},{"chuong":2248,"tieuDe":"Bước Tiến Hóa Cuối Cùng","tomTat":"Hàn Lập tôn trọng quyết định ở lại Ma giới của Tử Linh và dành một tháng truyền kinh nghiệm tu luyện Ma công cho nàng, trong khi Lam Dĩnh cũng dự thính. Quảng Nguyên Trai tìm ra địa điểm ghi trên bản đồ Khấp Linh, sau đó Hàn Lập cùng Tử Linh du ngoạn quanh hồ Lam Bộc, ôn lại chuyện cũ rồi chia tay mà không nối lại tình cảm năm xưa. Tử Linh giải thích rằng nàng muốn tự mình tiến lên Tiên giới, bởi đó mới là con đường có thể giúp nàng vĩnh viễn ở bên Hàn Lập. Nửa tháng sau, Hàn Lập hội hợp với Ngân Nguyệt và cùng nàng tạm hoãn trở về Linh giới để tìm bảo vật theo tàng bản đồ Ma tộc. Khi hai người tiến vào vùng đất hoang bằng phi thuyền, Ngân Nguyệt tu luyện còn Hàn Lập nghiên cứu tinh hạch còn lại của Minh Trùng Mẫu. Hắn từ bỏ ý định tự hấp thu tinh hoa trong tinh hạch và trao nó cho ba Ngụy Phệ Kim Trùng Vương đang ở bước tiến hóa cuối cùng. Ba linh trùng chia nhau nuốt tinh hạch rồi phát sinh biến đổi, cắn xé lẫn nhau tới trọng thương. Sau khi quan sát hồi lâu, Hàn Lập phóng kim hà thu cả ba linh trùng đang tranh đấu đi."},{"chuong":2249,"tieuDe":"Kẻ Thù Cũ","tomTat":"Hàn Lập thu ba Phệ Kim Trùng vào Linh Thú Hoàn để chúng tiếp tục cắn xé cho tới khi chỉ còn cá thể mạnh nhất, đồng thời dự định bồi dưỡng Báo Lân Thú bằng đan dược. Hắn và Ngân Nguyệt đi thuyền qua cánh đồng băng của Ma giới, quan sát Băng Giác Hùng và tiến gần khu vực có bảo tàng Khấp Linh. Trong số những di vật có thể được cất giữ tại đó, Hàn Lập đặc biệt chú ý đến Ma Linh Thánh Chu, pháp bảo phi hành từng đứng hàng thứ ba ở Ma giới. Sau khi phát hiện một cuộc giao chiến từ xa, Hàn Lập đổi hướng tới một ngọn núi băng và gặp lại Nguyên Sát. Dù đang suy yếu, Nguyên Sát vẫn giết một con giao long trắng bằng cự thủ màu lam và hắc diễm. Nàng nghi Hàn Lập được Bảo Hoa phái tới truy sát, nhưng hắn khẳng định lần hợp tác với Bảo Hoa trước đây chỉ là một cuộc giao dịch. Hàn Lập nhận ra tu vi Nguyên Sát đã rơi từ Đại Thừa xuống Hợp Thể, còn nàng tiết lộ chính mình đã tự làm hao tổn hơn phân nửa tu vi."},{"chuong":2250,"tieuDe":"Bảo Tàng Hiện Ra","tomTat":"Nguyên Sát tiết lộ đã tự hủy hơn nửa tu vi để đổi lấy con đường sống do Bảo Hoa chừa lại, còn Hàn Lập quyết định chỉ buộc nàng tự chặt một tay để kết thúc ân oán năm xưa. Nàng làm theo, phá hủy cánh tay đã chặt rồi rời đi; dù có thể tái tạo tay bằng ma khí, nguyên khí của nàng vẫn bị tổn thương và hy vọng trở lại Đại Thừa gần như không còn. Hàn Lập giải thích với Ngân Nguyệt rằng hắn không muốn phá vỡ quyết định của Bảo Hoa, nhất là khi sau này còn phải tới Ma giới. Hai người tiếp tục đến hồ nước nóng giữa bình nguyên băng, dùng bốn miếng gạch tạo pháp trận năm màu và mở vòng xoáy dẫn vào bảo tàng Khấp Linh. Trong mê cung dưới lòng hồ, họ chống lại tiếng gào khóc mê thần cùng nhiều đợt sói đen do khí đen biến thành. Sau lần tập kích thứ bảy, Hàn Lập nhận ra các cột trụ còn che giấu tác dụng khác và dùng năm ngón tay phủ lửa bạc kéo một vật chưa rõ khỏi hư không."},{"chuong":2251,"tieuDe":"Con Rối Khổng Lồ","tomTat":"Hàn Lập phát hiện những sợi âm khí dơ bẩn có thể âm thầm xâm nhập và tích tụ trong cơ thể, đồng thời cho biết hắn đã dùng thần niệm bảo vệ Ngân Nguyệt. Hai người tiếp tục vượt qua các ảo ảnh yêu thú và đến cánh cổng đỏ khổng lồ được luyện từ Hỏa Nguyên Tinh ở cuối mê cung. Khi cổng mở ra biển lửa dữ dội, Hàn Lập dùng Phệ Linh Chân Hỏa hóa thành chim lửa trắng để tách lửa và mở đường tiến vào. Phệ Linh hỏa điểu bị một lưỡi hái trong suốt chém đôi rồi hợp lại, nhưng sau đó bị quyền kình mang ký hiệu đỏ đánh tan thành vô số đốm lửa bạc. Một con rối Ma tinh khổng lồ có tu vi Hợp Thể hậu kỳ đại thành trồi lên từ dưới vùng tinh thạch đỏ và liên tiếp tấn công bằng kỳ hàn, cột sáng cùng cự chưởng nóng rực. Hàn Lập dùng một tay kẹp chặt lưỡi hái, chuyển dời cột sáng trắng ngà rồi đưa bàn tay trắng như ngọc nghênh đón cự chưởng của con rối."},{"chuong":2252,"tieuDe":"Đại Quân Con Rối","tomTat":"Hàn Lập dùng kiếm quang chém đôi con rối khổng lồ, nhưng nó lập tức hấp thu sức mạnh từ tinh thạch bên dưới để nối lại thân thể. Hắn chuyển sang ngưng tụ bàn tay vàng rực, ép con rối nổ tung hoàn toàn rồi bắt giữ quả cầu vàng đang định chạy trốn khỏi phần xác vỡ. Sau đó, Hàn Lập triệu hồi chim lửa bạc hút sạch biển lửa quanh đài cao, làm lộ vô số hầm sâu chứa gần mười vạn con rối ma tinh có thực lực từ Kết Đan đến Hợp Thể. Nhận ra giá trị của lực lượng này, hắn cùng Ngân Nguyệt dùng nhiều vòng trữ vật thu lấy toàn bộ, trong đó Ngân Nguyệt thi pháp áp chế nhóm con rối Hợp Thể kỳ. Khi con rối cuối cùng biến mất, đài cao chìm xuống hơn trăm trượng và để lộ một cửa đá dẫn vào bảo tàng thật sự của Khấp Linh thánh tổ. Hai người tiến vào đại điện chứa nhiều bảo vật cấp cao, đặc biệt chú ý đến cán thương xanh rỉ sét, hồ lô vàng nhạt và phi chu đen nhánh đặt trên ba bục đá cao nhất."},{"chuong":2253,"tieuDe":"Trở Về","tomTat":"Hàn Lập kiểm tra ba món bảo vật trong điện, trao ngọn thương chứa mảnh Huyền Thiên Thánh Khí cho Ngân Nguyệt, tự cất hồ lô màu vàng rồi kích hoạt chiếc thuyền đen. Ma Linh Thánh Chu hiện nguyên hình thành cự thuyền hơn ngàn trượng, mang theo nhiều cờ bạc và con rối ma tinh trước khi phá khỏi vùng hồ băng. Sau hai tháng, phi chu vận dụng thần thông không gian để đưa Hàn Lập và Ngân Nguyệt xuyên từ Ma giới về một dải núi vô danh tại Linh giới. Nhận thấy nơi này gần địa bàn Nhân tộc, Hàn Lập quyết định đi thẳng tới Thánh Đảo. Tại đó, Ngao Khiếu và Mạc Giản Ly đang lo cho sự an nguy của hắn, đồng thời bàn chuyện kết đôi Hàn Lập với Ngân Nguyệt. Hai người trở về đúng lúc, được các lão tổ vui mừng nghênh đón và trịnh trọng cảm tạ ơn cứu mạng. Khi thuật lại hành trình Ma giới, Hàn Lập giấu sự tồn tại của Chân Tiên trong phong ấn và quy công lao diệt Minh Trùng Mẫu cho Bảo Hoa cùng phong ấn thượng cổ. Cuối cuộc trò chuyện, Mạc Giản Ly có biểu hiện khác thường và khuyên Hàn Lập nghỉ ngơi, tạm thời không nên ra ngoài."},{"chuong":2254,"tieuDe":"Tam Thanh Lôi Tiêu Phù","tomTat":"Mạc Giản Ly tiết lộ đại thiên kiếp tiếp theo của Ngao Khiếu sẽ giáng xuống trong vài năm nữa. Ngao Khiếu đã dùng phương pháp đặc thù trì hoãn thiên kiếp hơn một nghìn năm để chờ Ngân Nguyệt trưởng thành và chuẩn bị đối phó biến động Ma giới, nhưng cái giá là cơ hội vượt kiếp hiện chưa tới nửa thành. Hải Đại Thiếu chưa đủ tu vi để phát huy Ẩn Lôi linh căn, còn ba ngọn cực sơn của Hàn Lập không thể chuyển cho người khác sử dụng, khiến các phương án hỗ trợ trực tiếp đều bế tắc. Mạc Giản Ly sau đó đưa ra manh mối về Tam Thanh Lôi Tiêu Phù, một bí phù có thể tăng thêm một hai phần tỷ lệ vượt lôi kiếp Đại Thừa. Nguồn tin đến từ Thạch Tâm lão tổ, người từng thấy bí phù tại Linh tộc và đạt thỏa thuận giao dịch nhưng đã chết trong phong ấn thượng cổ ở Ma giới. Chủ nhân hiện tại của nhiều lá phù được xác nhận là Linh Vương. Cả Ngao Khiếu lẫn Mạc Giản Ly đều kiêng kỵ vị Linh Vương có diện mạo và khí tức không đổi suốt trăm vạn năm, trong khi thân phận cùng tuổi thọ thật sự của ông vẫn là một bí ẩn."},{"chuong":2255,"tieuDe":"Nhắm Về Linh Tộc","tomTat":"Hàn Lập hỏi Mạc Giản Ly về giao dịch giữa Linh Vương và Thạch Tâm lão tổ, qua đó biết Tam Thanh Lôi Tiêu Phù từng được dùng làm thù lao cho một nhiệm vụ cực kỳ nguy hiểm. Mạc Giản Ly đề nghị Hàn Lập cùng tới Linh tộc, vừa đề phòng Linh Vương vừa tìm cơ hội lấy tiên phù có khả năng hỗ trợ vượt thiên kiếp. Khi biết thiên kiếp của Ngao Khiếu chỉ có thể trì hoãn tối đa mười năm và linh hồn lão còn bị thương bởi bí thuật thần niệm của côn trùng, Hàn Lập quyết định tham gia chuyến đi. Hắn trao Hồi Phần Đan cho Mạc Giản Ly và nhiều đan dược chữa linh hồn cho Ngao Khiếu, rồi thống nhất đợi một năm để Mạc Giản Ly hồi phục trước khi lên đường. Ngao Khiếu cảm kích nhưng cảnh báo họ không được quá mạo hiểm vì Nhân tộc và Yêu tộc hiện chỉ có ba tu sĩ Đại Thừa. Hàn Lập cũng biết địa bàn hai tộc đã dần phục hồi sau Ma kiếp và xuất hiện thêm một số hậu bối có tư chất nổi bật. Tối đó, hắn trở về động phủ tại Thánh Đảo, gặp các đệ tử và bất ngờ nhận thấy điều khác thường ở Bạch Quả Nhi."},{"chuong":2256,"tieuDe":"Cố Nhân Ở Man Hoang","tomTat":"Hàn Lập đánh giá tiến cảnh của các đệ tử và quyết định cho Khí Linh Tử cùng Bạch Quả Nhi tới khu hoang dã rèn luyện, bởi chỉ dựa vào tư chất và đan dược sẽ khó tiến vào Luyện Hư. Hắn trao cho mỗi người một chiếc vòng chứa bảo vật phòng thân, đủ giúp họ giữ mạng vài lần khi gặp đối thủ Hợp Thể Kỳ. Hải Đại Thiếu xin đi cùng nhưng bị giữ lại Thánh Đảo vì tu vi còn thấp và linh căn Ẩn Lôi dễ khiến hắn bị kẻ khác nhòm ngó. Sau khi hẹn Chu Quả Nhi tới phòng vào trưa hôm sau, Hàn Lập hỏi thăm Băng Phượng và lo nàng có thể đang bị giam giữ vì đã quá hạn trở về dù thẻ bài linh hồn vẫn bình an. Tại một vùng mặt nước thuộc đại lục Thiên Nguyên, một thanh niên áo trắng có diện mạo hơi giống Hàn Lập hiện sáu cánh ve, dùng tốc độ, hàn khí và nhiều bóng phân thân giết hơn nửa đàn sư tử lửa cấp Hóa Thần. Thiếu nữ áo bạc đi cùng triệu ra ảo ảnh phượng trắng để dùng khí lạnh hóa giải sóng lửa lan tới. Khi số cổ thú còn lại tháo chạy, thanh niên hợp nhất các bóng người, biến ra hơn mười cánh tay và phóng hàng loạt cột sáng trong suốt truy sát chúng, nhưng kết quả chưa được tiết lộ."},{"chuong":2257,"tieuDe":"Hạo Âm Chi Thạch","tomTat":"Lục Dực đóng băng rồi nuốt máu huyết và linh hồn của một đàn cổ thú để luyện hóa khí chất liệt dương trong chúng. Biết Hàn Lập đã tiến vào Đại Thừa Kỳ, hắn quyết tới đại lục Lôi Minh tìm Tố Âm tộc, dùng Nghịch Linh Đại Pháp hấp thu Tố Âm Tinh Khí và tu thành thân thể chân linh nhằm thoát khỏi uy hiếp của ấn ký chủ tớ. Băng Phượng phản đối kế hoạch giết Hàn Lập nhưng không đủ sức chống lại Lục Dực, còn bị hắn cưỡng ép đồng hành và nhắm làm bạn lữ song tu. Tại Thánh Đảo, Hàn Lập giao Bạch Quả Nhi tìm Hạo Âm Thạch trong khu hoang dã bằng thân thể Băng Tủy và thần thông Hàn Phách. Hắn đã luyện thành Nguyên Từ Cực Sơn, Thái Ất Thanh Quang Sơn và Đại Âm Dương Ngũ Hành Sơn, đồng thời dự định dùng Hạo Âm Thạch luyện ngọn thứ tư. Ngọn cuối cùng là Bắc Cực Nguyên Quang Sơn đã có manh mối tại Nhân giới, nhưng việc gửi thần niệm xuống giới dưới vẫn chứa nhiều nguy hiểm. Hàn Lập tin rằng khi hợp luyện đủ năm ngọn thành Nguyên Hợp Ngũ Cực Sơn, bảo vật sẽ giúp hắn chống các lần thiên kiếp sau và tăng khả năng phi thăng Tiên giới."},{"chuong":2258,"tieuDe":"Trùng Vương Xuất Thế","tomTat":"Trong mật thất được cấm chế bảo vệ trên Thánh Đảo, Hàn Lập hoàn tất phần lớn quá trình tế luyện và mở chiếc hồ lô vàng lấy từ kho tàng Khấp Linh. Hắn phát hiện bên trong là Liệt Sát Kim Cương Sa đã được luyện chế kỹ, đồng thời thử khả năng phân tán và tụ thành quả cầu cực nặng của dị bảo này. Sau khi thu cát trở lại hồ lô, Hàn Lập lấy ra quả trứng đen phủ văn tự tím và truyền chân nguyên giúp sinh vật bên trong phá vỏ. Phệ Kim Trùng Vương xuất thế dưới hình dạng một sinh vật hình người tí hon có làn da nửa vàng nửa tím. Nó lập tức phóng lưỡi sáng xuyên không gian làm cổ Hàn Lập chảy máu rồi dùng mười lưỡi kiếm mang khí lạnh chống lại ký hiệu khống chế. Hàn Lập dùng tiếng hừ làm Trùng Vương choáng váng và rót thần niệm vào dấu ấn tinh huyết, khiến nó thét lớn rồi ngã xuống. Chương kết thúc khi kết quả khống chế Phệ Kim Trùng Vương vẫn chưa được xác nhận."},{"chuong":2259,"tieuDe":"Yêu Tu Hoa Thạch","tomTat":"Phệ Kim Trùng Vương vẫn hôn mê sau khi tiến hóa thành hình dạng đứa bé tím vàng, khiến Hàn Lập quyết định dựng pháp trận và dùng tinh huyết tế luyện lại để củng cố cấm chế khống chế. Một tháng sau, Khí Linh Tử và Bạch Quả Nhi từ biệt rồi cùng lên đường thám hiểm vùng thế giới hoang dã. Hàn Lập cũng đưa Ngân Nguyệt và Chu Quả Nhi rời Thánh Đảo bằng Mặc Linh Thánh Thuyền, tiến vào lãnh địa Yêu tộc. Khi chiến thuyền đi qua vùng biển của Hoa Thạch, cảnh báo trong động phủ làm Yêu tu này phân tâm và phá hỏng mẻ đan dùng nguyên liệu quý, khiến hắn nổi giận lên mặt biển tìm kẻ gây chuyện. Hoa Thạch định rút lui khi nhận ra đối phương quá mạnh, nhưng vẫn bị bốn con rối ma tinh phá bảo vật hộ thân, khóa không gian và bắt lên thuyền. Trước Hàn Lập, hắn phải thừa nhận biết Ti Nam Tứ Phương Đàn, một đài tế thượng cổ luôn di động và khó xác định vị trí. Hàn Lập buộc Hoa Thạch dẫn đoàn đến những nơi đài tế thường xuất hiện, còn Chu Quả Nhi tỏ ra đặc biệt chú ý khi nghe thông tin này."},{"chuong":2260,"tieuDe":"Đài Tế Thượng Cổ","tomTat":"Sau hai tháng tìm kiếm bằng Mặc Linh Thánh Thuyền, Hàn Lập vẫn chưa thấy đài tế thượng cổ cho đến khi Hoa Thạch dẫn đoàn người vào Mật Vân Hung Lâm. Hàn Lập dùng lửa bạc dọn khí độc và độc trùng, còn Ngân Nguyệt giết những yêu thú cản đường, giúp cả đoàn tới đầm nước ở trung tâm khu rừng. Tại đây, Hàn Lập xác nhận đài tế lơ lửng trên mặt nước chính là Ti Nam Cổ Đàn mà Bảo Hoa từng chỉ dẫn. Hắn giải thích cổ đàn có thể đo đạc phương vị không gian, đồng thời mượn thần niệm mang khí tức Tiểu Linh Thiên của Chu Quả Nhi để tìm lối vào giới diện nơi Nam Cung Uyển có thể đang lưu lạc. Hàn Lập truyền lượng lớn pháp lực vào trận pháp, tiêu hao gần một phần tư chân nguyên mới tạo được vòng sáng chứa vô số văn tự và điểm sáng. Sau khi hắn dùng kính cổ cùng những sợi tơ pháp lực điều chỉnh vòng sáng, Chu Quả Nhi đưa thần niệm vào trung tâm, khiến toàn bộ ký hiệu rung chuyển và đổi vị trí cực nhanh. Chương kết thúc khi quá trình định vị vẫn đang tiếp diễn và chưa cho ra kết quả."},{"chuong":2261,"tieuDe":"Đi Linh Tộc","tomTat":"Hàn Lập vận hành Ti Nam Tế Đàn cùng chiếc kính cổ màu xanh và xác định lối vào Tiểu Linh Thiên thuộc Linh giới nhưng không nằm tại đại lục Phong Nguyên. Vì lối vào còn ổn định trong vài trăm năm, hắn tạm hoãn việc truy tìm và quyết định đến Linh tộc trước để xử lý chuyện độ kiếp của ông Ngân Nguyệt. Qua cuộc trao đổi với Ngân Nguyệt, Hàn Lập bày tỏ nghi ngờ về lai lịch Linh Vương và lịch sử phát triển bất thường của Linh tộc. Đoàn trở về Thánh Đảo, nơi Mạc Giản Ly hoàn toàn hồi phục còn Hoa Thạch nhờ đan dược và chỉ điểm của Hàn Lập mà đột phá lên Hợp Thể trung kỳ. Sau đó Hàn Lập, Ngân Nguyệt, Chu Quả Nhi, Mạc Giản Ly và Hoa Thạch lên Mặc Linh Thánh Thuyền, ghé thành Thiên Uyên rồi tiến vào thế giới hoang dã. Khi chiến thuyền gặp biển bão lốc với những cột lốc cao hàng vạn trượng, lực lượng khôi lỗi không thể hóa giải nguy cơ. Hàn Lập và Mạc Giản Ly phải trực tiếp ra tay bằng lôi kiếm cùng hình thái cự viên lông vàng, nhưng kết quả phá bão vẫn chưa được phân định."},{"chuong":2262,"tieuDe":"Cứ Điểm Linh Thiên","tomTat":"Hàn Lập và Mạc Giản Ly liên thủ phá tan thiên uy tại Bạo Phong Hải, đưa Mặc Linh Thánh Thuyền rời khỏi hạp cốc và sau nửa năm tới khu vực Linh tộc. Khi nhìn thấy cứ điểm Linh Thiên, họ quyết định tránh tuyến phòng thủ này để giữ kín hành tung và chuyện liên quan đến Lôi Tiêu Phù. Bối La Đồ tại cứ điểm phát hiện dao động linh áp do Thánh Thuyền để lại, nhưng đội vệ sĩ được Thiên Giám đại nhân phái đi không tìm thấy dấu vết. Đoàn Hàn Lập dùng linh quang hộ thể vượt qua thủy vực chứa nước độc, sương vàng và nhiều Huyền Thừ thú, nhờ đó bí mật tiến vào Linh vực. Hàn Lập tiếp tục thu nhỏ và cải biến ngoại hình Mặc Linh Thánh Thuyền, đồng thời bố trí các con rối ma tinh giả làm người Linh tộc để ứng phó trên đường. Trong lúc đó, hai tu sĩ Đại Thừa Dị tộc tại trung tâm Linh tộc cũng bí mật bàn về Linh Vương và Lôi Tiêu Phù. Chương khép lại tại một cấm địa, nơi năm ngọc bài được điện vàng bao quanh đang lơ lửng trên tầng cao nhất của ngọc tháp trắng."},{"chuong":2263,"tieuDe":"Núi Phục Linh","tomTat":"Hàn Lập điều khiển các con rối Ma Tinh giả làm người Linh tộc, giúp Mặc Linh Thánh Thuyền đi suốt hai tháng qua những tuyến đường vắng và tới thành Thúy Yên mà không bị nghi ngờ. Tại trung tâm Linh tộc, hai vị Đại Thừa biết núi Phục Linh đã bị phong tỏa vì Linh Vương tuyên bố bế quan, dù gần đây ông vẫn giao dịch với tu sĩ Đại Thừa dị tộc. Vì Lôi Tiêu Phù, Hàn Lập và Mạc Giản Ly để Ngân Nguyệt cùng các con rối ở lại trên thuyền rồi tự mình xâm nhập Thánh Địa. Mạc Giản Ly hóa thành chất lỏng trong suốt để độn dưới lòng đất, còn Hàn Lập dùng Thái Nhất Hóa Thanh Phù hóa hư và vượt qua nhiều tầng cấm chế dò xét. Khi tới cổng chào đỏ tía trên sườn núi, Hàn Lập lọt qua mà hai tu sĩ Hợp Thể không nhận ra. Mạc Giản Ly lại bị lệnh bài bảy màu phát hiện, bị ép hiện thân rồi rơi vào đòn phối hợp giữa lưới lửa và phù lục đỏ thẫm. Chương kết thúc khi hỏa liệm đỏ thẫm bất ngờ trói chặt vị Đại Thừa Nhân tộc."},{"chuong":2264,"tieuDe":"Nhầm Lẫn","tomTat":"Mạc Giản Ly bị dây xích lửa khóa chặt trong khi lưỡi đao bảy màu liên tiếp chém đôi các pháp bảo phòng ngự, buộc ông phải phóng nguyên anh đại thành chuẩn bị đón đòn. Hàn Lập kịp thời thuấn di tới và dùng một quyền đánh tan lưỡi đao, giúp Mạc Giản Ly có cơ hội dập lửa rồi phá nát dây xích, khiến người điều khiển chịu phản phệ. Hai thủ vệ tự xưng Linh Dẫn và Linh Chích nhận lỗi, nói rằng họ phụng lệnh Linh Vương và đã ra tay vì không biết thân phận khách đến. Sáu tu sĩ Hợp Thể mang khí tức dị bảo từ trên núi xuống tiếp ứng, nhưng gã trọc đầu khéo léo biến cuộc xung đột thành một vụ hiểu lầm. Lão già tóc trắng dẫn đầu nhóm này tưởng Hàn Lập và Mạc Giản Ly là Huyết Nhiên cùng Hắc Lân của đảo Địa Giao, qua đó tiết lộ Linh Vương đang chờ hai vị khách tại điện Tử Khí. Mạc Giản Ly công khai thân phận và yêu cầu được yết kiến, còn Hàn Lập nhận thấy vụ nhầm lẫn có thể giúp họ tránh bị Linh Vương đóng cửa không tiếp. Khi lão già tóc trắng xin lên bẩm báo vì hai người không nằm trong danh sách khách mời, Mạc Giản Ly lập tức phóng linh áp khủng bố để ép nhóm thủ vệ nhượng bộ."},{"chuong":2265,"tieuDe":"Linh Vương","tomTat":"Mạc Giản Ly phóng áp lực Đại Thừa uy hiếp tám tu sĩ Hợp Thể canh giữ núi Phục Linh, khiến bảo vật hộ thân của họ đồng loạt hiện ra, còn Hàn Lập âm thầm quan sát và ghi nhớ. Linh Vương từ đỉnh núi truyền lời, hóa giải áp lực của Mạc Giản Ly rồi phân phó người đón Huyết Nhiên và đưa hai vị khách lên Tử Khí Đường. Trên đường lên núi, Hàn Lập nhận ra cấm chế cùng sức mạnh huyền diệu có thể đánh lừa thần niệm, khiến quãng đường ngắn trở nên dài khác thường. Tại Tử Khí Đường, Linh Vương ban đầu không muốn giao dịch với người lạ, nhưng đổi ý khi Mạc Giản Ly đưa ra thẻ ngọc bạc của lão tổ Thạch Tâm. Cuộc đối thoại cũng xác nhận Thạch Tâm đã chết trong sự việc có liên quan đến Minh Trùng Mẫu. Linh Vương cho phép Hàn Lập và Mạc Giản Ly tham gia giao dịch, song cho rằng Mạc Giản Ly không đủ năng lực và chỉ Hàn Lập có hai ba phần khả năng thành công. Trước lời đánh giá ấy, Hàn Lập mỉm cười và nhẹ nhàng đáp lại."},{"chuong":2266,"tieuDe":"Huyết Nhiên Và Hắc Lân","tomTat":"Hàn Lập nhận ra Linh Vương chỉ dùng hóa thân Đồng Tâm tiếp khách, trong khi ngay cả Mạc Giản Ly cũng không phát hiện được bằng thần niệm. Huyết Nhiên và Hắc Lân xông vào đại sảnh, bất mãn vì bản thể Linh Vương không đích thân tiếp đón nhưng vẫn nhanh chóng chuyển sang bàn chuyện giao dịch. Linh Vương xác nhận đối tượng giao dịch ban đầu là Thạch Tâm, song sau khi người này qua đời, Hàn Lập và Mạc Giản Ly đã mang tín vật tới để tiếp tục. Huyết Nhiên, Hắc Lân và Mạc Giản Ly đều tuyên bố sẵn sàng dốc tài sản để lấy Tam Thanh Lôi Tiêu Phù. Linh Vương đưa Hàn Lập xem một danh mục tài liệu và bảo vật quý hiếm từ các giới diện khác, nhưng hắn vẫn cho rằng chúng không hấp dẫn bằng Lôi Tiêu Phù. Cuối cùng, Linh Vương từ chối đổi phù lấy bất kỳ bảo vật nào và tiết lộ điều kiện duy nhất là bốn người phải thực hiện một việc liên quan đến sống chết sau này của lão."},{"chuong":2267,"tieuDe":"Tiểu Tu La Giới","tomTat":"Linh Vương nói rõ mình cần Quang Âm Ti để duy trì sinh mệnh và sẵn sàng dùng một tấm Tam Thanh Lôi Tiêu Phù đổi lấy một sợi. Hàn Lập nhớ lại rằng loại bảo vật chứa pháp tắc thời gian này có thể kéo dài thọ nguyên và trì hoãn thiên kiếp, nhưng Quang Âm Hà sinh ra nó gần như không thể tồn tại tại Linh giới. Huyết Nhiên đoán mục tiêu thật sự là Tu La Thù trong Tiểu Tu La Giới, loài sinh vật có thiên phú khống chế thời gian và để lại tinh hạch dùng tinh luyện Quang Âm Ti. Mạc Giản Ly giải thích giới diện này từng xuất hiện trên đại lục Phong Nguyên khoảng hai mươi vạn năm trước, sau đó cửa vào bị phá hủy trong cuộc tranh đoạt giữa các đại tộc. Linh Vương đưa ra Tu La Tâm, vật có thể phối hợp với pháp trận thượng cổ để truyền tống vào giới diện và giúp người mang chống lực bài xích. Hai Tu La Tâm đã được ông cải tạo thành bốn phần, đủ cho Hàn Lập, Mạc Giản Ly, Huyết Nhiên và Hắc Lân cùng tiến vào, nhưng mỗi người chỉ có thể lưu lại khoảng mười ngày. Vì Thạch Tâm, người được lựa chọn ban đầu, đã chết tại Ma giới, Linh Vương chuyển hy vọng sang bốn người trước mặt và đặc biệt coi trọng huyết thống của Huyết Nhiên cùng Hắc Lân. Đến cuối chương, cả bốn vẫn im lặng và chưa quyết định có nhận lời tiến vào Tiểu Tu La Giới hay không."},{"chuong":2268,"tieuDe":"Núi Băng","tomTat":"Mạc Giản Ly và Linh Vương giải thích rằng Tu La Thù trưởng thành gần đạt Đại Thừa, sở hữu thần thông thời gian và thông thường phải dùng ba con mới tinh luyện được một sợi Quang Âm Ti. Huyết Nhiên cho rằng nhiệm vụ quá nguy hiểm so với thù lao ban đầu, buộc Linh Vương phải bổ sung quyền chọn thêm ba bảo vật ngoài Lôi Tiêu phù. Huyết Nhiên, Hắc Lân, Mạc Giản Ly và Hàn Lập sau đó đồng ý tiến vào Tiểu Tu La giới vào sáng hôm sau. Hàn Lập yêu cầu tự điều chỉnh tọa độ truyền tống khi trở về, được Huyết Nhiên hưởng ứng và Linh Vương chấp thuận. Trước khi rời đi, Hàn Lập dò hỏi lời đồn các đời Linh Vương thực chất là cùng một người sống hơn trăm vạn năm, khiến Linh Vương âm thầm nghi ngờ hắn đã phát hiện bí mật liên quan Chân Tiên giới. Khi mọi người đã về nơi nghỉ, Linh Vương truyền tống xuống lòng núi Phục Linh, nơi có một núi băng khổng lồ bị đại phù vàng bao phủ. Dưới đáy núi băng là một thanh niên áo vàng hôn mê, bị bùa chú trói toàn thân và mang hoa văn vàng tương ứng với phong ấn bên ngoài. Linh Vương đặt tay lên vách băng, để ánh sáng trắng từ lòng bàn tay truyền ra."},{"chuong":2269,"tieuDe":"Kim Hàn Tiên Cung","tomTat":"Trong không gian núi băng, Linh Vương đánh thức một người tí hon đồng thể để bàn về kế hoạch luyện hóa chân hồn Kim Tiên thành Tiên Hồn đan. Quang Âm Ti tại Tiểu Tu La giới được hé lộ là mục tiêu thật sự của giao dịch, vì vật này có thể rút ngắn hơn nửa thời gian luyện hóa; Hàn Lập được chọn do thực lực vượt xa Đại Thừa bình thường. Người tí hon giao toàn bộ việc bên ngoài cho Linh Vương rồi tiếp tục chuyên tâm luyện hóa, còn Linh Vương rời đi bằng truyền tống trận. Cảnh truyện sau đó chuyển tới Chân Tiên giới, nơi linh điền mênh mông được khôi lỗi nông phu chăm sóc và đạo đồng điều khiển linh vân tưới nước. Qua cuộc trò chuyện của hai đạo đồng, chế độ khảo nghiệm khắc nghiệt của Kim Hàn Tiên Cung được hé lộ: người không cô đọng được thân thể thật có thể bị đưa xuống Hạ giới. Cách Minh trở về dưới hình thái băng giao lam, hóa lại thành đạo sĩ mặt đen và lập tức xin gặp cung chủ vì có việc quan trọng. Dù đang bế quan, cung chủ vẫn chủ động truyền âm cho Cách Minh vào vì bản thân cũng đang cần tìm ông."},{"chuong":2270,"tieuDe":"Cửu Nguyên Quan","tomTat":"Cách Minh vào Kim Hàn Tiên Cung yết kiến cung chủ áo tím và báo cáo nhiệm vụ truy tìm phản đồ do sư tổ giao. Để tránh sự dò xét của các sứ giả giám sát, cung chủ triển khai linh vực vừa đạt tầng thứ ba Hóa Linh Cảnh, biến xung quanh thành một cung điện hoàn chỉnh với những thị nữ có tu vi và linh trí thấp. Cách Minh cho biết sau nhiều trăm năm điều tra và phải mượn dị bảo, ông đã xác định phản đồ chưa chết mà đang ở một hạ giới, có thể trong tình trạng bị giam giữ. Kẻ này từng mang khỏi Cửu Nguyên Quan một vật có ảnh hưởng cực lớn tới sự hưng suy của môn phái, đồng thời dùng thủ đoạn khiến hồn bài bản mạng không thể phản ánh chính xác sinh tử. Tung tích dẫn tới một tiểu Linh giới chưa xác định thuộc Tiểu Nam Châu Giới, nơi hàng trăm giới diện đã lệch tọa độ và mất liên lạc sau một biến cố khủng khiếp. Vì thiếu tọa độ chuẩn xác, Kim Hàn Tiên Cung không thể dùng Hàng Tiên Đài đưa người xuống, trong khi tu sĩ tại những giới ấy cũng khó phi thăng lên Chân Tiên giới. Cung chủ quyết định thỉnh sư tổ tìm phương pháp tiến vào vùng hạ giới thất lạc, đồng thời nghi ngờ cách phản đồ có thể đến được nơi này."},{"chuong":2271,"tieuDe":"Mã Lương","tomTat":"Tại Kim Hàn Tiên Cung, Cách Minh và cung chủ áo tím bàn về tên phản đồ Cửu Nguyên Quan đang thất lạc tại một hạ giới chưa xác định. Cách Minh tiết lộ Mã Lương vừa mãn hạn diện bích và có thể được chọn xuống hạ giới truy bắt phản đồ, dù người này từng hiến tế máu của hơn một triệu sinh linh để luyện bảo vật. Sau khi Cách Minh rời đi, cung chủ áo tím âm thầm lưu tâm đến Mã Lương và giới diện mất tích. Trên núi Phục Linh, Linh Vương vận hành đại trận đưa Hàn Lập, Mạc Giản Ly, Huyết Nhiên và Hắc Lân tới Tiểu Tu La giới, đồng thời cảnh báo họ phải sử dụng Tu La Tâm trước khi năng lượng cạn sạch. Huyết Nhiên xác nhận thỏa thuận tìm Quang Âm Ti, còn Linh Vương giao tám tu sĩ Hợp Thể Kỳ thay phiên canh giữ pháp trận sau khi đoàn người biến mất. Hàn Lập tỉnh lại một mình trong khu rừng cây thân trắng với cây cỏ héo úa, không thấy ba người đồng hành. Khi ngẩng đầu nhìn lên bầu trời, hắn bất ngờ đổi sắc mặt trước một dị trạng chưa được hé lộ."},{"chuong":2272,"tieuDe":"Bầy Dơi","tomTat":"Hàn Lập phát hiện ba vầng mặt trời xanh cùng hà quang đỏ như máu, sau đó tiêu diệt một dị thú có thi thể tỏa độc dữ dội và dùng lửa bạc thiêu hủy xác. Vì tinh cầu liên lạc không phản ứng, hắn nhận ra mình đã ở quá xa Mạc Giản Ly nên quyết định tạm thời tự tìm cơ duyên, đồng thời dùng thần niệm dò xét sâu dưới lòng đất để tìm Tu La chu. Ở một khu vực khác, Mạc Giản Ly giết đàn quái thú đầu hổ đuôi bọ cạp rồi sử dụng Bàn ti phiên có khí linh Ngân Cương chu, nhưng lần dò tìm đầu tiên không mang lại kết quả. Huyết Nhiên và Hắc Lân lần theo cảm ứng huyết mạch đến một hang động, song chỉ gặp bốn con nhện gai xanh và thu được hai viên đá vàng nhạt trước khi tiếp tục lên đường. Trong lúc dò xét gần một ngọn núi nhỏ, Hàn Lập bị biển dơi đỏ như máu bao vây. Con dơi đầu đàn ba mắt ra lệnh cho cả bầy hợp nhất dao động vô thanh thành một luồng sóng trong suốt khổng lồ đánh thẳng về phía hắn."},{"chuong":2273,"tieuDe":"Quái Ngư","tomTat":"Hàn Lập dẫn động thiên địa nguyên khí, ngưng tụ bàn tay năm màu tiêu diệt đàn dơi và luyện hoa văn còn lại của con đầu đàn thành một tấm da thú dùng cho việc luyện khí phòng ngự. Vì thời gian hạn hẹp, hắn tránh giao chiến với chim ưng bốn cánh một sừng và tiếp tục tìm Tu La Thù. Đến ngày thứ ba, những xác quái thú khô héo cùng sợi tơ có khả năng gây lão hóa giúp hắn xác nhận mình đã tiến vào phạm vi hoạt động của mục tiêu. Sau khi không tìm thấy dấu vết trên mặt đất, hắn dùng thần niệm dò sâu, phát hiện lối vào đường hầm bị lớp đá xanh nhạt dưới hồ che giấu và dùng lôi điện tiêu diệt đàn quái ngư. Hàn Lập lần theo sợi tơ xuống gần vạn trượng, thi triển thủ đoạn ẩn thân rồi vượt qua sóng lửa. Cuối đường hầm, hắn phát hiện hồ dung nham chứa nhiều cực phẩm hỏa linh thạch cùng một nhóm yêu quái nửa người nửa cá bốn tay và một cô gái chưa rõ thân phận."},{"chuong":2274,"tieuDe":"Theo Đuôi","tomTat":"Tại hồ dung nham ở Càn Hỏa Chi Địa, một cô gái Luyện Hư hậu kỳ buộc Không Ngư Nhất Tộc giao hai nữ tộc nhân làm tế phẩm. Nhóm Không Ngư thi triển Dục Hỏa thuật để phản kháng nhưng vẫn bị nàng đánh bại bằng những tia sáng và một cây roi móc câu chuyên khắc chế họ. Cô gái móc và ăn tim hai nữ Không Ngư, hành hạ những người còn lại rồi thu nhỏ hai thi thể để mang đi. Hàn Lập hiện thân sau khi nàng rời khỏi hồ, nhận ra đây là một chi Không Ngư thượng cổ vốn được cho là đã tuyệt tích. Hắn phái Phệ Kim Trùng Vương đã hoàn toàn tiến hóa xuống dung nham giám sát tộc đàn, còn bản thân bám theo cô gái vì nghi nàng có liên quan tới Nhện Tu La trưởng thành và Quang Âm Ti. Trên đường trở về, cô gái giết một con lợn vừa tiến giai Luyện Hư, hái hơn mười quả vàng rồi được bảy tám quái cầm nghênh đón tại một sơn mạch rộng lớn. Khi Hàn Lập ẩn nấp gần rìa sơn mạch, một luồng thần niệm khủng bố từ sâu bên trong quét qua vùng giáp ranh và lướt sát vị trí của hắn."},{"chuong":2275,"tieuDe":"Thần Niệm Chi Chiến","tomTat":"Hàn Lập phát hiện một luồng thần niệm có uy lực vượt xa Đại Thừa thông thường nên dùng Thái Nhất Hóa Thanh Phù hư hóa thân thể và tiếp tục bí mật tiến sâu vào dãy núi. Bám theo tia thần niệm lưu trên người cô gái đi trước, hắn nhận ra nhiều dị thú mạnh đã bị Tu La nhện thu phục và tổ chức thành các đội tuần tra quanh một thạch thành màu xanh mang tên Thiên Chu thành. Thành này được Đại Hóa Bạch Liên Cấm chế bảo vệ, một thủ đoạn độc môn có nguồn gốc từ đại tộc nổi tiếng tại Linh giới. Khi chủ nhân trong thành phát hiện dấu vết thần niệm trên cô gái, một nữ tử giọng khàn dùng pháp tướng nhện đỏ rà quét và công khai mời người ẩn nấp lộ diện. Hàn Lập đáp lại bằng bảy thành thần niệm, nghiền vỡ cấm chế rồi giao chiến với nữ tử. Một nam tử Đại Thừa khác tham chiến theo lời kêu gọi của nàng, nhưng cả hai vẫn bị Hàn Lập dùng chín thành thần niệm áp chế. Đúng lúc Hàn Lập cân nhắc tung toàn lực để trọng thương đối phương, thêm vài luồng thần niệm cấp Đại Thừa từ trong thành bất ngờ lao tới khiến tình thế thay đổi."},{"chuong":2276,"tieuDe":"Bí Ẩn","tomTat":"Hàn Lập cố ý thu hồi thần niệm để dụ hai đối thủ truy đuổi, sau đó ngưng tụ cự nhận trong suốt chém đôi thần niệm của nam tử xa lạ và khiến người này chịu trọng thương. Hắn tránh bàn tay thần niệm của nữ tử giọng khàn, triển khai đôi cánh lôi quang xanh trắng rồi nhanh chóng rời khỏi Thạch thành. Tộc Mẫu họ La và lão già họ Dịch không truy kích ngay vì e ngại sức mạnh, lai lịch cùng khả năng Hàn Lập có đồng bọn. Khi bị thẩm vấn, Bích Châu nhớ lại cảm giác khác thường xuất hiện ngay sau lúc rời Càn Hỏa Trì của Không Ngư Nhất Tộc, khiến hai người lập tức liên hệ vụ việc với một cơ duyên bí mật đã tìm hiểu nhiều năm. Họ chưa xác định Hàn Lập vô tình lọt vào Tiểu Tu La giới, nhắm tới bí mật tại Càn Hỏa Trì hay có ý đồ với chính Tu La nhện. Tộc Mẫu họ La vì thế triệu Triệu Vô Ảnh và Vạn Phong đến đại điện để tiến hành điều tra."},{"chuong":2277,"tieuDe":"Huyền Vũ Chân Huyết","tomTat":"Tộc Mẫu họ La và lão giả họ Dịch triệu Triệu Vô Ảnh cùng Vạn Phong tới, giao nhiệm vụ dò xét toàn bộ ngoại nhân đang có mặt trong Tiểu Tu La Giới. Hai tu sĩ Hợp Thể trung kỳ chia nhau hành động, một người hóa thành cuồng phong, người kia phân tán thành vô số ong vàng. Khi bàn cách kiểm soát Không Ngư Nhất Tộc, hai cường giả Đại Thừa hé lộ rằng tộc này chỉ có thể sống lâu dài tại nơi có Càn Hỏa và sẽ kích phát huyết mạch tự diệt nếu bị cưỡng ép di dời, vì vậy họ chuyển sang tăng cường giám sát Càn Hỏa trì. Ở nơi khác, Hàn Lập xác nhận lần thăm dò sào huyệt Tu La nhện đã đạt mục đích, đồng thời để lại hậu thủ theo dõi đối phương. Nhận thấy thực lực toàn tộc vượt dự liệu, hắn quyết định tìm Mạc Giản Ly và những người còn lại để hội quân thay vì đơn độc mạo hiểm. Hai ngày sau, Hàn Lập phát hiện một cự quy giao chiến với rắn đen hai đầu bên hồ có rong vàng và nhận ra nó mang huyết mạch chân linh Huyền Vũ, có thể giúp Kinh Trập quyết tăng thêm một tầng. Hắn chém chết rắn hai đầu, truy kích cự quy xuống hồ rồi dùng dây xanh trói chặt và kéo nó lên khỏi mặt nước."},{"chuong":2278,"tieuDe":"Xa Khấp Tử","tomTat":"Hàn Lập dùng sợi dây xanh xé nát rùa khổng lồ, thu toàn bộ huyết nhục chứa Huyền Vũ chân huyết vào bát trắng và xác nhận lượng chân huyết sau tinh luyện đủ để tu luyện Kinh Chập quyết. Một pháp khí cảm ứng bất ngờ phát động, khiến hắn đổi hướng tới nơi Mạc Giản Ly đang bị màn sương lam lục truy sát sau một ngày một đêm giao chiến. Mạc Giản Ly dùng cờ trắng và chùy đỏ thẫm chống trả nhưng vẫn tiêu hao gần nửa pháp lực. Truy binh hiện nguyên hình là quái vật đầu cóc thân bọ cạp với đôi cánh mang những gương mặt méo mó, sau đó dùng tiếng kêu áp chế thần niệm và biến cánh thành hai cự nhận. Hàn Lập kịp thời thuấn di tới, dùng Ích Tà thần lôi phá phần lớn lam lục khí trên cự nhận rồi giúp Mạc Giản Ly tỉnh táo. Mạc Giản Ly nhận diện đối phương là Xa Khấp Tử, hung vật thượng cổ của Tu La giới có độc khí đủ giết tu sĩ Đại Thừa trong ba khắc cùng một loại Nhiếp hồn thuật không được điển tịch ghi lại."},{"chuong":2279,"tieuDe":"Hợp Tác","tomTat":"Hàn Lập nhận ra Ích Tà Thần Lôi có thể khắc chế Xa Khấp Tử nên dùng kiếm quang mang điện vàng buộc hung thú hóa thành sương mù xanh và độn thổ bỏ chạy. Hắn không truy sát vì Xa Khấp Tử không có giá trị đủ lớn, còn Mạc Giản Ly kể rằng mình gặp nó sau khi xông nhầm vào hang ổ của một loài nhện khác. Hàn Lập tiết lộ đã tìm thấy hang ổ Tu La Thù, nhưng lực lượng bảo vệ gồm tộc mẫu mạnh ngang chân linh, một Đại Thừa dị tộc tương đương, ít nhất ba Tu La Thù trưởng thành và nhiều quái thú cấp cao. Do thời gian lưu lại giới diện không còn nhiều, Hàn Lập và Mạc Giản Ly tập hợp Huyết Nhiên cùng Hắc Lân để bàn kế hoạch hợp tác. Huyết Nhiên và Hắc Lân nhận đối phó tộc mẫu, Mạc Giản Ly cầm chân ba Tu La Thù trưởng thành, còn Hàn Lập nhận giao chiến với Đại Thừa dị tộc. Bốn người thống nhất ai giết được Tu La Thù sẽ sở hữu tinh hạch, nhưng ngay trước lúc nghỉ ngơi chờ xuất phát, Hắc Lân bất ngờ tuyên bố phải giải quyết một phiền toái nhỏ."},{"chuong":2280,"tieuDe":"Đưa Tin","tomTat":"Hắc Lân phát hiện một bóng người áo vàng đang rình trộm, ép hắn hiện thân rồi bắt giữ, nhưng thân thể ấy lập tức tự bạo. Hàn Lập và Huyết Nhiên nhận ra đây chỉ là một phân thân không có Nguyên Anh, còn Hắc Lân dù lục soát phạm vi vạn dặm vẫn không tìm được bản thể. Lo tin tức đã bị tiết lộ, Hàn Lập thuyết phục cả nhóm bỏ thời gian nghỉ ngơi và đi suốt đêm tới gần sào huyệt Tu La Thù. Bản thể thanh niên áo vàng thực ra đang ẩn trong một đại thụ cách đó khoảng mười vạn dặm và dùng mộc bài báo về việc có hơn bốn Đại Thừa ngoại lai. Tại Thạch Thành, Tộc Mẫu họ La cùng lão già họ Dịch khẩn cấp triệu hồi thuộc hạ, chín Âm Thi và các linh sủng để chuẩn bị ứng chiến. Lão già họ Dịch còn đề nghị thuê Xa Khấp Tử bằng trứng Tu La Thù đã chết và yêu cầu báo tin cho nhân vật thần bí trong Huyết Trì làm hậu thủ."},{"chuong":2281,"tieuDe":"Trước Khi Chiến Đấu","tomTat":"Trước nguy cơ bị đoàn Đại Thừa tìm tới, Tộc Mẫu họ La không cho gọi Anh Nhi xuất quan mà cùng lão già họ Dịch mở các cấm chế, đưa toàn bộ Thạch Thành rời khỏi sơn mạch và ẩn dưới đất cát tại một cao nguyên xa xôi. Tuy nhiên, Hàn Lập đã lưu một hóa thân gần sào huyệt để bám theo hướng di chuyển của thành trì, nhờ đó đoàn truy kích nhanh chóng điều chỉnh lộ trình. Hàn Lập giao cho Mạc Giản Ly mấy cỗ Ma Tinh Khôi Lỗi Hợp Thể kỳ nhằm cầm chân các Tu La Thù trưởng thành, trong khi một thanh niên áo bạc bí ẩn âm thầm theo dõi đoàn người từ sơn mạch. Khi tới cao nguyên đất vàng, Hắc Lân dùng thần niệm phát hiện Thạch Thành đang được che giấu trong một khối đất cát hơn vạn dặm phía trước. Huyết Nhiên, Hắc Lân và Mạc Giản Ly lần lượt bày lư hương, huyết sắc đồng tử, mây đen, trận kỳ và hai linh thú Hợp Thể kỳ để chuẩn bị giao chiến. Cuối cùng, Huyết Nhiên ra lệnh công kích, khiến tám cột sáng huyết hồng từ trên phi thuyền đồng loạt bắn xuống khu vực thành trì."},{"chuong":2282,"tieuDe":"Cuộc Chiến Với Tu La Thù(1)","tomTat":"Các cột huyết quang xuyên xuống sa mạc, sau đó Hắc Lân dùng côn dài màu vàng tím phá vỡ mặt đất, buộc thành đá của Tu La Thù trồi lên khỏi lòng đất. Hắc Lân và Huyết Nhiên yêu cầu đối phương giao tinh thạch chứa lực lượng thời gian, nhưng Tộc Mẫu họ La cự tuyệt và tuyên bố hai phe không chết không thôi. Lực lượng phòng thủ còn lại gồm hơn mười tồn tại Hợp Thể kỳ và bốn Tu La Thù trưởng thành có khí tức gần Đại Thừa, nhiều hơn một con so với lần Hàn Lập thăm dò trước. Huyết Nhiên điều khiển quỷ phong cùng tám ác quỷ tấn công, còn tộc Mẫu dùng kim thuẫn, bạch quang và tóc hóa thành trăn đen để chống trả. Tộc Mẫu tiếp tục thả cự nhện màu xanh ẩn vào hư không và phóng vô số tơ xanh tập kích Huyết Nhiên, buộc hắn dùng roi ngắn triệu hư ảnh núi phòng ngự. Đúng lúc tơ xanh sắp đánh trúng, Hắc Lân tạo màn sáng vàng tím chặn toàn bộ công kích rồi hiện thân bên cạnh Huyết Nhiên."},{"chuong":2283,"tieuDe":"Cuộc Chiến Với Tu La Thù 2","tomTat":"Trong khi Tộc Mẫu họ La giao chiến với Huyết Nhiên cùng một đối thủ khác, bốn Tu La Thù trưởng thành hợp lực tạo hư ảnh Nhện để tới trợ chiến. Mạc Giản Ly chặn đường, liên tiếp dùng Kiếm Sơn, khối gạch hóa Thái Cực Đồ, lực khống chế và phù lục quái thú nhưng hư ảnh Nhện kịp phân tán để tránh đòn quyết định. Bốn Tu La Thù sau đó dùng bản thể vây đánh, buộc Mạc Giản Ly triệu Bạch Hổ và Hỏa Phượng màu đỏ hồng rồi dựa vào nhiều phù lục mới miễn cưỡng cầm cự. Ở chiến trường khác, Hàn Lập dùng linh áp ngăn lão già họ Dịch can thiệp và nhận lão làm đối thủ trực tiếp. Lão già họ Dịch dùng cổ đăng màu xanh triệu Tử Sắc Khổng Tước, dùng gương cổ tạo hơn một ngàn mặt gương phóng hỏa và dùng quyển trục gọi ra mười tám giáp sĩ áo bạc. Hàn Lập nhận ra Tử Sắc Khổng Tước rất giống Mộ Lan Thánh Cầm từng gặp tại Nhân giới, dù thực lực mạnh hơn rất nhiều. Chương kết thúc khi linh cầm, biển lửa từ các mặt gương và mười tám giáp sĩ đồng loạt lao về phía Hàn Lập."},{"chuong":2284,"tieuDe":"Cuộc Chiến Với Tu La Thù 3","tomTat":"Hàn Lập thả Phệ Linh Hỏa Điểu đối đầu Tử Sắc Khổng Tước do linh diễm của lão già họ Dịch biến thành, khiến hai bên cắn xé mà chưa thể phân thắng bại. Lão già dùng hơn ngàn tấm gương vàng tạo lửa, kim mang và lưới tơ, nhưng Hàn Lập điều động bảy mươi hai thanh tiểu kiếm kết thành Kiếm Liên để hóa giải. Ba mũi tên bạc đánh lén bị hắn đẩy ngược giết ba giáp sĩ, còn những giáp sĩ được quyển trục gia trì cũng bị màn sáng xám trói giữ và ép tan trước khi kịp tự bạo. Hàn Lập gọi Pháp Tướng ba đầu sáu tay, hợp sáu quang cầu thành Động Tuyền Kim Quang để nghiền nát lưới tơ vàng và phá hủy ngọc bội Giao Long. Lão già họ Dịch dùng hào quang năm màu quét mất vòng xoáy, khiến Hàn Lập nhận ra Ngũ Sắc Thần Quang và xác định đối phương thuộc Ngũ Quang Tộc trong Phi Linh Tộc. Sau khi xác nhận lai lịch, lão già quyết định không che giấu nữa và hóa thành Ngũ Sắc Khổng Tước để chuẩn bị thi triển thực lực chân chính."},{"chuong":2285,"tieuDe":"Cuộc Chiến Với Tu La Thù 4","tomTat":"Hàn Lập dùng Chân Huyết Thánh Cầm biến thành Ngũ Sắc Khổng Tước để giao đấu với lão già họ Dịch, nhưng đối phương lập tức nhận ra hắn không phải người Ngũ Quang Tộc. Lão già họ Dịch vận dụng Ngũ Sắc Thần Quang và Cố Hóa Thiên Địa, dùng phù văn cùng cự trảo khóa chặt vùng hư không khiến Hàn Lập không thể cử động. Hàn Lập chuyển thành Tử Kim Cự Viên, dùng sức mạnh thân thể đánh tan cột sáng lưu ly, phá nát hai cự trảo và chấn vỡ toàn bộ cấm chế. Lão già họ Dịch liền thu lại thân Khổng Tước, biến thành quái vật đầu chim thân người với năm thanh trường kiếm khác màu sau lưng. Hàn Lập phóng đại thân Cự Viên lên ba bốn trăm trượng rồi ném hai tòa núi xanh và đen về phía đối thủ. Năm thanh kiếm thuấn di ra phía trước, hóa giải sức ép và giữ hai tòa núi bất động giữa hư không, khiến Hàn Lập phải cảnh giác trước thủ đoạn kỳ lạ này."},{"chuong":2286,"tieuDe":"Cuộc Chiến Với Tu La Thù 5","tomTat":"Năm thanh Tinh Kiếm của lão già họ Dịch phát động lực lượng Pháp Tắc, đẩy ngược hai tòa cực sơn và tạm thời cắt liên hệ thần niệm của Hàn Lập với chúng. Hàn Lập dùng hai tay chặn các cực sơn, khôi phục quyền điều khiển qua tiếp xúc trực tiếp rồi nhận ra đối thủ đang mượn ngoại lực vận dụng Thời Gian Pháp Tắc. Không dám xem thường lực lượng thời gian, hắn thúc Phạm Thánh Chân Ma công tới cực hạn và hóa thành Tam Niết của Niết Bàn Thánh Thể ba đầu sáu tay. Lão già họ Dịch hợp năm thanh Tinh Kiếm thành màn sáng năm màu để đình trệ biển quyền ảnh, nhưng phải thu hẹp phòng ngự và tiêu hao tinh huyết khi áp lực ngày càng lớn. Hàn Lập lấy Mộc kiếm màu xanh hấp thu Thiên Địa Nguyên Khí, chém ra lực lượng Pháp Tắc mạnh hơn để xé tan màn sáng và tạo thành vầng sáng bạc hỗn hợp. Hắn tiếp tục vung kiếm bằng sáu tay, tạo vòng kiếm xanh co rút thành lục tuyến và cắt toàn bộ vầng sáng thành hai phần."},{"chuong":2287,"tieuDe":"Cuộc Chiến Với Tu La Thù 6","tomTat":"Nhát chém của Hàn Lập phá vỡ vầng sáng bạc và xé rách hư không, khiến lão già họ Dịch mất nửa thân dưới nhưng vẫn sống nhờ màn sáng năm màu. Hàn Lập tiếp tục thúc giục Huyền Thiên Trảm Linh Kiếm lần thứ ba, phá tan thần thông Thời Gian, làm bốn thanh Tinh Kiếm nổ vỡ và thanh còn lại rơi xuống đất. Lão già họ Dịch tự bạo một cánh tay thành huyết ảnh, dùng bí thuật tương tự Hóa Kiếp Đại Pháp để thoát lên tường thành rồi dùng đan dược và phù lục tái tạo thân thể. Theo lời cầu viện của lão, Tộc Mẫu họ La bóp nát mộc bài đỏ, khiến kẻ bí ẩn trong mật thất dưới thành thức tỉnh và hơn mười huyết sắc viên cầu bắt đầu nứt vỡ. Trong khi Mạc Giản Ly vất vả kiềm chế bốn Tu La Thù trưởng thành, Hàn Lập giải trừ Niết Bàn biến thân và dùng Phạm Thánh Kim Thân tiếp tục truy kích. Hắn đồng thời ném ba ngọn núi và thúc giục ba thanh trường kiếm màu xanh nhạt, nhanh chóng phá gần hết cấm chế phòng hộ Thạch Thành. Khi chỉ còn tầng phòng hộ cuối cùng, Anh Nhi lên tiếng từ trong thành, gọi Tộc Mẫu họ La là mẫu thân và lão già họ Dịch là sư bá."},{"chuong":2288,"tieuDe":"Cuộc Chiến Với Tu La Thù 7","tomTat":"Hơn mười huyết ảnh từ Thạch Thành hóa thành sóng máu, chặn phần lớn kiếm quang và thế công của ba tòa Cực Sơn, nhưng Hàn Lập dùng Ích Tà Thần Lôi phá tan một vùng huyết khí. Huyết vụ sau đó hội tụ thành Anh Nhi, thiếu chủ Thạch Thành, cùng hơn mười quái vật đầu sói thân gấu có khả năng hợp lực sánh với tu sĩ Đại Thừa bình thường. Cuộc đàm phán nhanh chóng thất bại khi Hàn Lập yêu cầu Tu La Thù nhất tộc giao Tinh Thạch, còn tộc mẫu khẳng định đây là cuộc tranh đoạt thần thông Pháp Tắc không thể hòa giải. Anh Nhi dùng thế thân áp sát Hàn Lập rồi thi triển Huyết Linh Thuật làm ô uế một thanh Thanh Trúc Phong Vân Kiếm, nhưng hắn lập tức dùng thần lôi thanh tẩy phi kiếm. Hàn Lập tiếp tục phát động ba tòa Cực Sơn, khiến cấm chế Thạch Thành một lần nữa lung lay sắp đổ. Khi lão già họ Dịch phải ngừng chữa thương để ứng phó, Anh Nhi thi triển Vật Linh Hồi Sóc, dùng lực lượng Thời Gian Pháp Tắc đưa phần thân thể bị tổn hại của ông trở lại nguyên trạng. Sự việc khiến Hàn Lập kinh hãi, còn lão già họ Dịch nhận ra Anh Nhi dường như đã tìm hiểu thành công một vật bí ẩn."},{"chuong":2289,"tieuDe":"Cuộc Chiến Với Tu La Thù 8","tomTat":"Anh Nhi cho biết mình mới lĩnh ngộ phần ngoài của Vật Linh Hồi Sóc và tiếp tục phụ trợ lão già họ Dịch, giúp lão bù đắp một phần nguyên khí rồi gia tăng mạnh khí lực bằng Thị Huyết Thuật. Lão già họ Dịch biến quyển trục bạc thành chiến giáp, dùng gương đồng màu vàng hóa thành đôi cự kiếm để giao đấu với Hàn Lập. Hàn Lập lấy ba tòa Cực Sơn đẩy ngược kiếm khí, sau đó hợp bảy mươi hai tiểu kiếm màu xanh thành cự kiếm và phối hợp kim hồ phá nát cự kiếm vàng. Lão già họ Dịch tiếp tục dùng Tinh Thuẫn, Mộc Thước chứa kỳ độc và Thanh Ấn có lực hút để kiềm chế kim ảnh ba đầu sáu tay, trong khi Anh Nhi điều khiển đầu sói huyết vụ cắn giữ nó. Tuy nhiên, kim ảnh chỉ là Phạm Thánh Kim Thân được Hàn Lập tách khỏi cơ thể và dùng thần niệm điều khiển làm mồi nhử. Bản thể Hàn Lập trong hình thái Sơn Nhạc Cự Viên bí mật vòng ra sau lão già họ Dịch, đánh bay trường mâu tím đen rồi tung quyền thẳng vào một mặt Tinh Thuẫn."},{"chuong":2290,"tieuDe":"Cuộc Chiến Với Tu La Thù 9","tomTat":"Hàn Lập phá vỡ Tinh Thuẫn cùng các lớp phòng hộ, dùng văn trận bạc hủy diệt hoàn toàn nhục thân lão giả họ Dịch. Dư ba của đòn đánh khiến Huyết Nhiên, Hắc Lân và Tộc Mẫu họ La phải tạm lánh, trước khi ba người tiếp tục giao chiến bất phân thắng bại. Nguyên Anh lão giả họ Dịch hiện ra ở xa và liên tiếp dùng tiểu ấn, bí thuật thế thân cùng hình thái Khổng Tước để chạy về Thạch Thành. Hàn Lập đã dự liệu việc này nên điều động Phạm Thánh Kim Thân, hàn niệm và Liệt Sát Kim Cương Sa khóa chặt đường lui. Một thiếu nữ váy đỏ làm nổ bốn con sói thành huyết vụ để hỗ trợ lão giả phá vây, nhưng sáu vũ khí của Phạm Thánh Kim Thân vẫn đánh mất gần nửa thân hình Nguyên Anh của lão. Trong tình trạng gần tiêu vong, lão giả họ Dịch cầu xin Anh Nhi dùng Vật Linh Hồi Sóc tu bổ Nguyên Anh. Nàng chấp thuận và bắt đầu xuất thủ, song kết quả cứu chữa chưa được tiết lộ."},{"chuong":2291,"tieuDe":"Thời Không Chi Lực","tomTat":"Anh Nhi bất ngờ vận dụng Thời Không chi lực để bắt lại Nguyên Anh vừa thuấn di của lão giả họ Dịch, khiến ông nhận ra nàng đã hợp nhất pháp tắc thời gian và không gian. Bất chấp lời cầu cứu cùng cảnh báo về tai kiếp của ông, nàng cho biết đã lấy được phương pháp cần thiết từ đệ tử thân truyền rồi dùng Khiên Hồn Phiên thu Nguyên Anh để Hóa hồn. Tộc mẫu Tu La Thù không thể can ngăn con gái nên trở về Thạch Thành, chấp nhận thương lượng và giao quyền xử lý tình hình cho Anh Nhi. Sau khi nhận truyền âm, Hàn Lập thu Cự Viên biến hóa cùng Phạm Thánh Kim Thân, ngăn Huyết Nhiên và Hắc Lân truy kích vì Anh Nhi đề nghị giao một phần tinh hạch. Hơn mười tu sĩ Hợp Thể của Tu La Thù rời vị trí điều khiển cấm chế và xuất hiện trên tường thành để biểu thị thành ý đàm phán. Anh Nhi một mình bước ra ngoài màn sáng đối diện ba tu sĩ Đại Thừa, tự tin Thời Không pháp tắc đủ giúp mình bảo toàn tính mạng và đào thoát. Hàn Lập xác nhận đây là pháp tắc bậc cao nhất do thời gian và không gian hợp nhất, khiến Huyết Nhiên cùng Hắc Lân vô cùng kinh hãi."},{"chuong":2292,"tieuDe":"Thánh Vật Của Không Ngư Tộc","tomTat":"Nhận thấy Anh Nhi đã lĩnh ngộ Thời Không Pháp Tắc, Hàn Lập cùng Huyết Nhiên và Hắc Lân chấp nhận tạm ngừng giao chiến để nghe đề nghị của nàng. Anh Nhi thuyết phục Tộc mẫu Tu La Thù dùng số tinh hạch dự trữ đổi lấy sự trợ giúp của nhóm Hàn Lập trong việc tìm thánh vật Không Ngư Tộc đang chìm dưới một đầm lạnh. Sau quá trình trả giá, Hàn Lập chốt thỏa thuận mười hai viên tinh hạch, yêu cầu giao trước một nửa và bảo lưu quyền dừng việc nếu gặp nguy hiểm. Khi khổng tước tím không còn được pháp lực của lão giả họ Dịch duy trì và bị chim bạc nuốt, cổ đăng của ông rơi xuống rồi bị Hàn Lập thu lấy. Hai phe lần lượt gọi lực lượng đang ở xa trở về để chuẩn bị cho kế hoạch mới. Mạc Giản Ly xuất hiện trong tình trạng suy yếu, cho biết hai linh sủng của mình đã bị trọng thương và pháp trận tạm thời giam bốn Tu La Thù trưởng thành sắp mất hiệu lực."},{"chuong":2293,"tieuDe":"Hàn Đàm","tomTat":"Bốn Tu La Thù trưởng thành trở về Thạch Thành sau khi thoát khỏi pháp trận dụ địch của Mạc Giản Ly, nhưng đều phải chịu tổn thất. Anh Nhi giao trước sáu khỏa Tinh hạch, sau đó Hàn Lập chia năm khỏa cho Mạc Giản Ly, Huyết Nhiên và Hắc Lân, còn mình giữ một khỏa. Đoàn Tu La Thù cưỡi Cự Ưng dẫn đường, trong khi Hàn Lập dùng Phi Xa chở các đồng hành vượt biển tới một quần đảo từng là chiến trường thượng cổ. Sau khi tránh những cấm chế còn sót lại, cả nhóm hạ xuống một đảo băng và tiến vào sơn cốc có Hàn Đàm. Hai Tu La Thù trưởng thành phối hợp trận bàn tứ phương với trận kỳ Bạch Hổ để giải trừ ảo trận, làm hiện ra pháp trận lớn cùng đài Huyền Băng. Tộc mẫu Tu La Thù tiết lộ rằng pháp trận sử dụng nhiều bảo vật thuần dương để trấn áp luồng hàn khí có thể đóng băng vùng biển quanh quần đảo. Dù vậy, Hàn Lập vẫn yêu cầu phía Tu La Thù mở Hàn Đàm để cả nhóm quan sát kỹ trước khi hành động."},{"chuong":2294,"tieuDe":"Vớt","tomTat":"Theo lệnh của Tộc mẫu Tu La Thù và Anh Nhi, các tộc nhân cải tạo pháp trận quanh đài băng, làm đài băng vỡ vụn và để lộ Hàn Đàm bí mật. Tộc mẫu triệu bốn bảo vật thuần dương khỏi rìa đầm, khiến cột sáng trở nên đậm đặc và hàn khí tăng hơn mười lần; Huyết Nhiên cùng Mạc Giản Ly phải dùng bảo vật hộ thân, còn Hàn Lập dùng lửa bạc hấp thu kỳ hàn. Tộc mẫu và Anh Nhi giải thích rằng pháp trận vớt bảo cần sáu người có lực lượng từ Đại Thừa kỳ trở lên cùng quán chú, trong khi nhóm hiện diện chỉ có năm người đáp ứng điều kiện. Anh Nhi tiết lộ bí thuật dựa trên lực Thời Không có thể tạm nâng tu vi thêm một bậc, khiến Hàn Lập nhận ra căn nguyên của thuật và làm nàng bất ngờ. Anh Nhi, Huyết Nhiên, Hắc Lân, Mạc Giản Ly, Hàn Lập và Tộc mẫu lần lượt đứng trên sáu cột đá, hợp lực ngưng tụ quả cầu phù văn lớn như một tòa lầu các bao phủ Hàn Đàm. Khi pháp trận đạt trạng thái cần thiết, Tộc mẫu phun ra tấm lưới tơ xanh và bắt đầu vớt bảo vật dưới đầm."},{"chuong":2295,"tieuDe":"Bảo Vật Bên Trong Hàn Đàm","tomTat":"Tộc mẫu Tu La Thù điều khiển đám mây năm màu thả năm sợi tơ xuống Hàn Đàm, còn Hàn Lập, Mạc Giản Ly, Huyết Nhiên, Hắc Lân và những người khác liên tục truyền pháp lực vào pháp trận. Do hàn khí quá mạnh và độ sâu vượt quá một nghìn trượng, tốc độ hạ xuống của các sợi tơ gần như đình trệ, buộc Anh Nhi phải thi triển bí thuật tạm tăng khí tức và Tộc Mẫu phải dùng cả bản mạng tinh hạch. Nhờ lực lượng bổ sung, năm sợi tơ chạm đáy, giúp Tộc Mẫu dùng thần niệm xác định vị trí rồi kéo một viên đá màu lam nhạt chứa Không Gian Pháp Tắc lên khỏi vòng xoáy trên mặt đầm. Hắc Lân và Huyết Nhiên đều động lòng trước dị bảo, nhưng Huyết Nhiên từ bỏ ý định hành động sau khi bị Tộc Mẫu cảnh cáo và nhận thấy Hàn Lập cùng Mạc Giản Ly không tranh đoạt. Anh Nhi thu viên đá về cho Tu La Thù tộc rồi giao hộp ngọc chứa số Tinh Hạch còn lại theo đúng thỏa thuận. Hàn Lập kiểm tra số lượng và lấy bốn viên Tinh Hạch ra phân phối cho những người cùng tham gia."},{"chuong":2296,"tieuDe":"Trở Lại","tomTat":"Huyết Nhiên, Hắc Lân và Mạc Giản Ly kiểm tra rồi nhận số Tinh hạch dùng để thanh toán giao dịch, trong khi Tộc mẫu Tu La Thù yêu cầu các Đại Thừa ngoại giới sớm rời Tiểu Tu La giới. Sau khi nghe Mạc Giản Ly kể về Xa Khấp Tử, Huyết Nhiên trả thù lao để lấy ngọc giản ghi vị trí sào huyệt của hung thú. Theo đề nghị của Anh Nhi, Tu La Thù và nhóm Hàn Lập mở thêm một hội giao dịch tài nguyên đặc hữu, giúp cả hai phía đều thu hoạch đáng kể. Khi đoàn Tu La Thù rời đi, Huyết Nhiên đề nghị tập kích họ để cướp hòn đá chứa Không Gian Pháp Tắc, nhưng Hàn Lập từ chối nên hắn và Hắc Lân đành rời khỏi đảo. Mạc Giản Ly cũng quyết định dừng thám hiểm sau khi có ba Tinh hạch, tìm nơi ẩn náu chờ ngày trở về Linh Giới. Đợi mọi người đi xa, Hàn Lập bí mật quay lại Cự đảo và tiếp cận Hàn Đàm đã bị huyền băng đóng kín. Hắn triệu Phệ Linh Chân Hỏa thành Hỏa Điểu màu bạc khổng lồ rồi truyền nhiều đoàn tinh khí màu xanh nhạt vào cơ thể đang suy yếu của nó."},{"chuong":2297,"tieuDe":"Kiện Thánh Vật Thứ Hai","tomTat":"Hàn Lập thúc giục Phệ Linh Hỏa Điểu hòa tan huyền băng rồi hút sạch hàn khí trong Hàn Đàm, khiến chân hỏa bước đầu sinh ra dị biến gần như thực thể. Trước khi được thu hồi, hỏa điểu mang lên một tinh cầu cực lạnh mà thần niệm thông thường không thể thăm dò. Hàn Lập dùng thần niệm tinh hóa và kim hồ phá lớp vỏ, phát hiện Sơn Hải Châu chứa lực không gian mãnh liệt rồi phong kín nó trong hộp ngọc. Hắn nhận định Hàn Đàm từng chứa hai thánh vật Không Ngư Tộc và món nhỏ vừa tìm thấy có thể còn quan trọng hơn khối đá đã bị lấy đi. Trên đường trở về Thạch thành, Anh Nhi nói với Tộc mẫu Tu La Thù rằng tinh hạch Không Ngư Tộc đã thoái hóa và tiết lộ kế hoạch đào sâu Thời Không Pháp Tắc để truyền một tia mầm mống cho mẹ. Tu La Thù tộc vì thế dự định không tiếp tục săn Không Ngư Tộc và tránh xung đột với người ngoại lai. Cuối chương, Hàn Lập tới Càn Hỏa Địa, hiện thân dưới hồ dung nham rồi nhíu mày khi quan sát xung quanh."},{"chuong":2298,"tieuDe":"Không Ngư Tộc Trưởng","tomTat":"Hàn Lập trở lại hồ dung nham và phát hiện Kim Đồng đã tiêu diệt toàn bộ quái thú xâm nhập, khiến hắn nghi Tu La Thù đứng sau việc này. Sau khi thiêu sạch tàn thi, hắn mở phong ấn lam tinh châu và dùng dao động pháp tắc của nó dẫn người thuộc Không Ngư Tộc ra khỏi hồ. Không thể nhìn thấu tu vi của Hàn Lập, thủ lĩnh Không Ngư Tộc chấp nhận dẫn hắn đi gặp Tộc trưởng nhưng vẫn kín đáo phái người báo tin trước. Hàn Lập thi triển Tị Hỏa Thuật mở đường xuyên qua dung nham rồi tiến vào không gian bí mật có dân số chỉ khoảng năm sáu trăm người, phần lớn là người già, phụ nữ và trẻ em. Tại Thiên Vực Sảnh, hắn gặp Tộc trưởng Lưu Thước và xác nhận mình là tu sĩ Đại Thừa đến từ ngoại giới. Lưu Thước lập tức quỳ cầu Hàn Lập giải cứu Không Ngư Tộc khỏi Tu La Thù, đồng thời nguyện để toàn tộc cùng hậu duệ đời sau phụng hắn làm chủ."},{"chuong":2299,"tieuDe":"Sơn Hải Châu","tomTat":"Lưu Thước thay mặt Không Ngư Tộc xin phụng Hàn Lập làm chủ và đề nghị dùng sở trường Không Gian của toàn tộc để đổi lấy sự che chở. Khi Hàn Lập lấy viên châu màu lam ra, thánh ngấn trên người Lưu Thước cộng hưởng, giúp lão xác nhận đó là Sơn Hải Châu, thánh vật đã thất lạc của tộc. Lưu Thước tiết lộ bảo vật này là một Động Thiên Chi Bảo cực hiếm, có không gian đủ rộng để chứa sinh linh, núi lớn và biển rộng, nhưng vẫn mang phong ấn cùng ấn ký do tổ tiên Không Ngư Tộc lưu lại. Muốn luyện hóa nó, Hàn Lập cần tinh huyết toàn tộc, pháp quyết tế luyện đặc biệt và tu vi Đại Thừa để chống lại lực cắn trả. Sau khi Lưu Thước đề nghị để toàn bộ tộc nhân trốn vào động thiên của Sơn Hải Châu rồi cùng rời khỏi giới diện, Hàn Lập chấp thuận giao ước che chở nếu việc luyện hóa thành công. Không Ngư Tộc lập tức dựng pháp trận ngân quang, hiến tinh huyết vào cự đỉnh chứa Sơn Hải Châu và bắt đầu chuẩn bị nghi thức. Cùng lúc đó, tại một thượng cổ tế đàn dưới lòng đất ở Huyết Thiên Đại Lục, quang trận ngũ sắc đưa một thân ảnh trong suốt từ Tiên Giới xuống Linh Giới."},{"chuong":2300,"tieuDe":"Tộc Thệ","tomTat":"Một thanh niên áo đen do Quan Trung Hội phái xuống hạ giới xuất hiện tại vùng đất chết và nhận ra pháp lực của mình bị quy tắc nơi đây áp chế. Hắn quyết định lợi dụng tình thế để huyết tế đông đảo sinh linh nhằm hoàn thiện một bảo vật, sau đó dùng ống vàng chứa thẻ trúc xác định nơi có nhiều sinh linh nhất rồi lên đường. Tại nơi cư trú của Không Ngư Tộc, tộc trưởng xóa sạch dấu vết che giấu trong Sơn Hải Châu và trao viên châu cùng phương pháp tế luyện cho Hàn Lập. Hàn Lập dùng Phạm Thánh Pháp Tướng, thần niệm hóa tơ và bí thuật chuyên biệt để luyện hóa Sơn Hải Châu trong hai ngày hai đêm. Khi cảm nhận lực bài xích của Tu La Giới, hắn yêu cầu toàn tộc lập tức chuẩn bị rời đi. Tộc trưởng cùng năm trăm lẻ một tộc nhân dùng máu lập thệ đời đời phụng dưỡng Hàn Lập, còn hắn chính thức thu nhận họ và hứa sẽ không bạc đãi toàn tộc."},{"chuong":2301,"tieuDe":"Gặp Lại Linh Vương","tomTat":"Hàn Lập đưa toàn bộ Không Ngư Tộc vào nội động thiên của Sơn Hải Châu, cho họ tạm thời dựng nhà và định cư trên quần đảo trong lúc chờ một nơi an bài lâu dài. Sau khi rời Tiểu Tu La Giới và trở về Linh Giới an toàn, hắn kiểm tra tọa độ rồi chờ Mạc Giản Ly tìm tới. Hai người lập tức đến Phục Linh Sơn vì lo Huyết Nhiên và Hắc Lân sẽ đổi hết số Lôi Tiêu phù trước họ. Linh Dẫn xuất hiện theo lời dặn của Linh Vương, mở đường qua các tầng cấm chế và dẫn họ vào đại điện. Tại đây, Hàn Lập và Mạc Giản Ly gặp lại Huyết Nhiên cùng Hắc Lân, đồng thời biết Xa Khấp Tử đã bỏ sào huyệt chạy trốn sau lần giao thủ đầu tiên. Linh Vương sau đó kiểm tra tinh hạch Tu La nhện trưởng thành do Hắc Lân giao ra, xác nhận nó chứa đủ lực thời gian để đề luyện quang âm lực rồi trao lại một hộp ngọc bị phù lục phong kín."},{"chuong":2302,"tieuDe":"Nguyên Hồn Đăng","tomTat":"Hắc Lân, Huyết Nhiên và Mạc Giản Ly lần lượt dùng tinh hạch Tu La Thù để đổi Tam Thanh Lôi Tiêu Phù từ Linh Vương. Hàn Lập giao ba viên tinh hạch cùng cây tinh kiếm cuối cùng của lão giả họ Dịch, nhờ đó nhận được hai tấm phù còn lại. Sau khi giao dịch hoàn tất, Hàn Lập và Mạc Giản Ly tới sơn cốc nơi Ngân Nguyệt ẩn náu rồi dùng Mặc Linh Thánh Chu trở về Nhân Tộc. Trong mật thất trên phi chu, Hàn Lập kiểm tra chiến lợi phẩm và xác nhận lôi lực đáng kể của Tam Thanh Lôi Tiêu Phù. Sau một ngày đêm nghiên cứu cổ đăng, hắn biết đây là Nguyên Hồn Đăng, kỳ bảo có thể nuôi dưỡng phân hồn và hỗ trợ luyện hóa thân nguyên hồn mà không lo bị cắn trả. Hàn Lập lưu một luồng tinh hồn vào đèn để chuẩn bị bồi dưỡng hóa thân mới thay cho nguyên anh thứ hai đã mất tích. Cuối cùng, hắn uống Chân Huyết Huyền Vũ để hướng tới biến hóa thứ bảy của Kinh Trập Quyết."},{"chuong":2303,"tieuDe":"Tâm Đắc Về Pháp Tắc","tomTat":"Sau mấy ngày bế quan, Hàn Lập luyện hóa hoàn toàn Huyền Vũ chân huyết và thử biến thành cự quy đen, qua đó xác nhận hình thái Huyền Vũ có năng lực phòng ngự mạnh nhất trong các biến thân của mình. Tiến vào Sơn Hải Châu, hắn thấy Không Ngư Tộc chỉ dè dặt cư trú trên một đảo nhỏ nên cho phép họ sử dụng những đảo nhỏ khác, còn bản thân giữ lại đảo lớn nhất. Tộc trưởng Không Ngư Tộc giới thiệu cháu gái Lam Dược và xin phép thử trồng Linh Dược trong Động Thiên. Sau khi khảo nghiệm kiến thức luyện đan, Hàn Lập nhận Lam Dược làm đệ tử, ban đan dược cùng ngọc giản và yêu cầu nàng trước tiên tu luyện tới Luyện Hư kỳ. Tộc trưởng tiếp tục dâng cho hắn bộ tâm đắc Không Gian Pháp Tắc do nhiều đời đại năng trong tộc lưu lại, rồi quyết định tập trung tài nguyên của tộc để bồi dưỡng Lam Dược. Vài tháng sau, Mặc Linh Thánh Thuyền đưa đoàn Hàn Lập bình an trở lại lãnh địa Nhân Tộc, nhưng họ lập tức nhận được một tin tức khiến tất cả kinh hãi."},{"chuong":2304,"tieuDe":"Ngao Khiếu Qua Đời","tomTat":"Vừa trở lại Thiên Uyên Thành, Hàn Lập, Mạc Giản Ly và Ngân Nguyệt nhận tin Ngao Khiếu gặp sai sót khi bế quan nên phải độ thiên kiếp sau bảy ngày. Đoàn người lập tức dùng truyền tống trận rồi tiếp tục đi bằng Mặc Linh Thánh Thuyền, hy vọng kịp đưa Tam Thanh Lôi Tiêu Phù tới trợ giúp ông. Khi họ đến gần Thánh Đảo sau chín ngày, vệ sĩ báo Ngao Khiếu đang độ kiếp tại Hồng Vân cốc, nhưng ngọc bài mang hình ông trong tay Ngân Nguyệt đã vỡ thành bụi trên đường tới đó. Các trưởng lão Thánh Đảo sau đó xác nhận Ngao Khiếu chết trong thiên kiếp, chỉ để lại linh hạch và hai bảo vật hộ thân không trọn vẹn. Theo di chúc, Ngân Nguyệt tiếp nhận linh hạch cùng di vật rồi tự bế quan suốt nửa năm để vượt qua nỗi đau mất tổ phụ. Trong thời gian ấy, Hải Đại Thiếu tìm được một hòn đảo ngoài biển có linh khí tinh thuần và lưỡng nghi lực tự nhiên, khiến Hàn Lập quyết định chuyển môn hạ tới đó lập động phủ mới. Khi xuất quan, Ngân Nguyệt cho biết mình đã ổn định và lựa chọn tiếp tục rời Thánh Đảo cùng Hàn Lập."},{"chuong":2305,"tieuDe":"Vô Nhai Hải Cùng Nguyên Hợp Đảo","tomTat":"Hàn Lập chủ trì hoàn thiện Lưỡng Nghi Vạn Dẫn Đại Trận trên Nguyên Hợp Đảo, dùng Hắc Bạch Viên Thạch làm trận nhãn và dự tính liên kết các đảo có Từ Mạch thành mạng lưới phòng thủ bao phủ Vô Nhai Hải. Ngân Nguyệt từ chối trở về Lang Tộc tranh vị trí Lang Vương vì muốn tiếp tục tìm kiếm cơ hội tiến vào Đại Thừa. Hàn Lập đề xuất chuyển toàn bộ chân nguyên Vong Tình Quyết sang một hóa thân để tách ảnh hưởng bất lợi khỏi bản thể nàng, dù phương pháp có thể khiến tu vi của nàng hạ xuống Luyện Hư. Hắn trao Chi Tiên Linh Khu Hợp Thể hậu kỳ đại viên mãn cho Ngân Nguyệt, để nàng tế luyện trong một trăm ngày trước khi tiến hành chia tách chân nguyên. Hàn Lập đồng thời chuẩn bị chuyến đi tới đại lục khác, dự định mang Chu Quả Nhi để dò thông đạo tới Tiểu Linh Thiên và mang Hoa Thạch làm tùy tùng, nhưng không muốn Ngân Nguyệt cùng mạo hiểm. Ba năm sau, Nguyên Hợp Đảo đã trở thành một căn cơ phồn thịnh và được phòng thủ nghiêm mật; khi tiếng chuông vang lên, mấy ngàn tu sĩ trung cao giai tập trung trước cung điện bạc để chúc mừng Tổ Sư xuất quan."},{"chuong":2306,"tieuDe":"Hoàng Nguyên Tử","tomTat":"Hàn Lập chính thức đặt tên cung điện và hệ thống môn hạ trên Nguyên Hợp Đảo là Thanh Nguyên Cung, đồng thời hoạch định việc tuyển thêm đệ tử và bồi dưỡng lực lượng lâu dài. Trước khi đi xa, hắn giao Nguyệt Thiên quản lý tạp vụ đối ngoại, để Ngân Nguyệt xử lý công việc nội bộ và từ chối cho nàng đồng hành vì Linh Khu Hóa Thân chưa củng cố xong. Sau đó, Hàn Lập dẫn Chu Quả Nhi và Hoa Thạch lão tổ rời đảo bằng Mặc Linh Thánh Chu. Tại một nơi khác, Tam Toàn đạo nhân dưới hình thái ba đầu cự mãng nuốt sạch đàn quái thú rồi phát hiện Hoàng Nguyên Tử đã vượt cấm chế tiến vào Bích Lâm Tiểu Trúc. Hoàng Nguyên Tử cho biết mình dùng ba viên Trường Nguyên Đan để mượn Cửu Huyễn Như Ý Môn, nhờ đó dễ dàng xâm nhập nơi này. Hắn lấy manh mối nửa bộ Minh Ngục Chân Kinh làm điều kiện mời Tam Toàn cùng Bất Diệt Thiên Tôn liên thủ đối phó Thanh Nguyên Tử. Do Thanh Nguyên Tử mạnh hơn Hoàng Nguyên Tử và rất khó bị giết nếu bỏ chạy, nhóm này dự định lợi dụng lúc ông trải qua Đại Thiên Kiếp để thực hiện cuộc phục kích."},{"chuong":2307,"tieuDe":"Việt Long","tomTat":"Tam Toàn đạo nhân chưa nhận lời trợ chiến ngay mà hẹn Hoàng Nguyên Tử sau ba ngày sẽ đưa ra quyết định; nếu bị từ chối, Hoàng Nguyên Tử dự định tìm Cừu Oán của Huyết Oán Hiệp. Sau khi Tam Toàn rời đi, Hoàng Nguyên Tử triệu ra một cung điện vàng và được các thiếu nữ cung trang nghênh đón. Hơn hai năm sau khi rời Vô Nhai Hải, Hàn Lập cùng Hoa Thạch Lão Tổ, Chu Quả Nhi và Huyết Phách vượt Man Hoang Thế Giới bằng Mặc Linh Thánh Chu để tới khu vực Phi Linh Tộc. Huyết Phách xác nhận Hách Liên Thương Minh sở hữu pháp trận truyền tống xuyên đại lục và sắp đấu giá tư cách sử dụng, còn Hàn Lập báo trước rằng ông cần lưu lại Lôi Minh Đại Lục để tìm một vật. Khí tức Đại Thừa từ cự thuyền khiến các cường giả Phi Linh Tộc tránh né, nhưng Việt Long hiện thân dưới hình thái quái điểu chín đầu để hỏi rõ lai lịch người tới. Sau khi nhận ra Hàn Lập là người từng đối phó Minh Trùng Chi Mẫu và nghe nhắc tới ân cứu mạng của hảo hữu Viên Phi, Việt Long chuyển sang nhiệt tình tiếp đãi. Hàn Lập để đoàn người ở lại Mặc Linh Thánh Chu rồi theo Việt Long tới một bồn địa có thạch tháp khổng lồ hơn trăm tầng."},{"chuong":2308,"tieuDe":"Cực Nguyên Tinh Và Trọng Nguyên Tố Linh","tomTat":"Việt Long đưa Hàn Lập tới một trong bảy đại động phủ của mình, nơi các Phi Linh tộc nhân trong thung lũng đồng loạt quỳ xuống lễ bái khi hắn xuất hiện. Trong cự tháp, Việt Long dùng Hổ Nguyên Tửu tiếp đãi khách rồi cho thị nữ mang ra ba khối Cực Nguyên Tinh thuộc tính Thổ, Thủy và Hỏa do chính hắn luyện chế. Hàn Lập kiểm tra và nhận thấy vật liệu có lượng linh khí vượt xa Cực Phẩm Linh Thạch cùng thể tích, chứa Tiên Thiên Linh Vân và có độ cứng đáng kinh ngạc. Khi vết chém do kiếm quang tạo ra tự biến mất, hắn xác định Cực Nguyên Tinh mang kỳ hiệu Trọng Nguyên Tố Linh, có thể giúp bảo vật tự tu bổ nếu chưa bị hủy hoàn toàn. Việt Long đề nghị dùng cả ba khối làm thù lao để đổi lấy sự trợ giúp của Hàn Lập trong việc luyện hai loại Cực Nguyên Tinh thuộc tính Kim và Mộc, nhằm chuẩn bị vật liệu cho một kiện chí bảo Ngũ Hành chống Đại Thiên kiếp. Hắn giải thích lực lượng thiên địa của hai thuộc tính này mạnh hơn nhiều so với ba thuộc tính còn lại và phải do một người duy nhất khống chế. Hàn Lập không lập tức nhận lời mà truy hỏi nguyên nhân mình được lựa chọn, mức độ nguy hiểm và căn cứ bảo đảm thành công. Việt Long thừa nhận vẫn có rủi ro nhưng cho rằng có thể giảm thiểu bằng sự chuẩn bị đầy đủ, rồi dừng lại trước khi tiết lộ lý do cuối cùng."},{"chuong":2309,"tieuDe":"Gặp Lại Kim Duyệt","tomTat":"Việt Long giải thích rằng việc luyện hai loại Cực Nguyên Tinh thuộc tính Kim và Mộc phụ thuộc vào địa điểm cùng thời kỳ biến hóa của lực lượng Tinh Thần, nên phải hoàn thành trong thời hạn một năm. Hàn Lập đồng ý tương trợ với điều kiện không tốn quá nhiều thời gian, nhận ba khối Cực Nguyên Tinh làm tiền đặt cọc và yêu cầu thêm hai khối thuộc tính Kim, Mộc sau khi thành công. Trong buổi tiệc, hắn hỏi về Đại Thừa họ Dịch của Ngũ Quang Tộc nhưng che giấu kết cục thực sự giữa hai người. Kim Duyệt sau đó tới cầu kiến Việt Long và được vào đại sảnh nhờ Hàn Lập lên tiếng, song chưa nhận ra vị Thánh Tử năm xưa. Nàng tố Xích Dung Tộc chiếm Linh Mạch, thành trì, bắt giữ tộc nhân Thiên Bằng và liên thủ đánh mình bị thương. Việt Long cho biết phía Xích Dung Tộc đã tới tố ngược rằng Thiên Bằng Tộc xâm chiếm lãnh địa trước. Vì đang toàn tâm chuẩn bị đối phó Đại Thiên Kiếp, Việt Long từ chối phân xử cuộc tranh chấp khi nó chưa đe dọa trực tiếp tới sự tồn vong của một tộc và lạnh lùng đuổi Kim Duyệt lui xuống."},{"chuong":2310,"tieuDe":"Kim Canh Phong Ma Trận","tomTat":"Kim Duyệt quỳ cầu Việt Long bảo vệ Thiên Bằng Tộc trước sự chèn ép của Xích Dung Tộc nhưng bị khí tức của ông ép đến không thể đứng thẳng. Hàn Lập nể giao tình cũ nên lên tiếng cầu tình, đồng thời tuyên bố đây là lần tương trợ cuối cùng và từ đó duyên nợ giữa hắn với Thiên Bằng Tộc hoàn toàn chấm dứt. Hắn dùng hư không truyền tống đưa Kim Duyệt khỏi đại sảnh, khiến Việt Long càng đánh giá cao thần thông của hắn. Hơn nửa ngày sau, Hàn Lập theo Việt Long tới vùng đất trũng hoang vu từng chịu hai lần Thiên Kiếp để chuẩn bị dẫn phát lực Thiên Địa. Việt Long thay Kim Phong Trụ cũ đã hỏng bằng hơn trăm cự trụ đồng xanh, dựng thành pháp trận lớn rồi gia cố thêm nhiều lớp cấm chế. Khi cảnh sao trên la bàn bắt đầu biến hóa, ông cảnh báo Hàn Lập, kích hoạt toàn bộ cấm chế và dốc từ hồ lô tím ra một loại bột phấn cực nhỏ nhưng nặng dị thường."},{"chuong":2311,"tieuDe":"Lực Lượng Thiên Địa","tomTat":"Việt Long dùng quạt lông đỏ đậm, phấn vàng và máu đen dựng một phù trận khổng lồ để dẫn lực lượng thiên địa trong phạm vi ngàn dặm. Hắn đưa vô số tài liệu thuộc tính Kim vào cự đỉnh, đồng thời biến một trăm lẻ tám trụ đồng xanh thành khôi lỗi giáp sĩ nhằm suy yếu kim quang từ phù trận. Khi các đợt kim quang tăng lên ba đạo liên tiếp, Hàn Lập dùng Ích Tà Thần Lôi đánh giảm uy lực của chúng, giúp cự đỉnh tiếp nhận ổn định. Việt Long tiếp tục phá bình ngọc, giải phóng linh diễm xám trắng rồi dùng máu đen tăng cường ngọn lửa để nung chảy những tài liệu còn sót lại. Đến khi phù trận phóng từng đợt bốn đạo kim quang, Hàn Lập đổi sang dùng hồ lô màu vàng nhạt, thả hơn một ngàn hạt cát hóa thành cự thạch dựng Thạch Trận. Dù nhiều cự thạch bị phá vỡ, trận vẫn khiến bốn đạo kim quang co nhỏ và ảm đạm trước khi chúng xuyên qua, trong khi quá trình luyện chế vẫn chưa kết thúc."},{"chuong":2312,"tieuDe":"Kiếp Nạn Của Thanh Nguyên Tử","tomTat":"Hàn Lập theo yêu cầu của Việt Long dùng Thạch Trận và lưới đen để làm chậm, thu giữ rồi điều tiết lực lượng thiên địa thuộc tính Kim phục vụ việc luyện chế Cực Nguyên Tinh. Khi hàng trăm đạo Kim Quang tích tụ khiến việc khống chế trở nên nặng nề, hắn kích hoạt một viên Ngân Châu và hóa giải toàn bộ số Kim Quang trong lưới. Hai tháng sau, tại một sơn cốc bí mật sâu dưới Địa Uyên, Nguyên Dao và Nghiên Lệ chờ Thanh Nguyên Tử bắt đầu vượt Đại Thiên Kiếp. Thanh Nguyên Tử đã chuẩn bị đài cao bảy tầng, nhiều pháp khí, phiên kỳ và hàng trăm loại cấm chế trải rộng quanh sơn cốc. Nguyên Dao đã tiến vào Hợp Thể sơ kỳ để thi triển đại thần thông hỗ trợ nghĩa phụ, còn Nghiên Lệ được giao cảnh giới bên ngoài. Khi thiên tượng bắt đầu biến đổi, Thanh Nguyên Tử đưa Nguyên Dao lên đài và căn dặn nàng chỉ được ra tay đúng thời cơ. Cùng lúc đó, tại một vùng loạn thạch rất xa sơn cốc, hai bàn tay đen khổng lồ xuất hiện trong cuồng phong và bắt đầu xé mở hư không."},{"chuong":2313,"tieuDe":"Đại Địch Xuất Hiện","tomTat":"Hoàng Nguyên Tử dùng Cửu Huyễn Như Ý Môn làm suy yếu lực lượng không gian, tạo điều kiện để Bất Diệt Thiên Tôn xé mở hư không và đưa Tam Toàn đạo nhân cùng xâm nhập nơi Thanh Nguyên Tử Độ Kiếp. Hắn tiết lộ Thanh Nguyên Tử vốn là nguyên thần dị tộc chiếm thân thể tộc huynh ruột của mình, đồng thời tuyên bố cuộc đối đầu lần này chỉ một người có thể sống sót. Tại sơn cốc, Thanh Nguyên Tử bắt đầu Đại Thiên Kiếp và lần lượt dùng màn kiếm, kiếm khí hóa Cự Giao, Phù Trận năm màu cùng nguyên thần xuất khiếu chống quang cầu, lôi tiễn, đao phong và dòng dung nham trên trời. Nguyên Dao đứng dưới trận kỳ quan sát, liên tục thay đổi sắc mặt trước diễn biến dữ dội của kiếp nạn. Sau mười ngày, Thiên Kiếp bước vào giai đoạn hung mãnh nhất, còn ba cường giả Đại Thừa đã mai phục gần sơn cốc từ hai ngày trước để chờ Thanh Nguyên Tử suy yếu. Tam Toàn đạo nhân đề nghị lập tức phá cấm chế ngoại vi nhằm ngăn đối phương trốn thoát sau khi vượt kiếp, mở đầu cho cuộc tập kích đã được chuẩn bị."},{"chuong":2314,"tieuDe":"Địch Bạn Cùng Tới","tomTat":"Hoàng Nguyên Tử ra lệnh cho Tam Toàn đạo nhân tạo thanh thế lớn khi phá cấm chế, nhằm khiến Thanh Nguyên Tử không thể toàn tâm đối phó Thiên Kiếp. Tam Toàn nhanh chóng hóa giải ảo trận rừng hắc thiết, ba phù trận hỏa cầu cùng nhiều lớp phòng hộ ngoại vi, trong khi Thanh Nguyên Tử truyền âm giao Nghiên Lệ chủ trì mười tám Thiên Sát Trận. Nghiên Lệ dùng gương đồng theo dõi kẻ địch rồi vận dụng pháp khí hình la bàn và các trận kỳ, khiến toàn bộ hệ thống liên hoàn bao phủ sơn cốc bằng huyết vụ, bóng đen và sát khí. Sau khi nhận ra trận đầu tiên được tăng cường bằng uy năng của cả mười tám trận, Tam Toàn dự tính cần bốn ngày để phá giải nếu có Cửu Huyễn Như Ý Môn hỗ trợ. Hoàng Nguyên Tử cho rằng thời gian đó quá lâu nên quyết định dùng thêm Tử Mẫu Thi Âm Lôi, ấn định phải phá sạch phòng tuyến trong ba ngày và giữ Bất Diệt Thiên Tôn dưỡng sức để đối phó trực tiếp với Thanh Nguyên Tử. Hắn sau đó tế Cửu Huyễn Như Ý Môn, biến bảo vật thành cánh cửa khổng lồ mang theo lôi quang lao về phía đại trận. Cùng lúc ấy, Hàn Lập và Huyết Phách đi trên một cự chu màu đen xuyên qua khe hư không tiến vào đầm lầy trong Địa Uyên, xác nhận đã tới nơi người bạn của Hàn Lập đang ẩn cư."},{"chuong":2315,"tieuDe":"Nhìn Xem","tomTat":"Sau hơn mười ngày giúp Việt Long luyện thành Cực Nguyên Tinh thuộc tính Kim và Mộc, Hàn Lập nhận mỗi loại một khối làm thù lao rồi từ chối lưu lại. Hắn tìm nơi Không Gian Cách Giới Lực yếu nhất, dùng Huyền Thiên Trảm Linh Kiếm chém mở vách ngăn và điều khiển Mặc Linh Thánh Chu tiến vào Địa Uyên. Trên đường đi, Hàn Lập trò chuyện với Huyết Phách về một người bạn tri kỷ có khả năng đã tiến vào Hợp Thể kỳ, đồng thời khuyên nàng chờ ngày giải cứu bản thể đang bị phong ấn. Khi phát hiện chấn động Đại Thiên Kiếp gần động phủ Thanh Nguyên Tử, Hàn Lập để những người đồng hành ở lại Linh Thuyền và một mình đến dò xét. Bí thuật quan sát từ xa cho hắn thấy Hoàng Nguyên Tử, Tam Toàn đạo nhân và Bất Diệt Thiên Tôn đang phá Mười tám Thiên Sát Trận giữa biển Huyết Vụ. Bất Diệt Thiên Tôn phát hiện sự dò xét và tung chưởng phá thuật, khiến ba Đại Thừa cảnh giác trước người quan sát chưa rõ địch bạn. Do trận mới bị phá gần một nửa và biến số bất ngờ xuất hiện, Hoàng Nguyên Tử quyết định vận dụng Tử Mẫu Thi Âm Lôi ngay lập tức để cưỡng ép phá trận."},{"chuong":2316,"tieuDe":"Đại Chiến Bên Ngoài Cốc Thượng","tomTat":"Hoàng Nguyên Tử dùng ba viên Tử Mẫu Thi Âm Lôi, còn Tam Toàn Đạo Nhân biến ba lệnh bài thành hơn một trăm lá cờ mang lực lượng Pháp Tắc để nhanh chóng phá tầng đầu Thiên Sát Trận. Hàn Lập dò xét kẻ địch rồi dùng Truyền Tấn Phù liên lạc với Nghiên Lệ, qua đó biết Thanh Nguyên Tử đang độ Thiên Kiếp và Nguyên Dao đang trợ giúp sư tôn. Chàng lập tức đến ngoài sơn cốc, yêu cầu ba Đại Thừa rút lui và tuyên bố sẽ giúp Thanh Nguyên Tử. Bất Diệt Thiên Tôn dùng khôi lỗi hóa thân nghi binh rồi để bản thể ẩn nấp đánh lén, nhưng cú đấm bị Hàn Lập đỡ bằng một tay và chính hắn phải lùi hàng chục bước. Hoàng Nguyên Tử, Tam Toàn Đạo Nhân và Bất Diệt Thiên Tôn sau đó đồng loạt dùng tơ vàng, ba đầu rắn và thân thể cự hóa vây công Hàn Lập. Hàn Lập dựng màn sáng chặn tơ vàng, đồng thời triệu hư ảnh ba đầu sáu tay tung vô số quyền ảnh nghênh kích, khiến cuộc đại chiến bên ngoài cốc chính thức bùng nổ."},{"chuong":2317,"tieuDe":"Đại Chiến Bên Ngoài Cốc Trung","tomTat":"Hàn Lập điều khiển Phạm Thánh Kim Thân ghìm Bất Diệt Thiên Tôn, phá chiến giáp và đánh Cự Nhân lún sâu xuống đất. Bất Diệt Thiên Tôn dùng Bất Diệt Thân Thể nhanh chóng khép lại những vết thương do kiếm khí của Hàn Lập gây ra. Tam Toàn đạo nhân dựng pháp trận vây khốn và điều khiển Hóa Huyết Luyện Xá cắn trúng ngón tay Hàn Lập, nhưng Hàn Lập hóa thành Kim Mao Cự Viên phá sạch cấm chế. Hoàng Nguyên Tử mượn Cửu Huyễn Như Ý Môn đưa Vòng Huyền Thiên Tàn Bảo tới trói và thiêu Hàn Lập, song chiếc vòng bị Cự Viên trực tiếp làm nổ tung. Hàn Lập bước khỏi biển lửa mà không bị tổn hại rồi tiếp tục đánh Bất Diệt Thiên Tôn lún xuống đất. Khi Bất Diệt Thiên Tôn biến thân và lao tới trong luồng gió đen, Hàn Lập gọi Phệ Kim Trùng Vương ra bắn hai đạo kiếm mờ, khiến đối thủ kêu thảm và một trận mưa máu rơi xuống."},{"chuong":2318,"tieuDe":"Đại Chiến Bên Ngoài Cốc Hạ","tomTat":"Phệ Kim Trùng Vương hợp nhất Tinh Quang kiếm khí, phá tan thế công của Bất Diệt Thiên Tôn, chém hắn mất một chân và tiếp tục truy sát sau khi đấm nát Cốt Thuẫn. Bất Diệt Thiên Tôn nhanh chóng chữa lành thương thế và tái tạo chân, nhưng vì phần chân mới chưa hoàn chỉnh nên phải liên tục thuấn di tránh né. Ở chiến trường bên kia, Hàn Lập dùng thân thể Cự Viên cùng Vạn Độc Hỗn Nguyên Thân bức Huyết Độc ra ngoài, khiến Tam Toàn đạo nhân kinh hãi. Hoàng Nguyên Tử hiến tế một cánh tay để thúc giục Cửu Huyễn Như Ý Môn, sau đó lấy lời thề Tâm Ma và một nửa tài sản làm điều kiện yêu cầu Hàn Lập rút lui nhưng bị từ chối. Bị Hàn Lập đánh rách áo giáp và gây thương tích, Hoàng Nguyên Tử phát động chín Cánh Cửa cùng vô số Tử Mẫu Thi Âm Lôi. Cơ chế chuyển đổi thật giả của pháp bảo qua mặt cả Linh Mục lẫn Thần Niệm, khiến Hàn Lập bắt nhầm một viên lôi đã hóa thành vật thật. Viên lôi phát nổ, tạo ra vầng sáng xám và uy năng lớn bao phủ toàn thân Cự Viên, còn kết quả thương tổn chưa được xác định."},{"chuong":2319,"tieuDe":"Trảm Sát Cường Địch","tomTat":"Hàn Lập nhận ra các viên châu vây công mình chỉ là sản phẩm mô phỏng Tử Mẫu Thi Âm Lôi, liền thi triển Niết Bàn Tam Biến và dùng Huyền Thiên Trảm Linh Kiếm hóa giải toàn bộ thế công. Ba pháp nhãn giúp hắn tìm ra bản thể Hoàng Nguyên Tử giữa chín huyễn môn, sau đó quyền kình và kiếm quang phá sạch các phân thân cùng cánh cửa che giấu. Hoàng Nguyên Tử cầu cứu Tam Toàn đạo nhân nhưng người này quyết định bỏ chạy khỏi sơn cốc. Hàn Lập dùng tử thủ giam cầm không gian, nghiền nát thân thể Hoàng Nguyên Tử rồi điều khiển kiếm quang truy vào hư không tiêu diệt cả Nguyên Anh. Ở chiến trường cách đó hơn mười dặm, Phệ Kim Trùng Vương cũng tìm ra cách khắc chế bất diệt thân thể, chém đầu và giết chết Bất Diệt Thiên Tôn. Sau khi hai cường địch bị diệt, Hàn Lập thu vòng trữ vật của họ, nhận thủ cấp từ Phệ Kim Trùng Vương rồi dùng kim sắc hồ quang hủy sạch phần còn lại."},{"chuong":2320,"tieuDe":"Lấy Người","tomTat":"Sau trận chiến, Hàn Lập thu vòng tay trữ vật màu đen, phái Phệ Kim Trùng Vương truy sát Tam Toàn đạo nhân và thiêu sạch phần di thể còn lại của Bất Diệt Thiên Tôn. Hắn dùng quang kính liên lạc với Nghiên Lệ, biết Thanh Nguyên Tử cùng Nguyên Dao vẫn bình an và đang chống đỡ những vòng thiên kiếp cuối cùng. Không yêu cầu mở cấm chế, Hàn Lập ngồi chờ bên ngoài sơn cốc, triệu tập những người trên Mặc Linh Thánh Chu rồi tiếp tục hộ pháp. Ba ngày sau, Thanh Nguyên Tử vượt qua Đại Thiên Kiếp và được Hàn Lập bảo vệ thêm hai ngày để phục hồi nguyên khí, trong khi Kim Diễm Hậu vì kiêng sợ chiến lực của Hàn Lập cùng Phệ Kim Trùng Vương nên từ bỏ dị tâm rồi rút lui. Khi Thanh Nguyên Tử mở tiệc khoản đãi, hai người trao đổi gần nửa ngày về việc chuẩn bị ứng phó Đại Thiên Kiếp và con đường phi thăng Tiên Giới. Cuối cùng, Hàn Lập cho biết Nguyên Dao và Nghiên Lệ đã khôi phục thân thể Nhân tộc, đồng thời đề nghị Thanh Nguyên Tử dàn xếp để hắn đưa cả hai trở lại trong tộc."},{"chuong":2321,"tieuDe":"Chương 2321","tomTat":"Thanh Nguyên Tử cho phép Nguyên Dao và Nghiên Lệ tự quyết định việc đi hay ở, nhưng hai nữ giải thích rằng thân thể từng ở trạng thái nửa người nửa quỷ quá lâu nên cần tiếp tục lưu lại Minh Hà chi địa thêm hai, ba trăm năm. Ông dự định truyền cho họ vài môn đại thần thông và nhận định cả hai có cơ hội tiến tới Đại Thừa, còn Hàn Lập hứa sẽ tận lực trợ giúp khi họ trùng kích cảnh giới này. Qua chiến tích Tử Kim tiểu nhân dùng nhiều loại kiếm khí giết Bất Diệt Thiên Tôn, Thanh Nguyên Tử nhận ra Hàn Lập đã đào tạo thành công Phệ Kim Trùng Vương. Hàn Lập sau đó hỏi về Hách Liên Thương Minh và được biết đây là siêu cấp thế lực trải rộng qua nhiều đại lục, đồng thời Thanh Nguyên Tử nhận lời chế tác ngọc giản chứa các tư liệu liên quan. Sau bảy ngày, một đạo kiếm quang màu lục chém mở hư không để cự thuyền màu đen đưa Hàn Lập rời Minh Hà chi địa, trong lúc Nguyên Dao và Nghiên Lệ lưu luyến đứng tiễn. Cự thuyền tiếp đó xuất hiện trên bầu trời Xích Dung sơn mạch thuộc Phong Nguyên đại lục, khiến nhóm dị tộc cấp thấp đang tìm kiếm tài liệu gần núi lửa kinh hãi trước con thuyền khổng lồ cùng đông đảo giáp sĩ."},{"chuong":2322,"tieuDe":"Hắc Tiêu Phong","tomTat":"Một cô gái trẻ từ cự thuyền xuống hỏi đường và được lão giả Dị Hùng Tộc chỉ vị trí Hắc Tiêu Phong trong cụm ba ngọn núi đen ở trung tâm Xích Dung Sơn Mạch. Sau khi nhận mấy khối thượng phẩm linh thạch làm phần thưởng, lão giả nhận thấy ánh mắt tham lam xung quanh nên vội cất tài vật rồi rời đi, trong khi vài tu sĩ cùng cấp âm thầm theo sau. Cự thuyền được xác nhận là Ma Linh Thánh Thuyền của Hàn Lập, đang chở đoàn tới dự đấu giá hội của Hách Liên Thương Minh. Trên đường đi, Huyết Phách cho biết hội đấu giá có thể quy tụ nhiều tồn tại Đại Thừa và phần lớn người tham dự còn tổ chức trao đổi cá nhân ngoài phiên chính thức. Khi tới gần ba ngọn núi, đoàn bị đội vệ sĩ Dị Hùng Tộc cưỡi cự ưng chặn lại và yêu cầu xuất trình tín vật. Huyết Phách đưa ra lệnh bài khách khanh có chữ “Minh”, nhờ đó đoàn được phép tiến vào cấm địa với một vệ sĩ dẫn đường."},{"chuong":2323,"tieuDe":"Hương Nữ","tomTat":"Hồng phát lão giả dùng ngọc giản xác nhận Hàn Lập là Đại Thừa mới của Nhân Tộc và quyết định tiếp đãi hắn theo lễ nghi cao nhất. Sau khi nhận báo cáo lô vật phẩm đấu giá cuối cùng đã nhập kho, lão ra lệnh tăng cường cảnh giới và kiểm tra kỹ các pháp trận, cấm chế bảo vệ. Hàn Lập cùng Huyết Phách, Chu Quả Nhi và Hóa Thạch lão tổ truyền tống vào một thế giới rộng lớn dưới lòng đất, nơi thần niệm của hắn bị lực cản vô hình hạn chế. Tại trạm tiếp khách, họ gặp Phi Vân, Tiếp Dẫn Sứ được phái tới để công khai đón Hàn Lập theo đãi ngộ cao nhất. Phi Vân dùng ngọc bàn truyền tống đưa cả đoàn tới Thiên Tự Hiệu Quý Tân Các và giới thiệu mười hai Hương Nữ có tu vi Nguyên Anh. Hàn Lập nhận nhóm thiếu nữ làm lễ vật của Hách Liên Thương Minh rồi giao họ cho Chu Quả Nhi tạm thời quản lý."},{"chuong":2324,"tieuDe":"Tin Tức Bất Ngờ","tomTat":"Chu Quả Nhi tiếp nhận mười hai Hương Nữ, còn Hàn Lập từ chối ba mâm lễ vật bổ sung rồi đề nghị được đưa tới nơi nghỉ. Cô gái áo tím dẫn đoàn đi qua thị trấn giao dịch rộng lớn của bổn minh và giới thiệu tòa tháp chỉ là cửa vào sàn đấu giá nằm trong một Động Thiên. Dù đấu giá hội còn một tháng mới khai mạc, hơn hai mươi tu sĩ Đại Thừa đã tới. Hàn Lập sau đó biết đầu tiếp nhận của siêu cấp truyền tống pháp trận tại Lôi Minh Đại Lục gặp trục trặc, khiến danh ngạch tới nơi này bị hủy và danh ngạch đi Huyết Thiên Đại Lục được tăng thêm. Tại khu khách quý phòng chữ Thiên, Huyết Phách xác nhận không có con đường khác giúp họ sớm tới Lôi Minh Đại Lục. Hàn Lập vì thế quyết định cân nhắc sang Huyết Thiên Đại Lục trước, đồng thời dò hỏi Huyết Phách về Huyết Ma Đạo Công và những truyền thừa quỷ dị có thể giết địch từ ngoài vạn dặm hoặc vô hình hạ sát đối thủ."},{"chuong":2325,"tieuDe":"Bích Ảnh","tomTat":"Huyết Phách kể cho Hàn Lập về sự thịnh hành của Huyết Đạo Ma Công, thế lực của Huyết Đạo Đại Tông và truyền thừa Vu pháp bí ẩn tại Huyết Thiên đại lục. Nàng cũng thừa nhận từng đắc tội một trưởng lão Huyết Cốt Môn, nhưng yên lòng khi Hàn Lập hứa sẽ giúp đuổi địch nếu cừu gia xuất hiện. Ở phía thương minh, Phi Vân báo cáo việc Hàn Lập chỉ nhận hương nữ và được Minh Tôn ra lệnh tiếp tục đáp ứng tối đa mọi yêu cầu của hắn. Minh Tôn đánh giá Hàn Lập đủ sức tranh một vị trí trong mười cường giả mạnh nhất Linh giới, rồi dùng Thất khiếu tâm âm bích liên lạc với Bích Ảnh tại Huyết Thiên. Ông tiến cử Hàn Lập cho kế hoạch bí mật của Bích Ảnh và khẳng định Hàn Lập mới là người chủ yếu tiêu diệt Minh trùng mẫu. Bích Ảnh nhận món nhân tình, dự định tự thu xếp việc tiếp xúc và hợp tác khi Hàn Lập tới Huyết Thiên. Sau một tháng tĩnh tu, Hàn Lập nhận Truyền âm phù của Phi Vân và rời mật thất để tham dự đấu giá hội."},{"chuong":2326,"tieuDe":"Hồ Ngọc Song","tomTat":"Hàn Lập để Hóa Thạch lão tổ và mười hai Hương Nữ ở lại, chỉ đưa Huyết Phách cùng Chu Quả Nhi tới tòa tháp dự Đấu Giá Đại Hội. Phi Vân chờ sẵn bên ngoài, trực tiếp dẫn ba người qua lối truyền tống vào Động Thiên và bố trí họ trong một nhà đá màu bạc có màn sáng ngăn dò xét. Khi biết hội đấu giá có hai hoặc ba bảo vật đủ sức trì hoãn Đại Thiên Kiếp, Hàn Lập vẫn quyết định tránh tranh đoạt với các tu sĩ Đại Thừa khác và tập trung giành danh ngạch truyền tống. Sau khi hàng vạn Dị Tộc Nhân tập trung tại quảng trường, Minh Tôn công bố thân phận người chủ sự của Hách Liên Thương Minh trên đại lục, cảnh cáo những kẻ phá quy củ rồi tuyên bố khai mạc. Hồ Ngọc Song, một Tam Vĩ Mị Hồ từng hoạt động tại Huyết Thiên Đại Lục, xuất hiện thay ông chủ trì hội đấu giá. Khi bị một khách nam giấu mặt trêu ghẹo, nàng vận dụng mị lực khiến một nam tử trung niên mặt trắng mê đắm và đứng bật dậy, nhưng danh tính người đã lên tiếng vẫn chưa được xác nhận."},{"chuong":2327,"tieuDe":"Hoàng Kim Cốt Tủy","tomTat":"Hồ Ngọc Song dùng lời cảnh cáo đầy uy hiếp khiến Tra đạo hữu thuộc Thạch Dũng tộc phải vội lui về chỗ, đồng thời làm những người dự hội không dám tiếp tục trêu ghẹo nàng. Sau khi bị một lão giả trong phòng xám bạc thúc giục, nàng bắt đầu cuộc đấu giá bằng một bình cốt tủy Hoàng Kim Lôi Sư được đưa từ Lôi Minh đại lục tới. Hồ Ngọc Song giải thích cốt tủy có thể dùng luyện Lôi Tủy đan, giúp người dùng tạm thời tăng khả năng chống lôi điện khi đối phó thiên kiếp, rồi trực tiếp kiểm chứng kỳ trân bằng hiện tượng chất lỏng vàng hóa thành lôi quang. Hàn Lập không cần vật này vì hiệu quả của Lôi Tủy đan đối với cảnh giới và thân thể của hắn rất nhỏ. Trái lại, Huyết Phách muốn chuẩn bị vật chống thiên kiếp cho bản thể đang mất tích, nên Hàn Lập đồng ý để nàng tranh mua và hứa hỗ trợ linh thạch. Giá cốt tủy nhanh chóng tăng từ một nghìn vạn lên hàng chục triệu cực phẩm linh thạch khi nhiều khách dự hội và các nhân vật Đại Thừa lần lượt nhập cuộc. Cuối chương, một Đại Thừa lão tổ nâng mức giá lên năm nghìn vạn cực phẩm linh thạch sau khi bị người trong phòng xám bạc thứ ba cạnh tranh."},{"chuong":2328,"tieuDe":"Thương Minh Tứ Lão","tomTat":"Được Hàn Lập khuyến khích, Huyết Phách nâng giá lên năm ngàn năm trăm vạn linh thạch và mua được Cốt tủy Hoàng Kim Lôi Sư sau khi đối thủ Đại Thừa từ bỏ tranh đoạt. Hồ Ngọc Song tiếp tục giới thiệu Thanh Giao Trùng Nguyệt Kiếm, một phi kiếm có linh tính mạnh từng thuộc Trùng Nguyệt Lão Nhân; kiếm hóa thành thanh giao định bỏ trốn nhưng bị áp chế rồi được bán với giá hai ngàn sáu trăm vạn linh thạch. Huyết Cương Thiết cùng hàng trăm dị bảo và tài liệu khác lần lượt được bán trong suốt một ngày. Khi Hách Liên Thương Minh đưa ra nhóm bảo vật có thể ngăn cản hoặc trì hoãn thiên kiếp, các lão tổ Đại Thừa tranh giá quyết liệt, còn Hàn Lập rút lui khỏi một cuộc tranh mua khi giá đạt hai trăm triệu linh thạch. Cuối ngày, Hồ Ngọc Song tuyên bố bắt đầu đấu giá ba bảo vật áp trục và ba cung trang mỹ nữ mang các khay bạc được ánh sáng vàng che phủ tới quảng trường. Bốn đại trưởng lão cấp Đại Thừa của Hách Liên Thương Minh cũng đồng thời xuất hiện để tọa trấn. Lão giả áo gai tiết lộ cả bốn vốn đang bế quan tu luyện một loại thần thông tới thời điểm mấu chốt, nhưng phải xuất quan theo yêu cầu kiên quyết của Minh Tôn."},{"chuong":2329,"tieuDe":"Phiên Thiên Kỳ","tomTat":"Vì ba bảo vật áp trục có giá trị đặc biệt cao, Hách Liên Thương Minh điều bốn trưởng lão Đại Thừa xuất quan và trấn giữ bốn góc thạch đài. Hồ Ngọc Song công bố bảo vật đầu tiên là Phiên Thiên Kỳ, món đồ đứng thứ chín trên Hỗn Độn Vạn Linh Bảng và từng gây ra cuộc tranh đoạt đẫm máu trước khi mất tích nhiều năm. Trước sự chất vấn của các Đại Thừa, nàng thừa nhận món được bán chỉ là Phiên Thiên Âm Kỳ; bảo vật phải hợp nhất với Dương kỳ mới khôi phục đầy đủ uy năng Huyền Thiên Chi Bảo. Hồ Ngọc Song kích phát Âm kỳ, tạo vô số hoa vàng hấp thu thiên địa nguyên khí và phủ kín không trung quảng trường, nhưng một Đại Thừa dùng cuồng phong xanh phá hơn nửa số hoa để buộc nàng chuyển sang đấu giá. Giá khởi điểm ba trăm triệu linh thạch nhanh chóng tăng lên tám trăm triệu và tưởng như sắp thuộc về một nữ Đại Thừa. Hàn Lập bất ngờ trả chín trăm triệu linh thạch, khiến những Đại Thừa khác tiếp tục nhập cuộc và đẩy giá lên một tỷ hai trăm triệu, trong khi người thắng cuối cùng vẫn chưa được xác định."},{"chuong":2330,"tieuDe":"Ngọc Thư Tái Hiện","tomTat":"Cổ tiên tử, một Đại Thừa Thạch Tiêu tộc và lão giả Phù Du tộc liên tục nâng giá Phiên Thiên Kỳ, nhưng cuối cùng lão giả Phù Du tộc giành được bảo vật với giá 2,5 tỷ linh thạch. Hàn Lập giải thích với Huyết Phách rằng nửa kiện Huyền Thiên chi bảo chưa đủ lập tức tăng thực lực Nhân tộc, trái lại còn có thể kéo theo sự nhòm ngó của các đại tộc. Hồ Ngọc Song sau đó công bố vật đấu giá thứ hai là một trang Kim Khuyết Ngọc Thư nguyên vẹn, thuộc ba mươi sáu trang ngọc thư và chứa pháp quyết Tiên gia có thể tu luyện. Dù tên cùng công dụng cụ thể của pháp quyết được giữ kín, nàng xác nhận việc tu luyện chỉ có nhược điểm là vô cùng gian nan và kéo dài. Đại Thừa Thạch Tiêu tộc nâng giá Ngọc Thư lên 600 triệu linh thạch, nhưng Hàn Lập trả 610 triệu và giành được trang sách khi không còn ai tranh tiếp. Hắn thanh toán rồi thu Ngọc Thư vào vật trữ vật mà chưa kiểm tra, đồng thời vẫn giữ lại tài lực để chờ vật phẩm áp trục. Cuối chương, Hồ Ngọc Song tiến tới cung trang nữ tử thứ ba và bắt đầu mở cấm chế che giấu vật phẩm tiếp theo."},{"chuong":2331,"tieuDe":"Máu Của Tổ Long","tomTat":"Hồ Ngọc Song lấy một chiếc bát bạc từ khe hở hư không và công khai vật phẩm áp trục đang mang hình dạng Ngũ Trảo Kim Long, khiến toàn trường hoảng sợ vì tưởng Hách Liên Thương Minh đã bắt hậu duệ Thiên Long. Một trưởng lão của Thương Minh dùng uy áp trấn tĩnh đám đông, còn Cổ đạo hữu yêu cầu các lão tổ Đại Thừa tự quan sát kỹ linh vật. Hàn Lập vận dụng linh mục, nhận ra Kim Long chỉ là hình thái biến hóa và xác định bản thể của nó là một giọt linh huyết. Hồ Ngọc Song thi pháp khiến linh vật trở lại nguyên dạng là giọt chất lỏng màu vàng, qua đó xác nhận phán đoán của hắn. Nàng công bố rằng năng lượng trong giọt máu mạnh hơn chân huyết Thiên Long trên trăm lần, khiến các Đại Thừa suy đoán chủ nhân của nó là tồn tại tại Thượng Giới. Hách Liên Thương Minh cho rằng Tổ Long tại Tiên Giới là lời giải thích phù hợp nhất nhưng thừa nhận chưa thể chứng thực, đồng thời cho biết chính vì bảo vật quá khó lường nên tổ chức không dám giữ riêng mà đem ra đấu giá."},{"chuong":2332,"tieuDe":"Cướp Bảo","tomTat":"Hồ Ngọc Song giải thích rằng linh huyết có thể tạo ra chất tương đương vạn năm linh nhũ khi ngâm trong nước, nhưng Hách Liên Thương Minh chưa tìm được cách hấp thu nguồn năng lượng khủng bố trong đó. Một nam tử áo đen tỏ ra biết đặc điểm của bảo vật và được Minh Tôn cùng các trưởng lão cho phép tới gần kiểm tra. Hắn lợi dụng lúc cấm chế trên bình bát được gỡ bỏ để dùng ngân quang cướp cả vật chứa lẫn linh huyết. Lão già gầy lập tức ra tay nhưng bị một lão giả áo xám râu dài có tu vi Đại Thừa chặn lại, tạo nên dư chấn dữ dội trên bệ đá. Hách Liên Thương Minh huy động bốn trưởng lão, giáp sĩ, pháp bảo và nhiều tầng trận pháp để phong tỏa toàn bộ quảng trường. Nam tử áo đen xác nhận món đồ vừa cướp là Tổ Long chân huyết, còn đồng bọn tiết lộ họ đã rời tộc và chờ đợi bảo vật này từ lâu. Khi bị bao vây, nam tử áo đen kích hoạt một trận bàn, khiến hạt mầm màu xanh hóa thành cổ thụ xanh sẫm khổng lồ. Hàn Lập nhận ra hình dáng cự mộc và lập tức trở nên cảnh giác."},{"chuong":2333,"tieuDe":"Treo Thưởng Lớn","tomTat":"Lão giả gầy và ba trưởng lão Hách Liên Thương Minh hợp lực đánh vào cự mộc, nhưng nam tử áo đen cùng lão giả râu dài đã chui vào đó và vượt khỏi Động Thiên. Minh Tôn dẫn bốn trưởng lão truy đuổi song thất bại vì đối phương đã bố trí sẵn một truyền tống trận tạm thời bên ngoài. Hội đấu giá được tiếp tục, còn Hàn Lập gác nghi vấn về Tổ Long Huyết để mua danh ngạch truyền tống đến Huyết Thiên đại lục, ưu tiên mục tiêu sớm gặp lại Nam Cung Uyển. Sau khi khách thông thường rời đi, Minh Tôn treo ba yêu cầu cùng Tổ Long Huyết làm phần thưởng cho người bắt được hai kẻ cướp, khiến các Đại Thừa có mặt động tâm. Hàn Lập không tham gia cuộc săn lùng mà dẫn Huyết Phách và Chu Quả Nhi trở về chỗ ở, phân phó công việc trong thời gian chờ truyền tống. Cuối cùng, hắn vào mật thất và lấy trang nội thư Kim Khuyết Ngọc Thư vừa mua ra nghiên cứu."},{"chuong":2334,"tieuDe":"Ngũ Tạng Đoàn Nguyên Công","tomTat":"Hàn Lập đọc trang nội thư Kim Khuyết Ngọc Thư và xác định kinh văn bên trong là Ngũ Tạng Đoàn Nguyên Công, một bí thuật Tiên Giới có thể biến lục phủ ngũ tạng thành nơi chứa pháp lực tương tự đan điền. Công pháp có thể gia tăng mạnh pháp lực, phối hợp với Bách Mạch Luyện Bảo Quyết và sinh ra nhiều thần thông, nhưng yêu cầu thể chất cực mạnh cùng thời gian tu luyện tính bằng vạn năm nên Hàn Lập chưa quyết định có tu luyện hay không. Sau đó, Điền Phi Nhi bí mật xuất hiện ngoài mật thất và tiết lộ truyền tống trận tại đấu giá hội chỉ là thủ thuật che mắt, còn sai sót trong đường lui đã khiến hắn mắc kẹt trong Động Thiên. Hắn viện dẫn tình bạn với Phàn Bào Tử để tạo lòng tin rồi đề nghị Hàn Lập đưa mình theo khi sử dụng danh ngạch truyền tống vượt đại lục. Hàn Lập từ chối vì Hách Liên Thương Minh đang phong tỏa nghiêm ngặt và treo trọng thưởng truy bắt hai kẻ cướp, khiến việc giúp đỡ có nguy cơ dẫn tới sự truy cứu của một siêu cấp thế lực. Điền Phi Nhi hứa lấy tâm ma thề giữ bí mật, xác nhận bản thể là Chân Long và tuyên bố bản tộc sẽ công khai nhận trách nhiệm sau khi hắn trở về. Cuối cùng, khi Hàn Lập nhắc tới máu Tổ Long bị cướp, Điền Phi Nhi mỉa mai đặt nghi vấn rằng vật phẩm ấy có thể không phải thứ đã được công bố."},{"chuong":2335,"tieuDe":"Yểm Long Và Điền Phi Nhi","tomTat":"Nam tử áo đen giải thích cho Hàn Lập rằng giọt chân huyết đang bị truy tìm không thuộc về Tổ Long mà đến từ Yểm Long, Tổ Tiên của Ma Long Tộc và đại địch của Chân Long Tộc. Loại chân huyết này chứa lượng chân nguyên rất lớn nhưng mang lực lượng hỗn loạn, có thể ô nhiễm pháp lực ngoại tộc và biến người cưỡng ép tế luyện thành hình chiếu phân thân của Yểm Long. Người này tiếp tục xác nhận Long Lân màu bạc của Hàn Lập là thiếp mời đại hội Quảng Linh Đạo Quả, đồng thời tiết lộ Đạo Quả có thể ban Quảng Linh Đạo Thể trong một vạn năm và tăng mạnh tốc độ tu luyện, lĩnh hội công pháp. Với tư cách một trong ba mươi sáu chấp sự, đối phương đề nghị cung cấp tin tức nội bộ để đổi lấy sự giúp đỡ của Hàn Lập trong việc liên quan đến máu Yểm Long, và hắn chấp nhận giao dịch. Nàng dự định dùng bí thuật hóa thành đồ trang sức để theo Hàn Lập rời đại lục mà không chiếm danh ngạch truyền tống. Khi bị Hàn Lập nhìn thấu lớp ngụy trang nam giới, nàng thừa nhận mình là nữ và công khai tên thật Điền Phi Nhi. Bốn ngày sau, Minh Tôn gửi truyền âm báo pháp trận truyền tống đã chuẩn bị xong và thúc giục Hàn Lập khởi hành."},{"chuong":2336,"tieuDe":"Tiến Vào Huyết Thiên","tomTat":"Trong đại điện bí mật dưới lòng đất, Hách Liên Thương Minh hoàn tất việc lắp linh thạch cho pháp trận liên đại lục, còn Điền Phi Nhi biến thành vòng sáu màu trên cổ tay Hàn Lập để trà trộn vào đoàn. Minh Tôn đích thân kiểm tra, chủ động kết giao với Hàn Lập và khiến các Đại Thừa dị tộc nhận ra hắn là người từng tham chiến chống Minh Trùng Mẫu tại Ma Giới. Hàn Lập cùng Huyết Phách, Chu Quả Nhi và Hoa Thạch lão tổ sau đó được truyền tống từ Phong Nguyên Đại Lục tới Huyết Thiên Đại Lục. Dựa vào trận bàn, Minh Tôn và Phi Vân xác nhận đoàn có thêm một người ẩn mình, đồng thời tiết lộ Hách Liên Thương Minh đã biết vật bị cướp là máu Yểm Long có thể làm ô uế chân nguyên và cố ý để Chân Long tộc lấy đi. Tại đầu truyền tống bên Huyết Thiên, Bích Ảnh dưới tên Phương Tiến phát ngọc giản địa đồ cho những người mới tới. Khi Hàn Lập chuẩn bị dẫn cả nhóm rời đi, một nữ tử lạnh lùng bất ngờ nhận ra hắn, cho biết mình phụng mệnh đặc biệt tới đón và mời hắn tới một nơi chưa được tiết lộ."},{"chuong":2337,"tieuDe":"Bát Quỷ Phệ Phật Đồ","tomTat":"Một nữ tử lạnh lùng của Thương Minh phụng mệnh Tổng Chấp sự Bích Ảnh chờ Hàn Lập tại Huyết Thiên và mời hắn đến gặp, khiến hắn suy đoán Minh Tôn đã tiết lộ hành trình của mình. Nàng trao cho Hàn Lập một quyển trục đỏ như máu mang tên Bát Quỷ Phệ Phật Đồ; sau khi kiểm tra bằng thần niệm, hắn chủ động để huyết quang kéo mình vào không gian trong tranh. Hoa Thạch lão tổ lập tức dùng hắc khí hóa thành cự mãng uy hiếp sứ giả, nhưng Huyết Phách khuyên mọi người bình tĩnh chờ đợi vì tin vào thần thông của Hàn Lập. Trong không gian phủ huyết vụ, Hàn Lập gặp phân thần của Bích Ảnh ký gửi trong hình tượng tăng nhân áo xám. Bích Ảnh điều khiển tám ác quỷ phun Hoàng Tuyền Minh Phong, yêu cầu Hàn Lập không dùng pháp khí mà chống đỡ trong một khắc để chứng minh đủ tư cách biết một chuyện trọng đại. Hàn Lập dùng kim quang hộ thể ngăn minh phong rồi ngưng kết pháp tướng ba đầu sáu tay, tạo vòng xoáy vàng hút gần sạch tường gió để nghiên cứu. Lực hút còn khiến tám ác quỷ mất chỗ đứng và sắp bị cuốn vào vòng xoáy."},{"chuong":2338,"tieuDe":"Âm Ty Thập Vương","tomTat":"Sau khi Hàn Lập vượt qua trắc nghiệm, Bích Ảnh cứu tám Ác Quỷ khỏi Động Tuyền Kim Quang, còn Hàn Lập giữ lại Hoàng Tuyền Âm Phong đã bị nén thành một quả cầu đen để nghiên cứu. Bích Ảnh chính thức mời hắn gia nhập Hách Liên Thương Minh, nhưng Hàn Lập yêu cầu nghe rõ chính sự trước khi quyết định. Lão kể rằng chi nhánh tại Huyết Thiên đại lục đang tranh chấp một tiểu thế giới giàu tài nguyên với thế lực quỷ vật tự xưng đến từ Minh giới, và hai bên đã lập thệ ước dùng năm trận đấu một chọi một để phân chia lợi ích. Hàn Lập được mời trở thành người thứ năm trong đội hình của Thương Minh, trong khi phía đối phương nhiều khả năng sẽ cử các cường giả thuộc Âm Ty Thập Vương. Để thuyết phục hắn, Bích Ảnh hứa cho hắn vào Đăng Thiên Các chọn một bí thuật truyền từ Tiên giới nếu thắng trận. Lão còn tiết lộ tiền thân Hách Liên Thương Minh từng là tổ chức bí mật thay Tiên giới quản lý và giám sát Linh giới, còn những người sáng lập là hậu duệ trực hệ của tiên nhân. Cuối cùng, Bích Ảnh nhắc lại việc Hàn Lập từng cứu nhiều trưởng lão Thương Minh khỏi cấm chế của Minh Trùng Mẫu, nhưng Hàn Lập vẫn chưa đưa ra quyết định."},{"chuong":2339,"tieuDe":"Thành Huyết Hạc","tomTat":"Hàn Lập chưa nhận lời gia nhập Hách Liên Thương Minh nhưng đồng ý tham dự cuộc chiến Cường giả sau ba năm, đổi lại quyền sử dụng mạng lưới tình báo và tư liệu về Thượng Cổ tế đàn. Bích Ảnh chấp thuận, giao pháp bàn làm tín vật và cho người chuyển ngọc giản chứa dữ liệu chi tiết tới Hàn Lập. Sau khi đoàn người rời đi, thanh niên mặt tròn khôi phục hình dạng lão giả áo xanh, qua đó lộ rõ hắn chính là Bích Ảnh đã cải trang và áp chế tu vi; hắn cũng đánh giá Hàn Lập có thể ngang sức với những Quỷ Vương mạnh thuộc Âm Ty Thập Vương. Trên Mặc Linh Thánh Thuyền, Điền Phi Nhi hiện chân thân, lấy tâm ma thề giữ bí mật rồi cáo từ để trở về tộc. Huyết Phách đề nghị quay lại thành Huyết Hạc, nơi nàng từng phát hiện dấu vết bản thể nhưng phải bỏ chạy vì bị truy sát. Hàn Lập chấp thuận và quyết định khảo sát các Thượng Cổ tế đàn dọc đường, trong khi Huyết Phách cảnh báo thành Huyết Hạc thuộc địa bàn của Huyết Đạo đại tông, thế lực vốn có oán cừu với nàng."},{"chuong":2340,"tieuDe":"Huyết Cốt Môn","tomTat":"Hàn Lập cho Huyết Phách nghỉ ngơi rồi tiếp tục dùng Mặc Linh Thánh Thuyền dò tìm các tế đàn trên Huyết Thiên Đại Lục, nhưng điểm dừng trên đảo nhỏ giữa hồ vẫn không phải mục tiêu. Một tháng sau, cự thuyền bay ngang nơi hai nhóm dị tộc tranh đoạt Linh Dược, dùng khí thế áp đảo toàn bộ tu sĩ và xé một rãnh xuyên rừng nhưng không làm tổn hại những cây thuốc quý. Ba tháng sau, Hàn Lập huy động hơn ngàn khôi lỗi phong tỏa cấm địa Ly Hỏa Tông rồi cùng Chu Quả Nhi phá cấm chế kiểm tra một tế đàn thượng cổ, song vẫn không tìm thấy nơi cần tìm. Ly Hỏa Tông không đủ sức ngăn cản, còn Tông chủ sau khi nghe các trưởng lão báo cáo đã bác ý định nhờ Thượng Tông truy cứu và chỉ ra lệnh tăng cường phòng vệ. Trở lại thuyền, Huyết Phách cho biết phần lớn tế đàn lân cận đã được dò xét và địa điểm kế tiếp nằm trong phạm vi Huyết Cốt Môn. Biết tông môn Huyết Đạo này có khoảng năm sáu Đại Thừa, công pháp bá đạo và từng có thù với Huyết Phách, Hàn Lập quyết định thu liễm hành tung, đồng thời cân nhắc ngừng sử dụng Mặc Linh Thánh Thuyền."},{"chuong":2341,"tieuDe":"Nam Tử Đeo Mặt Nạ","tomTat":"Khi tiến vào địa phận Huyết Cốt Môn, Hàn Lập thu Mặc Linh Thánh Thuyền và đổi sang một chiếc phi xa màu đen kín đáo hơn. Tới gần Huyết Hạc Thành, Huyết Phách quyết định tách đoàn để tới Vạn Nguyệt sơn mạch tìm dấu vết bản thể, được Hàn Lập bố trí hai khôi lỗi Hợp Thể bảo vệ và giao truyền âm phù cầu viện. Hoa Thạch lão tổ dùng khí tức Hợp Thể khiến vệ sĩ cửa thành không dám tra hỏi, giúp ba người còn lại thuận lợi tiến vào thành. Các vệ sĩ sau đó tiết lộ hơn ba mươi tu sĩ Hợp Thể đã vào thành trong tháng nhưng dường như chưa ai rời đi, đồng thời nhiều nhân vật lạ có địa vị cũng xuất hiện trong hàng ngũ cấp trên. Tại quảng trường thương mại, Hàn Lập cho Hoa Thạch lão tổ và Chu Quả Nhi tự do mua sắm trong ba ngày. Trước khi rời quảng trường, Hàn Lập phát hiện một ánh nhìn ẩn trong hư không nhưng không vạch trần. Người theo dõi là một nam tử đeo mặt nạ có tu vi Đại Thừa, kẻ sau đó xác nhận Hàn Lập cũng đã nhận ra sự hiện diện của mình."},{"chuong":2342,"tieuDe":"Thanh Bình Đạo Nhân Và Vạn Hoa Phu Nhân","tomTat":"Tiêu Minh nhận định bí mật về một vật sắp mở ra không thể tiếp tục che giấu nên quyết định truyền tin, mượn sức những người khác mạo hiểm thăm dò. Trong khi đó, Hàn Lập tạm hoãn việc tìm tế đàn thượng cổ và cùng Hoa Thạch lão tổ, Chu Quả Nhi bế quan hơn một tháng tại Huyết Hạc Thành. Thanh Bình đạo nhân và Vạn Hoa phu nhân bất ngờ công kích giữa thành, phá hủy khu vực xung quanh và khiến gần một nghìn người thiệt mạng. Tiêu Minh hiện thân với tư cách thành chủ, chất vấn hai người rồi buộc Vạn Hoa phu nhân tới đấu trường tiếp ba chiêu để khép lại sự việc. Nhờ cấm chế toàn thành do mình bố trí, ông phát hiện Hàn Lập đang ẩn trong hư không và gọi hắn ra gặp mặt. Hàn Lập phủ nhận việc mình đến vì vật trong lời đồn, nhưng yêu cầu Thanh Bình đạo nhân cùng Vạn Hoa phu nhân tiếp một chiêu để bồi hoàn chuyện hắn suýt bị liên lụy. Sau khi hai bên nhận lời, Tiêu Minh mời cả ba Đại Thừa tới động phủ của mình khi những cuộc luận bàn kết thúc."},{"chuong":2343,"tieuDe":"Cửu Mục Huyết Thiềm","tomTat":"Hàn Lập và Thanh Bình đạo nhân nhận lời tới động phủ của Tiêu Minh, nhưng trước đó cùng mọi người chuyển tới đấu trường trong Thành Huyết Hạc. Hàn Lập truyền âm để Hoa Thạch lão tổ và Chu Quả Nhi rời đi riêng, còn mình ở lại quan sát Tiêu Minh giao đấu với Vạn Hoa phu nhân. Tiêu Minh trước tiên dùng cốt đao và các mảnh Thái Nhạc tấn công, song Vạn Hoa phu nhân triển khai Thực Cốt Ma Hỏa và Trảm Lân Ma Kiếm để hóa giải. Đến chiêu cuối, Tiêu Minh lần đầu vận dụng Huyết Thiềm Chân Thân, hóa thành Cửu Mục Huyết Thiềm khổng lồ khiến những người chứng kiến đều kinh ngạc. Vạn Hoa phu nhân nhờ thuẫn gỗ ẩn nặc cản được cú đánh bằng lưỡi cực nhanh nhưng vẫn bị đẩy lùi. Tiêu Minh tiếp tục nhảy tới trên đầu bà và đánh xuống chưởng ấn huyết sắc khiến hư không ngưng trệ, còn kết quả của đòn này chưa được hé lộ."},{"chuong":2344,"tieuDe":"Trận Đồ","tomTat":"Vạn Hoa phu nhân dùng đại ấn, pháp tướng Cự Sư và hắc hỏa chống lại Cửu Mục Huyết Thiềm Chân Thân nhưng vẫn bị Tiêu Minh áp chế, cuối cùng phải thừa nhận thua trong lượt luận bàn. Tiêu Minh chủ động thu thần thông, trở lại hình người rồi mời Hàn Lập vào trận. Vạn Hoa phu nhân từ chối nghỉ ngơi và lập tức nhận một chiêu của Hàn Lập. Hàn Lập triển khai trạng thái chưa hoàn toàn của Phạm Thánh Biến Thân, khiến Thanh Bình đạo nhân nhận lầm đó là Chân Ma Thân và lên tiếng cảnh báo. Vạn Hoa phu nhân tung ba trăm sáu mươi cây Hắc Huyết Châm, hợp thành trận đồ có khả năng công kích, trói buộc, phong ấn và phòng hộ. Hàn Lập dùng một cự chưởng vàng đánh bật phi châm, xé tan phù văn cùng dây trói rồi phá vỡ màn chắn cuối cùng. Bàn tay khổng lồ dừng ngay trên đầu Vạn Hoa phu nhân, nhưng kết quả chính thức của lượt luận bàn chưa được tuyên bố."},{"chuong":2345,"tieuDe":"Thiên Đỉnh Cung","tomTat":"Hàn Lập dùng cự chưởng vàng kim phá tan trận đồ và áp chế thủ đoạn mạnh nhất của Vạn Hoa phu nhân, khiến Thanh Bình đạo nhân chủ động nhận thua. Tiêu Minh nhận ra hắn qua chiến tích chém Minh Trùng Mẫu tại Ma Giới, còn Hàn Lập công khai xác nhận thân phận Nhân Tộc đến từ Phong Nguyên Đại Lục. Sau buổi tiệc, Tiêu Minh bí mật thương lượng với Vạn Hoa phu nhân và Thanh Bình đạo nhân về chuyến tiến vào Thiên Đỉnh cung, đồng thời đòi chín phần thu hoạch vì nắm chìa khóa nguyên bản. Hai người còn lại phản đối, cảnh báo chìa khóa giả vẫn có thể giúp nhiều Đại Thừa xác định thời gian và vị trí mở cung, khiến cuộc tranh đoạt trở nên nguy hiểm. Thanh Bình đạo nhân còn tiết lộ bí mật truyền thừa bằng truyền âm, làm Tiêu Minh chuyển sang kinh hỉ dù nội dung chưa được công khai. Cùng lúc đó tại sơn mạch Vạn Nguyệt, tên Thiên Đỉnh cung kích hoạt một phần ký ức bị phong ấn của Huyết Phách. Chiếc đỉnh nhỏ màu xanh nhạt trong tay Hàn Lập cũng liên tục phát sáng, còn một nhân vật bị giam lâu năm trong không gian bí mật tin rằng cửa cung sắp mở sẽ giúp mình thoát ra."},{"chuong":2346,"tieuDe":"Chìa Khóa","tomTat":"Ở rìa Vạn Nguyệt sơn mạch, hơn trăm cao giai tu sĩ bí mật kết thành một pháp trận lớn, trong khi ba lão giả tại một nơi khác cùng tu luyện quanh đỉnh xanh giữa ao độc trùng. Bích Ảnh nhận báo cáo rằng toàn bộ dân chúng của tám quốc gia và thành viên mười chín tông môn quanh Tề Vân sơn mạch đã biến mất, chỉ để lại khí tức Huyết Đạo cấp Đại Thừa, nên ông giao Đề Huyết môn, Phong Xà tộc và Yên Vũ chân nhân tham gia điều tra. Dưới đáy hồ phía bắc sơn mạch, một hạp cốc bị cấm chế phong kín chứa huyết hà, nơi bóng người bí ẩn đang hút máu vào một vật phát sáng. Sau khi nhận phù lục, Hàn Lập dẫn Hoa Thạch lão tổ và Huyết Phách rời Huyết Hạc thành tới Vạn Nguyệt sơn mạch, còn Tiêu Minh cùng Vạn Hoa phu nhân và Thanh Bình đạo nhân theo dõi hành tung của hắn và chuẩn bị tranh lợi tại Thiên Đỉnh cung. Huyết Phách tiết lộ bản thể từng mang chìa khóa thật vào cung, đồng thời để lại phân thân cùng Hư Thiên đỉnh bên ngoài làm phương án dự phòng. Hư Thiên đỉnh thực chất là chìa khóa phỏng chế từ bí thuật trong Kim Khuyết Ngọc Thư, chỉ có một nửa hiệu lực của chìa khóa thật nhưng có thể lợi dụng sơ hở đại trận để lẻn vào cứu bản thể. Hàn Lập lập tức chỉ ra rằng tính chất phỏng chế này đã không được nói rõ trong giao dịch trước kia, khiến sự thật không hoàn toàn phù hợp với ước định ban đầu."},{"chuong":2347,"tieuDe":"Hiện Thế","tomTat":"Huyết Phách thừa nhận trí nhớ từng bị phong ấn khiến nàng hiểu lầm Hư Thiên đỉnh là chìa khóa chân chính, còn Hàn Lập khẳng định sẽ giữ lời giải cứu bản thể Băng Phách. Hai người phân tích việc nhiều chìa khóa phỏng chế đang lưu lạc và khả năng các cường giả tại Huyết Hạc thành cũng sẽ tham dự cuộc tranh đoạt. Hàn Lập quyết định để Chu Quả Nhi cùng Hoa Thạch lão tổ ở lại động phủ, chỉ đưa Huyết Phách tiến vào Thiên Đỉnh cung. Khi dị tượng ngũ sắc xuất hiện tại một đầm nước trong Vạn Nguyệt sơn mạch, Hư Thiên đỉnh phát sinh phù văn chỉ dẫn và hơn ba mươi nhóm giữ chìa khóa đồng loạt lên đường. Đông đảo tu sĩ không có chìa khóa truy đuổi, phục kích và chém giết lẫn nhau trên khắp sơn mạch. Nha đạo hữu dựng Quang trận Phạn văn chặn Hàn Lập nhưng bị hắn dùng một chưởng phá trận, làm sập hạp cốc và diệt cả thân thể lẫn nguyên anh. Nhóm đồng bọn của Nha đạo hữu nhận ra Hàn Lập là Đại Thừa đứng đầu nên từ bỏ báo thù, còn một nhóm cự hán chặn đường phía sau cũng bị hắn giết tức khắc."},{"chuong":2348,"tieuDe":"Cánh Cửa Lớn","tomTat":"Sau khi đánh lui những kẻ cản đường, Hàn Lập đưa Huyết Phách tới một lòng chảo nơi cột sáng năm màu phun lên từ đầm nước và nhiều phe đã chiếm vị trí chờ sẵn. Hắn che chở Huyết Phách trước linh áp của các cường giả rồi lần lượt dò xét đôi đạo lữ Vô Cấu lão tổ và Hoa Tây tiên tử, Huyết Hợp Ngũ Tử cùng lực lượng đông đảo của Phụng Tông Chủ. Tiêu Minh, Thanh Bình đạo nhân, Vạn Hoa phu nhân và ba lão giả Đại Thừa tới sau, khiến tương quan lực lượng tại thung lũng thay đổi và mở ra những cuộc thăm dò thân phận giữa các phe. Qua đối thoại, lai lịch của Vô Cấu lão tổ, Phụng Tông Chủ và bí mật năm phân thân cùng bản nguyên của Huyết Hợp Ngũ Tử lần lượt được hé lộ. Cột sáng sau đó khuếch tán thành màn sáng, xé mở không gian và ngưng tụ thành cánh cửa năm màu cao vạn trượng dẫn vào Thiên Đỉnh cung. Hàn Lập nhận ra Kim Triện văn cùng Ngân Khoa văn của Tiên giới phủ trên cửa, còn Hoa Tây tiên tử cho biết đây mới là cửa đầu tiên trước các tầng phong ấn cần chìa khóa. Lo ngại thêm nhiều người sẽ kéo tới, Phụng Tông Chủ tuyên bố tiến vào trước, đẩy cuộc tranh đoạt Thiên Đỉnh cung sang giai đoạn trực tiếp."},{"chuong":2349,"tieuDe":"Song Đỉnh","tomTat":"Các nhóm cường giả lần lượt tự phá cánh cửa Thiên Đỉnh cung: Phụng Tông Chủ dùng quang trận hợp kiếm, Vô Cấu lão tổ đánh thủng vòng bảo vệ, còn ba lão giả khô gầy hợp lực xé cửa. Hàn Lập mang Huyết Phách xuyên thẳng qua cửa bằng hỏa diễm bạc, trong khi Tiêu Minh cùng hai đồng bạn đi sau và bỏ qua một kẻ đang ẩn nấp ngoài thung lũng. Khi các nhóm lớn đã rời đi, huyết ảnh hiện thân và sát hại toàn bộ những người đến muộn. Bên trong, mọi người phát hiện phong ấn dài hơn mấy trăm dặm do Thiên Đỉnh chân nhân bố trí một năm trước khi phi thăng, buộc từng nhóm phải tách ra tìm cách phá giải. Một chấn động bất ngờ cho thấy đã có người dùng chìa khóa nguyên bản vượt phong ấn và tiến vào nội cung trước. Hàn Lập vì thế từ bỏ ý định cưỡng ép phá phong ấn, lấy Hư Thiên đỉnh ra theo chỉ dẫn của Huyết Phách. Huyết Phách gọi thêm Hư Hoàng đỉnh và tiết lộ đây là chìa khóa phỏng chế thành công nhất, có bảy phần công hiệu của chìa khóa nguyên bản."},{"chuong":2350,"tieuDe":"Tiến Vào","tomTat":"Huyết Phách dùng tinh huyết nhập vào Hư Hoàng đỉnh, phối hợp với Hàn Lập thúc đẩy Hư Thiên đỉnh để phá phong ấn năm màu. Nàng bị phản phệ sau một kích, khiến Hàn Lập phải cho nàng dừng bí thuật rồi triệu pháp tướng ba đầu sáu tay hoàn tất việc mở thông đạo. Hai người xuyên qua phong ấn và xuất hiện trên một đồng cỏ, nhưng Hàn Lập nhanh chóng nhận ra đây chỉ là ảo cảnh che giấu nội cung Thiên Đỉnh cung. Sau khi phá ảo thuật, hắn phát hiện quần thể cung điện gồm hơn một trăm khu vực với cấm chế ngăn thần niệm ngày càng mạnh về phía trung tâm. Vì Thiên Đỉnh cung chỉ mở trong một tháng, Huyết Phách đề nghị chia đường: nàng tìm Băng Phách ở khu vực bên ngoài, còn Hàn Lập mang giọt máu cảm ứng tiến sâu vào trung tâm để đồng thời tìm người và tầm bảo. Lo hai khôi lỗi Hợp Thể kỳ không đủ bảo vệ Huyết Phách trước các Đại Thừa khác, Hàn Lập quyết định phái Kim nhi đi cùng nàng."},{"chuong":2351,"tieuDe":"Mặt Quỷ, Cự Hoa, Khôi Lỗi","tomTat":"Hàn Lập giao Kim Đồng bảo vệ Huyết Phách, nhận bình ngọc chứa máu huyết đã được gia trì bí thuật rồi cùng nàng chia nhau thăm dò các khu vực trong Thiên Đỉnh Cung. Sau khi phá một màn sáng trắng, hắn tiến vào rừng mặt quỷ, dùng ánh sáng xám hấp thu các đợt công kích và tiêu diệt toàn bộ gương mặt trên cây. Hắn tiếp tục vượt qua vườn cự hoa bằng Ích Tà Thần Lôi, quét sạch những ma đầu do hoa khổng lồ biến thành rồi đi tới một hồ nước đỏ thẫm. Ở khu vực khác, Vạn Hoa phu nhân, Tiêu Minh và Thanh Bình đạo nhân bị đội quân khôi lỗi đất vàng do cấm chế liên tục tái tạo vây hãm. Lo người khác giành được cấm chế trung tâm trước, họ quyết định dùng thủ đoạn mạnh để tìm mắt trận. Tiêu Minh vận dụng trận bàn bạch ngọc khiến một phù văn bạc khổng lồ hiện ra trong hư không, sau đó dùng hư ảnh Cửu Mục Huyết Thiềm phun sợi tơ vàng cắt nát phù văn."},{"chuong":2352,"tieuDe":"Huyết Ảnh Cùng Xích Lôi","tomTat":"Tiêu Minh phá tan cấm chế ký hiệu bạc ở khu ngoại vi, nhưng nhóm của ông sau đó lại bị ảo cảnh mặt biển tại đệ nhị Cung vây khốn khoảng hai ngày. Tại những khu vực khác, Cẩm Y đại hán phối hợp cùng hàng trăm đệ tử tiêu diệt Song đầu Cự Viên, còn một lão giả khô gầy bình thản ngồi trên Cự Trùng ba đầu giữa vòng vây mãnh thú. Bên ngoài ngũ sắc phong ấn, Huyết Hợp Ngũ Tử phục kích Huyết Ảnh Tử để đoạt chìa khóa, dẫn đến một trận chiến ngang sức. Trước cửa lớn Thiên Đỉnh Cung, Xích Lôi lão tổ dùng lôi pháp cưỡng ép xuyên qua cấm chế và khiến một số tu sĩ thiệt mạng. Ba ngày sau, Hàn Lập dùng Thanh ti phá hủy hai Kim Cương Khôi Lỗi canh cửa rồi phát hiện đại sảnh chứa hơn một nghìn pháp khí. Bảy ngày sau, Huyết Phách bị Xích Lôi lão tổ chặn đường và phải gọi hai Hợp Thể Khôi Lỗi phòng thủ. Dù nàng nói chìa khóa đang do Hàn Lập giữ và bản thân không thu hoạch được gì, Xích Lôi vẫn đòi giao toàn bộ vật phẩm, đe dọa dùng Sưu hồn thuật rồi tiến lên cưỡng đoạt."},{"chuong":2353,"tieuDe":"Huyết Mang Xà","tomTat":"Xích Lôi lão tổ áp sát Huyết Phách, phá hủy hai khôi lỗi Hợp Thể kỳ hộ vệ và ép nàng giao chìa khóa Thiên Đỉnh Cung cùng bảo vật. Khi hắn sắp bắt được nàng, một đạo tinh quang bí ẩn chặt nổ cánh tay của hắn, nhưng hắn nhanh chóng dùng huyết đạo tái tạo phần thân thể bị mất. Xích Lôi lão tổ tiếp tục phóng đoản thoi tập kích Huyết Phách, song Kim Đồng kịp hiện thân và dùng tay đập nát pháp bảo. Hai bên giao chiến dữ dội khi hắn phối hợp Xích Lôi với cổ kính Huyền Thiên tàn bảo tạo lôi vân, còn Kim Đồng dùng kim ty xuyên phá và phát động vô ảnh kiếm khí. Cuối cùng, hắn cho huyết sắc quái kiếm hóa thành Huyết Mang Xà, một trong Huyết Thiên thập đại độc trùng, để cắn vào vai Kim Đồng. Kim Đồng không hề trúng độc, trái lại bắt đúng bảy tấc rồi nuốt chửng Huyết Mang Xà trước sự kinh hãi của đối phương."},{"chuong":2354,"tieuDe":"Uy Của Phệ Linh","tomTat":"Kim Đồng dễ dàng cắn chết Huyết Mang Xà, phá liên tiếp các lớp phòng ngự rồi tiêu diệt cả thân thể lẫn nguyên anh của Xích Lôi lão tổ. Sau khi thu chiến lợi phẩm, nó tiếp tục ẩn thân bảo hộ Huyết Phách, còn nàng rời khu vực hiện tại để tiến sâu tìm bản thể. Mười ngày sau, hai thái thượng trưởng lão Huyết Cốt môn chỉ huy hàng trăm đệ tử cao giai lập pháp trận quanh thung lũng ngoài Thiên Đỉnh cung, chuẩn bị chặn người truyền tống ra để tranh đoạt bảo vật. Cuộc trò chuyện của họ hé lộ Tiêu lão quái từng giấu việc sở hữu chìa khóa, Thiên Đỉnh cung có nhiều chìa khóa và các điểm thoát mang tính ngẫu nhiên. Ở bên trong cung, Hàn Lập trong hình thái cự viên phá tường thủy tinh, bước lên truyền tống trận và tới một ngọn núi có nhiều khu vực bị quầng sáng cách ly. Ba lão giả khô gầy cũng xuất hiện tại đó rồi áp sát với địch ý, khiến Hàn Lập chủ động tung cự chưởng mở màn cuộc đối đầu một chọi ba."},{"chuong":2355,"tieuDe":"Tụ Tập Và Trùng Hợp","tomTat":"Trong hình thái Cự Viên, Hàn Lập lấy một địch ba, dùng ba tòa núi nhỏ áp đảo Vu Linh Tam thánh, khiến hai người trọng thương ở tay và buộc người còn lại phải hao tổn tinh khí tăng cường khôi lỗi cáo năm đuôi. Trước ý định tiếp tục lấy đông hiếp ít của đối phương, hắn dung hợp Phạm Thánh Pháp Tướng, đồng thời vận dụng Kinh Trập Quyết và Phạm Thánh Chân Ma Công để hóa thành Cự Viên ba đầu sáu tay. Đúng lúc đại chiến sắp bùng nổ, Tiêu Minh, Vạn Hoa phu nhân và Thanh Bình đạo nhân phá được cấm chế rồi truyền tống tới, khiến hai bên tạm thời kiềm chế. Lo ngại cuộc giằng co sẽ thu hút thêm các cường giả Đại Thừa, Tiêu Minh đề nghị mọi người đình chiến và hợp sức vượt qua những khu vực phía sau, được cả Hàn Lập lẫn Vu Linh Tam thánh chấp thuận. Sau khi ba lão rời đi, Hàn Lập bất ngờ đổi hướng, tiến vào màn sáng lam nhạt trùng với con đường bí mật dẫn tới trung tâm Thiên Đỉnh cung. Lựa chọn chính xác ấy khiến nhóm Tiêu Minh kinh nghi, bởi Thanh Bình đạo nhân khẳng định vị trí và phương pháp khống chế trung tâm vốn chỉ được lưu truyền trong nhất mạch Thiên Đỉnh tổ sư."},{"chuong":2356,"tieuDe":"Huyết Ngục","tomTat":"Tiêu Minh quyết định cùng Thanh Bình đạo nhân và Vạn Hoa Phu Nhân đi theo Hàn Lập vào khu vực băng tuyết, tạm gác kế hoạch thăm dò Huyết Ngục để ưu tiên tìm đường tới trung tâm Thiên Đỉnh cung. Hàn Lập phải dùng ngân diễm chống lại hàn khí xuyên qua hộ thể rồi bị hàng nghìn băng tước đồng loạt tập kích, trong khi nhóm Tiêu Minh ở phía sau bị những cự nhân băng có khả năng tái tạo cầm chân. Ở một tuyến khác, Vu Linh tam thánh tiến sâu vào Huyết Ngục nhờ bia đá cổ và tiết lộ mục tiêu tìm vu pháp của Thiên Vu để tăng cơ hội phi thăng. Ba lão giả cũng thừa nhận cuộc ác đấu trước đó chỉ nhằm ngăn Hàn Lập cùng những người khác bám theo. Khi hơn vạn Thôn Cốt Điệp xuất hiện phía sau và các Huyết Linh đầu lâu từ trụ máu chặn đường phía trước, cả nhóm rơi vào thế bị giáp công. Lão giả họ Ngô yêu cầu họ Dư thi triển khu linh đại pháp, còn hai người kia chuẩn bị ngăn hung vật để hộ pháp. Chương kết thúc khi các lệnh bài ngọc xanh đen hợp thành pháp trận và nâng lão giả họ Dư lên cao."},{"chuong":2357,"tieuDe":"Thần Thông Vu Đạo","tomTat":"Trong khi lão giả họ Dư chuẩn bị bí thuật vu đạo, hai người đồng hành dùng chiêng đồng, hồ lô và những bí thuật phòng thân để chống lại Huyết Linh cùng Thôn Cốt Điệp. Khi các thủ đoạn hộ pháp dần bị áp đảo, hình ma vật tám tay xuất hiện, vận dụng Kim Triện Văn, Phạm âm và ánh sáng bảy màu để tiêu diệt toàn bộ hai đàn quỷ vật. Lớp da thịt của ma vật sau đó vỡ ra, để lộ lão giả họ Ngô đang suy yếu nghiêm trọng vì hao tổn nguyên khí. Ba người nhận định cửa vào Huyết Ngục có thể đã ở gần nên tiếp tục hành trình tìm công pháp chân truyền của Thiên Vu. Ở một nơi khác, Hàn Lập hóa thành Cự Viên ba đầu sáu tay, hợp sáu kim sắc cự nhận thành kiếm quang và biển kiếm để triệt diệt hai Băng Giao cùng các phân thân tái sinh. Nhờ hiểu biết cấm chế và thần niệm mạnh, hắn tìm được thạch thai chứa truyền tống trận loại nhỏ nhưng bị Ngũ Hành Quang Tráo bảo vệ. Không thể nhanh chóng phá cấm chế bằng phương pháp thông thường, Hàn Lập chấp nhận hao tổn nguyên khí, gọi Huyền Thiên Trảm Linh Kiếm cùng Phạm Thánh Pháp Tướng và vung kiếm chém xuống."},{"chuong":2358,"tieuDe":"Tấm Bia Lớn","tomTat":"Hàn Lập dùng Huyền Thiên Trảm Linh Kiếm hấp thu thiên địa nguyên khí, phá tan lồng sáng rồi kích hoạt truyền tống trận trên đài đá. Hắn được đưa tới một không gian u tối có tấm bia đỏ tươi cao như núi, trong khi nhóm Tiêu Minh lại tới khu điện phủ và lầu các ngoài trung khu sau khi thoát khỏi cấm chế băng tuyết. Tiêu Minh, Thanh Bình đạo nhân và Vạn Hoa phu nhân nhận ra lộ trình đã bị thay đổi, suy đoán có người từ lần Thiên Đỉnh Cung mở trước từng can thiệp một phần cấm chế, rồi quyết định cưỡng ép xuyên qua màn sáng để tiến tới trung khu. Tại tấm bia lớn, Hàn Lập dùng giọt linh huyết xác định bản thể Băng Phách đang bị vây gần đó và lần ra một nhóm Ngân Khoa Văn đặc biệt. Hắn điều khiển các vân bạc hợp thành phù văn lớn, mở một thông đạo lát đá xanh với linh văn đỏ tươi và mùi máu tanh. Do thần niệm và khả năng phi hành đều bị áp chế mạnh, Hàn Lập dựa vào thân thể chạy theo lối dốc lên hơn trăm trượng. Cuối cùng, hắn bước vào một gian phòng cực lớn và kinh ngạc trước cảnh tượng chưa được hé lộ."},{"chuong":2359,"tieuDe":"Lồng Sắt","tomTat":"Hàn Lập tiến vào một căn phòng rộng lớn, khảo sát hài cốt và pháp khí để suy ra nơi đây từng xảy ra trận chiến giữa một con thú Hợp Thể hậu kỳ đại thành với khoảng bốn, năm tu sĩ. Thấy mười khay bạc trên giá gỗ đều đã bị vét sạch, hắn rời đi qua thông đạo và tới một không gian có miếu thờ hình tam giác, nhưng bình nhỏ óng ánh không phản ứng với nơi này. Ở một khu vực khác, Vu Linh Tam thánh trong tình trạng suy yếu dùng Thanh Cương Phong quét biển sương mù trước Huyết Ngục, để lộ hồ máu đầy sinh vật giống giòi và hơn mười lồng sắt. Ba người tìm kiếm y bát Thiên Vu, cuối cùng xác định bộ xương nửa người nửa ngựa bị xích máu trói là chân thân của ông nhờ khí tức Vu Đạo còn sót lại. Họ còn phát hiện một vật màu đen giống ngọc bài hoặc ngọc giản khảm trong xương sườn của di hài. Đòn hợp lực của cả ba không thể để lại bất kỳ dấu vết nào trên lồng sắt. Không cam lòng, lão giả họ Dư lấy đoản kiếm đỏ máu khắc quái trùng ra, tự chặt vài ngón tay để huyết tế pháp bảo và chuẩn bị phá lồng lần nữa."},{"chuong":2360,"tieuDe":"Hài Cốt","tomTat":"Lão giả họ Dư dùng đoản kiếm quái trùng chém lồng sắt nhưng bị hồ quang vàng đánh bật, khiến bảo vật hư hại nặng. Vu Linh tam thánh nhận ra cấm chế này là loại thần lôi đã qua tinh luyện, có uy lực vượt xa Ích Tà Thần Lôi thông thường và đặc biệt khắc chế Vu Đạo, nên một lão giả chuyển sang dùng U Minh Âm Thủy thử phá cấm. Trong một điện phủ khác, Hàn Lập khảo sát pho tượng được cho là Thiên Đỉnh Chân Nhân, kiểm tra khôi lỗi, hài cốt và thu bốn vòng tay trữ vật. Hắn phát hiện dấu tinh huyết của Băng Phách trên pháp trận truyền tống bị phá hủy, qua đó xác định nàng từng đi qua nơi này rồi rời đi bằng trận pháp. Hàn Lập lập tức lấy dụng cụ bày trận và tinh thạch, bắt đầu tu bổ những linh văn bị khuyết để khôi phục khả năng truyền tống. Sau một ngày, Vu Linh tam thánh dùng ba pho tượng quái thú đầu hươu thân người triệu hiện quái vật cầm dao bạc, cuối cùng đánh thủng lồng sắt. Ba lão giả tiến vào bên trong và cẩn thận quan sát bộ hài cốt nửa người nửa ngựa đang bị xích máu cùng những mũi nhọn quỷ dị trói giữ."},{"chuong":2361,"tieuDe":"Huyết Sát Thi","tomTat":"Vu Linh Tam Thánh thận trọng kiểm tra di hài Thiên Vu, thiêu hủy huyết xích rồi phát hiện vật màu đen giấu trong xương không thể bị thần niệm dò rõ. Lão giả họ Dư dùng U Cốt Kiếm chém thử nhưng không thể để lại dấu vết, khiến lão giả họ Ngô phải uống đan dược và thi triển Thấu Hoán Thuật để lấy vật ra. Vật đó là một ngọc bài phủ linh văn đen chứ không phải ngọc giản truyền thừa như họ mong đợi. Ngọc bài bất ngờ nổ tung, phóng phù văn đen xuyên qua phòng hộ và khóa thân thể, chân nguyên cùng Nguyên Anh của cả ba người. Cấm chế đồng thời kích thích di hài Thiên Vu phát sinh Huyết Sát Thi biến, để tơ máu trong xương xé nát và cắn nuốt tơ đen trấn áp. Khi Huyết Sát Thi bắt đầu ngồi dậy, hai lão giả họ Ngô và họ Dư cho Nguyên Anh xuất khiếu, còn người thứ ba hóa thành người cây khổng lồ để liều mạng thoát hiểm."},{"chuong":2362,"tieuDe":"Tam Thánh Vẫn Lạc","tomTat":"Lão giả cuối cùng biến thành người cây và tự nổ để thoát khỏi tơ đen, nhưng hư ảnh của lão vẫn bị huyết hà kéo trở lại rồi bị hài cốt Thiên Vu cắn nuốt. Hai Nguyên Anh họ Ngô và họ Dư từ bỏ ý định phản công, song trên đường chạy trốn lại bị Huyết Ảnh Tử cùng Huyết Hợp Ngũ Tử đã biến thành Huyết Khôi Lỗi chặn giết. Sau khi cắn nuốt hai Nguyên Anh và đoạt bảo vật, Huyết Ảnh Tử nhận ra giá trị của Huyết Sát Thi được tạo từ hài cốt cường giả Đại Thừa nên dẫn thuộc hạ tới bắt giữ và tế luyện. Huyết Sát Thi lúc này đã hấp thu hết tơ đen, thoát khỏi lồng sắt và chủ động nghênh chiến nhóm Huyết Ảnh Tử trên hồ máu. Ở một nơi khác, Hàn Lập sửa truyền tống pháp trận để nó có thể hoạt động thêm hai hoặc ba lần rồi tiến vào một không gian tối đen. Hắn mở Linh Mục quan sát và dùng phi kiếm màu xanh chém tan cảnh núi non giả tạo, làm lộ ra đình viện có tường đá bao quanh. Hàn Lập sau đó phát hiện một người đang ẩn nấp sau đại thụ và lên tiếng yêu cầu đối phương hiện thân."},{"chuong":2363,"tieuDe":"Băng Phách Hiện Thân","tomTat":"Hàn Lập phát hiện nữ tử áo vàng ẩn sau đại thụ, nhận ra nàng là Băng Phách và xác định nàng vừa tiến vào cảnh giới Đại Thừa. Hắn trao bình tinh huyết của Huyết Phách để chứng minh mình đến cứu viện, khiến Băng Phách tin tưởng và kể lại việc bị mắc kẹt trong trung khu Thiên Đỉnh Cung sau khi pháp trận bên ngoài bị phá hủy. Trong thời gian không thể thoát ra, nàng nhận được một phần y bát công pháp của Thiên Đỉnh chân nhân, chuyên tâm tu luyện và tiến giai Đại Thừa vài năm trước. Hàn Lập tiết lộ mình xuất thân từ cùng một Nhân giới, từng vào Hư Thiên Điện và nhận được Hư Thiên Đỉnh cùng di lưu của nàng. Băng Phách chưa muốn rời đi vì bảo tàng cuối cùng vẫn chưa mở, nên hứa giao hơn nửa số trọng bảo cho Hàn Lập nếu hắn giúp phá cấm chế. Tại đại điện màu xám trắng, Hàn Lập xác định màn sáng quanh tòa tháp nhỏ có thể phản xạ công kích, rồi ném tòa núi nhỏ màu xanh vào đó để thử giới hạn chịu đựng của cấm chế."},{"chuong":2364,"tieuDe":"Lấy Bảo","tomTat":"Hàn Lập dùng ngọn núi màu xanh công kích màn sáng bảo vệ tháp nhỏ màu vàng, nhưng tượng Thiên Đỉnh Chân Nhân lập tức chữa lành cấm chế và đẩy pháp bảo trở lại. Nhận ra tượng và tháp hỗ trợ lẫn nhau, hắn hóa thành Kim Mao Cự Viên, gọi Phạm Thánh Pháp Tướng và phối hợp hai ngọn núi xanh đen để phá hủy bức tượng. Màn sáng tan biến, Hàn Lập thu lấy tháp rồi trao cả tháp cùng phần lớn bảo vật cho Băng Phách, chỉ nhận ngọc giản màu đỏ hồng ghi bí thuật. Băng Phách cho biết nàng đã khống chế được một phần cấm chế Thiên Đỉnh Cung và dự định thiết lập trung tâm pháp trận, hội hợp với Huyết Phách rồi đóng cung để đưa mọi người ra ngoài. Hàn Lập cùng nàng trở lại Truyền Tống Trận và rời khỏi đại điện. Ở một nơi khác, Tiêu Minh, Thanh Bình đạo nhân và Vạn Hoa Phu Nhân tới được không gian có tấm bia đá màu máu. Thanh Bình phát hiện phương pháp mở cửa đã bị can thiệp, khiến lần điều khiển bốn Ngân Khoa văn thất bại. Ba người vì thế chuẩn bị thử thêm một lần trước khi liên thủ dùng sức mạnh phá cửa."},{"chuong":2365,"tieuDe":"Liên Thủ","tomTat":"Vân trận trên bia đá mở thông đạo, đưa Hàn Lập và Băng Phách tới nơi Tiêu Minh, Thanh Bình đạo nhân và Vạn Hoa phu nhân đang chờ. Khi biết Băng Phách đã nhận truyền thừa Thiên Đỉnh, ba người đề nghị trả giá để sao chép công pháp và bí thuật, nhưng nàng giải thích huyết thệ cấm truyền trước khi tu thành và kiên quyết không cho Thanh Bình dò xét thức hải. Nàng còn tiết lộ Thiên Đỉnh Chân Nhân vượt qua nhiều Đại Thiên Kiếp nhờ từng ăn Đàm Lôi Tiên Quả từ Tiên giới. Trước sự ngăn cản của đối phương, Hàn Lập phóng khí tức ép lui cả ba Đại Thừa, khiến Tiêu Minh thừa nhận họ liên thủ vẫn khó thắng. Vô Cấu Lão Tổ và Hoa Tây Tiên Tử bất ngờ xuất hiện, đồng thời để lộ việc dùng Vô Trần Cổ truy tung nhóm Tiêu Minh từ trước khi vào Thiên Đỉnh Cung. Có thêm hai cường giả trợ giúp, Tiêu Minh quyết định không để Băng Phách mang truyền thừa rời đi, còn Hàn Lập tuyên bố sẵn sàng một mình giao chiến với cả năm người."},{"chuong":2366,"tieuDe":"Chiến Ngũ Tổ","tomTat":"Tiêu Minh đề nghị cùng Hoa Tây tiên tử và Vô Cấu lão tổ cầm chân Hàn Lập, để Thanh Bình đạo nhân và Vạn Hoa phu nhân bắt Băng Phách rồi chia nhau bảo vật cùng bản sao y bát của Thiên Đỉnh chân nhân. Sau khi nghe Tiêu Minh truyền âm về lai lịch Hàn Lập, Hoa Tây tiên tử từ chỗ xem nhẹ chuyển sang kiêng kị và chấp thuận kế hoạch. Hàn Lập âm thầm trấn an Băng Phách, bí mật bắn một sợi tơ vàng nhạt vào hư không rồi dùng ba tòa núi phòng thủ trước đợt vây công. Hắn hóa thành Cự Viên lông vàng, ném trọng sơn và tung quyền ảnh để một mình cầm chân Tiêu Minh, Hoa Tây cùng Vô Cấu. Trong khi đó, Thanh Bình và Vạn Hoa giáp công Băng Phách bằng thanh mang cùng Hỏa Giao lửa đen, khiến hàn khí quanh lồng băng của nàng suy yếu nhanh chóng. Một đạo lôi điện bạc bất ngờ đánh tan Hỏa Giao, để lộ Hoàng Kim Cự Giải đang lao vào cứu viện. Vạn Hoa phu nhân triệu hư ảnh Cự Sư đen chống trả, dùng luồng sáng hóa thành lửa đỏ quấn chặt chiếc càng khổng lồ khi cuộc giao chiến vẫn chưa phân thắng bại."},{"chuong":2367,"tieuDe":"Hàn Vũ Huyền Quy","tomTat":"Hoàng Kim Cự Giải phá tan dây lửa và ép Vạn Hoa phu nhân phải dùng mặt thuẫn, hư ảnh sư tử cùng pháp trận phi châm để toàn lực ứng chiến, qua đó tách nàng khỏi cuộc vây bắt Băng Phách. Thanh Bình đạo nhân một mình vận dụng tơ xanh, cọc gỗ và lôi hỏa công phá phòng tuyến, nhưng Băng Phách triệu Hàn Vũ Huyền Quy phun khí lạnh chữa lành và gia cố bức tường băng. Không thể nhanh chóng bắt được nàng, Thanh Bình chuyển sang duy trì thế công nhằm tiêu hao pháp lực. Ở chiến trường khác, Hàn Lập triệu Phạm Thánh Kim Thân dùng sáu cự nhận tấn công Tiêu Minh, song Cửu Mục Huyết Thiềm hóa giải đao khí, đánh thủng ngực Kim Thân rồi ẩn mình trong biển sương mù máu. Kim Thân nhanh chóng tự phục hồi và tiếp tục truy kích, trong khi bản thể Cự Viên của Hàn Lập bất ngờ bị Vô Cấu lão tổ đánh lén. Vô Cấu hóa giải phần lớn quyền lực và dùng bí thuật tàn ảnh né kiếm quang trước khi lộ rõ chân thân. Cùng lúc đó, Hoa Tây tiên tử vẫn chống đỡ một tòa cực sơn, còn người lửa màu vàng kim xuất hiện và liên tục phóng hỏa cầu vào tòa cực sơn thứ hai."},{"chuong":2368,"tieuDe":"Đại Chiến","tomTat":"Trong hình thái Cự Viên, Hàn Lập vận dụng Minh Thanh Linh Mục nhìn xuyên bí bảo che giấu thi khí và phát hiện Vô Cấu lão tổ đã trở thành tồn tại nửa người nửa thi. Vô Cấu giải thích rằng biến đổi này bắt nguồn từ sai lầm khi luyện công, sau đó cùng Hoa Tây tiên tử triển khai thế hợp kích bằng hàng trăm hư ảnh, cổ đao tinh sa và áp lực khóa không gian. Hàn Lập ngưng tụ áo giáp phù trận, cường hóa thân thể để phá thế phong tỏa rồi dùng biển lôi điện đánh tan phần lớn hư ảnh của Vô Cấu. Hắn tiếp tục dùng hỏa điểu bạc vây khốn Hoa Tây, đồng thời lấy lực lượng hư không, lôi quang và quyền ảnh áp chế hạt châu phòng ngự của Vô Cấu. Khi nhiều bảo vật và lồng tinh sa bị linh diễm thiêu hủy, Hoa Tây buộc phải cầu cứu Vô Cấu. Vô Cấu dùng bổn mạng chân diễm xuyên qua biển lửa, nhưng sau khi đến bên Hoa Tây lại bất ngờ bọc lửa vàng quanh cánh tay và đâm thẳng về phía nàng."},{"chuong":2369,"tieuDe":"Rút Đi","tomTat":"Vô Cấu lão tổ dùng Thế Linh Đại Pháp đánh lén Hoa Tây tiên tử, bắt lấy Nguyên Anh và tiết lộ rằng Đồng Mệnh Cấm Chế giữa hai người đã bị phá giải từ nhiều năm trước. Lão để Hỏa Nhân thiêu cả thân thể lẫn Nguyên Anh của Hoa Tây thành tro, lấy một trận bàn màu đen từ ngọn lửa rồi khiến nó phong hóa thành khói để nuốt vào bụng. Nhận thấy không thể thắng Hàn Lập, Vô Cấu từ bỏ truyền thừa của Thiên Đỉnh chân nhân và rời khỏi chiến trường. Tiêu Minh thấy phe mình không còn phần thắng nên chủ động nhận thua, buộc Vạn Hoa phu nhân và Thanh Bình đạo nhân thu hồi thần thông. Hàn Lập không cho ba người tùy ý rời đi và nhận ba khối Âm Huyết Tinh từ Tiêu Minh làm vật bồi thường. Sau đó, Băng Phách cảm tạ Hàn Lập đã cứu mạng rồi dùng trận bàn mượn lực lượng cấm chế để dịch chuyển cùng hắn và Hoàng Kim Cự Giải tới một lầu các. Tại đây, Băng Phách cuối cùng gặp lại hóa thân Huyết Phách đang thu lấy các bảo vật."},{"chuong":2370,"tieuDe":"Trở Về","tomTat":"Huyết Phách xác nhận mình vốn là hóa thân của Băng Phách rồi hóa thành huyết quang dung nhập vào bản thể; Băng Phách chịu đau đớn trong quá trình hợp nhất và tạm phong ấn hơn nửa ký ức vừa thu hồi. Hàn Lập nhận định Thiên Đỉnh Cung không còn vật đáng lưu tâm nên thu Kim Đồng cùng Giải đạo nhân lại và chuẩn bị rời đi. Bên ngoài, Huyết Cốt Môn đã dựng đại trận khổng lồ trên Vạn Nguyệt Sơn Mạch, còn việc Thiên Đỉnh Cung đột ngột đóng sớm khiến Phụng tông chủ, các môn nhân và Huyết Hợp Ngũ Tử bị cưỡng chế truyền tống ra ngoài. Lão già mắt thâm dùng Lưu Ly Huyễn Mục nhìn thấu năm thanh niên là huyết nhục khôi lỗi, buộc Huyết ảnh ẩn phía sau phải hiện thân. Vì Huyết Thần thuật là cấm thuật trên Huyết Thiên đại lục, Huyết Cốt Môn lập tức phát động truy sát, trong khi Huyết ảnh đánh tan lôi quang rồi hóa thành biển máu cuốn năm khôi lỗi phá vây. Phụng tông chủ dẫn môn nhân dựng kim sắc đao kiếm pháp trận, Địa Mộng triệu hồi đàn chim gáy huyết sắc, khiến một trận đại chiến bất ngờ bùng nổ ngoài Thiên Đỉnh Cung."},{"chuong":2371,"tieuDe":"Vạn Linh Huyết Tỷ","tomTat":"Hàn Lập và Băng Phách được truyền tống ra khu vực gần rìa Vạn Nguyệt Sơn Mạch, sau đó Băng Phách quyết định ẩn cư vài năm để củng cố cảnh giới Đại Thừa và tế luyện những trọng bảo mới nhận. Hai người chia đường, còn Hàn Lập dùng phù lục triệu tập Chu Quả Nhi cùng Hoa Thạch Lão Tổ và dự định tiếp tục lưu lại Huyết Thiên Đại Lục hoặc tới Lôi Minh Đại Lục. Tin tức sau trận chiến cho biết Huyết Hợp Ngũ Tử đã bị tiêu diệt, Thiên Khuyết và Địa Mộng trọng thương, Phụng tông chủ vẫn lạc, trong khi chuyện Băng Phách nhận truyền thừa Thiên Đỉnh Chân Nhân lan khắp đại lục nhưng vai trò của Hàn Lập hoàn toàn không được nhắc tới. Một năm rưỡi sau, trong một sơn cốc bí mật, thanh niên áo đen đã giết Yên Vũ Chân Nhân và dùng khí tức Vạn Linh Huyết Tỷ vừa hoàn thành huyết tế để áp chế tu vi những Đại Thừa còn lại. Lão giả xà văn biến thành Cự Xà bốn cánh xanh để chạy trốn nhưng bị hư ảnh Ấn Tỷ khóa cứng, diệt cả thân thể lẫn Nguyên Anh rồi hấp thu linh quang. Đại hán áo giáp tím liều mạng triệu pháp tướng, phóng lôi cầu, tự bạo hơn mười pháp khí và từ bỏ thân thể để Nguyên Anh ẩn độn. Chương kết thúc khi thanh niên áo đen không né tránh đòn phản công mà bình thản đưa bàn tay giấu sau lưng ra phía trước."},{"chuong":2372,"tieuDe":"Lục Dực Lại Xuất Hiện","tomTat":"Thanh niên áo đen dùng vách tường tinh thể bảy màu chặn hợp kích, sau đó phá thuấn di và tiêu diệt Nguyên Anh của Đại hán. Hắn phát hiện Lục Dực cùng Băng Phượng đang ẩn nấp, tự nhận là Chân Tiên hạ giới và ra lệnh cho cả hai làm Linh nô. Lục Dực cự tuyệt, dùng viên châu màu xanh tạo cặp linh cánh thứ tư rồi hiện nguyên hình sương công tám cánh, mang Băng Phượng đào thoát. Thanh niên áo đen thu dòng sông máu để tăng pháp lực nhưng lập tức bị lực lượng giới diện áp chế, khiến khí tức tiêu tán và bản thân phun máu bạc. Dù không thể vận dụng toàn lực, hắn vẫn tiếp tục truy đuổi hai linh vật. Hai ngày sau, Lục Dực tiết lộ đã thu nạp Tố Âm tinh khí và muốn tìm Tố Âm tộc để học pháp thuật giúp đạt chân thân. Khi hai người còn đang bàn cách đối phó, Lục Dực đột ngột cảm ứng được Chân Tiên đã đuổi tới gần."},{"chuong":2373,"tieuDe":"Thiên Cơ Toái","tomTat":"Lục Dực mang theo Băng Phượng hóa thành rết tám cánh xuyên núi đào tẩu, nhưng thanh niên áo đen vẫn nhiều lần lần đúng tung tích, buộc hắn phải liên tục hao tổn Tố Âm tinh khí suốt nhiều tháng. Tại Huyết Thiên, Bích Ảnh nhận tin Yên Vũ chân nhân cùng hai Đại Thừa đã bị một đối thủ duy nhất giết chết ở Tề Vân sơn mạch, trong khi phản ứng của Bản Mệnh Bài từng bị che lấp. Hung ma tiếp tục dùng huyết hà hủy diệt toàn bộ sinh linh và hàng chục tông môn tại Đại Long Quốc, khiến Huyết Cốt Môn cùng các đại thế lực chuẩn bị thành lập Đồ Ma Minh. Bích Ảnh cử Quân Dịch Mộng dự đại hội, đồng thời điều phối Văn Tâm Phượng, Lôi đại nhân, Hàn Lập và Huyết Sát cho cuộc chiến Cường giả sắp tới. Sau đó, bảo vật Thiên Cơ được ông tế luyện bằng máu xuất hiện vết nứt trên văn trận và đồ án Thái Cực, báo hiệu kiếp nạn số mệnh có thể giáng xuống trong cuộc chiến. Không chịu phó mặc cho thiên mệnh, Bích Ảnh quyết định tăng thêm hậu thủ rồi dùng ánh sáng lục khiến trận bàn trắng bên trong bảo vật hóa thành bột phấn."},{"chuong":2374,"tieuDe":"Đại Chiến Sắp Bắt Đầu","tomTat":"Sau khi dò xét Thượng Cổ tế đàn cuối cùng trên Lạc Triều thảo nguyên mà không thu được manh mối, Hàn Lập nhận tín hiệu triệu tập của Hách Liên Thương Minh và quyết định thực hiện cam kết trợ chiến. Nhóm ba người tới Thiên Mã thành, trực tiếp vượt qua cấm chế cấm không rồi dùng phá không truyền tống trận tại phân bộ Thương Minh để sang tiểu giới chiến trường. Bích Ảnh đích thân nghênh đón Hàn Lập, hóa giải khúc mắc từ lần thử nhau bằng Phệ Phật Đồ và giới thiệu Văn Tâm Phượng, một trưởng lão được chọn xuất chiến. Văn Tâm Phượng giải thích mối liên hệ lâu đời giữa Huyễn Tâm môn và Hách Liên Thương Minh, còn Bích Ảnh cho biết Lôi đại nhân cùng Huyết Sát sắp tới hội quân. Cuộc chiến cường giả còn hai tháng nữa sẽ diễn ra tại biên giới giữa địa bàn Thương Minh và Minh giới, trong khi đại quân hai bên cũng có thể được điều động để đề phòng biến cố. Hàn Lập được đưa tới một cứ điểm tiền tuyến phòng vệ nghiêm ngặt, giao Chu Quả Nhi và Hoa Thạch lão tổ thay phiên chờ lệnh rồi vào mật thất đả tọa dưỡng sức trước đại chiến."},{"chuong":2375,"tieuDe":"Âm Ti Ngũ Vương","tomTat":"Hai tháng sau, Hàn Lập nhận lời triệu tập của Bích Ảnh và gặp Văn Tâm Phượng cùng Lôi Nguyên, còn Huyết Sát vì gặp trở ngại trên đường nên chưa tới. Đoàn quân dùng hàng chục pháp khí phi hành hình đảo chở hàng ngàn giáp sĩ tới sơn mạch giáp Minh Giới, sau đó nhanh chóng dựng cứ điểm, bố trí pháp trận và khôi lỗi tuần tra. Bích Ảnh giải thích cuộc chiến sẽ diễn ra trên năm ngọn núi, mỗi bên cử năm cường giả, không hạn chế thần thông hay pháp bảo và chỉ kết thúc khi có người nhận thua hoặc phân định sinh tử. Hàn Lập thăm dò khả năng người thắng sớm can thiệp trận đấu khác, trong khi Bích Ảnh tiết lộ đã bí mật điều thêm quân đề phòng đối phương bội ước. Ở phía Minh Giới, năm quỷ vương thuộc Âm Ti Thập Vương họp trong cung điện máu giữa những ngọn núi xương trắng và tranh luận về sức mạnh của đối thủ. Một quỷ vương muốn lấy tinh hồn cường giả để hoàn thiện Ngũ Âm Tỏa Tâm Chùy, còn những người khác nhắc tới việc Minh Hùng đang bận tranh đoạt âm giới với Dạ Quỷ nhất tộc. Cuối cùng, quỷ vương có giọng âm trầm thể hiện uy thế cao nhất, đánh giá phe mình có nhiều phần thắng và hỏi Thất Khiếu Vương về kế hoạch chuẩn bị sau trận."},{"chuong":2376,"tieuDe":"Hung Ty Vương","tomTat":"Năm cường giả Minh giới xác nhận ngàn vạn quỷ binh đã vào vị trí, đồng thời quyết định dùng các cuộc quyết đấu để phân định quyền kiểm soát Tiểu Thế Giới vì không thể xâm nhập ngược Chủ Giới Diện của đối phương. Sau khi trận pháp sư hai phe hoàn tất và kiểm tra cấm chế tại năm ngọn núi, Bích Ảnh triệu tập Hàn Lập, Huyết Sát, Lôi đại nhân và Văn Tâm Phượng rồi đưa cả đội tới chiến trường. Hai phe lần lượt chia năm cường giả vào năm ngọn núi, mỗi nơi được cấm chế hai tầng phong kín để ngăn quan sát và can thiệp từ bên ngoài. Hàn Lập gặp đối thủ tự xưng Hung Ty Vương, một cường giả Minh giới mang thân thể đầu trâu thân người do đoạt xá hung thú rồi luyện hóa. Hung Ty Vương dùng Lang Nha Bổng đỏ tươi tạo nhiều hư ảnh đánh xuống, nhưng Hàn Lập tùy ý tung quyền ảnh vàng triệt tiêu toàn bộ thế công. Không để đối thủ kịp suy tính, Hàn Lập gọi trường kiếm màu xanh ra và phóng vô số tia sáng xanh mở màn đợt phản kích."},{"chuong":2377,"tieuDe":"Ngũ Ma","tomTat":"Hung Ty Vương dùng tiếng rống tạo hào quang chân không rồi điều khiển Lang Nha Bổng gọi ra hắc long, nhưng Hàn Lập hợp phi kiếm thành liên hoa kiếm và chém nát đòn công kích. Hung Ty Vương biến binh khí thành Huyết Phiên Kỳ, triệu xuất Ngũ Ma được luyện từ Nguyên Anh của những cường địch từng bị hắn giết. Hàn Lập gọi Kim Đồng ra nghênh chiến, khiến Phệ Kim Trùng Vương cùng năm quỷ yêu rơi vào thế giằng co giữa kiếm khí kim sắc, lôi hỏa màu đen và cốt châu huyết sắc. Hung Ty Vương tiếp tục dùng mặt quỷ phóng dải lụa đen xuyên phá Nguyên Từ Thần Quang, trói Hàn Lập trong hắc kén phủ huyết diễm rồi dùng búa đen chém xuống. Hàn Lập không bị thương mà biến thành Kim Mao Cự Viên ba đầu sáu tay, dùng ngân diễm nuốt huyết diễm và phá kén thoát ra. Hắn tung quyền ảnh dày đặc đánh vỡ màn hào quang chân không, nhưng Hung Ty Vương kịp biến binh khí thành lá chắn xương và dùng mặt quỷ hút sạch những quang cầu còn lại."},{"chuong":2378,"tieuDe":"Quỷ Khí Cuồn Cuộn","tomTat":"Hung Ty Vương dùng tinh huyết thúc động lá chắn mặt quỷ thi triển Thôn Phệ Thiên Địa, nhưng Hàn Lập hợp sáu kim cầu thành vòng xoáy vàng để đối kháng. Hai bên tiếp tục hóa thành pháp thân cự đại giao chiến trực diện, khiến sáu trọng binh của Hàn Lập vỡ vụn còn hai tay Hung Ty Vương bị đánh thành huyết vụ. Hung Ty Vương tái sinh cánh tay rồi liên tiếp tung hắc long, gai huyết sắc và bầy quái trùng, song Hàn Lập lần lượt hóa giải bằng lôi mãng, cương phong và ngân diễm. Nguyên thần thứ hai của Hung Ty Vương bất ngờ đánh lén nhưng không phá được vân trận bạc hộ thể, sau đó dù bị chém đôi vẫn hóa khí thoát khỏi lưới thần lôi và nhập lại vào bản thể. Nhận thấy thủ đoạn thông thường không thể uy hiếp Hàn Lập, Hung Ty Vương triệu hồi Ngũ Ma nhập thân để phát động bản mạng thần thông, làm hơn một nghìn mặt quỷ hiện ra trên cơ thể. Đúng lúc các mặt quỷ bắt đầu mở mắt, một đạo kiếm quang vàng bất ngờ chém rơi đầu cự nhân. Một tiểu nhân màu vàng lập tức hiện thân và phóng vô số kiếm khí vô hình về phía thân thể không đầu, trong khi kết cục của Hung Ty Vương vẫn chưa rõ."},{"chuong":2379,"tieuDe":"Thiên Quỷ Lực Lượng","tomTat":"Kim Đồng dùng tinh quang bổn mạng phá màn hào quang và chém đầu Hung Ty Vương, nhưng đối thủ lập tức tiêu hao lực lượng Lệ Quỷ để tái tạo, đồng thời tiết lộ mình có hơn một nghìn mạng sống. Hung Ty Vương dồn các mặt quỷ vào hai cánh tay, tạo thành hai cự trảo mang Thiên quỷ lực lượng để chia nhau truy kích Kim Đồng và Hàn Lập. Kim Đồng nhiều lần chém nát cự trảo nhưng không thể liên tục vận dụng tinh quang, còn Hàn Lập cũng chưa thể phá thế công bằng quyền lực, ngân diễm, phi kiếm và văn trận hộ thể. Hàn Lập buộc phải thi triển tam giai biến thân của Niết Bàn thân thể, dung nhập hư ảnh Thiên Phượng, Chân Long và Côn Bằng để ma hóa cự viên ba đầu sáu tay. Sau khi bóp nát cự trảo, hắn dùng Kim Hà nuốt lưới đen và tạo sáu vòng xoáy mang lực lượng Pháp tắc để hút sạch các mặt quỷ. Hung Ty Vương tiếp tục thi triển Thiên Mục chi lực, nhưng cột sáng xanh bị bàn tay tử kim của Hàn Lập bóp nổ mà không gây thương tổn. Cuối chương, Hàn Lập gọi ra trường kiếm màu xanh lá cây, biến nó thành lưỡi kiếm khổng lồ rồi dùng cả sáu tay chém về phía Hung Ty Vương."},{"chuong":2380,"tieuDe":"Liên Thai Huyết Cốt","tomTat":"Hàn Lập toàn lực thúc giục Huyền Thiên Trảm Linh Kiếm, dùng lực pháp tắc trấn áp Hung Ty Vương và tiếp tục truy sát dù đối phương đã nhận thua. Hung Ty Vương liên tiếp tự bạo mặt quỷ, thân thể và huyết vụ để trốn chạy, nhưng cuối cùng tàn khu, tinh hồn, Nguyên thần thứ hai cùng quỷ vật trong hắc khí đều bị Hàn Lập và Kim Đồng tiêu diệt. Tại một thế giới khác, bóng đen trong quan tài đá xanh nhận biết bản thể đã chết, tuyên bố sẽ đúc lại thân thể và báo thù. Hàn Lập thu viên châu đỏ chứa vô số mặt quỷ rồi cùng Kim Đồng phá cấm chế quanh ngọn núi của Văn Tâm Phượng. Bên trong, một con chồn có cánh đang giao chiến giằng co với thằn lằn hai đầu, còn Văn Tâm Phượng dùng trận bàn trắng ngà đối kháng Bạch Cốt ngồi trên đài sen giữa huyết hải. Khi vận dụng Linh Mục quan sát, Hàn Lập phát hiện khoảng không giữa hai người thực chất là một thế giới vô hình có hai cực sinh diệt hoàn toàn đối lập."},{"chuong":2381,"tieuDe":"Chuyển Luân Vương","tomTat":"Hàn Lập nhận ra Phật Cốt Vương và Văn Tâm Phượng đều đang vận dụng một phần Linh Vực, bèn giao Phệ Kim Trùng Vương đối phó thằn lằn hai đầu còn mình hóa thành Lôi Bằng tấn công biển máu. Phệ Kim Trùng Vương phá hủy chiếc bát màu đỏ và chém thằn lằn thành nhiều đoạn, để con chồn của Văn Tâm Phượng ăn sạch đối thủ. Hàn Lập dùng Ích Tà Thần Lôi tiêu diệt toàn bộ giao long huyết sắc, buộc Phật Cốt Vương cho thế giới lửa đỏ tự hủy rồi dùng đài sen màu đen thuấn di bỏ chạy. Hàn Lập và Văn Tâm Phượng truy đuổi tới ngọn núi trung tâm, nơi Bích Ảnh cùng Chuyển Luân Vương đang đánh cờ thay cho việc đấu pháp sinh tử. Chuyển Luân Vương không truy cứu cái chết của Hung Tư Vương và công nhận phe Bích Ảnh đã thắng hai trận đầu. Tuy nhiên, ông yêu cầu Hàn Lập, Văn Tâm Phượng và Phật Cốt Vương ở nguyên tại chỗ để không can thiệp hai trận còn lại, còn Bích Ảnh thay họ chấp nhận điều kiện này."},{"chuong":2382,"tieuDe":"Thắng Bại","tomTat":"Trong lúc Bích Ảnh và Chuyển Luân Vương tiếp tục ván cờ quyết định lợi ích, Lôi đạo hữu bị thiếu nữ áo tím đánh trọng thương và phải thừa nhận thất bại. Trước trận cuối, Chuyển Luân Vương cảnh báo Thất Khiếu Vương là một trong ba cường giả mạnh nhất Âm Ti Thập Vương. Một ngày sau, Thất Khiếu Vương rời chiến trường với chiếc đầu khô quắt của Huyết Sát, giúp Minh giới giành trận thắng thứ hai. Tuy nhiên, tổng kết năm trận vẫn là Minh giới thắng hai và thua ba, khiến Chuyển Luân Vương chủ động nhận thua. Hai bên thống nhất để Minh giới nhận bốn phần tài nguyên của tiểu thế giới, còn liên minh của Bích Ảnh nhận sáu phần. Chuyển Luân Vương đánh giá thần thông của Hàn Lập không dưới Thất Khiếu Vương rồi cùng các Quỷ Vương rút về quỷ vực. Sau cùng, Văn Tâm Phượng nêu nghi vấn Huyết Sát chưa chết thật vì từng có tin đồn ông đã luyện thành một hóa thân giống hệt bản thể và có thực lực gần tương đương."},{"chuong":2383,"tieuDe":"Thảo Ma","tomTat":"Sau cuộc chiến cường giả, Bích Ảnh tiết lộ người ngã xuống chỉ là hóa thân được Huyết Sát tế luyện hơn vạn năm, còn bản thể của hắn vốn đã nguyên khí đại thương. Lôi đạo hữu kể rằng mình phải nhận thua một nữ cường giả Minh giới vì quỷ ảnh của nàng có thể khiến cơ thể hóa thành hư không, đồng thời làm hắn hao tổn nhiều chí bảo bảo mệnh. Trên thuyền đen, Hàn Lập nghiên cứu Nguyên Cương Tráo do Bích Ảnh giao và pháp quyết tinh luyện sấm sét của Thiên Đỉnh Chân Nhân do Băng Phách trao, chuẩn bị dùng pháp quyết thứ hai để tinh luyện Ích Tà Thần Lôi. Bích Ảnh sau đó họp các trưởng lão Thương Minh và quyết định nhận lời đến xem Huyết Cốt Môn cùng mười hai tu sĩ Đại Thừa bố trí Khốn Ma Đại Trận tiêu diệt một hung ma. Khi ở một mình, hắn lo lắng về Thiên Cơ Toái và đại kiếp nạn chưa rõ đã qua hay vẫn chưa tới. Nửa tháng sau, Hàn Lập chỉ huy đám rối khai quật một tế đàn, còn Bích Ảnh dẫn vệ sĩ tới một tòa thành lớn trên Huyết Thiên Đại Lục. Gần đó, Lục Dực và Băng Phượng kiệt sức ẩn náu trong lòng núi sau thời gian dài bị một đại địch không thể chống cự truy đuổi."},{"chuong":2384,"tieuDe":"Mai Phục","tomTat":"Lục Dực và Băng Phượng bàn cách thoát khỏi Chân Tiên đang truy sát, nhưng vừa rời nơi ẩn náu đã bị bốn Đại Thừa Huyết Thiên chặn đường. Gã mặt xanh đại diện nhóm này đề nghị Lục Dực làm mồi nhử, dẫn kẻ truy sát vào một trận địa đã chuẩn bị để trả thù việc hắn huyết tế hàng tỉ sinh linh Huyết Thiên. Lục Dực nhận lời nhưng âm thầm muốn Chân Tiên và lực lượng mai phục lưỡng bại câu thương, qua đó giúp mình cùng Băng Phượng thoát thân, trong khi thanh niên gầy gò áo đen vẫn tiếp tục bám theo. Ở tuyến khác, Hàn Lập hoàn tất thi pháp trên tế đàn và xác định cửa vào Tiểu Linh Thiên nằm dưới đáy biển sâu, cách Huyết Thiên đại lục khá xa. Hắn giao Hoa Thạch phụ trách tìm kiếm dưới nước rồi đưa Hoa Thạch cùng Chu Quả Nhi lên thuyền xuất phát. Bảy ngày sau, tại một sa mạc bí ẩn, hàng vạn đệ tử Huyết đạo cùng hơn mười Đại Thừa đã vào vị trí trong hai tòa siêu cấp trận pháp, chờ mục tiêu bị dẫn tới."},{"chuong":2385,"tieuDe":"Thiên Địa Lưỡng Trận","tomTat":"Tại Huyết Thiên, Xa Kỵ và lão giả mập mạp chờ Lục Dực dẫn Mã Lương vào sa mạc đã được bố trí mai phục, trong khi Bích Ảnh cùng ba Đại Thừa khác theo dõi chiến trường từ một tòa tháp vàng trong đại thành. Lục Dực và nữ tử mặc cung trang bạc cuối cùng chạy tới trung tâm sa mạc, kéo theo Mã Lương đang hóa thành lôi đình bảy màu truy đuổi phía sau. Thiên Địa Lưỡng Cực đại trận lập tức phát động từ cả dưới đất lẫn trên trời, còn mười hai lão tổ Đại Thừa Huyết đạo xuất hiện bao vây mục tiêu. Mã Lương nhanh chóng phá trạng thái định thân, tuyên bố sẽ giết sạch phe mai phục rồi tiếp tục truy sát Lục Dực và người đồng hành. Lão giả chân trần áo đen phát lệnh khai chiến, khiến các Đại Thừa đồng loạt xuất bảo vật trong khi hai tầng trận dùng chỉ bạc, chữ “Phong” và dao động pháp tắc để phong tỏa Mã Lương. Tuy nhiên, Mã Lương bộc phát khí tức hủy diệt, làm xiềng xích tử kim quanh thân phát sáng và hút Thiên Địa nguyên khí toàn sa mạc hội tụ về mình. Nhận ra đại trận không thể khống chế đối phương, Tiêu Minh lấy Hoàng Phong Đồ và thi triển Phong khởi, khiến những tường gió vàng cuốn cát bụi từ bốn phương tám hướng ép vào trung tâm chiến trường."},{"chuong":2386,"tieuDe":"Tuyệt Thế Hung Uy","tomTat":"Tiêu Minh thôi động Hoàng Phong Đồ, khiến cuồng phong và bão cát che phủ sa mạc, ngăn Quan Thiên Kính tiếp tục quan sát chiến trường. Trong tòa tháp vàng, Bích Ảnh cảm thấy nguy hiểm cực độ từ Hung Ma, còn ba vị Đại Thừa ban đầu chưa tin vào dự cảm của ông. Một luồng kim quang bất ngờ xuyên qua cuồng phong và làm Quan Thiên Kính nổ tung, sau đó lão giả mắt ưng cũng không thể liên lạc với Tiêu Minh. Bích Ảnh, Linh Vân phu nhân, Hà đại tiên sinh và lão giả mắt ưng quyết định ở lại, huy động hơn mười vạn đệ tử cùng đại trận trong thành để chuẩn bị nghênh chiến. Trên sa mạc, Mã Lương đã biến thành Cự Nhân vàng ngàn trượng và thi triển Linh Vực, tạo thế giới kim sắc hỏa diễm cùng những núi lửa khổng lồ để nghiền nát pháp trận và tiêu diệt lực lượng Đại Thừa. Hắn bắt Huyết Thiềm, dò xét Nguyên Thần để biết Huyết Đạo tông môn và Hách Liên Thương Minh đang tụ tập, rồi thiêu sinh linh này thành tro. Giới lực sau đó phản phệ khiến Mã Lương phải thu thân và phun huyết, nhưng Kim Phẩm Thế Thân Tiên Phù do tổ sư ban cho đã giúp hắn tránh bị ép nổ tung, đồng thời vẫn còn đủ dùng thêm hai lần. Mã Lương quyết định quét sạch các cường giả Huyết Thiên và tiết lộ rằng hai kẻ chạy thoát đã bị gieo hạt giống Chân Hồn nên khó thoát khỏi cuộc truy sát."},{"chuong":2387,"tieuDe":"Tình Cờ Gặp Trên Biển","tomTat":"Sau trận chiến diệt Ma tại thành Bích Ảnh, toàn bộ cường giả Đại Thừa của các đại tông môn do Huyết Cốt Môn cầm đầu đều tử trận, chỉ Linh Vân phu nhân trọng thương sống sót và đưa Vạn Cổ Sơn vào trạng thái phong bế vạn năm. Trong lúc Huyết Thiên đại lục tiếp tục chấn động bởi những vụ huyết tế, Hàn Lập đã đưa Chu Quả Nhi và Hoa Thạch rời đại lục, dùng Mặc Linh Thánh Chu vượt biển suốt nửa năm. Khi phát hiện một cuộc giao tranh cấp Đại Thừa, họ tìm thấy ba trưởng lão Trấn Hải Cung đang vây đánh một Giao Long bạc trọng thương. Hàn Lập triệu Pháp Tướng ba đầu sáu tay, dùng linh áp áp đảo và lời đe dọa buộc ba hải thú phải rút lui. Giao Long bạc hóa thành Đồ Giảo, chính là Nhân Diện Giao Hàn Lập từng gặp tại đấu giá hội Vân Thành. Đồ Giảo tiết lộ mình bị đại địch ám toán nên không thể thi triển thần thông cấp Đại Thừa, còn con gái hắn nhận ra Hàn Lập nhờ khí tức quen thuộc của mụ mụ. Hàn Lập đề nghị kiểm tra nội thương cho Đồ Giảo và cảnh báo rằng tình trạng của nữ đồng không thể kéo dài lâu hơn."},{"chuong":2388,"tieuDe":"Trấn Hải Cung","tomTat":"Đồ Giảo cầu Hàn Lập chữa trị cho con gái và chấp nhận hỗ trợ tìm một địa điểm dưới đáy biển làm điều kiện trao đổi. Chỉ sau một đêm, thương thế của hai cha con đều được chữa khỏi, còn Đồ Giảo khôi phục đủ thần thông Đại Thừa để đối phó lực lượng truy sát. Hắn tiết lộ Trấn Hải Cung có ba Cung chủ Đại Thừa cùng lực lượng hải thú đông đảo, trong khi Thanh Giao Điện đang mở cuộc tấn công để kiềm chế hai Cung chủ khác. Dựa vào manh mối từ Thượng cổ Tế Đàn, Đồ Giảo và Hoa Thạch thu hẹp được khu vực có thể chứa lối vào Tiểu Linh Thiên. Hai tháng sau, đoàn Hàn Lập tới một hải vực đầy đá san hô và triển khai hàng nghìn khôi lỗi cùng thần niệm của hai Đại Thừa để dò tìm. Đúng lúc Hàn Lập cảm thấy lần tìm kiếm này có thể thu được kết quả, đại quân Trấn Hải Cung do một nam tử râu dài đội ngọc quan chỉ huy tiến đến. Người này ra lệnh bố trí Vạn Thú Đại Trận nhằm vây giết Hàn Lập, còn quân tiên phong nhanh chóng phá hủy toàn bộ đội khôi lỗi chặn đường."},{"chuong":2389,"tieuDe":"Tiểu Linh Thiên","tomTat":"Kim Đồng bất ngờ xuất hiện giữa đại quân Hải Thú, phá bảo bối phòng ngự rồi tiêu diệt cả thân thể lẫn nguyên thần của nam tử râu dài chỉ huy chúng. Sau khi đánh tan số Hải Thú còn lại và lấy túi trữ vật, Kim Đồng biến mất, còn Hàn Lập nhận được phù lục báo rằng cửa vào Tiểu Linh Thiên đã được tìm thấy. Dưới đáy biển, Hoa Thạch và Đồ Giảo dẫn hắn tới một cự thạch đỏ thẫm có dao động không gian. Hàn Lập bảo vệ Chu Quả Nhi, xông vào cự thạch và hóa thành Kim Mao Cự Viên để phá sức ngưng trệ của cấm chế, từ đó vượt qua quầng sáng bảy màu. Hai người tới một khu rừng trong Tiểu Linh Thiên, nơi có linh khí kém Linh Giới, rồi dùng bản đồ xác định vị trí hiện tại là Lục Hải thuộc lãnh địa Lục Linh Tộc. Hàn Lập quay lại đưa Hoa Thạch cùng Mặc Linh Thánh Thuyền qua thông đạo, trong khi cha con Đồ Giảo cảm tạ rồi rời đi. Cuối cùng, Hàn Lập nói rằng mục đích của hắn là gặp mẹ Chu Quả Nhi, nhưng vùng Nhân tộc nơi nàng từng sống lại nằm ở phía đối lập và cách Lục Hải cực kỳ xa."},{"chuong":2390,"tieuDe":"Lục Linh Tộc","tomTat":"Chu Quả Nhi cảnh báo Hàn Lập rằng Lục Linh Tộc là dị tộc mạnh nhất Tiểu Linh Thiên và có thể câu thông Cổ Thụ Tổ Linh. Không muốn dây dưa, Hàn Lập dùng trận kỳ che giấu thông đạo, ngăn cách dao động không gian, phục nguyên cảnh vật rồi để lại một chưởng ấn khổng lồ làm lời cảnh cáo. Thốc Ảnh cùng hai cường giả Lục Linh Tộc phát hiện chưởng ấn, nhận ra người ra tay mạnh hơn hẳn họ nhưng vẫn quyết định truy đuổi nhờ lợi thế triệu hoán Tổ Linh tại Lục Hải. Ở phía trước, khoảng một nghìn tộc nhân Lục Linh Tộc vây đánh Mặc Linh Thánh Chu, trong khi Ma Tinh Khôi Lỗi trên thuyền dùng cột sáng và lôi hỏa phản kích. Hơn trăm tộc nhân hợp lực tạo cự lá nhằm trói thánh thuyền, song bị cự thủ màu xanh của Hàn Lập bóp nát và chịu phản phệ. Hàn Lập sau đó hiện thân, quyết định tiêu diệt những kẻ cản đường và kích nổ lôi cầu vàng, khiến vô số hồ quang bắn về phía đội quân đang tháo chạy."},{"chuong":2391,"tieuDe":"Cổ Thụ Tổ Linh","tomTat":"Sau khi lực lượng truy kích của Lục Linh tộc gần như bị tiêu diệt, ba cường giả Hợp Thể gồm một nữ hai nam đuổi kịp Mặc Linh Thánh Chu và nhận ra Hàn Lập là tu sĩ Đại Thừa đến từ giới diện khác. Vì muốn tra hỏi về lối vào Tiểu Linh Thiên, họ kích hoạt hình cổ thụ trên cánh tay, hút mộc linh khí từ Lục Hải rồi ký phụ ba Cổ Thụ Tổ Linh, hóa thành những Cự Nhân có sức mạnh tạm thời đạt cấp Đại Thừa. Hàn Lập nhận ra lôi thuộc tính có thể khắc chế đối phương nên gọi Giải đạo nhân ra nghênh chiến và dặn ông bắt sống một người. Giải đạo nhân hóa thành Hoàng Kim Giải, dùng lôi điện bạc cùng lôi trận khổng lồ bao phủ và áp chế cả ba Cự Nhân. Sau thời gian một chén trà, ông trở về thuyền và giao cho Hàn Lập chiếc bình bạc giam Nguyên Anh héo rút của nam tử cao gầy Lục Linh tộc. Mặc Linh Thánh Chu tiếp tục hành trình, còn Lục Linh tộc từ đó không dám phái người tới ngăn cản nữa."},{"chuong":2392,"tieuDe":"Chấn Động Nhân Tộc","tomTat":"Tin một vị Đại Thừa Nhân tộc diệt ba cường giả Lục Linh Tộc, kể cả Cổ Thụ Tổ Linh, nhanh chóng làm chấn động toàn bộ Tiểu Linh Thiên. Lục Linh Tộc rút nhân thủ về Lục Hải, trong khi các dị tộc phái người điều tra và những cường giả Hợp Thể của Nhân tộc tổ chức hội nghị đánh giá tình hình. Họ suy đoán người mới xuất hiện đến từ Linh giới, nhìn thấy cơ hội vượt giới diện chi lực để rời Tiểu Linh Thiên nhưng vẫn quyết định chuẩn bị đề phòng. Nam Cung Uyển đang bế quan gửi phi kiếm truyền thư, xác nhận sẽ cùng mọi người gặp vị Đại Thừa khi hắn tiến vào địa bàn Nhân tộc. Hơn nửa tháng sau, Mặc Linh Thánh Chu chở đoàn Hàn Lập vượt biên giới mà không bị ngăn cản, dù hành trình liên tục bị bí mật theo dõi và báo tin. Hàn Lập đưa Chu Quả Nhi trở về đoàn tụ với mẫu thân Thạch Tiêm Vân, nhận lời vào động phủ của bà để hỏi một số chuyện và lệnh Hoa Thạch lão tổ ở lại bên ngoài."},{"chuong":2393,"tieuDe":"Gặp Mặt Thượng","tomTat":"Sau khi Hoa Thạch trở về cự thuyền, Hàn Lập theo Thạch Tiêm Vân và Chu Quả Nhi vào động phủ, trong khi các tu sĩ Nhân tộc lân cận bí mật quan sát và suy đoán hắn là một tồn tại Đại Thừa. Tại đại sảnh, hắn nhận ra Tuyết Nhi là Tuyết Tùng thú sắp khai mở linh trí hoàn toàn nên ban cho nó một viên linh đan, giúp nó hóa đi xương ngang và nói được tiếng người. Hàn Lập sau đó xác nhận Thạch Tiêm Vân đã truyền Tố Nữ Luân Hồi Công cho Chu Quả Nhi, nhưng công pháp vốn đến từ một nữ tiền bối bí ẩn. Do bị lời thề ràng buộc, Thạch Tiêm Vân không thể tiết lộ danh tính người ấy mà chỉ nhận lời chuyển tin xin phép. Thiếu nữ áo trắng trong mật thất băng phong nhận được quang văn và đồng ý tới gặp Hàn Lập vào sáng hôm sau. Hàn Lập kín đáo lộ vẻ kích động, tìm hiểu thêm về Tiểu Linh Thiên rồi trở lại Mặc Linh Thánh Thuyền. Sự xuất hiện của hắn tiếp tục thu hút các tu sĩ cao giai địa phương, khiến nhiều người tìm đến Thạch Tiêm Vân để dò hỏi tin tức."},{"chuong":2394,"tieuDe":"Gặp Mặt Hạ","tomTat":"Lăng Phi Tiên công khai thân phận của Hàn Lập, khiến các tu sĩ Nhân tộc tại Tiểu Linh Thiên kéo đến thánh thuyền mong được bái kiến. Sáng hôm sau, Hàn Lập thu hồi cấm chế và chính thức đoàn tụ với Nam Cung Uyển, người cũng chính là Nguyệt tiên tử. Nam Cung Uyển kể rằng trận tử chiến giữa La Hầu và Bách Đầu Trùng đã phá vỡ không gian tiết điểm, cuốn nàng cùng thi thể hai Chân Linh vào Tiểu Linh Thiên. Hai tinh hạch Chân Linh thu được giúp nàng nhanh chóng tăng tiến tu vi và còn được dùng để bồi dưỡng mẹ Chu Quả Nhi làm người hộ pháp. Sau khi trao đổi chuyện cố nhân, nàng giải thích việc bí mật truyền Tố Nữ Luân Hồi Công cho Chu Quả Nhi thông qua mẹ cô bé. Hàn Lập hứa tự mình hộ pháp, cung cấp thêm thủ đoạn giúp Nam Cung Uyển vượt Đại Thừa chi kiếp và tiết lộ chiến lực của mình đủ đối đầu Thượng Cổ Chân Linh. Trước đề nghị đưa một số bằng hữu cùng hậu bối ưu tú về Linh giới, hắn nhận ra việc rút hết cường giả sẽ khiến Nhân tộc ở lại suy yếu. Vì thông đạo không đủ ổn định để di chuyển toàn tộc, Hàn Lập yêu cầu các bên cử đại diện đến thánh thuyền thương nghị sau ba ngày."},{"chuong":2395,"tieuDe":"Uy Trấn Chư Tộc","tomTat":"Hàn Lập triệu kiến bốn tu sĩ Hợp Thể Nhân tộc và đồng ý đưa họ cùng hơn trăm hậu bối ưu tú trở về Linh Giới, nhưng trước hết yêu cầu họ an bài chu toàn cho đồng tộc còn ở lại Tiểu Linh Thiên. Nam Cung Uyển chính thức thu Chu Quả Nhi làm đệ tử, còn Hoa Thạch lão tổ dẫn Khôi Lỗi đi thu thập tài liệu đặc hữu. Trong những tháng tiếp theo, Hàn Lập và Nam Cung Uyển đi khắp Tiểu Linh Thiên uy trấn các Dị tộc. Hàn Lập một kích giết cường giả mạnh nhất Phong Linh Tộc, dùng lôi điện và kiếm quang tiêu diệt đàn cự trùng cùng thủ lĩnh mặt người, rồi phá đại trận của Nguyệt Nha Tộc và đánh tan ba đại trưởng lão. Dạ Miên Tộc lựa chọn thần phục, còn các Dị tộc khác cũng bị khuất phục trước uy thế áp đảo của hắn. Sau khi cuộc tuyển chọn hậu bối hoàn tất, Hàn Lập dẫn Nam Cung Uyển, các tu sĩ Hợp Thể và đoàn người tới Lục Hải. Tại gốc đại thụ khổng lồ, hắn mở cổng quầng sáng bảy màu để Mặc Linh Thánh Thuyền xuyên qua, chính thức rời Tiểu Linh Thiên."},{"chuong":2396,"tieuDe":"Biến Động Tại Huyết Thiên","tomTat":"Mặc Linh Thánh Chu đưa Hàn Lập, Nam Cung Uyển và đông đảo tu sĩ Tiểu Linh Thiên trở lại Linh Giới trước khi thông đạo bảy màu tan vỡ. Hàn Lập tự tin có thể đối đầu những cường giả Đại Thừa hàng đầu, nhưng vẫn cho rằng kế hoạch chấn hưng Nhân tộc cần được cân nhắc lâu dài. Muốn trở về Phong Nguyên đại lục, hắn đưa đoàn người tới một thành thị ven biển Huyết Thiên để tìm phân minh của Hách Liên thương minh. Người phụ trách tại đây cho biết Bích Ảnh đã vẫn lạc, thương minh co rút hơn nửa lực lượng và đang do nhiều trưởng lão tạm thời đồng quản lý. Ông còn suy đoán hung ma là Chân Tiên hàng lâm, bởi kẻ này từng bị dây xích Pháp Tắc của giới diện phong bế phần lớn pháp lực. Hung ma đã huyết tế hơn mười nơi ở phía tây Huyết Thiên, tàn sát lực lượng cao tầng của Huyết Ngân tông rồi dùng pháp trận vượt đại lục tới Lôi Minh. Tại Lôi Minh đại lục, một thanh niên áo trắng bị thương nặng cùng nữ tử áo bào bạc đang chạy trốn kẻ truy đuổi, sau khi bị ép phải truyền tống vội vàng tới sai đại lục."},{"chuong":2397,"tieuDe":"Họa Thủy Đông Di","tomTat":"Trong lúc chạy trốn Mã Lương, Băng Phượng tiêu hao một phần bổn nguyên kỳ hàn để chữa kinh mạch và bổ sung chân nguyên cho Lục Dực. Sau khi hồi phục, Lục Dực thực hiện kế họa thủy đông di, dẫn kẻ truy sát vào lãnh địa Giác Xi tộc với ý định mượn các cường giả của siêu cấp thế lực này cầm chân hắn. Một tháng sau, Mã Lương dùng biển máu huyết tế toàn bộ Cái Linh thành, giết Đại Thừa trấn thủ Thiên Tượng cùng hơn trăm tu sĩ cao giai. Hắn tiếp tục đánh bại một Đại Thừa Giác Xi hóa thành ma tượng xanh, bắt Nguyên Anh đối phương để dò xét rồi ném vào biển máu. Mã Lương ra tối hậu thư buộc Giác Xi tộc giao Lục Dực và Băng Phượng trong ba ngày, nếu không sẽ tiếp tục huyết tế toàn tộc. Ở nơi cách Cái Linh thành rất xa, Lục Dực và Băng Phượng đã cải trang thành tộc nhân Giác Xi, tiếp tục tiến về một thành lớn khác sau khi biết kế sách dẫn họa của mình bước đầu phát huy tác dụng."},{"chuong":2398,"tieuDe":"Mất Tích","tomTat":"Lục Dực và Băng Phượng đem toàn bộ thần hồn ký phụ vào hai tu sĩ Giác xi tộc, nhờ đó tạm che giấu dấu vết trước Mã Lương nhưng phải chịu nhiều hạn chế và nguy hiểm. Hai người dự định lợi dụng xung đột giữa Mã Lương với Giác xi tộc để tìm truyền tống trận trở về Phong Nguyên, còn Băng Phượng xem Hàn Lập là phương án cuối để giải trừ Ấn ký thần hồn. Tại một chủ thành Giác xi tộc, Mã Lương đánh tan cuộc mai phục của sáu Đại thừa lão tổ nhưng cũng bị thương bởi nhiều kiện Huyền Thiên Tàn Bảo tự bạo. Hắn sau đó huyết tế liên tiếp ba thành lớn, buộc cao tầng Giác xi tộc triệu hồi Đề Long, Thái Tước và Dương Lộc từ không gian khác. Sau nhiều ngày đại chiến, cả Mã Lương lẫn ba Thượng cổ Chân linh đều mất tích, khiến kết quả cuộc chiến trở thành bí ẩn. Nhận được tin này, Lục Dực và Băng Phượng dùng truyền tống trận xuyên Đại lục trở về Phong Nguyên, trong khi Hàn Lập cũng đưa Nam Cung Uyển cùng những người đi theo trở về bằng một tuyến khác. Hàn Lập sau đó gặp Minh Tôn, nghe ông nói về cái chết của Bích Ảnh và sự suy giảm của bổn minh tại Huyết Thiên, rồi nhận định Mã Lương là tồn tại nghịch thiên không kém Minh Trùng Mẫu."},{"chuong":2399,"tieuDe":"Đề Nghị Của Minh Tôn","tomTat":"Minh Tôn đưa cho Hàn Lập tình báo mới, cho biết Hung Ma đã chém chết bốn Đại Thừa Giác Xi tộc, giao chiến với ba Thượng Cổ Chân Linh rồi mất tích tại Lôi Minh Đại Lục giữa những dấu vết không gian bất thường. Hai người nhận định đối phương nhiều khả năng chưa chết mà đã mượn lực lượng không gian để ẩn trốn, trong khi Phong Nguyên Đại Lục và Nhân tộc có thể trở thành mục tiêu huyết tế tiếp theo. Qua hai bức chân dung, Hàn Lập nhận ra Băng Phượng và suy đoán người mang bản thể Lục Dực ngô công là một cố nhân; cả hai đã bị Hung Ma truy sát từ Huyết Thiên sang Lôi Minh rồi cùng mất tung tích. Minh Tôn dựa trên những công pháp và bí thuật Tiên giới từng được Hung Ma thi triển để nhận định hắn có chín thành khả năng là Chân Tiên. Ông đề nghị tập hợp các Đại Thừa hàng đầu và Chân Linh cường đại, tận dụng việc phần lớn thực lực của đối phương đang bị phong ấn để ép hắn rời đi hoặc trấn áp hoàn toàn. Hàn Lập tạm chấp thuận kế hoạch nhưng tuyên bố sẽ rút lui nếu liên minh không tập hợp đủ cường giả Đại Thừa. Minh Tôn sau đó trao cho Hàn Lập một tấm phù truyền tin màu bạc nhạt để báo tin và triệu tập khi phát hiện hành tung Hung Ma."},{"chuong":2400,"tieuDe":"Xiềng Xích Pháp Tắc","tomTat":"Sau khi hoàn tất việc bàn bạc với Minh đạo hữu, Hàn Lập lên thuyền rời đại điện và hẹn sẽ kể rõ nội dung cuộc gặp cho Nam Cung Uyển. Mấy tháng sau, trong một không gian bí ẩn, thanh niên áo đen cùng Dương Lộc, Đề Long và Cự Tước màu xám đều bị Xiềng Xích Pháp Tắc liên kết. Thanh niên áo đen dụ ba Chân Linh đầu hàng bằng lời hứa ban Chân Hồn Đan, đưa lên Chân Tiên giới và chặt đứt khế ước với Giác Xi tộc. Khi chân nguyên liên tục bị cắn nuốt, Đề Long và Cự Tước bắt đầu dao động, còn ba Chân Linh dần nghi kỵ lẫn nhau. Xiềng xích trên người Đề Long sau đó đột ngột bộc phát, tạo cơ hội để thanh niên áo đen dùng huyết sắc đại ấn tiêu diệt cả thân thể lẫn thần hồn hắn. Thân ảnh thanh niên vốn bị trói cũng tan biến, chứng tỏ đó chỉ là thủ đoạn đánh lừa. Cự Tước tìm cách tháo chạy nhưng bị Dương Lộc chặn lại và nhận ra đối phương đã sớm quy thuận thanh niên áo đen, đồng thời phá hoại Xiềng Xích Pháp Tắc. Thanh niên áo đen từ chối lời xin hàng muộn của Cự Tước, ra lệnh cho Dương Lộc giết nó và tuyên bố kẻ chiến thắng mới được nhận Chân Hồn Đan, trở thành Linh bộc của hắn."},{"chuong":2401,"tieuDe":"Tiểu Bình Tái Hiện","tomTat":"Dương Lộc và Cự Tước màu xám lao vào giao chiến, tạo cơ hội để thanh niên áo đen cùng cự ấn màu máu thoát khỏi không gian bí ẩn và xuất hiện trên Lôi Minh đại lục. Hắn thả Dương Lộc trọng thương khỏi bình nhỏ, nhận nó làm linh bộc và dùng Tiên Linh Bảo Giám đính lập khế ước vào chủ hồn của nó. Sau đó, thanh niên trao Chân Hồn Đan cho Dương Lộc, nhưng nó quyết định giữ viên đan đến khi về Tiên giới để tránh bị pháp tắc hạ giới bài xích. Thanh niên tiến vào không gian trong bình để chữa thương, còn Dương Lộc đưa bình chìm sâu vào lòng núi rồi ở lại canh giữ. Bên trong bình, hắn xác định thương thế bắt nguồn từ pháp bảo tự bạo của những người Giác Xi tộc và sự trói buộc của pháp tắc chi lực. Nhờ Động địa phỏng chế phẩm do tổ sư ban, hắn thúc sinh linh hoa dị thảo, hấp thu dược khí màu xanh và bắt đầu quá trình tĩnh dưỡng với thời gian được rút ngắn xuống mười lần."},{"chuong":2402,"tieuDe":"Nhân Tộc Tái Tụ","tomTat":"Nửa năm sau, Mặc Linh Thánh Thuyền trở về Thiên Uyên thành, khiến Nhân tộc và Yêu tộc trong thành chấn động, còn Hàn Lập cho các tu sĩ từ Tiểu Linh Thiên tự quyết định ở lại hay rời đi. Mạc Giản Ly đến gặp Hàn Lập và Nam Cung Uyển, tiếp nhận nàng như người ngang hàng rồi tặng bộ một trăm lẻ tám cây Huyền Nữ Toái Âm châm làm lễ gặp mặt. Hàn Lập báo tin Băng Phách đã được cứu, nhờ cơ duyên tiến giai Đại Thừa nhưng phải lưu lại Huyết Thiên đại lục thêm vài năm để ổn định căn cơ. Trước viễn cảnh Nhân tộc có ba tu sĩ Đại Thừa, Mạc Giản Ly đề xuất khuếch trương lãnh thổ, song Hàn Lập cho rằng hiện tại chưa phải thời cơ thích hợp. Hàn Lập tiếp tục thuật lại tin tức từ Hách Liên thương minh về huyết tế và hung ma Chân Tiên, cảnh báo rằng Nhân tộc có thể gặp họa diệt vong nếu ứng phó sơ suất. Hắn xác nhận đã tạm nhận lời liên thủ với Minh Tôn và có thể tham gia trấn áp Chân Tiên nếu xuất hiện cơ hội. Sau khi suy xét tình hình, Mạc Giản Ly nêu ra một nghi vấn mới nhưng nội dung câu hỏi chưa được tiết lộ."},{"chuong":2403,"tieuDe":"Lập Kế Hoạch","tomTat":"Hàn Lập và Mạc Giản Ly phân tích việc Chân Tiên dùng thân thể hàng lâm Linh giới, nhận định đối phương hẳn phải có mục đích quan trọng vì phải chịu áp chế pháp tắc và trả giá rất lớn. Hai người thống nhất nhờ Minh Tôn tiếp tục điều tra, đồng thời tìm cách liên lạc với hai người đang bị truy sát để cân nhắc dùng họ làm mồi nhử. Mạc Giản Ly nhận trách nhiệm tập trung nhân khẩu tại các thành lớn, sơ tán hơn nửa Nhân tộc và gia cố đại trận Thiên Uyên thành, còn Hàn Lập quyết định trở về Thanh Nguyên Cung bế quan lĩnh ngộ bí thuật. Sau hai tháng, Mặc Linh Thánh Chu đưa Hàn Lập, Nam Cung Uyển cùng đoàn người tới Nguyên Hợp Đảo và được hơn vạn tu sĩ Nhân Yêu hai tộc nghênh đón. Hàn Lập giới thiệu Nam Cung Uyển với Cổ Nguyệt Thiên, qua đó xác lập nàng là sư nương và nữ chủ nhân Thanh Nguyên Cung. Khi hỏi thăm Ngân Nguyệt, Hàn Lập được báo nàng đang bế quan ở thời điểm mấu chốt, còn Nam Cung Uyển mong gặp nàng sau khi xuất quan để bàn lại chuyện năm xưa tại Nhân giới."},{"chuong":2404,"tieuDe":"Phòng Ngừa Chu Đáo","tomTat":"Hàn Lập đưa Nam Cung Uyển tham quan Thanh Nguyên Cung, để nàng chọn Thiên điện làm nơi ở, đồng thời trao bí bảo, đan dược và lệnh bài ra vào Tàng Kinh Các cùng Vạn Bảo Khố. Sau khi xử lý việc trong cung và phái người tìm Băng Phượng, hắn cùng Nam Cung Uyển du ngoạn Nguyên Hợp Đảo và Vô Nhai Hải rồi lần lượt bế quan, giao công việc trên đảo cho Cổ Nguyệt Thiên. Trong mật thất, Hàn Lập tạm gác Ngũ Tạng Đoàn Nguyên Công và Nguyên Cương Tráo để chuyên tâm vào bí thuật tinh luyện lôi lực, khiến Tịch Tà Thần Lôi bắt đầu xuất hiện biến đổi tím vàng. Tại Lôi Minh đại lục, Mã Lương hoàn toàn bình phục, rời bình nhỏ màu xanh và dùng Thần Ma ký phụ xác định hai mục tiêu đã chạy về hướng Phong Nguyên đại lục. Hắn ra lệnh cho Dương Lộc dẫn tới truyền tống trận vượt đại lục để tiếp tục truy tìm thần hồn kẻ phản đồ. Cùng lúc đó tại Phong Nguyên đại lục, Lục Dực và Băng Phượng bị bốn Đại Thừa cùng đại hình cấm chế vây trong u cốc. Khi Lục Dực định dùng vũ lực phá trận, Minh Tôn bất ngờ xuất hiện và cưỡng ép mời cả hai đến liên minh của mình làm khách."},{"chuong":2405,"tieuDe":"Đại Kiếp Nạn Buông Xuống","tomTat":"Minh Tôn dẫn năm Đại Thừa của Hách Liên Thương Minh đến chiêu mộ Lục Dực và Băng Phượng nhằm chuẩn bị đối phó Hung Ma. Lục Dực chấp nhận đi cùng sau khi được hứa cung cấp đan dược khôi phục chân nguyên, còn Băng Phượng vui mừng nhận lời khi biết Hàn Lập từng nhờ Minh Tôn chiếu cố nàng. Một tháng sau tại Thanh Nguyên cung, Hàn Lập nhận tin hai người đã được tìm thấy và phái Hoa Thạch lão tổ rời Nguyên Hợp đảo để trực tiếp hỏi thăm. Ba tháng sau, Mã Lương cùng Dương Lộc giết người canh giữ đầu truyền tống bên kia rồi cưỡng dụng pháp trận của Giáp Đồn tộc để xâm nhập Phong Nguyên đại lục. Dương Lộc giết các vệ sĩ tiến vào Truyền Tống điện, ăn Phí thống lĩnh và dùng chiến giáp cùng cự phủ phá hủy cấm chế ba mươi sáu đồng trụ. Mã Lương ngăn thuộc hạ tiếp tục tàn sát để ưu tiên chính sự, sau đó cả hai rời cấm địa. Khi đến gần một dãy núi, Mã Lương bất ngờ dừng lại vì nhận thấy điều bất thường chưa được hé lộ."},{"chuong":2406,"tieuDe":"Giáp Đồn Cường Giả","tomTat":"Mã Lương phát hiện một cường giả đang truy đuổi, còn Dương Lộc nhận ra người tới là Đệ nhất Thái Thượng Trưởng lão Giáp Đồn tộc, một trong năm cường giả hàng đầu Linh giới. Sau khi biết Dương Lộc là Chân linh phụng Mã Lương làm chủ, lão giả tìm cách hòa hoãn rồi điều khiển cỗ xe xương trắng rút lui. Dương Lộc dùng búa đen chặn đường, trong khi Mã Lương kích phát Vạn Linh Huyết Tỷ nghiền vỡ cốt hoàn, đánh tan hơn trăm ác quỷ Hợp Thể kỳ và dùng sông máu vây kín Cốt Long do cỗ xe biến thành. Không thể thoát khỏi lực lượng pháp tắc, lão giả xuất Nguyên Anh, phân hóa thành mười ảo ảnh và đồng thời vận dụng trường thương đỏ thẫm cùng chuông xương để phản kích. Cuộc chống cự thất bại, lão giả bị Mã Lương giết và có thể sẽ bị lấy tinh hồn luyện thành chủ hồn của Vạn Linh Huyết Tỷ. Từ tình báo thu được, Mã Lương biết Hách Liên Thương Minh đang triệu tập nhiều cường giả tại Phong Nguyên đại lục để đối phó mình. Hắn quyết định trực tiếp tiêu diệt thương minh nhằm răn đe các thế lực khác, nhưng trước đó sẽ dùng bí thuật kiểm tra mục tiêu mình tìm kiếm có thật sự ở đại lục này hay không."},{"chuong":2407,"tieuDe":"Nguy Cơ Của Thương Minh","tomTat":"Dưới sự hộ pháp của Dương Lộc, Mã Lương dùng tinh cầu hai màu và phù lục vàng kim để xác định phương hướng của những kẻ bị truy tìm cùng mục tiêu lần hạ giới. Dù đã tìm được mục tiêu, hắn quyết định tấn công Hách Liên Thương Minh trước và dùng thêm các trận huyết tế để hoàn thành Vạn Linh Huyết Tỷ. Cùng lúc đó, một thanh niên tuấn mỹ bị phong ấn trong cấm địa Linh Tộc xuất hiện linh văn vàng kim giữa hai mày, nhưng những người trông coi không tìm thấy nguyên nhân nên chỉ kiểm tra lại cấm chế và tăng cường thủ vệ. Minh Tôn nhận tin Mã Lương đã giết đệ nhất Thái Thượng Trưởng lão Giáp Đồn tộc và chỉ còn cách tổng bộ thương minh khoảng nửa tháng. Ông quyết định chia nhỏ thương minh để rút lui, chuyển sang hoạt động bí mật, đồng thời triệu tập cường giả tại Minh Sát chi địa ở Thiên Ngoại Thiên. Minh Tôn còn dự định dùng Lục Dực làm yếu tố dẫn Mã Lương tới chiến trường, nơi thương minh có thể triệu hoán các Chân Linh được cung phụng. Tại Thanh Nguyên cung trên Nguyên Hợp đảo, Hàn Lập điều khiển một đoàn lôi điện tử kim nhỏ bằng nắm tay, chớp sáng nhưng hoàn toàn không phát ra tiếng sét."},{"chuong":2408,"tieuDe":"Minh Sát Chi Địa","tomTat":"Hàn Lập thử Tịch Tà Thần Lôi sau tinh luyện và vui mừng khi thấy lôi cầu tím vàng có thể xuyên phá không gian. Nhận tin Mã Lương đã tới đại lục Phong Nguyên, hắn quyết định tham gia đối phó Chân Tiên, giao Nam Cung Uyển quản lý Thanh Nguyên Cung rồi một mình lên đường. Trong khi đó, Mã Lương cùng Dương Lộc tiếp tục truy tìm Lục Dực và Băng Phượng qua ấn ký tâm hồn, dù nhận ra Hách Liên Thương Minh có thể đang dùng họ làm mồi nhử. Minh Tôn giao Phong Thần Chu và phù lục cho hai người, yêu cầu họ kéo Mã Lương đi vòng quanh rồi dẫn hắn tới Minh Sát sau ba tháng, còn lực lượng thương minh phân tán rút khỏi các cứ điểm. Trên đường truy sát, Mã Lương phá hủy một cứ điểm bỏ trống và huyết tế thành chính Tế Hòa Tộc, khiến hơn trăm nghìn người thiệt mạng và tin dữ lan khắp Phong Nguyên. Hơn mười cường giả hàng đầu sau đó sử dụng truyền tống trận của Hách Liên Thương Minh để tập kết tại vùng đất Minh Sát thuộc Thiên Ngoại Thiên. Khi Hàn Lập chuẩn bị tiến vào vùng âm sát khí dày đặc, hắn nghe thấy những tiếng nổ liên tiếp như một quái vật khổng lồ đang chạy tới từ hướng khác."},{"chuong":2409,"tieuDe":"Thiên Ngoại Thiên","tomTat":"Trên đường đến điểm tụ hội, Hàn Lập chứng kiến Ngân Cương Tử hóa thành người khổng lồ màu bạc, đánh chết Thổ Quy và nuốt yêu đan của nó. Hai người trao đổi thân phận, nhận ra danh tiếng của nhau rồi quyết định kết bạn và đồng hành. Ngân Cương Tử mời Hàn Lập lên Bích Ba Xa, vừa đi vừa hỏi những tin tức hắn biết về tiên nhân gây ra các cuộc huyết tế. Khi tiến vào trung tâm Minh Sát, Hàn Lập nhìn thấy Thiên Ngoại Thiên với không gian đen trắng và vô số khối đá, cung điện lơ lửng. Ngân Cương Tử kể nơi này từng là cấm địa của một đại tộc thượng cổ đã biến mất bí ẩn trước khi âm sát khí bùng phát. Một nam tử áo lam của thương minh phụng lệnh Minh Tôn ra nghênh đón và dẫn hai người đến cung điện trên đảo đá. Minh Tôn đang bàn bạc cùng nhiều khách mời thì vui mừng đứng dậy chào đón Hàn Lập và Ngân Cương Tử, mở đầu cuộc tụ hội tại Thiên Ngoại Thiên."},{"chuong":2410,"tieuDe":"Quần Hùng Tụ Hội","tomTat":"Hàn Lập theo Ngân Cương Tử tới cuộc tụ hội do Minh Tôn chủ trì và gặp năm tu sĩ Đại Thừa đang chờ sẵn. Minh Tôn giới thiệu chiến tích của Hàn Lập, đồng thời cho biết đạo hữu họ Lãnh, hai huynh muội Vân Đạm Nguyệt và Hiên Cửu Linh cũng sẽ tham gia kế hoạch đối phó chân tiên. Ông xác nhận mục tiêu là một chân tiên đỉnh cấp từng giết mười Đại Thừa tại Huyết Thiên đại lục và đã thu phục Dương Lộc làm tùy tùng. Để vây giết đối phương, liên minh sẽ huy động bốn chân linh, hai huyền thiên chi bảo và bố trí đại trận Lưỡng Nghi Diệt Trần nhằm phong tỏa đường lui. Liên minh yêu cầu một phần ba bảo vật thu được, còn phần còn lại sẽ được chia đều cho những người tham chiến. Hàn Lập chấp nhận phương án này nhưng đề nghị mọi công pháp và bí thuật lấy được từ chân tiên phải được sao chép cho toàn bộ thành viên, khiến mọi người đồng tình và Minh Tôn chấp thuận. Sau vài canh giờ tiếp tục bàn kế hoạch, hội nghị giải tán và Hàn Lập một mình chọn một khối đá trôi nổi ở xa làm nơi tạm trú."},{"chuong":2411,"tieuDe":"Hiên Cửu Linh","tomTat":"Hoa Thạch trở về báo rằng Băng Phượng xác nhận đã bị Lục Dực bắt cóc và đã nhận đủ bảo vật Hàn Lập gửi tới. Trong hơn nửa tháng Hàn Lập điều dưỡng, thương minh hoàn tất Lưỡng Nghi Diệt Trần, bố trí hai huyền thiên chi bảo làm mắt trận và chuẩn bị nghi thức triệu linh. Khi Lục Dực dẫn chân tiên tới gần khu vực Minh Sát, Minh Tôn triệu tập các cao thủ, ra lệnh bắt đầu triệu linh nhưng chưa được tự tiện mở đại trận. Hàn Lập gặp huynh muội Vân Đạm Nguyệt và biết Hiên Cửu Linh đã tới Thiên Ngoại Thiên, hiện đang tế luyện một bí thuật uy lực lớn để đảm nhận trọng trách khác. Minh Tôn giao một mắt trận cho Hàn Lập và mắt trận còn lại cho hai huynh muội Vân Đạm Nguyệt bảo vệ. Sau khi mọi người rời đi, một bóng người xa lạ xuất hiện từ bóng của Minh Tôn và tiết lộ Cửu Kiếp Diệt Chân Đại Pháp có thể phá hủy thân thể chân tiên nhưng chỉ thi triển được một lần. Hai người dự định buộc đối phương khôi phục chân thân rồi tung đòn quyết định, dù điều đó có thể khiến bốn chân linh được triệu hồi trở thành vật hi sinh."},{"chuong":2412,"tieuDe":"Trận Nhãn","tomTat":"Minh Tôn úp mở mục đích bố trí Hàn Lập cùng huynh muội Vân Đạm Nguyệt trấn giữ hai mắt trận, đồng thời hứa chia Chân Hồn Đan cho bóng người mờ ảo nếu lấy được từ chân tiên. Hàn Lập được dẫn vào đại trận bao phủ hơn nửa Minh Sát, nhận lệnh bài và tiếp quản gần một ngàn giáp sĩ bảo vệ trận nhãn. Giải Đạo Nhân nhận ra nơi đây mang đặc điểm của Lưỡng Nghi Vi Trần, một đại trận có thể vây khốn, làm suy yếu và hiến tế sinh linh cùng bảo vật để tự phát nổ. Hàn Lập vì thế hiểu rằng mình và huynh muội Vân Đạm Nguyệt có nguy cơ bị Minh Tôn dùng làm tế phẩm. Không muốn đồng quy vu tận với chân tiên, hắn đồng ý để Giải Đạo Nhân bí mật sửa mắt trận. Phệ Kim Trùng Vương thu nhỏ như hạt gạo và khắc ký hiệu lên cả tám cột sáng mà lực lượng canh giữ không phát hiện. Sau đó Minh Tôn hội quân với các Đại Thừa, công khai thông báo ba người đã được giao trấn thủ hai mắt trận để những người còn lại có thể toàn lực đối phó chân tiên."},{"chuong":2413,"tieuDe":"Đánh Cược","tomTat":"Ngân Cương Tử lo lực lượng mai phục suy yếu vì thiếu ba người Hàn Lập, nhưng Minh Tôn giải thích họ phải bảo vệ mắt trận Lưỡng Nghi Diệt Trần và cho biết Hiên Cửu Linh đã bí mật tới Minh Sát. Trong khi đó, Lục Dực và Băng Phượng tiếp tục dẫn Mã Lương vào vùng phục kích sau một thời gian dài bị truy đuổi đến mức gần cạn linh dược, phù chú và bổn nguyên. Hai người tranh luận về khả năng Hàn Lập phi thăng trong vòng vạn năm rồi lấy tương lai của chính mình làm điều kiện đánh cược. Họ cùng dùng máu thi pháp lập tâm ma thệ, theo đó Lục Dực phải vĩnh viễn tránh Băng Phượng nếu Hàn Lập thành công, còn Băng Phượng phải làm thị thiếp nghe lệnh hắn nếu Hàn Lập thất bại. Khi mây máu của Mã Lương áp sát, Băng Phượng sử dụng lá Tị Phong Phù cuối cùng, giúp thuyền ngọc lưu ly tăng tốc và tạm thời bỏ xa đối phương. Tiến sâu vào Minh Sát, Mã Lương nhận thấy âm sát khí hạn chế thần niệm và chủ động suy đoán nơi đây có thể đã được bố trí thành cạm bẫy nhằm đối phó mình."},{"chuong":2414,"tieuDe":"Hắc Nghê Thú","tomTat":"Dương Lộc lo ngại Hách Liên Thương Minh đã bố trí thủ đoạn bí mật tại vùng đất Minh Sát, nhưng Mã Lương vẫn tiến vào và muốn dùng trận chiến này để răn đe toàn Linh giới. Khi thuyền ngọc lưu ly biến mất, gần trăm đại kỳ hiện ra, khởi động Lưỡng Nghi Diệt Trần và vây kín đám mây máu. Trận pháp di chuyển đòn đánh, tạo ảo cảnh và dẫn xuống áp lực pháp tắc, khiến pháp lực của Mã Lương cùng Dương Lộc bị ngưng trệ. Mã Lương dùng gương hai màu đen trắng phá gương năm màu, sau đó tế ô xanh để hóa giải phần lớn sức ép và thoát khỏi trói buộc. Hắn điều tám ngũ trảo huyết long tấn công đội hình Đại Thừa, buộc Minh Tôn ra lệnh nghênh chiến và triệu hồi bốn Hắc Nghê. Bốn chân linh nhanh chóng đánh ngã các người khổng lồ đỏ do mây máu biến thành, nhưng bị tiếng quát của Mã Lương cùng xúc tua và lửa đỏ phản kích. Cuối cùng, Hắc Nghê phá lửa và phóng lớn thân hình, trong khi bốn người khổng lồ cũng đứng dậy với xúc tua đỏ mọc sau lưng, khiến cuộc giao tranh tiếp tục giằng co."},{"chuong":2415,"tieuDe":"Kịch Chiến Bắt Đầu","tomTat":"Bốn Hắc Nghê áp đảo các huyết linh khổng lồ bằng đao đen và cận chiến, nhưng khả năng hóa thành mây máu để tái sinh khiến hai bên rơi vào thế giằng co. Mã Lương xác định đại trận có hai mắt trận nên phái Dương Lộc mang Ý Niệm Châu cùng một phần Thanh Độn Tán đi phá một nơi, đồng thời giải phong người tí hon đeo mặt nạ quỷ để công kích nơi còn lại. Nhận ra ý đồ ấy, Minh Tôn giao trận bàn huyền thiên tàn bảo cho Lục Dực, cử Băng Phượng hỗ trợ hắn và truyền tống cả hai đi ngăn Dương Lộc. Hiên Cửu Linh cũng chủ động nhận nhiệm vụ tiêu diệt người tí hon vì tin rằng công pháp của mình khắc chế loại sinh vật này. Trong khi Mã Lương và Minh Tôn vẫn giữ vị trí quan sát, Hàn Lập cảm ứng chấn động từ mắt trận mình trấn thủ rồi dùng linh mục nhìn ra ngoài mấy ngàn dặm. Hắn thấy pháp trận trắng ngà đang giam giữ một bóng đen, nhận ra Băng Phượng và suy đoán nam tử áo trắng bên cạnh nàng chính là Lục Dực."},{"chuong":2416,"tieuDe":"Thần Hồn Ấn Ký","tomTat":"Hàn Lập truyền âm gọi Băng Phượng và Lục Dực tới tế đài do mình trấn thủ, đồng thời cảnh báo Lục Dực rằng ở lại vị trí cũ có thể mất mạng. Lục Dực cuối cùng rời Càn Khôn Pháp Bàn, khiến pháp trận giam chân linh suy yếu và rung chuyển dữ dội trước sự vùng vẫy của mục tiêu bên trong. Sau khi hội ngộ Băng Phượng, Hàn Lập biết Lục Dực đã tiến cấp Đại Thừa và sở hữu độn thuật khiến ngay cả chân tiên cũng khó đuổi kịp. Lục Dực tin tu vi mới đủ giúp mình chống lại huyết khế, nhưng lập tức bị thần thức vượt trội của Hàn Lập kích phát khế ước và định trụ trước khi kịp phản kháng. Băng Phượng sau đó kể rằng nàng và Lục Dực từng bị người của Minh Tôn ép làm mồi nhử, rồi bị một chân tiên truy sát dai dẳng nhờ dấu vết bí ẩn để lại trong thần hồn. Hàn Lập nhận định thủ đoạn này chủ yếu dựa vào sức mạnh thần hồn của người thi triển và đồng ý thử giải trừ. Chương kết thúc khi Băng Phượng buông lỏng thức hải để Hàn Lập bắt đầu thi pháp."},{"chuong":2417,"tieuDe":"Trảm Lộc Thượng","tomTat":"Hàn Lập dùng thần niệm hóa thành sợi tơ, lần lượt loại bỏ ấn ký chân tiên khỏi thần hồn Băng Phượng và Lục Dực. Hắn thỏa thuận sẽ giải trừ huyết khế nếu Lục Dực thu thập đủ hơn mười loại tài liệu quý trong một nghìn năm và lập lời thề tương trợ Nhân tộc ba lần. Sau khi được xóa ấn ký, Lục Dực rời Minh Sát tìm vật liệu, còn Băng Phượng nghe lời cảnh báo của Hàn Lập và trở về Nhân tộc. Một pháp trận màu trắng ngà ở xa bất ngờ nổ tung, để Dương Lộc trong hình thái cự thú đầu lộc mình gấu thoát ra và lao về mắt trận. Hàn Lập ra lệnh cho các vệ sĩ thương minh giữ nguyên vị trí rồi chủ động nghênh chiến. Kiếm quang giao long của hắn cắt nát bàn tay khổng lồ do Dương Lộc chụp tới, khiến đối phương chuyển sang hút mây vàng và phun ra một biển đạn cuồn cuộn tấn công."},{"chuong":2418,"tieuDe":"Trảm Lộc Hạ","tomTat":"Hàn Lập phóng Liệt Sát Kim Cương Sa từ hồ lô vàng, tạo biển cát trong suốt nghiền nát các biến hóa của biển cát vàng do Dương Lộc điều khiển. Khi Dương Lộc áp sát bằng song chưởng, màn sáng trắng ngà và viên đạn sương mù, Hàn Lập dùng kiếm xanh cùng sức mạnh thân thể phá tan thế công rồi đánh lui đối thủ. Hắn tiếp tục hiện Chân Ma Thể ba đầu sáu tay, lấy ra huyền thiên chi bảo và cuối cùng chém đầu Dương Lộc. Ở một chiến trường khác, người áo xám mất gần nửa thân thể khi giao chiến với Hỏa Tu Thú nhưng vẫn hóa kiếm bạc chém tan biển lửa do thân quái giao vỡ ra. Mã Lương từ chối tháo cấm chế cho người tí hon đỏ đậm, dùng mây vàng khiến đối phương ngủ say rồi dán phù và thu vào hộp ngọc. Trong khi đó, Ngân Cương Tử cùng đàn Hắc Nghê ép tám huyết long và những người khổng lồ phải lui về mây máu để nhận chân nguyên duy trì chiến đấu. Sau khi chứng kiến cả Dương Lộc lẫn Hỏa Tu Thú thất bại, Mã Lương quyết định giải trừ phong ấn thêm một lần nữa và gọi ra một tấm bùa vàng chói mắt."},{"chuong":2419,"tieuDe":"Chân Tiên Chi Thân Thượng","tomTat":"Mã Lương kích hoạt tấm phù vàng, thu các xiềng xích phong ấn cùng nguyên thần vào thiên linh và khôi phục thực lực, khiến mây bảy màu cùng sấm chớp tím vàng bao phủ Minh Sát. Hiên Cửu Linh trở về sau khi tiêu diệt con rối hỏa trung thánh thú và bảo toàn mắt trận, dù đã mất nửa thân thể; hắn giữ lại Cửu Kiếp Diệt Linh Đại Pháp để đối phó Mã Lương rồi dùng Thủy Nguyên Đan tái tạo máu thịt. Sau khi giải phong, Mã Lương biến tám huyết giao và bốn người khổng lồ thành một trận mưa máu bao trùm chiến trường. Công kích xuyên qua nhiều tầng bảo vật và hộ thể, làm tên đầu trọc mất toàn bộ da thịt trên mặt và khiến thiếu phụ mặc cung trang mất một cánh tay. Mã Lương cho biết đây mới chỉ là linh huyết được luyện hóa sơ bộ, còn kém huyết nguyên lực thực sự rất xa. Hắn công khai mình đến từ Tiên giới, đã tu thành chân tiên thân từ lâu và xuống Linh giới để hoàn thành một trọng trách đã tìm được manh mối. Cuối cùng, Mã Lương tuyên bố sẽ giết nhóm Đại Thừa rồi kết một pháp quyết cổ quái để chuẩn bị ra tay."},{"chuong":2420,"tieuDe":"Chân Tiên Chi Thân Hạ","tomTat":"Mã Lương khôi phục Chân Tiên chi thân, hóa thành kim sắc cự nhân và tạm thời thoát khỏi sự áp chế của giao diện chi lực, khiến Lưỡng Nghi Vi Trần Trận suy yếu nghiêm trọng. Hắn triển khai Kim Sắc Linh Vực, biến hư không cùng đại địa thành một thế giới kim sắc và dùng Linh Vực để chuyển hóa pháp lực thành Tiên Linh lực. Trước tình thế đó, Minh Tôn trấn an các Đại Thừa, dựng Cực Nhạc Phạm Hà Giới để tạm ngăn Linh Vực khuếch tán và tiết lộ rằng Hiên Cửu Linh vẫn đang ẩn thân chờ cơ hội phản kích. Mã Lương sau đó thu Huyết Hà thành Vạn Linh Huyết Tỷ, rót hơn phân nửa Tiên Linh lực vào bảo vật rồi giáng xuống phòng tuyến. Một kích này đánh nổ toàn bộ tám mươi mốt tinh châu và phá hủy hắc sắc quang trận. Ô Linh Phu Nhân cùng vài Đại Thừa lập tức tháo chạy, nhưng sức ép phong tỏa phạm vi trăm dặm đánh bật mọi độn quang, buộc họ hiện hình trở lại trong trạng thái kinh hãi."},{"chuong":2421,"tieuDe":"Uy Lực Của Tỷ Ấn","tomTat":"Hơi máu từ Vạn Linh Huyết Tỷ khiến phần lớn cường giả Đại Thừa choáng váng, nhưng Minh Tôn nhận định bỏ chạy riêng lẻ chỉ khiến họ lần lượt bị Mã Lương truy sát nên thúc giục tất cả dốc toàn lực. Phe Đại Thừa đồng loạt sử dụng Ngân Quân Thiên Thư, Tạo Hóa Chi Thân, Pháp Tướng và nhiều pháp bảo để hợp kích, song Mã Lương dùng thần thông chữ Định trấn áp các đòn chủ lực, phá hủy bảo vật và đánh vỡ nhiều Pháp Tướng. Minh Tôn dùng tinh huyết thúc đẩy Ngân Quân Thiên Thư dựng tháp bạc, tạm thời làm chậm tỷ ấn nhưng không thể ngăn nó tiếp tục ép xuống. Ô Linh Phu Nhân, Ngân Cương Tử và các Đại Thừa khác mở đợt phản công thứ hai, nhưng kiếm quang, lôi hỏa và hư ảnh Ngũ Trảo Kim Long đều bị màn gió vàng của Mã Lương hóa giải. Trong khi đó, Minh Tôn thuyết phục bốn Hắc Nghê Thú tung bổn mạng chân hỏa toàn lực một lần để hoàn thành khế ước, và chúng đồng ý rời đi ngay sau đòn đánh bất kể kết quả. Trước khi kế hoạch ấy được thực hiện, Mã Lương đưa một giọt máu vàng vào tỷ ấn, khiến gần triệu tia máu xuyên thủng không gian. Minh Tôn kịp dùng màn sáng bảo vệ ba đồng minh ở gần, còn nhiều Đại Thừa bên ngoài bị xuyên thủng thân thể, hóa thành lửa xanh và chết cả Nguyên Anh."},{"chuong":2422,"tieuDe":"Cửu Kiếp Hiện","tomTat":"Màn tơ máu của Mã Lương giết chết nhiều cường giả Phong Nguyên Đại lục, nhưng nhóm Minh Tôn được Ngân Quân Thiên Thư bảo vệ còn Bốn Hắc Nghê tránh được nhờ lửa đen. Trước sức ép của Vạn Linh Huyết Tỷ, Minh Tôn phân công Ngân Cương Tử, Ô Linh Phu Nhân và các đồng minh cầm chân huyết ấn để ông chuẩn bị bí thuật phong ấn. Ngân Cương Tử cùng Ô Linh Phu Nhân dốc pháp lực chống giữ huyết ấn, trong khi nữ tử mặc cung trang dùng ba hạt giống Băng Đàm Hoa đóng băng một nửa bảo vật này. Mã Lương nhanh chóng dùng hào quang vàng và huyết diễm phá lớp băng, nhưng ngay sau đó Liên Cấm Nguyên Đăng do Minh Tôn kích phát đã thu biển lửa và làm tiên linh lực của hắn ngưng đọng. Bốn Hắc Nghê nhân cơ hội phun bốn hỏa cầu đen tập kích; Mã Lương đánh nổ ba quả nhưng hỏa cầu cuối biến hóa né quyền. Hiên Cửu Linh hiện thân từ hỏa cầu ấy, áp sát hông cự nhân và phát động Cửu Kiếp Diệt Linh Đại Pháp."},{"chuong":2423,"tieuDe":"Quần Cường Vẫn Lạc","tomTat":"Hiên Cửu Linh tự bạo một cánh tay để thi triển Cửu Kiếp Chân Diễm, thiêu sạch huyết nhục của Mã Lương đến mức chỉ còn bộ xương vàng. Cung trang nữ tử nhận ra uy lực của Vạn Linh Huyết Tỷ không hề suy giảm và cảnh báo rằng vị Chân Tiên vẫn chưa chết. Minh Tôn, Hiên Cửu Linh và Bốn Hắc Nghê tiếp tục hợp lực công kích, nhưng tất cả đòn đánh đều bị chiến giáp thủy tinh cùng phù văn tím vàng hóa giải. Mã Lương gọi ra Ngụy Thiên Bình, dùng trận mưa xanh nhạt tái tạo hoàn chỉnh huyết nhục chỉ trong vài nhịp thở. Sau khi khôi phục, hắn tuyên bố sẽ giết sạch mọi người rồi phát động Linh vực với ánh sáng vàng, đầu lâu kim sắc, núi lửa và dung nham bao phủ thiên địa. Minh Tôn cùng các cường giả lần lượt thi triển thủ đoạn tháo chạy, trong khi Cung trang nữ tử chậm một bước và không còn kịp thoát khỏi Linh vực."},{"chuong":2424,"tieuDe":"Huyết Tế","tomTat":"Kim Đồng chém đứt những ngón tay vàng đang khống chế mình rồi chống trả các bàn tay vàng và giáp sĩ của Mã Lương, nhưng dần bị lực lượng pháp tắc trong Linh Vực áp chế. Từ một mắt trận xa xôi, Hàn Lập dùng mặt kính màu xanh theo dõi trận chiến do chính hắn âm thầm bố trí Kim Đồng tham gia. Tại Thiên Ngoại Thiên, Minh Tôn dùng pháp bàn màu bạc phát động thủ đoạn cuối cùng dù biết việc này sẽ khiến Phong Nguyên Đại Lục đại thương nguyên khí. Vân Đạm và Nguyệt Sơ phát hiện mắt trận của mình là một tuyệt địa huyết tế, nơi hai người cùng hơn một nghìn vệ sĩ Thương Minh bị dùng thay cho Huyền Thiên Chi Bảo. Mọi nỗ lực phá vây đều thất bại, khiến hai huynh muội cùng các vệ sĩ hóa thành huyết vụ và bị vòng xoáy của đại trận hấp thụ, trong khi Hàn Lập được màn sáng cách ly bảo vệ tại mắt trận khác. Huyết tế sau đó kích hoạt một siêu cấp quang trận phủ hơn nửa Minh Sát Chi Địa, lấy Mã Lương làm trung tâm và khiến hắn kinh hãi lập tức bỏ chạy."},{"chuong":2425,"tieuDe":"Chưởng Thiên Bình","tomTat":"Lưỡng Nghi Vi Trần Trận tự bạo, quét sạch các giáp sĩ màu vàng và san bằng khu vực vạn dặm tại trung tâm Minh Sát Chi Địa thành một thung lũng khổng lồ. Giải Đạo Nhân nhận định pháp trận chỉ còn khoảng một phần mười uy năng nguyên bản nhưng vẫn đủ khiến Mã Lương mất trạng thái thân thể Chân Tiên, trọng thương và chịu giới diện phản phệ. Vì khả năng Mã Lương mang Chân Hồn Đan, Hàn Lập quyết định mạo hiểm cùng Giải Đạo Nhân truyền tống tới chiến trường. Mã Lương sống sót nhưng trở lại hình dáng bình thường, còn Phệ Kim Trùng Vương dùng ve sầu thoát xác để bảo toàn tính mạng dù khí tức suy yếu hơn phân nửa. Hàn Lập đánh tan Cự Phủ bạc do phù lục của Mã Lương biến thành, thu Phệ Kim Trùng Vương vào tay áo rồi từ chối giao nó cho đối phương. Khi hai bên chuẩn bị giao chiến, Ngụy Thiên Bình của Mã Lương phát sinh cảm ứng với chiếc bình nhỏ màu xanh nhạt của Hàn Lập. Mã Lương nhận ra đó chính là Chưởng Thiên Bình mà mình đang tìm cho Thủy Tổ, nhưng đồng thời kết luận bảo vật hiện chỉ còn vỏ ngoài và truy hỏi tung tích bình linh."},{"chuong":2426,"tieuDe":"Trảm Tiên Thượng","tomTat":"Mã Lương cho rằng việc Hàn Lập không biết bình linh chứng tỏ hắn có lẽ không liên quan tới kẻ phản đồ, nhưng vẫn quyết định bắt đối phương để sưu hồn. Hắn vận dụng Vạn Linh Huyết Tỷ triệu hồi tám Ngũ Trảo Huyết Long, trong đó Giải Đạo Nhân hiện nguyên hình cua vàng và giữ chân hai con. Hàn Lập lập Thanh Bàn kiếm trận, liên tục ngưng tụ Thanh Long bằng kiếm khí để đối phó số huyết long còn lại, dù phải tiêu hao gần một nửa pháp lực. Khi Mã Lương dùng hư ảnh huyết ấn trấn áp, Hàn Lập nhận ra chân nguyên đối phương đã suy giảm và hợp ba tòa tiểu sơn thành Nguyên Hợp Ngũ Cực Sơn để chống đỡ. Hắn tiếp tục dùng lực lượng pháp tắc triệt tiêu sự áp chế, rồi dung hợp Phạm Thánh Pháp Tướng cùng các hư ảnh Chân Linh để thi triển Niết Bàn thánh thể tam niết. Với Huyền Thiên Trảm Linh Kiếm, Hàn Lập phá tan các binh khí bạc, chém đôi tấm chắn đen và đánh vỡ Trảm Nguyên Tiên Kiếm. Mã Lương chịu phản chấn đến mức phun tinh huyết vàng, kinh sợ và thề sẽ không để Hàn Lập chết dễ dàng."},{"chuong":2427,"tieuDe":"Trảm Tiên (Trung)","tomTat":"Hàn Lập chém ra sợi tơ kiếm khí thứ hai từ Huyền Thiên Trảm Linh Kiếm, buộc Mã Lương phải tự bạo gần trăm bảo vật và hy sinh một ngón tay mới hóa giải được. Mã Lương sau đó dùng sáo bạc tạo ảo cảnh biển máu, nhưng Hàn Lập phá cảnh tượng giả bằng năm trọng binh và vận chuyển pháp quyết từ Nguyên Anh để thanh tỉnh thức hải. Nhận ra thần thức đối thủ có thể mạnh hơn mình, Mã Lương không thể phát động sát chiêu đã chuẩn bị. Hàn Lập chuyển sang dùng Phạm Thánh Ma Thần ba đầu sáu tay, liên tục thuấn di và truy kích Mã Lương trong phạm vi trăm dặm. Bị dồn ép, Mã Lương phá hộp ngọc và giải tầng cấm chế thứ hai cho Hỏa Tu Tử để tìm viện thủ. Sau khi buộc Mã Lương thề dưới danh nghĩa Cửu Nguyên Đạo Tổ, Hỏa Tu Tử đồng ý quấy nhiễu Hàn Lập và phục vụ thêm một vạn năm khi trở lại Tiên Giới, nhưng tuyên bố việc kết liễu đối thủ vẫn phải do Mã Lương thực hiện."},{"chuong":2428,"tieuDe":"Trảm Tiên Hạ","tomTat":"Hỏa Tu Tử giữ lời trợ chiến cho Mã Lương, hóa thành quái giao khổng lồ để ngăn trọng binh và tấn công Hàn Lập bằng hỏa lực cực nóng, nhưng bị bầy bọ cánh cứng màu vàng hóa khiên cản lại. Mã Lương bí mật phóng phân hồn đánh lén, song Hàn Lập dùng Phá Diện Pháp Mục mở hắc động, trục xuất phân hồn vào khe hở không gian và khiến hắn chịu phản phệ. Hàn Lập tiếp tục thả Phệ Linh Hỏa Điểu, lợi dụng khả năng thôn phệ linh diễm và khắc chế Linh Thú hỏa thuộc tính để ép Hỏa Tu Tử chuyển sang phòng thủ. Bị dồn vào thế khó, Mã Lương nuốt Chân Hồn Đan triệu hồi Ma Quang và yêu cầu đối phương đánh bại Hàn Lập nhưng giữ lại Nguyên Anh. Ma Quang hóa thân gần như vô hình, xuyên qua rồi phá nát năm kiện trọng binh, sau đó đánh thủng bụng Phạm Thánh Ma Thần bằng ma diễm. Khi Mã Lương tưởng Hàn Lập đã trọng thương, Động Tuyền Kim Quang bất ngờ khóa cứng hắn và mộc kiếm phá hộ thể, chém rơi đầu khiến thân thể không đầu ngã quỵ. Chương kết thúc khi tình trạng Nguyên Anh, thần hồn và sinh cơ của Mã Lương vẫn chưa được xác nhận."},{"chuong":2429,"tieuDe":"Thiên Ma Khế Ước","tomTat":"Hàn Lập dùng Phạm Thánh Pháp Tướng làm thế thân, ẩn vào hư không rồi bất ngờ dùng Huyền Thiên Trảm Linh Kiếm chém nát cả thân thể lẫn Nguyên Anh của Mã Lương. Ma Quang tiết lộ Mã Lương là đệ tử chân truyền của Cửu Nguyên Đạo Tổ, sau đó dùng quỷ đầu thu nạp phần thần hồn còn lại của hắn. Khi khế ước cũ mất hiệu lực, Ma Quang đề nghị đi theo Hàn Lập bằng Thiên Ma Khế Ước, đổi quyền chịu sai khiến lấy máu huyết định kỳ nhưng sẽ thu lấy thần hồn Hàn Lập nếu hắn chết trong thời hạn khế ước. Hàn Lập thu vòng tay trữ vật, Vạn Linh Huyết Tỷ, ngọn núi ba màu và bảy mươi hai khẩu tiểu kiếm, rồi hỏi Giải Đạo Nhân về độ tin cậy của lời đề nghị. Được biết đây là một trong ba loại khế ước linh nghiệm nhất Tiên Giới và chưa từng có bằng chứng Thiên Ngoại Ma Tộc làm trái, Hàn Lập đồng ý ký với điều kiện được đặt thêm cấm chế. Ma Quang khiến Hỏa Tu Tử và Phệ Linh Hỏa Điểu ngừng chiến, đồng thời nhận diện Phệ Linh Thiên Hỏa là Tinh Viêm Chi Hỏa cực hiếm, có thể cắn nuốt linh diễm để trưởng thành. Cuối cùng, Ma Quang dùng hy vọng trở lại Tiên Giới, tìm bổn mạng tinh châu và duy trì tu vi để thuyết phục Hỏa Tu Tử nhận Hàn Lập làm chủ, nhưng câu trả lời của Hỏa Tu Tử vẫn chưa rõ."},{"chuong":2430,"tieuDe":"Bổn Mệnh Bài","tomTat":"Hỏa Tu Tử chấp nhận làm linh bộc có điều kiện cho Hàn Lập, yêu cầu được đưa theo khi phi thăng Tiên Giới và được giúp tìm lại bản mạng linh châu. Hàn Lập, Hỏa Tu Tử và Ma Quang dùng máu huyết cùng thần niệm hoàn thành Thiên Ma khế ước. Hỏa Tu Tử sau đó phát hiện Minh Tôn ẩn dưới đất; khi đường đào tẩu bằng quang trận bị phá, Minh Tôn hiện thân và tiết lộ kẻ đã chết trước đó chỉ là một bộ phận do Thuật Phân Hồn tạo ra. Hàn Lập bác bỏ lời biện giải của Minh Tôn và giao cho Ma Quang cùng Hỏa Tu Tử truy sát, đồng thời bí mật phái Phệ Kim Trùng Vương theo dõi họ. Khi kiểm tra di vật của Mã Lương, Hàn Lập tìm thấy hai viên Chân Hồn Đan và một Bổn Mệnh Bài hư hại. Vì ngọc bài chưa vỡ hoàn toàn nên hắn xác định nó không thuộc về Mã Lương, còn Giải Đạo Nhân cho biết có thể dùng bí thuật để kiểm tra chủ nhân thật sự có đang ở Linh giới hay không."},{"chuong":2431,"tieuDe":"Đệ Nhất Đại Thừa","tomTat":"Ma Quang và Hỏa Tu Tử mang xác Nguyên Anh cùng vòng trữ vật của Minh Tôn trở về, giúp Hàn Lập xác nhận đối phương đã chết trước khi thiêu di thể thành tro. Hàn Lập thu chiến lợi phẩm, tập hợp các trợ thủ rồi dùng phi xa rời Minh Sát Chi Địa. Sau khi bổn mệnh bài của những cường giả tham chiến đồng loạt vỡ, tin tức về tổn thất kinh người lan khắp Linh giới, còn Nhân tộc công bố Mã Lương và Minh Tôn đã đồng quy vu tận trong vụ tự bạo Lưỡng Nghi Diệt Trần đại trận. Việc Hàn Lập là người duy nhất bình an trở về khiến nhiều Đại Thừa tin rằng bảo vật Chân tiên đã rơi vào tay hắn và kéo tới Vô Nhai Hải, nhưng hơn hai mươi người lần lượt bị Phệ Kim Trùng Vương cùng Giải Đạo Nhân đánh lui. Tám cường giả đỉnh cấp từ Huyết Thiên Đại Lục và Lôi Minh Đại Lục sau đó liên thủ tới Thanh Nguyên Cung, song đều suy yếu sau ba ngày đối đầu trong khi Hàn Lập vẫn không biểu hiện tổn hao. Hàn Lập bán cho họ một viên Chân Hồn Đan để đổi lấy cam kết ngừng quấy nhiễu, đồng thời ra lệnh cho bốn trợ thủ bắt hoặc giết mọi kẻ tiếp tục xâm nhập Vô Nhai Hải. Chiến tích này khiến các thế lực cao cấp từ bỏ ý định cưỡng đoạt và đưa Hàn Lập lên vị thế cường giả số một Phong Nguyên Đại Lục, thậm chí được tôn là Đệ nhất Đại Thừa của Linh giới."},{"chuong":2432,"tieuDe":"Gặp Lại Linh Vương","tomTat":"Hai năm sau trận chiến tại Minh Sát, Hàn Lập vận dụng Dung Nguyên Tiên thuật trong mật thất Thanh Nguyên Cung, dung hợp hoàn toàn bình nhỏ phỏng chế vào Chưởng Thiên bình và nắm được phương pháp điều khiển bảo vật. Hắn xác định kế hoạch tiếp theo là tu thành các thần thông mới, hoàn thiện Nguyên Hợp Ngũ Cực Sơn, tích lũy pháp lực và chuẩn bị nghênh đón thiên kiếp phi thăng. Dựa trên kết quả truy xét Bổn Mệnh Bài của Giải Đạo Nhân, Hàn Lập đến Phục Linh Sơn tìm Linh Vương và dùng tiếng gọi mang thần thông áp chế lực lượng phòng vệ Linh tộc. Linh Vương nhận ra khí tức trên mệnh bài rồi dẫn hắn vào một không gian ngầm, nơi một Chân Tiên tuấn mỹ đang bị phong ấn dưới khối băng. Sau khi thu hồi hóa thân màu trắng, Linh Vương hiển lộ khí tức mạnh mẽ và xác nhận mình đã trấn áp người này nhiều năm. Hàn Lập muốn tiêu diệt Chân Tiên để trừ hậu họa, nhưng Linh Vương cho biết đối phương đã thay thế thân thể và dùng bí thuật niêm phong pháp lực, nguyên thần cùng thân thể thành một khối. Thân thể ấy mạnh đến mức ngay cả Huyền Thiên Chi Bảo cũng không thể gây tổn thương, khiến việc tiêu diệt người bị phong ấn trở thành một vấn đề khó giải quyết."},{"chuong":2433,"tieuDe":"Tung Tích","tomTat":"Hàn Lập đề nghị dùng Sưu hồn thuật với Chân Tiên bị phong ấn, còn Linh Vương đặt điều kiện hắn phải đứng nguyên tại chỗ tiếp ba chiêu. Hai người chuyển sang nơi khác giao đấu, nhưng sau hai lần ra tay, đoản nhận màu đen của Linh Vương đã bị chém gãy và ông chủ động nhận thua, đồng ý giao Chân Tiên cho Hàn Lập xử trí trước mặt mình. Hàn Lập xâm nhập thức hải đối phương và đọc được một phần ký ức, song khi hắn tiếp tục thăm dò vùng ký ức bị phong tỏa, đầu Chân Tiên nổ tung, thần hồn tiêu tán và thân thể hóa tro. Những ký ức còn lại cho biết người này từng dùng Đại Na Di phù trốn khỏi Cửu Nguyên Quan, nhưng bị lực lượng thần bí can thiệp trong lúc truyền tống và rơi xuống Hạ giới. Trong biến cố ấy, Bình Linh thi triển thần thông thiên phú, tự phân thành hai phần rồi chạy vào hai giới diện khác nhau, khiến Chưởng Thiên Bình không còn hoàn chỉnh. Hàn Lập biết Bình Linh có khả năng đang ẩn trong Ma giới, đồng thời lấy được linh huyết để thi triển thuật Truy Tung của Chân Tiên. Hắn cũng hiểu hoa sen bạc từng lấy tại Quảng Hàn Giới chính là linh dược cần cho việc đúc lại tiên thể, gián tiếp khiến Chân Tiên vội đi tìm mình rồi bị Linh Vương bắt giữ. Trên đường rời Phục Linh Sơn, Hàn Lập quyết định tới Ma giới tìm Bình Linh, đúng lúc lân phiến bạc trên người phát tiếng long ngâm và tự bay ra trước mặt hắn."},{"chuong":2434,"tieuDe":"Trở Lại Ma Nguyên","tomTat":"Hàn Lập nhận thông báo đại hội Quảng Linh Đạo Quả sẽ tổ chức tại Chân Long đảo sau hai năm và dự định tìm cách giành một quả sau khi hoàn thành chuyến đi Ma giới. Sau khi liên lạc với Nam Cung Uyển, hắn dùng Huyền Thiên Trảm Linh Kiếm phá mở một tiết điểm yếu giữa hai giới rồi tiến vào Ma giới. Hàn Lập phối hợp bình nhỏ màu xanh với quang trận để xác nhận Bình Linh đang ở giới này, sau đó liên tục truy theo cảm ứng suốt nửa năm. Dấu vết đưa hắn tới Ma Nguyên Hải, nơi hắn triệu Mặc Linh Thánh Thuyền và nhờ Giải Đạo Nhân dẫn đường vượt qua vùng biển đầy lôi điện. Tại Khổ Linh Đảo, Hàn Lập triển khai trận pháp lần nữa và bị Nguyên Yểm cưỡi Hắc Giao ba đầu xuất hiện chất vấn. Hắn khẳng định mục tiêu không phải Tẩy Linh Trì nhưng từ chối tiết lộ vật mình đang tìm, còn Nguyên Yểm vì nhiều điều kiêng kị nên không ra tay ngăn cản. Sau khi xác định tọa độ liên quan đến Bình Linh, Hàn Lập thu hồi bảo vật rồi cùng Giải Đạo Nhân rời đi, trong khi Nguyên Yểm lập tức bám theo."},{"chuong":2435,"tieuDe":"Bình Linh Trở Về","tomTat":"Hàn Lập, Giải Đạo Nhân và Nguyên Yểm tiến vào Khổ Linh Đảo, nơi cấm chế tự tan để lộ Khổ Linh Cốc cùng Linh Tiêu Thiên Trụ. Chưởng Thiên Bình bất ngờ bay khỏi tay áo Hàn Lập, đồng thời Bình Linh dưới hình dạng chiếc bình vàng lao ra khỏi cột sáng và tìm cách dung hợp với nó. Hàn Lập không thể trực tiếp bắt giữ Bình Linh nhưng nhận ra pháp quyết phối hợp bình phỏng chế với Chưởng Thiên Bình có thể kiềm chế linh thể này. Nguyên Yểm nảy ý tranh đoạt song bị Giải Đạo Nhân chắn đường, cuối cùng phải từ bỏ sau khi cân nhắc thực lực của hai đối thủ. Hàn Lập dùng phù lục tạo biển sương mù ngăn thần niệm và bí mật thu phục Bình Linh sau bảy ngày bảy đêm. Rời Khổ Linh Đảo, Hàn Lập và Giải Đạo Nhân đi thêm vài tháng tới một khe sâu tại Ma Giới, thu Mặc Linh Thánh Thuyền và chuẩn bị phá giới tới Ly Long Đảo để tiếp cận Ma Kha Giới."},{"chuong":2436,"tieuDe":"Sứ Giả Long Đảo","tomTat":"Hàn Lập mở khe nứt không gian dưới đáy hẻm núi, thu cự thuyền màu đen rồi cùng Giải Đạo Nhân rời Thánh giới để tiến vào Ma Kha Giới. Sau khi họ đi khỏi, Bảo Hoa và Niết Bàn hiện thân, tiết lộ đã nhận tin từ Nguyên Yểm và bí mật theo dõi Hàn Lập, đồng thời bàn luận về chiến tích hắn giết Chân Tiên và đoạt Chân Hồn Đan. Niết Bàn thừa nhận bổn nguyên của mình bị hao tổn nghiêm trọng sau biến cố Minh Trùng Mẫu, còn Bảo Hoa quyết định bế quan để hướng tới phi thăng Chân Ma Giới. Hai Thủy tổ cũng xác nhận Hàn Lập đã tu thành một phiên bản Niết Bàn Thánh Thể, loại pháp quyết luyện thể được suy diễn từ ma công trụ cột của Ma tộc. Một tháng sau, Giải Đạo Nhân cho Hàn Lập biết trí nhớ của mình đang bị cấm chế và chỉ có thể mở thêm khi thu thập đủ tài liệu cần thiết. Tại rừng phong đỏ thẫm, Điền Phi Nhi hóa từ Giao Long Ngũ Trảo thành nữ tử áo xanh rồi tới nghênh đón Hàn Lập dự Đạo Quả Đại Hội. Nàng cho biết Chân Long tộc đã huy động gần nửa tộc nhân làm sứ giả tiếp khách và cảnh báo nhiều cường giả đang nhòm ngó Chân Hồn Đan của Hàn Lập."},{"chuong":2437,"tieuDe":"Long Đảo","tomTat":"Điền Phi Nhi cảnh báo Hàn Lập rằng tin tức về Chân Hồn Đan đã lan rộng và chuyển lời Kim Long Đại Trưởng Lão muốn dùng một vật hữu ích hơn đối với Thiên Kiếp Phi Thăng để đổi lấy đan này. Hàn Lập ban đầu từ chối vì Chân Hồn Đan rất quan trọng cho việc độ kiếp, nhưng sau đó đồng ý cân nhắc gặp riêng đối phương khi tới Long Đảo. Điền Phi Nhi triệu Phong Linh Xa do bốn Nanh Mã kéo, thi triển pháp quyết tăng tốc rồi đưa hắn vượt hư không trong nhiều tháng. Khi tới Long Đảo, Hàn Lập được xác nhận đã vượt qua kiểm nghiệm thiếp mời và có thể tự do ra vào trong thời gian Đạo Quả Đại Hội, ngoại trừ các khu cấm địa. Trước khi rời đi làm nhiệm vụ chấp sự, Điền Phi Nhi trao cho hắn ngọc giản đã hứa để hoàn trả nhân tình. Hàn Lập sau đó dùng lân phiến bạc của Phàn Bào Tử liên kết bia đá với truyền tống pháp trận và biến mất khỏi quảng trường."},{"chuong":2438,"tieuDe":"Thu Hoạch","tomTat":"Sau một tháng ở Long Đảo, Hàn Lập che giấu dung mạo và tới một cửa hàng trong tiểu trấn để mua Phong Tinh Kim, nhưng chỉ còn tám ngàn cân nên hắn mua toàn bộ rồi kiểm tra hàng sau khi rời trấn. Ba tháng sau, hắn tham dự cuộc trao đổi kín trong một sơn cốc thuộc vùng sơn mạch đỏ thẫm, nơi lão giả da màu bích lục bày hơn mười vật phẩm và công bố những tài liệu mình muốn đổi. Bé gái dùng Hiên Viên mộc đổi lấy Thái Ất Kim đan, còn nam tử trung niên dùng Uế Âm Dịch đổi ngọc khuyết; các giao dịch tiếp diễn khiến hơn nửa số vật phẩm trên bàn được đổi đi. Hàn Lập cũng thu được một loại tài liệu đặc biệt giống vàng lẫn đá rồi chủ động nhận lượt trao đổi tiếp theo. Bốn tháng sau, hắn gặp Kim Đại Trưởng lão trên một chiếc thuyền vàng giữa hồ và cho biết chưa tìm thấy vật nào có giá trị tương xứng với Chân Hồn Đan. Kim Đại Trưởng lão đồng ý cho hắn xem vật trao đổi trước, đồng thời tiết lộ mình cần viên đan để hoàn trả nhân tình cho một lão hữu chứ không phải vì nó có tác dụng lớn với tộc Chân Long. Chương kết thúc khi ông ra lệnh cho Phàn Bào Tử mang vật định dùng trao đổi ra."},{"chuong":2439,"tieuDe":"Trao Đổi, Đại Hội","tomTat":"Phàn Bào Tử đưa Hàn Lập tới gặp Kim trưởng lão để kiểm tra bảy lân phiến lưu giữ trải nghiệm độ thiên kiếp phi thăng của Chân Long. Sau khi biết mỗi lân phiến chỉ dùng được ba lần, Hàn Lập đồng ý giao một viên Chân Hồn Đan để nhận bộ lân phiến cùng một lọ Kim Tang Dịch vạn năm. Rời kim sắc cự thuyền, hắn trò chuyện với Phàn Bào Tử về chiến tích đối phó Minh Trùng Mẫu, Mã Lương, triển vọng tranh Đạo Quả và nhân tình của Điền Phi Nhi. Nửa tháng sau, Hàn Lập nghiên cứu ngọc giản tình báo về Phong Nguyệt Chân Quân, Thiên Tước Tử và Bát Nhã tán nhân. Ba tháng tiếp theo, Chân Long tộc cử hành nghi thức và chính thức mở cuộc tranh đoạt Đạo Quả trong một không gian cấm chế riêng. Khi Hàn Lập bay qua khu rừng, nhiều đại thụ hóa thành cự nhân, đồng loạt dùng lôi hỏa và quyền ảnh phục kích hắn. Hắn dùng kiếm khí phá phần lớn thế công, hiện hóa Ma thần ba đầu sáu tay quét sạch số quyền ảnh còn lại rồi phun quả cầu ánh sáng chứa một bình nhỏ màu xanh về phía kẻ ẩn nấp."},{"chuong":2440,"tieuDe":"Đắc Quả","tomTat":"Hàn Lập thúc giục bình nhỏ màu xanh lá phá hủy rừng cây và đất đá trên phạm vi rộng, ép Thiên Tượng Tôn Giả phải hiện thân. Thiên Tượng Tôn Giả không thể phá xiềng xích pháp tắc nên nhận thua, giao ba Đạo Bài rồi bị quang trận năm màu truyền tống khỏi cuộc tranh đoạt. Vài ngày sau, Hàn Lập hóa thành Cự Viên vàng ba đầu sáu tay, giết một cự trùng huyễn thú trong sa mạc đỏ thẫm và lấy thêm một Đạo Bài. Nửa tháng sau, hắn tranh giành một cự kình huyễn thú với lão giả áo vàng và Hoa Dung phu nhân, buộc hai người hợp sức dùng nhiều bảo vật cùng biển lửa tấn công. Một tháng sau, Hàn Lập trở thành người đầu tiên mang đủ một trăm lẻ tám Đạo Quả Lệnh Bài tới Đạo Đài Chi Nhân. Kim trưởng lão xác nhận hắn đủ điều kiện, còn Phong trưởng lão trao Quảng Linh Đạo Quả. Bất chấp lời khuyên nên cất giữ, Hàn Lập ăn hết linh quả ngay tại chỗ, khiến các trưởng lão Long tộc kinh ngạc."}];
